def invoke(self, cli: Command, args: str | cabc.Sequence[str] | None=None, input: str | bytes | t.IO[t.Any] | None=None, env: cabc.Mapping[str, str | None] | None=None, catch_exceptions: bool | None=None, color: bool=False, **extra: t.Any) -> Result:
    exc_info = None
    if catch_exceptions is None:
        catch_exceptions = self.catch_exceptions
    cap_out: _FDCapture | None = None
    cap_err: _FDCapture | None = None
    if self.capture == 'fd':
        cap_out = _FDCapture(1)
        cap_err = _FDCapture(2)
        try:
            cap_out.start()
            cap_err.start()
        except OSError:
            cap_out = cap_err = None
    with self.isolation(input=input, env=env, color=color) as outstreams:
        if cap_out is not None and cap_err is not None:
            sys.stdout._original_fd = cap_out.saved_fd
            sys.stderr._original_fd = cap_err.saved_fd
        return_value = None
        exception: BaseException | None = None
        exit_code = 0
        if isinstance(args, str):
            args = shlex.split(args)
        try:
            prog_name = extra.pop('prog_name')
        except KeyError:
            prog_name = self.get_default_prog_name(cli)
        try:
            return_value = cli.main(args=args or (), prog_name=prog_name, **extra)
        except SystemExit as e:
            exc_info = sys.exc_info()
            e_code = t.cast('int | t.Any | None', e.code)
            if e_code is None:
                e_code = 0
            if e_code != 0:
                exception = e
            if not isinstance(e_code, int):
                sys.stdout.write(str(e_code))
                sys.stdout.write('\n')
                e_code = 1
            exit_code = e_code
        except Exception as e:
            if not catch_exceptions:
                raise
            exception = e
            exit_code = 1
            exc_info = sys.exc_info()
        finally:
            sys.stdout.flush()
            sys.stderr.flush()
            if cap_out is not None and cap_err is not None:
                fd_out = cap_out.stop()
                fd_err = cap_err.stop()
                if fd_out:
                    outstreams[0].write(fd_out)
                if fd_err:
                    outstreams[1].write(fd_err)
            stdout = outstreams[0].getvalue()
            stderr = outstreams[1].getvalue()
            output = outstreams[2].getvalue()
    return Result(runner=self, stdout_bytes=stdout, stderr_bytes=stderr, output_bytes=output, return_value=return_value, exit_code=exit_code, exception=exception, exc_info=exc_info)

@contextlib.contextmanager
def isolated_filesystem(self, temp_dir: str | os.PathLike[str] | None=None) -> cabc.Generator[str]:
    import warnings
    warnings.warn("'isolated_filesystem' is deprecated and will be removed in Click 9.0. Use 'tempfile.TemporaryDirectory' or pytest's 'tmp_path' fixture with absolute paths instead.", DeprecationWarning, stacklevel=3)
    cwd = os.getcwd()
    dt = tempfile.mkdtemp(dir=temp_dir)
    os.chdir(dt)
    try:
        yield dt
    finally:
        os.chdir(cwd)
        if temp_dir is None:
            import shutil
            try:
                shutil.rmtree(dt)
            except OSError:
                pass

def to_info_dict(self) -> ParamTypeInfoDict:
    param_type = type(self).__name__.partition('ParamType')[0]
    param_type = param_type.partition('ParameterType')[0]
    if hasattr(self, 'name'):
        name = self.name
    else:
        name = param_type
    return {'param_type': param_type, 'name': name}

def normalize_choice(self, choice: object, ctx: Context | None) -> str:
    normed_value = choice.name if isinstance(choice, enum.Enum) else str(choice)
    if ctx is not None and ctx.token_normalize_func is not None:
        normed_value = ctx.token_normalize_func(normed_value)
    if not self.case_sensitive:
        normed_value = normed_value.casefold()
    return normed_value

def convert(self, value: t.Any, param: Parameter | None, ctx: Context | None) -> _ValueT_co:
    normed_value = self.normalize_choice(choice=value, ctx=ctx)
    normalized_mapping = self._normalized_mapping(ctx=ctx)
    try:
        return next((original for original, normalized in normalized_mapping.items() if normalized == normed_value))
    except StopIteration:
        self.fail(self.get_invalid_choice_message(value=value, ctx=ctx), param=param, ctx=ctx)

def get_invalid_choice_message(self, value: t.Any, ctx: Context | None) -> str:
    choices_str = ', '.join(map(repr, self._normalized_mapping(ctx=ctx).values()))
    return ngettext('{value!r} is not {choice}.', '{value!r} is not one of {choices}.', len(self.choices)).format(value=value, choice=choices_str, choices=choices_str)

def shell_complete(self, ctx: Context, param: Parameter, incomplete: str) -> list[CompletionItem]:
    from click.shell_completion import CompletionItem
    str_choices = [self.normalize_choice(choice, ctx) for choice in self.choices]
    if self.case_sensitive:
        matched = (c for c in str_choices if c.startswith(incomplete))
    else:
        incomplete = incomplete.lower()
        matched = (c for c in str_choices if c.lower().startswith(incomplete))
    return [CompletionItem(c) for c in matched]

@abc.abstractmethod
def _clamp(self: _NumberRangeBase[t.Any, _FloatValueT], bound: _FloatValueT, dir: t.Literal[1, -1], open: bool) -> _FloatValueT:
