    return '<Polygon><outerBoundaryIs>%s</outerBoundaryIs>%s</Polygon>' % (self[0].kml, inner_kml)

def check_cs_op(result, func, cargs):
    if result == 0:
        raise GEOSException('Could not set value on coordinate sequence')
    else:
        return result

def check_cs_get(result, func, cargs):
    check_cs_op(result, func, cargs)
    return last_arg_byref(cargs)

def check_dbl(result, func, cargs):
    if result != 1:
        return None
    return last_arg_byref(cargs)

def check_geom(result, func, cargs):
    if not result:
        raise GEOSException('Error encountered checking Geometry returned from GEOS C function "%s".' % func.__name__)
    return result

def check_minus_one(result, func, cargs):
    if result == -1:
        raise GEOSException('Error encountered in GEOS C function "%s".' % func.__name__)
    else:
        return result

def check_predicate(result, func, cargs):
    if result == 1:
        return True
    elif result == 0:
        return False
    else:
        raise GEOSException('Error encountered on GEOS C predicate function "%s".' % func.__name__)

def check_sized_string(result, func, cargs):
    if not result:
        raise GEOSException('Invalid string pointer returned by GEOS C function "%s"' % func.__name__)
    s = string_at(result, last_arg_byref(cargs))
    free(result)
    return s

def check_string(result, func, cargs):
    if not result:
        raise GEOSException('Error encountered checking string return value in GEOS C function "%s".' % func.__name__)
    s = string_at(result)
    free(result)
    return s

def read(self, wkb):
    if isinstance(wkb, memoryview):
        wkb_s = bytes(wkb)
        return wkb_reader_read(self.ptr, wkb_s, len(wkb_s))
    elif isinstance(wkb, bytes):
        return wkb_reader_read_hex(self.ptr, wkb, len(wkb))
    elif isinstance(wkb, str):
        wkb_s = wkb.encode()
        return wkb_reader_read_hex(self.ptr, wkb_s, len(wkb_s))
    else:
        raise TypeError(f"'wkb' must be bytes, str or memoryview (got {wkb!r} instead).")

def write(self, geom):
    geom = self._handle_empty_point(geom)
    wkb = wkb_writer_write(self.ptr, geom.ptr, byref(c_size_t()))
    return memoryview(wkb)

def _build_kml_sources(self, sources):
    kml_sources = []
    if sources is None:
        sources = apps.get_models()
    for source in sources:
        if isinstance(source, models.base.ModelBase):
            for field in source._meta.fields:
                if isinstance(field, GeometryField):
                    kml_sources.append((source._meta.app_label, source._meta.model_name, field.name))
        elif isinstance(source, (list, tuple)):
            if len(source) != 3:
                raise ValueError('Must specify a 3-tuple of (app_label, module_name, field_name).')
            kml_sources.append(source)
        else:
            raise TypeError('KML Sources must be a model or a 3-tuple.')
    return kml_sources

def get_urls(self, page=1, site=None, protocol=None):
    urls = Sitemap.get_urls(self, page=page, site=site, protocol=protocol)
    for url in urls:
        url['geo_format'] = self.geo_format
    return urls

def kml(request, label, model, field_name=None, compress=False, using=DEFAULT_DB_ALIAS):
    placemarks = []
    try:
        klass = apps.get_model(label, model)
    except LookupError:
        raise Http404('You must supply a valid app label and module name. Got "%s.%s"' % (label, model))
    if field_name:
        try:
            field = klass._meta.get_field(field_name)
            if not isinstance(field, GeometryField):
                raise FieldDoesNotExist
        except FieldDoesNotExist:
            raise Http404('Invalid geometry field.')
    connection = connections[using]
    if connection.features.has_AsKML_function:
        placemarks = klass._default_manager.using(using).annotate(kml=AsKML(field_name))
    else:
        placemarks = []
        if connection.features.has_Transform_function:
            qs = klass._default_manager.using(using).annotate(**{'%s_4326' % field_name: Transform(field_name, 4326)})
            field_name += '_4326'
        else:
            qs = klass._default_manager.using(using).all()
        for mod in qs:
            mod.kml = getattr(mod, field_name).kml
            placemarks.append(mod)
    if compress:
        render = render_to_kmz
    else:
        render = render_to_kml
    return render('gis/kml/placemarks.kml', {'places': placemarks})

def __init__(self, model, data, mapping, layer=0, source_srs=None, encoding='utf-8', transaction_mode='commit_on_success', transform=True, unique=None, using=None):
    if isinstance(data, (str, Path)):
        self.ds = DataSource(data, encoding=encoding)
    else:
        self.ds = data
    self.layer = self.ds[layer]
    self.using = using if using is not None else router.db_for_write(model)
    connection = connections[self.using]
    self.spatial_backend = connection.ops
    self.mapping = mapping
    self.model = model
    self.check_layer()
    if connection.features.supports_transform:
        self.geo_field = self.geometry_field()
    else:
        transform = False
    if transform:
        self.source_srs = self.check_srs(source_srs)
        self.transform = self.coord_transform()
    else:
        self.transform = transform
    if encoding:
        from codecs import lookup
        lookup(encoding)
        self.encoding = encoding
    else:
        self.encoding = None
    if unique:
        self.check_unique(unique)
        transaction_mode = 'autocommit'
        self.unique = unique
    else:
        self.unique = None
    self.transaction_mode = transaction_mode
    if transaction_mode == 'autocommit':
        self.transaction_decorator = None
    elif transaction_mode == 'commit_on_success':
        self.transaction_decorator = transaction.atomic
    else:
        raise LayerMapError('Unrecognized transaction mode: %s' % transaction_mode)

def check_fid_range(self, fid_range):
    if fid_range:
        if isinstance(fid_range, (tuple, list)):
            return slice(*fid_range)
        elif isinstance(fid_range, slice):
            return fid_range
        else:
            raise TypeError
    else:
        return None

def check_layer(self):
    self.geom_field = False
    self.fields = {}
    ogr_fields = self.layer.fields
    ogr_field_types = self.layer.field_types

    def check_ogr_fld(ogr_map_fld):
        try:
            idx = ogr_fields.index(ogr_map_fld)
        except ValueError:
            raise LayerMapError('Given mapping OGR field "%s" not found in OGR Layer.' % ogr_map_fld)
        return idx
    for field_name, ogr_name in self.mapping.items():
        try:
            model_field = self.model._meta.get_field(field_name)
        except FieldDoesNotExist:
            raise LayerMapError('Given mapping field "%s" not in given Model fields.' % field_name)
        fld_name = model_field.__class__.__name__
        if isinstance(model_field, GeometryField):
            if self.geom_field:
                raise LayerMapError('LayerMapping does not support more than one GeometryField per model.')
            coord_dim = model_field.dim
            try:
                if coord_dim == 3:
                    gtype = OGRGeomType(ogr_name + '25D')
                else:
                    gtype = OGRGeomType(ogr_name)
            except GDALException:
                raise LayerMapError('Invalid mapping for GeometryField "%s".' % field_name)
            ltype = self.layer.geom_type
            if not (ltype.name.startswith(gtype.name) or self.make_multi(ltype, model_field)):
                raise LayerMapError('Invalid mapping geometry; model has %s%s, layer geometry type is %s.' % (fld_name, '(dim=3)' if coord_dim == 3 else '', ltype))
            self.geom_field = field_name
            self.coord_dim = coord_dim
            fields_val = model_field
        elif isinstance(model_field, models.ForeignKey):
            if isinstance(ogr_name, dict):
                rel_model = model_field.remote_field.model
                for rel_name, ogr_field in ogr_name.items():
                    idx = check_ogr_fld(ogr_field)
                    try:
                        rel_model._meta.get_field(rel_name)
                    except FieldDoesNotExist:
                        raise LayerMapError('ForeignKey mapping field "%s" not in %s fields.' % (rel_name, rel_model.__class__.__name__))
                fields_val = rel_model
            else:
                raise TypeError('ForeignKey mapping must be of dictionary type.')
        else:
            if model_field.__class__ not in self.FIELD_TYPES:
                raise LayerMapError('Django field type "%s" has no OGR mapping (yet).' % fld_name)
            idx = check_ogr_fld(ogr_name)
            ogr_field = ogr_field_types[idx]
            if not issubclass(ogr_field, self.FIELD_TYPES[model_field.__class__]):
                raise LayerMapError('OGR field "%s" (of type %s) cannot be mapped to Django %s.' % (ogr_field, ogr_field.__name__, fld_name))
            fields_val = model_field
        self.fields[field_name] = fields_val

def check_srs(self, source_srs):
    if isinstance(source_srs, SpatialReference):
        sr = source_srs
    elif isinstance(source_srs, self.spatial_backend.spatial_ref_sys()):
        sr = source_srs.srs
    elif isinstance(source_srs, (int, str)):
        sr = SpatialReference(source_srs)
    else:
        sr = self.layer.srs
    if not sr:
        raise LayerMapError('No source reference system defined.')
    else:
        return sr

def check_unique(self, unique):
    if isinstance(unique, (list, tuple)):
        for attr in unique:
            if attr not in self.mapping:
                raise ValueError
    elif isinstance(unique, str):
        if unique not in self.mapping:
            raise ValueError
    else:
        raise TypeError('Unique keyword argument must be set with a tuple, list, or string.')

def feature_kwargs(self, feat):
    kwargs = {}
    for field_name, ogr_name in self.mapping.items():
        model_field = self.fields[field_name]
        if isinstance(model_field, GeometryField):
            try:
                val = self.verify_geom(feat.geom, model_field)
            except GDALException:
                raise LayerMapError('Could not retrieve geometry from feature.')
        elif isinstance(model_field, models.base.ModelBase):
            val = self.verify_fk(feat, model_field, ogr_name)
        else:
            val = self.verify_ogr_field(feat[ogr_name], model_field)
        kwargs[field_name] = val
    return kwargs

def unique_kwargs(self, kwargs):
    if isinstance(self.unique, str):
        return {self.unique: kwargs[self.unique]}
    else:
        return {fld: kwargs[fld] for fld in self.unique}

def verify_ogr_field(self, ogr_field, model_field):
    if isinstance(ogr_field, OFTString) and isinstance(model_field, (models.CharField, models.TextField)):
        if self.encoding and ogr_field.value is not None:
            val = force_str(ogr_field.value, self.encoding)
        else:
            val = ogr_field.value
        if model_field.max_length and val is not None and (len(val) > model_field.max_length):
            raise InvalidString('%s model field maximum string length is %s, given %s characters.' % (model_field.name, model_field.max_length, len(val)))
    elif isinstance(ogr_field, OFTReal) and isinstance(model_field, models.DecimalField):
        try:
            d = Decimal(str(ogr_field.value))
        except DecimalInvalidOperation:
            raise InvalidDecimal('Could not construct decimal from: %s' % ogr_field.value)
        dtup = d.as_tuple()
        digits = dtup[1]
        d_idx = dtup[2]
        max_prec = model_field.max_digits - model_field.decimal_places
        if d_idx < 0:
            n_prec = len(digits[:d_idx])
        else:
            n_prec = len(digits) + d_idx
        if n_prec > max_prec:
            raise InvalidDecimal('A DecimalField with max_digits %d, decimal_places %d must round to an absolute value less than 10^%d.' % (model_field.max_digits, model_field.decimal_places, max_prec))
        val = d
    elif isinstance(ogr_field, (OFTReal, OFTString)) and isinstance(model_field, models.IntegerField):
        try:
            val = int(ogr_field.value)
        except ValueError:
            raise InvalidInteger('Could not construct integer from: %s' % ogr_field.value)
    else:
        val = ogr_field.value
    return val

def verify_fk(self, feat, rel_model, rel_mapping):
    fk_kwargs = {}
    for field_name, ogr_name in rel_mapping.items():
        fk_kwargs[field_name] = self.verify_ogr_field(feat[ogr_name], rel_model._meta.get_field(field_name))
    try:
        return rel_model.objects.using(self.using).get(**fk_kwargs)
    except ObjectDoesNotExist:
        raise MissingForeignKey('No ForeignKey %s model found with keyword arguments: %s' % (rel_model.__name__, fk_kwargs))

def verify_geom(self, geom, model_field):
    if geom.is_measured:
        geom.set_measured(False)
    if self.coord_dim == 2 and geom.is_3d:
        geom.set_3d(False)
    if self.make_multi(geom.geom_type, model_field):
        multi_type = self.MULTI_TYPES[geom.geom_type.num]
        g = OGRGeometry(multi_type)
        g.add(geom)
    else:
        g = geom
    if self.transform:
        g.transform(self.transform)
    return g.wkt

def coord_transform(self):
    SpatialRefSys = self.spatial_backend.spatial_ref_sys()
    try:
        target_srs = SpatialRefSys.objects.using(self.using).get(srid=self.geo_field.srid).srs
        return CoordTransform(self.source_srs, target_srs)
    except Exception as exc:
        raise LayerMapError('Could not translate between the data source and model geometry.') from exc

def geometry_field(self):
    opts = self.model._meta
    return opts.get_field(self.geom_field)

def save(self, verbose=False, fid_range=False, step=False, progress=False, silent=False, stream=sys.stdout, strict=False):
    default_range = self.check_fid_range(fid_range)
    if progress:
        if progress is True or not isinstance(progress, int):
            progress_interval = 1000
        else:
            progress_interval = progress

    def _save(feat_range=default_range, num_feat=0, num_saved=0):
        if feat_range:
            layer_iter = self.layer[feat_range]
        else:
            layer_iter = self.layer
        for feat in layer_iter:
            num_feat += 1
            try:
                kwargs = self.feature_kwargs(feat)
            except LayerMapError as msg:
                if strict:
                    raise
                elif not silent:
                    stream.write('Ignoring Feature ID %s because: %s\n' % (feat.fid, msg))
            else:
                is_update = False
                if self.unique:
                    try:
                        u_kwargs = self.unique_kwargs(kwargs)
                        m = self.model.objects.using(self.using).get(**u_kwargs)
                        is_update = True
                        geom_value = getattr(m, self.geom_field)
                        if geom_value is None:
                            geom = OGRGeometry(kwargs[self.geom_field])
                        else:
                            geom = geom_value.ogr
                            new = OGRGeometry(kwargs[self.geom_field])
                            for g in new:
                                geom.add(g)
                        setattr(m, self.geom_field, geom.wkt)
                    except ObjectDoesNotExist:
                        m = self.model(**kwargs)
                else:
                    m = self.model(**kwargs)
                try:
                    m.save(using=self.using)
                    num_saved += 1
                    if verbose:
                        stream.write('%s: %s\n' % ('Updated' if is_update else 'Saved', m))
                except Exception as msg:
                    if strict:
                        if not silent:
                            stream.write('Failed to save the feature (id: %s) into the model with the keyword arguments:\n' % feat.fid)
                            stream.write('%s\n' % kwargs)
                        raise
                    elif not silent:
                        stream.write('Failed to save %s:\n %s\nContinuing\n' % (kwargs, msg))
            if progress and num_feat % progress_interval == 0:
                stream.write('Processed %d features, saved %d ...\n' % (num_feat, num_saved))
        return (num_saved, num_feat)
    if self.transaction_decorator is not None:
        _save = self.transaction_decorator(_save)
    nfeat = self.layer.num_feat
    if step and isinstance(step, int) and (step < nfeat):
        if default_range:
            raise LayerMapError('The `step` keyword may not be used in conjunction with the `fid_range` keyword.')
        beg, num_feat, num_saved = (0, 0, 0)
        indices = range(step, nfeat, step)
        n_i = len(indices)
        for i, end in enumerate(indices):
            if i + 1 == n_i:
                step_slice = slice(beg, None)
            else:
                step_slice = slice(beg, end)
            try:
                num_feat, num_saved = _save(step_slice, num_feat, num_saved)
                beg = end
            except Exception:
                stream.write('%s\nFailed to save slice: %s\n' % ('=-' * 20, step_slice))
                raise
    else:
        _save()

def ogrinfo(data_source, num_features=10):
    if isinstance(data_source, str):
        data_source = DataSource(data_source)
    elif isinstance(data_source, DataSource):
        pass
    else:
        raise Exception('Data source parameter must be a string or a DataSource object.')
    for i, layer in enumerate(data_source):
        print('data source : %s' % data_source.name)
        print('==== layer %s' % i)
        print('  shape type: %s' % GEO_CLASSES[layer.geom_type.num].__name__)
        print('  # features: %s' % len(layer))
        print('         srs: %s' % layer.srs)
        extent_tup = layer.extent.tuple
        print('      extent: %s - %s' % (extent_tup[0:2], extent_tup[2:4]))
        print('Displaying the first %s features ====' % num_features)
        width = max(*map(len, layer.fields))
        fmt = ' %%%ss: %%s' % width
        for j, feature in enumerate(layer[:num_features]):
            print('=== Feature %s' % j)
            for fld_name in layer.fields:
                type_name = feature[fld_name].type_name
                output = fmt % (fld_name, type_name)
                val = feature.get(fld_name)
                if val:
                    if isinstance(val, str):
                        val_fmt = ' ("%s")'
                    else:
                        val_fmt = ' (%s)'
                    output += val_fmt % val
                else:
                    output += ' (None)'
                print(output)

def mapping(data_source, geom_name='geom', layer_key=0, multi_geom=False):
    if isinstance(data_source, str):
        data_source = DataSource(data_source)
    elif isinstance(data_source, DataSource):
        pass
    else:
        raise TypeError('Data source parameter must be a string or a DataSource object.')
    _mapping = {}
    for field in data_source[layer_key].fields:
        mfield = field.lower()
        if mfield[-1:] == '_':
            mfield += 'field'
        _mapping[mfield] = field
    gtype = data_source[layer_key].geom_type
    if multi_geom:
        gtype.to_multi()
    _mapping[geom_name] = str(gtype).upper()
    return _mapping

def _ogrinspect(data_source, model_name, geom_name='geom', layer_key=0, srid=None, multi_geom=False, name_field=None, imports=True, decimal=False, blank=False, null=False):
    if isinstance(data_source, str):
        data_source = DataSource(data_source)
    elif isinstance(data_source, DataSource):
        pass
    else:
        raise TypeError('Data source parameter must be a string or a DataSource object.')
    layer = data_source[layer_key]
    ogr_fields = layer.fields

    def process_kwarg(kwarg):
        if isinstance(kwarg, (list, tuple)):
            return [s.lower() for s in kwarg]
        elif kwarg:
            return [s.lower() for s in ogr_fields]
        else:
            return []
    null_fields = process_kwarg(null)
    blank_fields = process_kwarg(blank)
    decimal_fields = process_kwarg(decimal)

    def get_kwargs_str(field_name):
        kwlist = []
        if field_name.lower() in null_fields:
            kwlist.append('null=True')
        if field_name.lower() in blank_fields:
            kwlist.append('blank=True')
        if kwlist:
            return ', ' + ', '.join(kwlist)
        else:
            return ''
    if imports:
        yield '# This is an auto-generated Django model module created by ogrinspect.'
        yield 'from django.contrib.gis.db import models'
        yield ''
        yield ''
    yield ('class %s(models.Model):' % model_name)
    for field_name, width, precision, field_type in zip(ogr_fields, layer.field_widths, layer.field_precisions, layer.field_types):
        mfield = field_name.lower()
        if mfield[-1:] == '_':
            mfield += 'field'
        kwargs_str = get_kwargs_str(field_name)
        if field_type is OFTReal:
            if field_name.lower() in decimal_fields:
                yield ('    %s = models.DecimalField(max_digits=%d, decimal_places=%d%s)' % (mfield, width, precision, kwargs_str))
            else:
                yield ('    %s = models.FloatField(%s)' % (mfield, kwargs_str[2:]))
        elif field_type is OFTInteger:
            yield ('    %s = models.IntegerField(%s)' % (mfield, kwargs_str[2:]))
        elif field_type is OFTInteger64:
            yield ('    %s = models.BigIntegerField(%s)' % (mfield, kwargs_str[2:]))
        elif field_type is OFTString:
            yield ('    %s = models.CharField(max_length=%s%s)' % (mfield, width, kwargs_str))
        elif field_type is OFTDate:
            yield ('    %s = models.DateField(%s)' % (mfield, kwargs_str[2:]))
        elif field_type is OFTDateTime:
            yield ('    %s = models.DateTimeField(%s)' % (mfield, kwargs_str[2:]))
        elif field_type is OFTTime:
            yield ('    %s = models.TimeField(%s)' % (mfield, kwargs_str[2:]))
        else:
            raise TypeError('Unknown field type %s in %s' % (field_type, mfield))
    gtype = layer.geom_type
    if multi_geom:
        gtype.to_multi()
    geom_field = gtype.django
    if srid is None:
        if layer.srs is None:
            srid_str = 'srid=-1'
        else:
            srid = layer.srs.srid
            if srid is None:
                srid_str = 'srid=-1'
            elif srid == 4326:
                srid_str = ''
            else:
                srid_str = 'srid=%s' % srid
    else:
        srid_str = 'srid=%s' % srid
    yield ('    %s = models.%s(%s)' % (geom_name, geom_field, srid_str))
    if name_field:
        yield ''
        yield ('    def __str__(self): return self.%s' % name_field)

def add_srs_entry(srs, auth_name='EPSG', auth_srid=None, ref_sys_name=None, database=None):
    database = database or DEFAULT_DB_ALIAS
    connection = connections[database]
    if not hasattr(connection.ops, 'spatial_version'):
        raise Exception('The `add_srs_entry` utility only works with spatial backends.')
    if not connection.features.supports_add_srs_entry:
        raise Exception('This utility does not support your database backend.')
    SpatialRefSys = connection.ops.spatial_ref_sys()
    if not isinstance(srs, SpatialReference):
        srs = SpatialReference(srs)
    if srs.srid is None:
        raise Exception('Spatial reference requires an SRID to be compatible with the spatial backend.')
    kwargs = {'srid': srs.srid, 'auth_name': auth_name, 'auth_srid': auth_srid or srs.srid, 'proj4text': srs.proj4}
    srs_field_names = {f.name for f in SpatialRefSys._meta.get_fields()}
    if 'srtext' in srs_field_names:
        kwargs['srtext'] = srs.wkt
    if 'ref_sys_name' in srs_field_names:
        kwargs['ref_sys_name'] = ref_sys_name or srs.name
    try:
        SpatialRefSys.objects.using(database).get(srid=srs.srid)
    except SpatialRefSys.DoesNotExist:
        SpatialRefSys.objects.using(database).create(**kwargs)

@register.filter(is_safe=True)
def ordinal(value):
    try:
        value = int(value)
    except (TypeError, ValueError):
        return value
    if value < 0:
        return str(value)
    if value == 1:
        value = pgettext('ordinal is 1', '{}st').format(value)
    elif value % 100 in (11, 12, 13):
        value = pgettext('ordinal 11, 12, 13', '{}th').format(value)
    else:
        templates = (pgettext('ordinal 0', '{}th'), pgettext('ordinal 1', '{}st'), pgettext('ordinal 2', '{}nd'), pgettext('ordinal 3', '{}rd'), pgettext('ordinal 4', '{}th'), pgettext('ordinal 5', '{}th'), pgettext('ordinal 6', '{}th'), pgettext('ordinal 7', '{}th'), pgettext('ordinal 8', '{}th'), pgettext('ordinal 9', '{}th'))
        value = templates[value % 10].format(value)
    return mark_safe(value)

@register.filter(is_safe=True)
def intcomma(value, use_l10n=True):
    if use_l10n:
        try:
            if not isinstance(value, (float, Decimal)):
                value = Decimal(value)
