def chunks(self, chunk_size=None):
    chunk_size = chunk_size or self.DEFAULT_CHUNK_SIZE
    try:
        self.seek(0)
    except (AttributeError, UnsupportedOperation):
        pass
    while True:
        data = self.read(chunk_size)
        if not data:
            break
        yield data

def get_image_dimensions(file_or_path, close=False):
    from PIL import ImageFile as PillowImageFile
    p = PillowImageFile.Parser()
    if hasattr(file_or_path, 'read'):
        file = file_or_path
        file_pos = file.tell()
        file.seek(0)
    else:
        try:
            file = open(file_or_path, 'rb')
        except OSError:
            return (None, None)
        close = True
    try:
        chunk_size = 1024
        while 1:
            data = file.read(chunk_size)
            if not data:
                break
            try:
                p.feed(data)
            except zlib.error as e:
                if e.args[0].startswith('Error -5'):
                    pass
                else:
                    raise
            except struct.error:
                pass
            except RuntimeError:
                pass
            if p.image:
                return p.image.size
            chunk_size *= 2
        return (None, None)
    finally:
        if close:
            file.close()
        else:
            file.seek(file_pos)

def file_move_safe(old_file_name, new_file_name, chunk_size=1024 * 64, allow_overwrite=False):
    try:
        if os.path.samefile(old_file_name, new_file_name):
            return
    except OSError:
        pass
    if not allow_overwrite and os.access(new_file_name, os.F_OK):
        raise FileExistsError(f'Destination file {new_file_name} exists and allow_overwrite is False.')
    try:
        os.rename(old_file_name, new_file_name)
        return
    except OSError:
        pass
    with open(old_file_name, 'rb') as old_file:
        fd = os.open(new_file_name, os.O_WRONLY | os.O_CREAT | getattr(os, 'O_BINARY', 0) | (os.O_EXCL if not allow_overwrite else 0) | os.O_TRUNC)
        try:
            locks.lock(fd, locks.LOCK_EX)
            current_chunk = None
            while current_chunk != b'':
                current_chunk = old_file.read(chunk_size)
                os.write(fd, current_chunk)
        finally:
            locks.unlock(fd)
            os.close(fd)
    try:
        copystat(old_file_name, new_file_name)
    except PermissionError:
        try:
            copymode(old_file_name, new_file_name)
        except PermissionError:
            pass
    try:
        os.remove(old_file_name)
    except PermissionError as e:
        if getattr(e, 'winerror', 0) != 32:
            raise

@classmethod
def from_dict(cls, file_dict):
    return cls(file_dict['filename'], file_dict['content'], file_dict.get('content-type', 'text/plain'))

def new_file(self, *args, **kwargs):
    super().new_file(*args, **kwargs)
    self.file = TemporaryUploadedFile(self.file_name, self.content_type, 0, self.charset, self.content_type_extra)

def handle_raw_input(self, input_data, META, content_length, boundary, encoding=None):
    stream = getattr(input_data, '_stream', input_data)
    try:
        content_length = stream.seek(0, os.SEEK_END)
    except (UnsupportedOperation, AttributeError):
        pass
    else:
        stream.seek(0)
    self.activated = content_length is not None and content_length <= settings.FILE_UPLOAD_MAX_MEMORY_SIZE

def receive_data_chunk(self, raw_data, start):
    if self.activated:
        self.file.write(raw_data)
    else:
        return raw_data

def file_complete(self, file_size):
    if not self.activated:
        return
    self.file.seek(0)
    return InMemoryUploadedFile(file=self.file, field_name=self.field_name, name=self.file_name, content_type=self.content_type, size=file_size, charset=self.charset, content_type_extra=self.content_type_extra)

def get_available_name(self, name, max_length=None):
    name = str(name).replace('\\', '/')
    dir_name, file_name = os.path.split(name)
    if '..' in pathlib.PurePath(dir_name).parts:
        raise SuspiciousFileOperation("Detected path traversal attempt in '%s'" % dir_name)
    validate_file_name(file_name)
    file_ext = ''.join(pathlib.PurePath(file_name).suffixes)
    file_root = file_name.removesuffix(file_ext)
    while not self.is_name_available(name, max_length=max_length):
        name = os.path.join(dir_name, self.get_alternative_name(file_root, file_ext))
        if max_length is None:
            continue
        truncation = len(name) - max_length
        if truncation > 0:
            file_root = file_root[:-truncation]
            if not file_root:
                raise SuspiciousFileOperation('Storage can not find an available filename for "%s". Please make sure that the corresponding file field allows sufficient "max_length".' % name)
            name = os.path.join(dir_name, self.get_alternative_name(file_root, file_ext))
    return name

def generate_filename(self, filename):
    filename = str(filename).replace('\\', '/')
    dirname, filename = os.path.split(filename)
    if '..' in pathlib.PurePath(dirname).parts:
        raise SuspiciousFileOperation("Detected path traversal attempt in '%s'" % dirname)
    return os.path.normpath(os.path.join(dirname, self.get_valid_name(filename)))

def _datetime_from_timestamp(self, ts):
    tz = UTC if settings.USE_TZ else None
    return datetime.fromtimestamp(ts, tz=tz)

def resolve(self, path, create_if_missing=False, leaf_cls=None, check_exists=True):
    path_segments = list(pathlib.Path(path).parts)
    current_node = self
    while path_segments:
        path_segment = path_segments.pop(0)
        if isinstance(current_node, InMemoryFileNode):
            path_segments = os.path.split(path)
            current_path = '/'.join(path_segments[:path_segments.index(path_segment)])
            raise NotADirectoryError(errno.ENOTDIR, os.strerror(errno.ENOTDIR), current_path)
        current_node = current_node._resolve_child(path_segment, create_if_missing, leaf_cls if len(path_segments) == 0 else InMemoryDirNode)
        if current_node is None:
            break
    if current_node is None and check_exists:
        raise FileNotFoundError(errno.ENOENT, os.strerror(errno.ENOENT), path)
    if leaf_cls and (not isinstance(current_node, leaf_cls)):
        error_cls, error_code = (NotADirectoryError, errno.ENOTDIR) if leaf_cls is InMemoryDirNode else (IsADirectoryError, errno.EISDIR)
        raise error_cls(error_code, os.strerror(error_code), path)
    return current_node

def _clear_cached_properties(self, setting, **kwargs):
    if setting == 'MEDIA_ROOT':
        self.__dict__.pop('base_location', None)
        self.__dict__.pop('location', None)
    elif setting == 'MEDIA_URL':
        self.__dict__.pop('base_url', None)
    elif setting == 'FILE_UPLOAD_PERMISSIONS':
        self.__dict__.pop('file_permissions_mode', None)
    elif setting == 'FILE_UPLOAD_DIRECTORY_PERMISSIONS':
        self.__dict__.pop('directory_permissions_mode', None)

def get_script_prefix(scope):
    if settings.FORCE_SCRIPT_NAME:
        return settings.FORCE_SCRIPT_NAME
    return scope.get('root_path', '') or ''

async def handle(self, scope, receive, send):
    try:
        body_file = await self.read_body(receive)
    except RequestAborted:
        return
    with closing(body_file):
        set_script_prefix(get_script_prefix(scope))
        await signals.request_started.asend(sender=self.__class__, scope=scope)
        request, error_response = self.create_request(scope, body_file)
        if request is None:
            body_file.close()
            await self.send_response(error_response, send)
            await sync_to_async(error_response.close)()
            return

        class RequestProcessed(Exception):
            pass
        response = None
        try:
            try:
                async with asyncio.TaskGroup() as tg:
                    tg.create_task(self.listen_for_disconnect(receive))
                    response = await self.run_get_response(request)
                    await self.send_response(response, send)
                    raise RequestProcessed
            except* (RequestProcessed, RequestAborted):
                pass
        except BaseExceptionGroup as exception_group:
            if len(exception_group.exceptions) == 1:
                raise exception_group.exceptions[0]
            raise
        if response is None:
            await signals.request_finished.asend(sender=self.__class__)
        else:
            await sync_to_async(response.close)()

async def read_body(self, receive):
    body_file = tempfile.SpooledTemporaryFile(max_size=settings.FILE_UPLOAD_MAX_MEMORY_SIZE, mode='w+b')
    while True:
        message = await receive()
        if message['type'] == 'http.disconnect':
            body_file.close()
            raise RequestAborted()
        if 'body' in message:
            on_disk = getattr(body_file, '_rolled', False)
            if on_disk:
                async_write = sync_to_async(body_file.write, thread_sensitive=False)
                await async_write(message['body'])
            else:
                body_file.write(message['body'])
        if not message.get('more_body', False):
            break
    body_file.seek(0)
    return body_file

def create_request(self, scope, body_file):
    try:
        return (self.request_class(scope, body_file), None)
    except UnicodeDecodeError:
        logger.warning('Bad Request (UnicodeDecodeError)', exc_info=sys.exc_info(), extra={'status_code': 400})
        return (None, HttpResponseBadRequest())
    except RequestDataTooBig:
        return (None, HttpResponse('413 Payload too large', status=413))

def handle_uncaught_exception(self, request, resolver, exc_info):
    try:
        return super().handle_uncaught_exception(request, resolver, exc_info)
    except Exception:
        return HttpResponseServerError(traceback.format_exc() if settings.DEBUG else 'Internal Server Error', content_type='text/plain')

async def send_response(self, response, send):
    response_headers = []
    for header, value in response.items():
        if isinstance(header, str):
            header = header.encode('ascii')
        if isinstance(value, str):
            value = value.encode('latin1')
        response_headers.append((bytes(header), bytes(value)))
    for c in response.cookies.values():
        response_headers.append((b'Set-Cookie', c.OutputString().encode('ascii')))
    await send({'type': 'http.response.start', 'status': response.status_code, 'headers': response_headers})
    if response.streaming:
        async with aclosing(aiter(response)) as content:
            async for part in content:
                for chunk, _ in self.chunk_bytes(part):
                    await send({'type': 'http.response.body', 'body': chunk, 'more_body': True})
        await send({'type': 'http.response.body'})
    else:
        for chunk, last in self.chunk_bytes(response.content):
            await send({'type': 'http.response.body', 'body': chunk, 'more_body': not last})

@classmethod
def chunk_bytes(cls, data):
    position = 0
    if not data:
        yield (data, True)
        return
    while position < len(data):
        yield (data[position:position + cls.chunk_size], position + cls.chunk_size >= len(data))
        position += cls.chunk_size

def load_middleware(self, is_async=False):
    self._view_middleware = []
    self._template_response_middleware = []
    self._exception_middleware = []
    get_response = self._get_response_async if is_async else self._get_response
    handler = convert_exception_to_response(get_response)
    handler_is_async = is_async
    for middleware_path in reversed(settings.MIDDLEWARE):
        middleware = import_string(middleware_path)
        middleware_can_sync = getattr(middleware, 'sync_capable', True)
        middleware_can_async = getattr(middleware, 'async_capable', False)
        if not middleware_can_sync and (not middleware_can_async):
            raise RuntimeError('Middleware %s must have at least one of sync_capable/async_capable set to True.' % middleware_path)
        elif not handler_is_async and middleware_can_sync:
            middleware_is_async = False
        else:
            middleware_is_async = middleware_can_async
        try:
            adapted_handler = self.adapt_method_mode(middleware_is_async, handler, handler_is_async, debug=settings.DEBUG, name='middleware %s' % middleware_path)
            mw_instance = middleware(adapted_handler)
        except MiddlewareNotUsed as exc:
            if settings.DEBUG:
                if str(exc):
                    logger.debug('MiddlewareNotUsed(%r): %s', middleware_path, exc)
                else:
                    logger.debug('MiddlewareNotUsed: %r', middleware_path)
            continue
        else:
            handler = adapted_handler
        if mw_instance is None:
            raise ImproperlyConfigured('Middleware factory %s returned None.' % middleware_path)
        if hasattr(mw_instance, 'process_view'):
            self._view_middleware.insert(0, self.adapt_method_mode(is_async, mw_instance.process_view))
        if hasattr(mw_instance, 'process_template_response'):
            self._template_response_middleware.append(self.adapt_method_mode(is_async, mw_instance.process_template_response))
        if hasattr(mw_instance, 'process_exception'):
            self._exception_middleware.append(self.adapt_method_mode(False, mw_instance.process_exception))
        handler = convert_exception_to_response(mw_instance)
        handler_is_async = middleware_is_async
    handler = self.adapt_method_mode(is_async, handler, handler_is_async)
    self._middleware_chain = handler

def adapt_method_mode(self, is_async, method, method_is_async=None, debug=False, name=None):
    if method_is_async is None:
        method_is_async = iscoroutinefunction(method)
    if debug and (not name):
        name = name or 'method %s()' % method.__qualname__
    if is_async:
        if not method_is_async:
            if debug:
                logger.debug('Synchronous handler adapted for %s.', name)
            return sync_to_async(method, thread_sensitive=True)
    elif method_is_async:
        if debug:
            logger.debug('Asynchronous handler adapted for %s.', name)
        return async_to_sync(method)
    return method

def _get_response(self, request):
    response = None
    callback, callback_args, callback_kwargs = self.resolve_request(request)
    for middleware_method in self._view_middleware:
        response = middleware_method(request, callback, callback_args, callback_kwargs)
        if response:
            break
    if response is None:
        wrapped_callback = self.make_view_atomic(callback)
        if iscoroutinefunction(wrapped_callback):
            wrapped_callback = async_to_sync(wrapped_callback)
        try:
            response = wrapped_callback(request, *callback_args, **callback_kwargs)
        except Exception as e:
            response = self.process_exception_by_middleware(e, request)
            if response is None:
                raise
    self.check_response(response, callback)
    if hasattr(response, 'render') and callable(response.render):
        for middleware_method in self._template_response_middleware:
            response = middleware_method(request, response)
            self.check_response(response, middleware_method, name='%s.process_template_response' % (middleware_method.__self__.__class__.__name__,))
        try:
            response = response.render()
        except Exception as e:
            response = self.process_exception_by_middleware(e, request)
            if response is None:
                raise
    return response

async def _get_response_async(self, request):
    response = None
    callback, callback_args, callback_kwargs = self.resolve_request(request)
    for middleware_method in self._view_middleware:
        response = await middleware_method(request, callback, callback_args, callback_kwargs)
        if response:
            break
    if response is None:
        wrapped_callback = self.make_view_atomic(callback)
        if not iscoroutinefunction(wrapped_callback):
            wrapped_callback = sync_to_async(wrapped_callback, thread_sensitive=True)
        try:
            response = await wrapped_callback(request, *callback_args, **callback_kwargs)
        except Exception as e:
            response = await sync_to_async(self.process_exception_by_middleware, thread_sensitive=True)(e, request)
            if response is None:
                raise
