def handle_template(self, template, subdir):
    if template is None:
        return os.path.join(django.__path__[0], 'conf', subdir)
    else:
        template = template.removeprefix('file://')
        expanded_template = os.path.expanduser(template)
        expanded_template = os.path.normpath(expanded_template)
        if os.path.isdir(expanded_template):
            return expanded_template
        if self.is_url(template):
            absolute_path = self.download(template)
        else:
            absolute_path = os.path.abspath(expanded_template)
        if os.path.exists(absolute_path):
            return self.extract(absolute_path)
    raise CommandError("couldn't handle %s template %s." % (self.app_or_project, template))

def download(self, url):

    def cleanup_url(url):
        tmp = url.rstrip('/')
        filename = tmp.split('/')[-1]
        if url.endswith('/'):
            display_url = tmp + '/'
        else:
            display_url = url
        return (filename, display_url)
    prefix = 'django_%s_template_' % self.app_or_project
    tempdir = tempfile.mkdtemp(prefix=prefix, suffix='_download')
    self.paths_to_remove.append(tempdir)
    filename, display_url = cleanup_url(url)
    if self.verbosity >= 2:
        self.stdout.write('Downloading %s' % display_url)
    the_path = os.path.join(tempdir, filename)
    opener = build_opener()
    opener.addheaders = [('User-Agent', f'Django/{django.__version__}')]
    try:
        with opener.open(url) as source, open(the_path, 'wb') as target:
            headers = source.info()
            target.write(source.read())
    except OSError as e:
        raise CommandError("couldn't download URL %s to %s: %s" % (url, filename, e))
    used_name = the_path.split('/')[-1]
    content_disposition = headers['content-disposition']
    if content_disposition:
        _, params = parse_header_parameters(content_disposition)
        guessed_filename = params.get('filename') or used_name
    else:
        guessed_filename = used_name
    ext = self.splitext(guessed_filename)[1]
    content_type = headers['content-type']
    if not ext and content_type:
        ext = mimetypes.guess_extension(content_type)
        if ext:
            guessed_filename += ext
    if used_name != guessed_filename:
        guessed_path = safe_join(tempdir, guessed_filename)
        shutil.move(the_path, guessed_path)
        return guessed_path
    return the_path

def splitext(self, the_path):
    base, ext = posixpath.splitext(the_path)
    if base.lower().endswith('.tar'):
        ext = base[-4:] + ext
        base = base[:-4]
    return (base, ext)

def extract(self, filename):
    prefix = 'django_%s_template_' % self.app_or_project
    tempdir = tempfile.mkdtemp(prefix=prefix, suffix='_extract')
    self.paths_to_remove.append(tempdir)
    if self.verbosity >= 2:
        self.stdout.write('Extracting %s' % filename)
    try:
        archive.extract(filename, tempdir)
        return tempdir
    except (archive.ArchiveException, OSError) as e:
        raise CommandError("couldn't extract file %s to %s: %s" % (filename, tempdir, e))

def is_url(self, template):
    if ':' not in template:
        return False
    scheme = template.split(':', 1)[0].lower()
    return scheme in self.url_schemes

def make_writeable(self, filename):
    if not os.access(filename, os.W_OK):
        st = os.stat(filename)
        new_permissions = stat.S_IMODE(st.st_mode) | stat.S_IWUSR
        os.chmod(filename, new_permissions)

def popen_wrapper(args, stdout_encoding='utf-8'):
    try:
        p = run(args, capture_output=True, close_fds=os.name != 'nt')
    except OSError as err:
        raise CommandError('Error executing %s' % args[0]) from err
    return (p.stdout.decode(stdout_encoding), p.stderr.decode(DEFAULT_LOCALE_ENCODING, errors='replace'), p.returncode)

def handle_extensions(extensions):
    ext_list = []
    for ext in extensions:
        ext_list.extend(ext.replace(' ', '').split(','))
    for i, ext in enumerate(ext_list):
        if not ext.startswith('.'):
            ext_list[i] = '.%s' % ext_list[i]
    return set(ext_list)

