def create_test_db(self, verbosity=1, autoclobber=False, serialize=None, keepdb=False):
    from django.core.management import call_command
    test_database_name = self._get_test_db_name()
    if verbosity >= 1:
        action = 'Creating'
        if keepdb:
            action = 'Using existing'
        self.log('%s test database for alias %s...' % (action, self._get_database_display_str(verbosity, test_database_name)))
    self._create_test_db(verbosity, autoclobber, keepdb)
    self.connection.close()
    settings.DATABASES[self.connection.alias]['NAME'] = test_database_name
    self.connection.settings_dict['NAME'] = test_database_name
    try:
        if self.connection.settings_dict['TEST']['MIGRATE'] is False:
            old_migration_modules = settings.MIGRATION_MODULES
            settings.MIGRATION_MODULES = {app.label: None for app in apps.get_app_configs()}
        call_command('migrate', verbosity=max(verbosity - 1, 0), interactive=False, database=self.connection.alias, run_syncdb=True)
    finally:
        if self.connection.settings_dict['TEST']['MIGRATE'] is False:
            settings.MIGRATION_MODULES = old_migration_modules
    if serialize is not None:
        warnings.warn('DatabaseCreation.create_test_db(serialize) is deprecated. Call DatabaseCreation.serialize_test_db() once all test databases are set up instead if you need fixtures persistence between tests.', stacklevel=2, category=RemovedInDjango70Warning)
        if serialize:
            self.connection._test_serialized_contents = self.serialize_db_to_string()
    call_command('createcachetable', database=self.connection.alias)
    self.connection.ensure_connection()
    if os.environ.get('RUNNING_DJANGOS_TEST_SUITE') == 'true':
        self.mark_expected_failures_and_skips()
    return test_database_name

def serialize_db_to_string(self):

    def get_objects():
        from django.db.migrations.loader import MigrationLoader
        loader = MigrationLoader(self.connection)
        for app_config in apps.get_app_configs():
            if app_config.models_module is not None and app_config.label in loader.migrated_apps and (app_config.name not in settings.TEST_NON_SERIALIZED_APPS):
                for model in app_config.get_models():
                    if model._meta.can_migrate(self.connection) and router.allow_migrate_model(self.connection.alias, model):
                        queryset = model._base_manager.using(self.connection.alias).order_by(model._meta.pk.name)
                        chunk_size = 2000 if queryset._prefetch_related_lookups else None
                        yield from queryset.iterator(chunk_size=chunk_size)
    out = StringIO()
    serializers.serialize('json', get_objects(), indent=None, stream=out)
    return out.getvalue()

