def get_constraints(self, cursor, table_name):
    constraints = {}
    name_query = "\n            SELECT kc.`constraint_name`, kc.`column_name`,\n                kc.`referenced_table_name`, kc.`referenced_column_name`,\n                c.`constraint_type`\n            FROM\n                information_schema.key_column_usage AS kc,\n                information_schema.table_constraints AS c\n            WHERE\n                kc.table_schema = DATABASE() AND\n                (\n                    kc.referenced_table_schema = DATABASE() OR\n                    kc.referenced_table_schema IS NULL\n                ) AND\n                c.table_schema = kc.table_schema AND\n                c.constraint_name = kc.constraint_name AND\n                c.constraint_type != 'CHECK' AND\n                kc.table_name = %s\n            ORDER BY kc.`ordinal_position`\n        "
    cursor.execute(name_query, [table_name])
    for constraint, column, ref_table, ref_column, kind in cursor.fetchall():
        if constraint not in constraints:
            constraints[constraint] = {'columns': OrderedSet(), 'primary_key': kind == 'PRIMARY KEY', 'unique': kind in {'PRIMARY KEY', 'UNIQUE'}, 'index': False, 'check': False, 'foreign_key': (ref_table, ref_column) if ref_column else None}
            if self.connection.features.supports_index_column_ordering:
                constraints[constraint]['orders'] = []
        constraints[constraint]['columns'].add(column)
    if self.connection.features.can_introspect_check_constraints:
        unnamed_constraints_index = 0
        columns = {info.name for info in self.get_table_description(cursor, table_name)}
        if self.connection.mysql_is_mariadb:
            type_query = '\n                    SELECT c.constraint_name, c.check_clause\n                    FROM information_schema.check_constraints AS c\n                    WHERE\n                        c.constraint_schema = DATABASE() AND\n                        c.table_name = %s\n                '
        else:
            type_query = "\n                    SELECT cc.constraint_name, cc.check_clause\n                    FROM\n                        information_schema.check_constraints AS cc,\n                        information_schema.table_constraints AS tc\n                    WHERE\n                        cc.constraint_schema = DATABASE() AND\n                        tc.table_schema = cc.constraint_schema AND\n                        cc.constraint_name = tc.constraint_name AND\n                        tc.constraint_type = 'CHECK' AND\n                        tc.table_name = %s\n                "
        cursor.execute(type_query, [table_name])
        for constraint, check_clause in cursor.fetchall():
            constraint_columns = self._parse_constraint_columns(check_clause, columns)
            if set(constraint_columns) == {constraint}:
                unnamed_constraints_index += 1
                constraint = '__unnamed_constraint_%s__' % unnamed_constraints_index
            constraints[constraint] = {'columns': constraint_columns, 'primary_key': False, 'unique': False, 'index': False, 'check': True, 'foreign_key': None}
    cursor.execute('SHOW INDEX FROM %s' % self.connection.ops.quote_name(table_name))
    for table, non_unique, index, colseq, column, order, type_ in [x[:6] + (x[10],) for x in cursor.fetchall()]:
        if index not in constraints:
            constraints[index] = {'columns': OrderedSet(), 'primary_key': False, 'unique': not non_unique, 'check': False, 'foreign_key': None}
            if self.connection.features.supports_index_column_ordering:
                constraints[index]['orders'] = []
        constraints[index]['index'] = True
        constraints[index]['type'] = Index.suffix if type_ == 'BTREE' else type_.lower()
        constraints[index]['columns'].add(column)
        if self.connection.features.supports_index_column_ordering:
            constraints[index]['orders'].append('DESC' if order == 'D' else 'ASC')
    for constraint in constraints.values():
        constraint['columns'] = list(constraint['columns'])
    return constraints

def _create_missing_fk_index(self, model, *, fields, expressions=None):
    first_field_name = None
    if fields:
        first_field_name = fields[0]
    elif expressions and self.connection.features.supports_expression_indexes and isinstance(expressions[0], F) and (LOOKUP_SEP not in expressions[0].name):
        first_field_name = expressions[0].name
    if not first_field_name:
        return
    first_field = model._meta.get_field(first_field_name)
    if first_field.get_internal_type() == 'ForeignKey':
        column = self.connection.introspection.identifier_converter(first_field.column)
        with self.connection.cursor() as cursor:
            constraint_names = [name for name, infodict in self.connection.introspection.get_constraints(cursor, model._meta.db_table).items() if infodict['index'] and infodict['columns'][0] == column]
        if len(constraint_names) == 1:
            self.execute(self._create_index_sql(model, fields=[first_field], suffix=''))

def _set_field_new_type(self, field, new_type):
    if field.has_db_default():
        default_sql, params = self.db_default_sql(field)
        default_sql %= tuple((self.quote_value(p) for p in params))
        new_type += f' DEFAULT {default_sql}'
    if field.null:
        new_type += ' NULL'
    else:
        new_type += ' NOT NULL'
    return new_type

def check_field_type(self, field, field_type):
    errors = []
    if field_type.startswith('varchar') and field.unique and (field.max_length is None or int(field.max_length) > 255):
        errors.append(checks.Warning('%s may not allow unique CharFields to have a max_length > 255.' % self.connection.display_name, obj=field, hint='See: https://docs.djangoproject.com/en/%s/ref/databases/#mysql-character-fields' % get_docs_version(), id='mysql.W003'))
    if field.db_index and field_type.lower() in self.connection._limited_data_types:
        errors.append(checks.Warning('%s does not support a database index on %s columns.' % (self.connection.display_name, field_type), hint="An index won't be created. Silence this warning if you don't care about it.", obj=field, id='fields.W162'))
    return errors

@staticmethod
def _output_type_handler(cursor, name, defaultType, length, precision, scale):
    if defaultType == Database.NUMBER:
        if scale == -127:
            if precision == 0:
                outconverter = FormatStylePlaceholderCursor._output_number_converter
            else:
                outconverter = float
        elif precision > 0:
            outconverter = FormatStylePlaceholderCursor._get_decimal_converter(precision, scale)
        else:
            outconverter = FormatStylePlaceholderCursor._output_number_converter
        return cursor.var(Database.STRING, size=255, arraysize=cursor.arraysize, outconverter=outconverter)
    elif defaultType == Database.DB_TYPE_NCLOB:
        return cursor.var(Database.DB_TYPE_NCLOB, arraysize=cursor.arraysize)

@cached_property
def _maindb_connection(self):
    settings_dict = settings.DATABASES[self.connection.alias]
    user = settings_dict.get('SAVED_USER') or settings_dict['USER']
    password = settings_dict.get('SAVED_PASSWORD') or settings_dict['PASSWORD']
    settings_dict = {**settings_dict, 'USER': user, 'PASSWORD': password}
    DatabaseWrapper = type(self.connection)
    return DatabaseWrapper(settings_dict, alias=self.connection.alias)

def set_as_test_mirror(self, primary_settings_dict):
    self.connection.settings_dict['USER'] = primary_settings_dict['USER']
    self.connection.settings_dict['PASSWORD'] = primary_settings_dict['PASSWORD']

def _destroy_test_db(self, test_database_name, verbosity=1):
    if not self.connection.is_pool:
        self.connection.settings_dict['USER'] = self.connection.settings_dict['SAVED_USER']
        self.connection.settings_dict['PASSWORD'] = self.connection.settings_dict['SAVED_PASSWORD']
    self.connection.close()
    self.connection.close_pool()
    parameters = self._get_test_db_params()
    with self._maindb_connection.cursor() as cursor:
        if self._test_user_create():
            if verbosity >= 1:
                self.log('Destroying test user...')
            self._destroy_test_user(cursor, parameters, verbosity)
        if self._test_database_create():
            if verbosity >= 1:
                self.log('Destroying test database tables...')
            self._execute_test_db_destruction(cursor, parameters, verbosity)
    self._maindb_connection.close()
    self._maindb_connection.close_pool()

def _execute_allow_fail_statements(self, cursor, statements, parameters, verbosity, acceptable_ora_err):
    try:
        allow_quiet_fail = acceptable_ora_err is not None and len(acceptable_ora_err) > 0
        self._execute_statements(cursor, statements, parameters, verbosity, allow_quiet_fail=allow_quiet_fail)
        return True
    except DatabaseError as err:
        description = str(err)
        if acceptable_ora_err is None or acceptable_ora_err not in description:
            raise
        return False

def _test_settings_get(self, key, default=None, prefixed=None):
    settings_dict = self.connection.settings_dict
    val = settings_dict['TEST'].get(key, default)
    if val is None and prefixed:
        val = TEST_DATABASE_PREFIX + settings_dict[prefixed]
    return val

