def get_constraints(self, cursor, table_name):
    constraints = {}
    try:
        table_schema = cursor.execute("SELECT sql FROM sqlite_master WHERE type='table' and name=%s", [table_name]).fetchone()[0]
    except TypeError:
        pass
    else:
        columns = {info.name for info in self.get_table_description(cursor, table_name)}
        constraints.update(self._parse_table_constraints(table_schema, columns))
    cursor.execute('PRAGMA index_list(%s)' % self.connection.ops.quote_name(table_name))
    for row in cursor.fetchall():
        number, index, unique = row[:3]
        cursor.execute("SELECT sql FROM sqlite_master WHERE type='index' AND name=%s", [index])
        sql, = cursor.fetchone() or (None,)
        if not sql:
            continue
        cursor.execute('PRAGMA index_info(%s)' % self.connection.ops.quote_name(index))
        for index_rank, column_rank, column in cursor.fetchall():
            if index not in constraints:
                constraints[index] = {'columns': [], 'primary_key': False, 'unique': bool(unique), 'foreign_key': None, 'check': False, 'index': True}
            constraints[index]['columns'].append(column)
        if constraints[index]['index']:
            constraints[index]['type'] = Index.suffix
            orders = self._get_index_columns_orders(sql)
            if orders is not None:
                constraints[index]['orders'] = orders
    pk_columns = self.get_primary_key_columns(cursor, table_name)
    if pk_columns:
        constraints['__primary__'] = {'columns': pk_columns, 'primary_key': True, 'unique': False, 'foreign_key': None, 'check': False, 'index': False}
    relations = enumerate(self.get_relations(cursor, table_name).items())
    constraints.update({f'fk_{index}': {'columns': [column_name], 'primary_key': False, 'unique': False, 'foreign_key': (ref_table_name, ref_column_name), 'check': False, 'index': False} for index, (column_name, (ref_column_name, ref_table_name, _)) in relations})
    return constraints

def _remake_table(self, model, create_field=None, delete_field=None, alter_fields=None):

    def is_self_referential(f):
        return f.is_relation and f.remote_field.model is model
    body = {f.name: f.clone() if is_self_referential(f) else f for f in model._meta.local_concrete_fields}
    pk = model._meta.pk
    if isinstance(pk, CompositePrimaryKey):
        body[pk.name] = pk.clone()
    mapping = {f.column: self.quote_name(f.column) for f in model._meta.local_concrete_fields if f.generated is False}
    rename_mapping = {}
    restore_pk_field = None
    alter_fields = alter_fields or []
    if getattr(create_field, 'primary_key', False) or any((getattr(new_field, 'primary_key', False) for _, new_field in alter_fields)):
        for name, field in list(body.items()):
            if field.primary_key and (not any((name == new_field.name for _, new_field in alter_fields))):
                field.primary_key = False
                restore_pk_field = field
                if field.auto_created:
                    del body[name]
                    del mapping[field.column]
    if create_field:
        body[create_field.name] = create_field
        if not create_field.has_db_default() and (not create_field.generated) and create_field.concrete:
            mapping[create_field.column] = self.prepare_default(self.effective_default(create_field))
    for alter_field in alter_fields:
        old_field, new_field = alter_field
        body.pop(old_field.name, None)
        mapping.pop(old_field.column, None)
        body[new_field.name] = new_field
        rename_mapping[old_field.name] = new_field.name
        if new_field.generated:
            continue
        if old_field.null and (not new_field.null):
            if not new_field.has_db_default():
                default = self.prepare_default(self.effective_default(new_field))
            else:
                default, _ = self.db_default_sql(new_field)
            case_sql = 'coalesce(%(col)s, %(default)s)' % {'col': self.quote_name(old_field.column), 'default': default}
            mapping[new_field.column] = case_sql
        else:
            mapping[new_field.column] = self.quote_name(old_field.column)
    if delete_field:
        del body[delete_field.name]
        mapping.pop(delete_field.column, None)
        if delete_field.many_to_many and delete_field.remote_field.through._meta.auto_created:
            return self.delete_model(delete_field.remote_field.through)
    apps = Apps()
    unique_together = [[rename_mapping.get(n, n) for n in unique] for unique in model._meta.unique_together]
    indexes = model._meta.indexes
    if delete_field:
        indexes = [index for index in indexes if delete_field.name not in index.fields]
    constraints = list(model._meta.constraints)
    body_copy = copy.deepcopy(body)
    meta_contents = {'app_label': model._meta.app_label, 'db_table': model._meta.db_table, 'unique_together': unique_together, 'indexes': indexes, 'constraints': constraints, 'apps': apps}
    meta = type('Meta', (), meta_contents)
    body_copy['Meta'] = meta
    body_copy['__module__'] = model.__module__
    type(model._meta.object_name, model.__bases__, body_copy)
    body_copy = copy.deepcopy(body)
    meta_contents = {'app_label': model._meta.app_label, 'db_table': 'new__%s' % strip_quotes(model._meta.db_table), 'unique_together': unique_together, 'indexes': indexes, 'constraints': constraints, 'apps': apps}
    meta = type('Meta', (), meta_contents)
    body_copy['Meta'] = meta
    body_copy['__module__'] = model.__module__
    new_model = type('New%s' % model._meta.object_name, model.__bases__, body_copy)
    if delete_field and delete_field.attname == new_model._meta.pk.attname:
        auto_pk = new_model._meta.pk
        delattr(new_model, auto_pk.attname)
        new_model._meta.local_fields.remove(auto_pk)
        new_model.pk = None
    self.create_model(new_model)
    self.execute('INSERT INTO %s (%s) SELECT %s FROM %s' % (self.quote_name(new_model._meta.db_table), ', '.join((self.quote_name(x) for x in mapping)), ', '.join(mapping.values()), self.quote_name(model._meta.db_table)))
    self.delete_model(model, handle_autom2m=False)
    self.alter_db_table(new_model, new_model._meta.db_table, model._meta.db_table)
    for sql in self.deferred_sql:
        self.execute(sql)
    self.deferred_sql = []
    if restore_pk_field:
        restore_pk_field.primary_key = True

def add_field(self, model, field):
    from django.db.models.expressions import Value
    if field.many_to_many and field.remote_field.through._meta.auto_created:
        self.create_model(field.remote_field.through)
    elif isinstance(field, CompositePrimaryKey):
        return
    elif field.primary_key or field.unique or (not field.null) or (self.effective_default(field) is not None) or (field.has_db_default() and (not isinstance(field.db_default, Value))):
        self._remake_table(model, create_field=field)
    else:
        super().add_field(model, field)

def remove_field(self, model, field):
    if field.many_to_many:
        if field.remote_field.through._meta.auto_created:
            self.delete_model(field.remote_field.through)
    elif not field.primary_key and (not field.unique) and (not field.db_index) and (not (field.remote_field and field.db_constraint)):
        super().remove_field(model, field)
    else:
        if field.db_parameters(connection=self.connection)['type'] is None:
            return
        self._remake_table(model, delete_field=field)

def _alter_field(self, model, old_field, new_field, old_type, new_type, old_db_params, new_db_params, strict=False):
    if old_field.column != new_field.column and self.column_sql(model, old_field) == self.column_sql(model, new_field) and (not (old_field.remote_field and old_field.db_constraint or (new_field.remote_field and new_field.db_constraint))):
        return self.execute(self._rename_field_sql(model._meta.db_table, old_field, new_field, new_type))
    self._remake_table(model, alter_fields=[(old_field, new_field)])
    old_collation = old_db_params.get('collation')
    new_collation = new_db_params.get('collation')
    if new_field.unique and (old_type != new_type or old_collation != new_collation):
        related_models = {rel.related_model for _, rel in _related_non_m2m_objects(old_field, new_field) if rel.related_model != model}
        opts = new_field.model._meta
        if new_field.primary_key:
            for many_to_many in opts.many_to_many:
                if many_to_many.related_model == model:
                    continue
                if many_to_many.remote_field.through._meta.auto_created:
                    related_models.add(many_to_many.remote_field.through)
        for related_model in related_models:
            self._remake_table(related_model)

def _sqlite_format_dtdelta(connector, lhs, rhs):
    if connector is None or lhs is None or rhs is None:
        return None
    connector = connector.strip()
    try:
        real_lhs = _sqlite_prepare_dtdelta_param(connector, lhs)
        real_rhs = _sqlite_prepare_dtdelta_param(connector, rhs)
    except (ValueError, TypeError):
        return None
    if connector == '+':
        out = str(real_lhs + real_rhs)
    elif connector == '-':
        out = str(real_lhs - real_rhs)
    elif connector == '*':
        out = real_lhs * real_rhs
    else:
        out = real_lhs / real_rhs
    return out

def _prepare(cls):
    opts = cls._meta
    opts._prepare(cls)
    if opts.order_with_respect_to:
        cls.get_next_in_order = partialmethod(cls._get_next_or_previous_in_order, is_next=True)
        cls.get_previous_in_order = partialmethod(cls._get_next_or_previous_in_order, is_next=False)
        if opts.order_with_respect_to.remote_field:
            wrt = opts.order_with_respect_to
            remote = wrt.remote_field.model
            lazy_related_operation(make_foreign_order_accessors, cls, remote)
    if cls.__doc__ is None:
        cls.__doc__ = '%s(%s)' % (cls.__name__, ', '.join((f.name for f in opts.fields)))
    get_absolute_url_override = settings.ABSOLUTE_URL_OVERRIDES.get(opts.label_lower)
    if get_absolute_url_override:
        setattr(cls, 'get_absolute_url', get_absolute_url_override)
    if not opts.managers:
        if any((f.name == 'objects' for f in opts.fields)):
            raise ValueError("Model %s must specify a custom Manager, because it has a field named 'objects'." % cls.__name__)
        manager = Manager()
        manager.auto_created = True
        cls.add_to_class('objects', manager)
    for index in cls._meta.indexes:
        if not index.name:
            index.set_name_with_model(cls)
    class_prepared.send(sender=cls)

def __getstate__(self):
    state = self.__dict__.copy()
    state['_state'] = copy.copy(state['_state'])
    state['_state'].fields_cache = state['_state'].fields_cache.copy()
    _memoryview_attrs = []
    for attr, value in state.items():
        if isinstance(value, memoryview):
            _memoryview_attrs.append((attr, bytes(value)))
    if _memoryview_attrs:
        state['_memoryview_attrs'] = _memoryview_attrs
        for attr, value in _memoryview_attrs:
            state.pop(attr)
    return state

def refresh_from_db(self, using=None, fields=None, from_queryset=None):
    if fields is None:
        self._prefetched_objects_cache = {}
    else:
        prefetched_objects_cache = getattr(self, '_prefetched_objects_cache', ())
        fields = set(fields)
        for field in fields.copy():
            if field in prefetched_objects_cache:
                del prefetched_objects_cache[field]
                fields.remove(field)
        if not fields:
            return
        if any((LOOKUP_SEP in f for f in fields)):
            raise ValueError('Found "%s" in fields argument. Relations and transforms are not allowed in fields.' % LOOKUP_SEP)
    if from_queryset is None:
        hints = {'instance': self}
        from_queryset = self.__class__._base_manager.db_manager(using, hints=hints)
    elif using is not None:
        from_queryset = from_queryset.using(using)
    db_instance_qs = from_queryset.filter(pk=self.pk)
    deferred_fields = self.get_deferred_fields()
    if fields is not None:
        db_instance_qs = db_instance_qs.only(*fields)
    elif deferred_fields:
        db_instance_qs = db_instance_qs.only(*{f.attname for f in self._meta.concrete_fields if f.attname not in deferred_fields})
    db_instance = db_instance_qs.get()
    non_loaded_fields = db_instance.get_deferred_fields()
    for field in self._meta.fields:
        if field.attname in non_loaded_fields:
            continue
        if field.concrete:
            setattr(self, field.attname, getattr(db_instance, field.attname))
        if field.is_relation:
            if field.is_cached(db_instance):
                field.set_cached_value(self, field.get_cached_value(db_instance))
            elif field.is_cached(self):
                field.delete_cached_value(self)
    for rel in self._meta.related_objects:
        if (fields is None or rel.name in fields) and rel.is_cached(self):
            rel.delete_cached_value(self)
    for field in self._meta.private_fields:
        if (fields is None or field.name in fields) and field.is_relation and field.is_cached(self):
            field.delete_cached_value(self)
    self._state.db = db_instance._state.db

def serializable_value(self, field_name):
    try:
        field = self._meta.get_field(field_name)
    except FieldDoesNotExist:
        return getattr(self, field_name)
    return getattr(self, field.attname)

def save(self, *, force_insert=False, force_update=False, using=None, update_fields=None):
    self._prepare_related_fields_for_save(operation_name='save')
    using = using or router.db_for_write(self.__class__, instance=self)
    if force_insert and (force_update or update_fields):
        raise ValueError('Cannot force both insert and updating in model saving.')
    deferred_non_generated_fields = {f.attname for f in self._meta.concrete_fields if f.attname not in self.__dict__ and f.generated is False}
    if update_fields is not None:
        if not update_fields:
            return
        update_fields = frozenset(update_fields)
        field_names = self._meta._non_pk_concrete_field_names
        not_updatable_fields = update_fields.difference(field_names)
        if not_updatable_fields:
            raise ValueError('The following fields do not exist in this model, are m2m fields, primary keys, or are non-concrete fields: %s' % ', '.join(not_updatable_fields))
    elif not force_insert and deferred_non_generated_fields and (using == self._state.db) and self._is_pk_set():
        field_names = set()
        pk_fields = self._meta.pk_fields
        for field in self._meta.concrete_fields:
            if field not in pk_fields and (not hasattr(field, 'through')):
                field_names.add(field.attname)
        loaded_fields = field_names.difference(deferred_non_generated_fields)
        if loaded_fields:
            update_fields = frozenset(loaded_fields)
    self.save_base(using=using, force_insert=force_insert, force_update=force_update, update_fields=update_fields)

def save_base(self, raw=False, force_insert=False, force_update=False, using=None, update_fields=None):
    using = using or router.db_for_write(self.__class__, instance=self)
    assert not (force_insert and (force_update or update_fields))
    assert update_fields is None or update_fields
    cls = origin = self.__class__
    if cls._meta.proxy:
        cls = cls._meta.concrete_model
    meta = cls._meta
    if not meta.auto_created:
        pre_save.send(sender=origin, instance=self, raw=raw, using=using, update_fields=update_fields)
    if meta.parents:
        context_manager = transaction.atomic(using=using, savepoint=False)
    else:
        context_manager = transaction.mark_for_rollback_on_error(using=using)
    with context_manager:
        parent_inserted = False
        if not raw:
            force_insert = self._validate_force_insert(force_insert)
            parent_inserted = self._save_parents(cls, using, update_fields, force_insert)
        updated = self._save_table(raw, cls, force_insert or parent_inserted, force_update, using, update_fields)
    self._state.db = using
    self._state.adding = False
    if not meta.auto_created:
        post_save.send(sender=origin, instance=self, created=not updated, update_fields=update_fields, raw=raw, using=using)

def _save_parents(self, cls, using, update_fields, force_insert, updated_parents=None):
    meta = cls._meta
    inserted = False
    if updated_parents is None:
        updated_parents = {}
    for parent, field in meta.parents.items():
        if field and getattr(self, parent._meta.pk.attname) is None and (getattr(self, field.attname) is not None):
            setattr(self, parent._meta.pk.attname, getattr(self, field.attname))
        if (parent_updated := updated_parents.get(parent)) is None:
            parent_inserted = self._save_parents(cls=parent, using=using, update_fields=update_fields, force_insert=force_insert, updated_parents=updated_parents)
            updated = self._save_table(cls=parent, using=using, update_fields=update_fields, force_insert=parent_inserted or issubclass(parent, force_insert))
            if not updated:
                inserted = True
            updated_parents[parent] = updated
        elif not parent_updated:
            inserted = True
        if field:
            setattr(self, field.attname, self._get_pk_val(parent._meta))
            if field.is_cached(self):
                field.delete_cached_value(self)
    return inserted

def _save_table(self, raw=False, cls=None, force_insert=False, force_update=False, using=None, update_fields=None):
    meta = cls._meta
    pk_fields = meta.pk_fields
    non_pks_non_generated = [f for f in meta.local_concrete_fields if f not in pk_fields and (not f.generated)]
    if update_fields:
        non_pks_non_generated = [f for f in non_pks_non_generated if f.name in update_fields or f.attname in update_fields]
    if not self._is_pk_set(meta):
        pk_val = meta.pk.get_pk_value_on_save(self)
        setattr(self, meta.pk.attname, pk_val)
    pk_set = self._is_pk_set(meta)
    if not pk_set and (force_update or update_fields):
        raise ValueError('Cannot force an update in save() with no primary key.')
    updated = False
    if not raw and (not force_insert) and (not force_update) and self._state.adding and all((f.has_default() or f.has_db_default() for f in meta.pk_fields)):
        force_insert = True
    if pk_set and (not force_insert):
        base_qs = cls._base_manager.using(using)
        values = [(f, None, getattr(self, f.attname) if raw else f.pre_save(self, False)) for f in non_pks_non_generated]
        forced_update = update_fields or force_update
        pk_val = self._get_pk_val(meta)
        returning_fields = [f for f in meta.local_concrete_fields if f.generated and f.referenced_fields.intersection(non_pks_non_generated)]
        for field, _model, value in values:
            if (update_fields is None or field.name in update_fields) and hasattr(value, 'resolve_expression'):
                returning_fields.append(field)
        results = self._do_update(base_qs, using, pk_val, values, update_fields, forced_update, returning_fields)
        if (updated := bool(results)):
            self._assign_returned_values(results[0], returning_fields)
        elif force_update:
            raise self.NotUpdated('Forced update did not affect any rows.')
        elif update_fields:
            raise self.NotUpdated('Save with update_fields did not affect any rows.')
    if not updated:
        if meta.order_with_respect_to:
            field = meta.order_with_respect_to
            filter_args = field.get_filter_kwargs_for_object(self)
            self._order = cls._base_manager.using(using).filter(**filter_args).aggregate(_order__max=Coalesce(ExpressionWrapper(Max('_order') + Value(1), output_field=IntegerField()), Value(0)))['_order__max']
        insert_fields = [f for f in meta.local_concrete_fields if not f.generated and (pk_set or f is not meta.auto_field)]
        returning_fields = list(meta.db_returning_fields)
        can_return_columns_from_insert = connections[using].features.can_return_columns_from_insert
        for field in insert_fields:
            value = getattr(self, field.attname) if raw else field.pre_save(self, add=True)
            if hasattr(value, 'resolve_expression'):
                if field not in returning_fields:
                    returning_fields.append(field)
            elif field.db_returning and (not can_return_columns_from_insert) and (not (pk_set and field is meta.auto_field)):
                returning_fields.remove(field)
        results = self._do_insert(cls._base_manager, using, insert_fields, returning_fields, raw)
        if results:
            self._assign_returned_values(results[0], returning_fields)
    return updated

def _do_update(self, base_qs, using, pk_val, values, update_fields, forced_update, returning_fields):
    filtered = base_qs.filter(pk=pk_val)
    if not values:
        if update_fields is not None or filtered.exists():
            return [()]
        return []
    if self._meta.select_on_save and (not forced_update):
        if not filtered.exists():
            return []
        if (results := filtered._update(values, returning_fields)):
            return results
        return [()] if filtered.exists() else []
    return filtered._update(values, returning_fields)

def validate_unique(self, exclude=None):
    unique_checks, date_checks = self._get_unique_checks(exclude=exclude)
    errors = self._perform_unique_checks(unique_checks)
    date_errors = self._perform_date_checks(date_checks)
    for k, v in date_errors.items():
        errors.setdefault(k, []).extend(v)
    if errors:
        raise ValidationError(errors)

def _get_unique_checks(self, exclude=None, include_meta_constraints=False):
    if exclude is None:
        exclude = set()
    unique_checks = []
    unique_togethers = [(self.__class__, self._meta.unique_together)]
    constraints = []
    if include_meta_constraints:
        constraints = [(self.__class__, self._meta.total_unique_constraints)]
    for parent_class in self._meta.all_parents:
        if parent_class._meta.unique_together:
            unique_togethers.append((parent_class, parent_class._meta.unique_together))
        if include_meta_constraints and parent_class._meta.total_unique_constraints:
            constraints.append((parent_class, parent_class._meta.total_unique_constraints))
    for model_class, unique_together in unique_togethers:
        for check in unique_together:
            if not any((name in exclude for name in check)):
                unique_checks.append((model_class, tuple(check)))
    if include_meta_constraints:
        for model_class, model_constraints in constraints:
            for constraint in model_constraints:
                if not any((name in exclude for name in constraint.fields)):
                    unique_checks.append((model_class, constraint.fields))
    date_checks = []
    fields_with_class = [(self.__class__, self._meta.local_fields)]
    for parent_class in self._meta.all_parents:
        fields_with_class.append((parent_class, parent_class._meta.local_fields))
    for model_class, fields in fields_with_class:
        for f in fields:
            name = f.name
            if name in exclude:
                continue
            if isinstance(f, CompositePrimaryKey):
                names = tuple((field.name for field in f.fields))
                if exclude.isdisjoint(names):
                    unique_checks.append((model_class, names))
                continue
            if f.unique:
                unique_checks.append((model_class, (name,)))
            if f.unique_for_date and f.unique_for_date not in exclude:
                date_checks.append((model_class, 'date', name, f.unique_for_date))
            if f.unique_for_year and f.unique_for_year not in exclude:
                date_checks.append((model_class, 'year', name, f.unique_for_year))
            if f.unique_for_month and f.unique_for_month not in exclude:
                date_checks.append((model_class, 'month', name, f.unique_for_month))
    return (unique_checks, date_checks)

def full_clean(self, exclude=None, validate_unique=True, validate_constraints=True):
    errors = {}
    if exclude is None:
        exclude = set()
    else:
        exclude = set(exclude)
    try:
        self.clean_fields(exclude=exclude)
    except ValidationError as e:
        errors = e.update_error_dict(errors)
    try:
        self.clean()
    except ValidationError as e:
        errors = e.update_error_dict(errors)
    if validate_unique:
        for name in errors:
            if name != NON_FIELD_ERRORS and name not in exclude:
                exclude.add(name)
        try:
            self.validate_unique(exclude=exclude)
        except ValidationError as e:
            errors = e.update_error_dict(errors)
    if validate_constraints:
        for name in errors:
            if name != NON_FIELD_ERRORS and name not in exclude:
                exclude.add(name)
        try:
            self.validate_constraints(exclude=exclude)
        except ValidationError as e:
            errors = e.update_error_dict(errors)
    if errors:
        raise ValidationError(errors)

def clean_fields(self, exclude=None):
    if exclude is None:
        exclude = set()
    errors = {}
    for f in self._meta.fields:
        if f.name in exclude or f.generated:
            continue
        raw_value = getattr(self, f.attname)
        if f.blank and raw_value in f.empty_values:
            continue
        if isinstance(raw_value, DatabaseDefault):
            continue
        try:
            setattr(self, f.attname, f.clean(raw_value, self))
        except ValidationError as e:
            errors[f.name] = e.error_list
    if errors:
        raise ValidationError(errors)

@classmethod
def _check_swappable(cls):
    errors = []
    if cls._meta.swapped:
        try:
            apps.get_model(cls._meta.swapped)
        except ValueError:
            errors.append(checks.Error("'%s' is not of the form 'app_label.app_name'." % cls._meta.swappable, id='models.E001'))
        except LookupError:
            app_label, model_name = cls._meta.swapped.split('.')
            errors.append(checks.Error("'%s' references '%s.%s', which has not been installed, or is abstract." % (cls._meta.swappable, app_label, model_name), id='models.E002'))
    return errors

@classmethod
def _check_managers(cls, **kwargs):
    errors = []
    for manager in cls._meta.managers:
        errors.extend(manager.check(**kwargs))
    return errors

@classmethod
def _check_fields(cls, **kwargs):
    errors = []
    for field in cls._meta.local_fields:
        errors.extend(field.check(**kwargs))
    for field in cls._meta.local_many_to_many:
        errors.extend(field.check(from_model=cls, **kwargs))
    return errors

@classmethod
def _check_m2m_through_same_relationship(cls):
    errors = []
    seen_intermediary_signatures = []
    fields = cls._meta.local_many_to_many
    fields = (f for f in fields if isinstance(f.remote_field.model, ModelBase))
    fields = (f for f in fields if isinstance(f.remote_field.through, ModelBase))
    for f in fields:
        signature = (f.remote_field.model, cls, f.remote_field.through, f.remote_field.through_fields)
        if signature in seen_intermediary_signatures:
            errors.append(checks.Error("The model has two identical many-to-many relations through the intermediate model '%s'." % f.remote_field.through._meta.label, obj=cls, id='models.E003'))
        else:
            seen_intermediary_signatures.append(signature)
    return errors

@classmethod
def _check_id_field(cls):
    fields = [f for f in cls._meta.local_fields if f.name == 'id' and f != cls._meta.pk]
    if fields and (not fields[0].primary_key) and (cls._meta.pk.name == 'id'):
        return [checks.Error("'id' can only be used as a field name if the field also sets 'primary_key=True'.", obj=cls, id='models.E004')]
    else:
        return []

@classmethod
def _check_field_name_clashes(cls):
    errors = []
    used_fields = {}
    for parent in cls._meta.all_parents:
        for f in parent._meta.local_fields:
            clash = used_fields.get(f.name) or used_fields.get(f.attname) or None
            if clash:
                errors.append(checks.Error("The field '%s' from parent model '%s' clashes with the field '%s' from parent model '%s'." % (clash.name, clash.model._meta, f.name, f.model._meta), obj=cls, id='models.E005'))
            used_fields[f.name] = f
            used_fields[f.attname] = f
    for parent in cls._meta.all_parents:
        for f in parent._meta.get_fields():
            if f not in used_fields:
                used_fields[f.name] = f
    for parent_link in cls._meta.parents.values():
        if not parent_link:
            continue
        clash = used_fields.get(parent_link.name) or None
        if clash:
            errors.append(checks.Error(f"The field '{parent_link.name}' clashes with the field '{clash.name}' from model '{clash.model._meta}'.", obj=cls, id='models.E006'))
    for f in cls._meta.local_fields:
        clash = used_fields.get(f.name) or used_fields.get(f.attname) or None
        id_conflict = f.name == 'id' and clash and (clash.name == 'id') and (clash.model == cls)
        if clash and (not id_conflict):
            errors.append(checks.Error("The field '%s' clashes with the field '%s' from model '%s'." % (f.name, clash.name, clash.model._meta), obj=f, id='models.E006'))
        used_fields[f.name] = f
        used_fields[f.attname] = f
    return errors

@classmethod
def _check_unique_together(cls):
    if not isinstance(cls._meta.unique_together, (tuple, list)):
        return [checks.Error("'unique_together' must be a list or tuple.", obj=cls, id='models.E010')]
    elif any((not isinstance(fields, (tuple, list)) for fields in cls._meta.unique_together)):
        return [checks.Error("All 'unique_together' elements must be lists or tuples.", obj=cls, id='models.E011')]
    else:
        errors = []
        for fields in cls._meta.unique_together:
            errors.extend(cls._check_local_fields(fields, 'unique_together'))
        return errors

@classmethod
def _check_ordering(cls):
    if cls._meta._ordering_clash:
        return [checks.Error("'ordering' and 'order_with_respect_to' cannot be used together.", obj=cls, id='models.E021')]
    if cls._meta.order_with_respect_to or not cls._meta.ordering:
        return []
    if not isinstance(cls._meta.ordering, (list, tuple)):
        return [checks.Error("'ordering' must be a tuple or list (even if you want to order by only one field).", obj=cls, id='models.E014')]
    errors = []
    fields = cls._meta.ordering
    fields = (f for f in fields if isinstance(f, str) and f != '?')
    fields = (f.removeprefix('-') for f in fields)
    _fields = []
    related_fields = []
    for f in fields:
        if LOOKUP_SEP in f:
            related_fields.append(f)
        else:
            _fields.append(f)
    fields = _fields
    for field in related_fields:
        _cls = cls
        fld = None
        for part in field.split(LOOKUP_SEP):
            try:
                if part == 'pk':
                    fld = _cls._meta.pk
                else:
                    fld = _cls._meta.get_field(part)
                if fld.is_relation:
                    _cls = fld.path_infos[-1].to_opts.model
                else:
                    _cls = None
            except (FieldDoesNotExist, AttributeError):
                if fld is None or (fld.get_transform(part) is None and fld.get_lookup(part) is None):
                    errors.append(checks.Error("'ordering' refers to the nonexistent field, related field, or lookup '%s'." % field, obj=cls, id='models.E015'))
    fields = {f for f in fields if f != 'pk'}
    invalid_fields = []
    opts = cls._meta
    valid_fields = set(chain.from_iterable(((f.name, f.attname) if not (f.auto_created and (not f.concrete)) else (f.field.related_query_name(),) for f in chain(opts.fields, opts.related_objects))))
    invalid_fields.extend(fields - valid_fields)
    for invalid_field in invalid_fields:
        errors.append(checks.Error("'ordering' refers to the nonexistent field, related field, or lookup '%s'." % invalid_field, obj=cls, id='models.E015'))
    return errors

@classmethod
def _check_long_column_names(cls, databases):
    if not databases:
        return []
    errors = []
    allowed_len = None
    db_alias = None
    for db in databases:
        if not router.allow_migrate_model(db, cls):
            continue
        connection = connections[db]
        max_name_length = connection.ops.max_name_length()
        if max_name_length is None or connection.features.truncates_names:
            continue
        elif allowed_len is None:
            allowed_len = max_name_length
            db_alias = db
        elif max_name_length < allowed_len:
            allowed_len = max_name_length
            db_alias = db
    if allowed_len is None:
        return errors
    for f in cls._meta.local_fields:
        if f.db_column is None and (column_name := f.column) is not None and (len(column_name) > allowed_len):
            errors.append(checks.Error('Autogenerated column name too long for field "%s". Maximum length is "%s" for database "%s".' % (column_name, allowed_len, db_alias), hint="Set the column name manually using 'db_column'.", obj=cls, id='models.E018'))
    for f in cls._meta.local_many_to_many:
        if isinstance(f.remote_field.through, str):
            continue
        for m2m in f.remote_field.through._meta.local_fields:
            if m2m.db_column is None and (rel_name := m2m.column) is not None and (len(rel_name) > allowed_len):
                errors.append(checks.Error('Autogenerated column name too long for M2M field "%s". Maximum length is "%s" for database "%s".' % (rel_name, allowed_len, db_alias), hint="Use 'through' to create a separate model for M2M and then set column_name using 'db_column'.", obj=cls, id='models.E019'))
    return errors

def model_unpickle(model_id):
    if isinstance(model_id, tuple):
        model = apps.get_model(*model_id)
    else:
        model = model_id
    return model.__new__(model)

def add(self, objs, source=None, nullable=False, reverse_dependency=False):
    if not objs:
        return []
    new_objs = []
    model = objs[0].__class__
    instances = self.data[model]
    for obj in objs:
        if obj not in instances:
            new_objs.append(obj)
    instances.update(new_objs)
    if source is not None and (not nullable):
        self.add_dependency(source, model, reverse_dependency=reverse_dependency)
    return new_objs

def can_fast_delete(self, objs, from_field=None):
    if self.force_collection:
        return False
    if from_field and from_field.remote_field.on_delete is not CASCADE:
        return False
    if hasattr(objs, '_meta'):
        model = objs._meta.model
    elif hasattr(objs, 'model') and hasattr(objs, '_raw_delete'):
        model = objs.model
    else:
        return False
    if self._has_signal_listeners(model):
        return False
    opts = model._meta
    return all((link == from_field for link in opts.concrete_model._meta.parents.values())) and all((related.field.remote_field.on_delete in SKIP_COLLECTION for related in get_candidate_relations_to_delete(opts))) and (not any((hasattr(field, 'bulk_related_objects') for field in opts.private_fields)))

def get_del_batches(self, objs, fields):
    conn_batch_size = max(connections[self.using].ops.bulk_batch_size(fields, objs), 1)
    if len(objs) > conn_batch_size:
        return [objs[i:i + conn_batch_size] for i in range(0, len(objs), conn_batch_size)]
    else:
        return [objs]

def collect(self, objs, source=None, nullable=False, collect_related=True, source_attr=None, reverse_dependency=False, keep_parents=False, fail_on_restricted=True):
    if self.can_fast_delete(objs):
        self.fast_deletes.append(objs)
        return
    new_objs = self.add(objs, source, nullable, reverse_dependency=reverse_dependency)
    if not new_objs:
        return
    model = new_objs[0].__class__
    if not keep_parents:
        concrete_model = model._meta.concrete_model
        for ptr in concrete_model._meta.parents.values():
            if ptr:
                parent_objs = [getattr(obj, ptr.name) for obj in new_objs]
                self.collect(parent_objs, source=model, source_attr=ptr.remote_field.related_name, collect_related=False, reverse_dependency=True, fail_on_restricted=False)
    if not collect_related:
        return
    model_fast_deletes = defaultdict(list)
    protected_objects = defaultdict(list)
    for related in get_candidate_relations_to_delete(model._meta):
        if keep_parents and related.model._meta.concrete_model in model._meta.all_parents:
            continue
        field = related.field
        on_delete = field.remote_field.on_delete
        if on_delete in SKIP_COLLECTION:
            if self.force_collection and (forced_on_delete := getattr(on_delete, 'forced_collector', None)):
                on_delete = forced_on_delete
            else:
                continue
        related_model = related.related_model
        if self.can_fast_delete(related_model, from_field=field):
            model_fast_deletes[related_model].append(field)
            continue
        batches = self.get_del_batches(new_objs, [field])
        for batch in batches:
            sub_objs = self.related_objects(related_model, [field], batch)
            if not (sub_objs.query.select_related or self._has_signal_listeners(related_model)):
                referenced_fields = set(chain.from_iterable(((rf.attname for rf in rel.field.foreign_related_fields) for rel in get_candidate_relations_to_delete(related_model._meta))))
                sub_objs = sub_objs.only(*tuple(referenced_fields))
            if getattr(on_delete, 'lazy_sub_objs', False) or sub_objs:
                try:
                    on_delete(self, field, sub_objs, self.using)
                except ProtectedError as error:
                    key = "'%s.%s'" % (field.model.__name__, field.name)
                    protected_objects[key] += error.protected_objects
    if protected_objects:
        raise ProtectedError('Cannot delete some instances of model %r because they are referenced through protected foreign keys: %s.' % (model.__name__, ', '.join(protected_objects)), set(chain.from_iterable(protected_objects.values())))
    for related_model, related_fields in model_fast_deletes.items():
        batches = self.get_del_batches(new_objs, related_fields)
        for batch in batches:
            sub_objs = self.related_objects(related_model, related_fields, batch)
            self.fast_deletes.append(sub_objs)
    for field in model._meta.private_fields:
        if hasattr(field, 'bulk_related_objects'):
            sub_objs = field.bulk_related_objects(new_objs, self.using)
            self.collect(sub_objs, source=model, nullable=True, fail_on_restricted=False)
    if fail_on_restricted:
        for related_model, instances in self.data.items():
            self.clear_restricted_objects_from_set(related_model, instances)
        for qs in self.fast_deletes:
            self.clear_restricted_objects_from_queryset(qs.model, qs)
        if self.restricted_objects.values():
            restricted_objects = defaultdict(list)
            for related_model, fields in self.restricted_objects.items():
                for field, objs in fields.items():
                    if objs:
                        key = "'%s.%s'" % (related_model.__name__, field.name)
                        restricted_objects[key] += objs
            if restricted_objects:
                raise RestrictedError('Cannot delete some instances of model %r because they are referenced through restricted foreign keys: %s.' % (model.__name__, ', '.join(restricted_objects)), set(chain.from_iterable(restricted_objects.values())))

def related_objects(self, related_model, related_fields, objs):
    predicate = query_utils.Q.create([(f'{related_field.name}__in', objs) for related_field in related_fields], connector=query_utils.Q.OR)
    return related_model._base_manager.using(self.using).filter(predicate)

@cached_property
def output_field(self):
    output_field = self._resolve_output_field()
    if output_field is None:
        raise OutputFieldIsNoneError('Cannot resolve expression type, unknown output_field')
    return output_field

@property
def _output_field_or_none(self):
    try:
        return self.output_field
    except OutputFieldIsNoneError:
        return

def _resolve_output_field(self):
    sources_iter = (source for source in self.get_source_fields() if source is not None)
    for output_field in sources_iter:
        for source in sources_iter:
            if not isinstance(output_field, source.__class__):
                raise FieldError('Expression contains mixed types: %s, %s. You must set output_field.' % (output_field.__class__.__name__, source.__class__.__name__))
        return output_field

@cached_property
def convert_value(self):
    field = self.output_field
    internal_type = field.get_internal_type()
    if internal_type == 'FloatField':
        return lambda value, expression, connection: None if value is None else float(value)
    elif internal_type.endswith('IntegerField'):
        return lambda value, expression, connection: None if value is None else int(value)
    elif internal_type == 'DecimalField':
        return lambda value, expression, connection: None if value is None else Decimal(value)
    return self._convert_value_noop

def flatten(self):
    yield self
    for expr in self.get_source_expressions():
        if expr:
            if hasattr(expr, 'flatten'):
                yield from expr.flatten()
            else:
                yield expr

def select_format(self, compiler, sql, params):
    if hasattr(self.output_field, 'select_format'):
        return self.output_field.select_format(compiler, sql, params)
    return (sql, params)

def __init__(self, value, output_field=None):
    super().__init__(output_field=output_field)
    self.value = value

def check(self, model, connection):
    errors = []
    if self.name[0] == '_' or self.name[0].isdigit():
        errors.append(checks.Error("The index name '%s' cannot start with an underscore or a number." % self.name, obj=model, id='models.E033'))
    if len(self.name) > self.max_name_length:
        errors.append(checks.Error("The index name '%s' cannot be longer than %d characters." % (self.name, self.max_name_length), obj=model, id='models.E034'))
    references = set()
    if self.contains_expressions:
        for expression in self.expressions:
            references.update((ref[0] for ref in model._get_expr_references(expression)))
    errors.extend(model._check_local_fields({*[field for field, _ in self.fields_orders], *self.include, *references}, 'indexes'))
    required_db_features = model._meta.required_db_features
    if not (connection.features.supports_partial_indexes or 'supports_partial_indexes' in required_db_features) and any((self.condition is not None for index in model._meta.indexes)):
        errors.append(checks.Warning('%s does not support indexes with conditions.' % connection.display_name, hint="Conditions will be ignored. Silence this warning if you don't care about it.", obj=model, id='models.W037'))
    if not (connection.features.supports_covering_indexes or 'supports_covering_indexes' in required_db_features) and any((index.include for index in model._meta.indexes)):
        errors.append(checks.Warning('%s does not support indexes with non-key columns.' % connection.display_name, hint="Non-key columns will be ignored. Silence this warning if you don't care about it.", obj=model, id='models.W040'))
    if not (connection.features.supports_expression_indexes or 'supports_expression_indexes' in required_db_features) and any((index.contains_expressions for index in model._meta.indexes)):
        errors.append(checks.Warning('%s does not support indexes on expressions.' % connection.display_name, hint="An index won't be created. Silence this warning if you don't care about it.", obj=model, id='models.W043'))
    return errors

def clone(self):
    _, args, kwargs = self.deconstruct()
    return self.__class__(*args, **kwargs)

def set_name_with_model(self, model):
    _, table_name = split_identifier(model._meta.db_table)
    column_names = [model._meta.get_field(field_name).column for field_name, order in self.fields_orders]
    column_names_with_order = [('-%s' if order else '%s') % column_name for column_name, (field_name, order) in zip(column_names, self.fields_orders)]
    hash_data = [table_name, *column_names_with_order, self.suffix]
    self.name = '%s_%s_%s' % (table_name[:11], column_names[0][:7], '%s_%s' % (names_digest(*hash_data, length=6), self.suffix))
    if len(self.name) > self.max_name_length:
        raise ValueError('Index too long for multiple database support. Is self.suffix longer than 3 characters?')
    if self.name[0] == '_' or self.name[0].isdigit():
        self.name = 'D%s' % self.name[1:]

def deconstruct(self):
    qs_class = self._queryset_class
    if getattr(self, '_built_with_as_manager', False):
        return (True, None, '%s.%s' % (qs_class.__module__, qs_class.__name__), None, None)
    else:
        module_name = self.__module__
        name = self.__class__.__name__
        module = import_module(module_name)
        if not hasattr(module, name):
            raise ValueError("Could not find manager %s in %s.\nPlease note that you need to inherit from managers you dynamically generated with 'from_queryset()'." % (name, module_name))
        return (False, '%s.%s' % (module_name, name), None, self._constructor_args[0], self._constructor_args[1])

def _set_creation_counter(self):
    self.creation_counter = BaseManager.creation_counter
    BaseManager.creation_counter += 1

def normalize_together(option_together):
    try:
        if not option_together:
            return ()
        if not isinstance(option_together, (tuple, list)):
            raise TypeError
        first_element = option_together[0]
        if not isinstance(first_element, (tuple, list)):
            option_together = (option_together,)
        return tuple((tuple(ot) for ot in option_together))
    except TypeError:
        return option_together

def _format_names(self, objs):
    names = {'app_label': self.app_label.lower(), 'class': self.model_name}
    new_objs = []
    for obj in objs:
        obj = obj.clone()
        obj.name %= names
        new_objs.append(obj)
    return new_objs

def can_migrate(self, connection):
    if self.proxy or self.swapped or (not self.managed):
        return False
    if isinstance(connection, str):
        connection = connections[connection]
    if self.required_db_vendor:
        return self.required_db_vendor == connection.vendor
    if self.required_db_features:
        return all((getattr(connection.features, feat, False) for feat in self.required_db_features))
    return True

@cached_property
def verbose_name_raw(self):
    if isinstance(self.verbose_name, str):
        return self.verbose_name
    with override(None):
        return str(self.verbose_name)

@cached_property
def swapped(self):
    if self.swappable:
        swapped_for = getattr(settings, self.swappable, None)
        if swapped_for:
            try:
                swapped_label, swapped_object = swapped_for.split('.')
            except ValueError:
                return swapped_for
            if '%s.%s' % (swapped_label, swapped_object.lower()) != self.label_lower:
                return swapped_for
    return None

@cached_property
def fields(self):

    def is_not_an_m2m_field(f):
        return not (f.is_relation and f.many_to_many)

    def is_not_a_generic_relation(f):
        return not (f.is_relation and f.one_to_many)

    def is_not_a_generic_foreign_key(f):
        return not (f.is_relation and f.many_to_one and (not (hasattr(f.remote_field, 'model') and f.remote_field.model)))
    return make_immutable_fields_list('fields', (f for f in self._get_fields(reverse=False) if is_not_an_m2m_field(f) and is_not_a_generic_relation(f) and is_not_a_generic_foreign_key(f)))

@cached_property
def concrete_fields(self):
    return make_immutable_fields_list('concrete_fields', (f for f in self.fields if f.concrete))

@cached_property
def local_concrete_fields(self):
    return make_immutable_fields_list('local_concrete_fields', (f for f in self.local_fields if f.concrete))

@cached_property
def many_to_many(self):
    return make_immutable_fields_list('many_to_many', (f for f in self._get_fields(reverse=False) if f.is_relation and f.many_to_many))

@cached_property
def related_objects(self):
    all_related_fields = self._get_fields(forward=False, reverse=True, include_hidden=True)
    return make_immutable_fields_list('related_objects', (obj for obj in all_related_fields if not obj.hidden or obj.field.many_to_many))

def get_field(self, field_name):
    try:
        return self._forward_fields_map[field_name]
    except KeyError:
        if not self.apps.models_ready:
            raise FieldDoesNotExist("%s has no field named '%s'. The app cache isn't ready yet, so if this is an auto-created related field, it won't be available yet." % (self.object_name, field_name))
    try:
        return self.fields_map[field_name]
    except KeyError:
        raise FieldDoesNotExist("%s has no field named '%s'" % (self.object_name, field_name))

def get_base_chain(self, model):
    if not self.parents:
        return []
    if model in self.parents:
        return [model]
    for parent in self.parents:
        res = parent._meta.get_base_chain(model)
        if res:
            res.insert(0, parent)
            return res
    return []

@cached_property
def all_parents(self):
    result = OrderedSet(self.parents)
    for parent in self.parents:
        for ancestor in parent._meta.all_parents:
            result.add(ancestor)
    return tuple(result)

def get_ancestor_link(self, ancestor):
    if ancestor in self.parents:
        return self.parents[ancestor]
    for parent in self.parents:
        parent_link = parent._meta.get_ancestor_link(ancestor)
        if parent_link:
            return self.parents[parent] or parent_link

def get_path_to_parent(self, parent):
    if self.model is parent:
        return []
    proxied_model = self.concrete_model
    path = []
    opts = self
    for int_model in self.get_base_chain(parent):
        if int_model is proxied_model:
            opts = int_model._meta
        else:
            final_field = opts.parents[int_model]
            targets = (final_field.remote_field.get_related_field(),)
            opts = int_model._meta
            path.append(PathInfo(from_opts=final_field.model._meta, to_opts=opts, target_fields=targets, join_field=final_field, m2m=False, direct=True, filtered_relation=None))
    return path

def _populate_directed_relation_graph(self):
    related_objects_graph = defaultdict(list)
    all_models = self.apps.get_models(include_auto_created=True)
    for model in all_models:
        opts = model._meta
        if opts.abstract:
            continue
        fields_with_relations = (f for f in opts._get_fields(reverse=False, include_parents=False) if f.is_relation and f.related_model is not None)
        for f in fields_with_relations:
            if not isinstance(f.remote_field.model, str):
                remote_label = f.remote_field.model._meta.concrete_model._meta.label
                related_objects_graph[remote_label].append(f)
    for model in all_models:
        related_objects = related_objects_graph[model._meta.concrete_model._meta.label]
        model._meta.__dict__['_relation_tree'] = related_objects
    return self.__dict__.get('_relation_tree', EMPTY_RELATION_TREE)

def get_fields(self, include_parents=True, include_hidden=False):
    if include_parents is False:
        include_parents = PROXY_PARENTS
    return self._get_fields(include_parents=include_parents, include_hidden=include_hidden)

def _get_fields(self, forward=True, reverse=True, include_parents=True, include_hidden=False, topmost_call=True):
    if include_parents not in (True, False, PROXY_PARENTS):
        raise TypeError('Invalid argument for include_parents: %s' % (include_parents,))
    cache_key = (forward, reverse, include_parents, include_hidden, topmost_call)
    try:
        return self._get_fields_cache[cache_key]
    except KeyError:
        pass
    fields = []
    if include_parents is not False:
        parent_fields = set()
        for parent in self.parents:
            if parent._meta.concrete_model != self.concrete_model and include_parents == PROXY_PARENTS:
                continue
            for obj in parent._meta._get_fields(forward=forward, reverse=reverse, include_parents=include_parents, include_hidden=include_hidden, topmost_call=False):
                if (not getattr(obj, 'parent_link', False) or obj.model == self.concrete_model) and obj not in parent_fields:
                    fields.append(obj)
                    parent_fields.add(obj)
    if reverse and (not self.proxy):
        all_fields = self._relation_tree
        for field in all_fields:
            if include_hidden or not field.remote_field.hidden:
                fields.append(field.remote_field)
    if forward:
        fields += self.local_fields
        fields += self.local_many_to_many
        if topmost_call:
            fields += self.private_fields
    fields = make_immutable_fields_list('get_fields()', fields)
    self._get_fields_cache[cache_key] = fields
    return fields

@cached_property
def total_unique_constraints(self):
    return [constraint for constraint in self.constraints if isinstance(constraint, UniqueConstraint) and constraint.condition is None and (not constraint.contains_expressions)]

@cached_property
def _property_names(self):
    names = set()
    seen = set()
    for klass in self.model.__mro__:
        names |= {name for name, value in klass.__dict__.items() if isinstance(value, property) and name not in seen}
        seen |= set(klass.__dict__)
    return frozenset(names)

@cached_property
def _non_pk_concrete_field_names(self):
    names = []
    all_pk_fields = set(self.pk_fields)
    for parent in self.all_parents:
        all_pk_fields.update(parent._meta.pk_fields)
    for field in self.concrete_fields:
        if field not in all_pk_fields:
            names.append(field.name)
            if field.name != field.attname:
                names.append(field.attname)
    return frozenset(names)

@cached_property
def _reverse_one_to_one_field_names(self):
    return frozenset((field.name for field in self.related_objects if field.one_to_one))

@cached_property
def db_returning_fields(self):
    return [field for field in self._get_fields(forward=True, reverse=False, include_parents=PROXY_PARENTS) if getattr(field, 'db_returning', False)]

def __deepcopy__(self, memo):
    obj = self.__class__()
    for k, v in self.__dict__.items():
        if k == '_result_cache':
            obj.__dict__[k] = None
        else:
            obj.__dict__[k] = copy.deepcopy(v, memo)
    return obj

def __iter__(self):
    self._fetch_all()
    return iter(self._result_cache)

def __getitem__(self, k):
    if not isinstance(k, (int, slice)):
        raise TypeError('QuerySet indices must be integers or slices, not %s.' % type(k).__name__)
    if isinstance(k, int) and k < 0 or (isinstance(k, slice) and (k.start is not None and k.start < 0 or (k.stop is not None and k.stop < 0))):
        raise ValueError('Negative indexing is not supported.')
    if self._result_cache is not None:
        return self._result_cache[k]
    if isinstance(k, slice):
        qs = self._chain()
        if k.start is not None:
            start = int(k.start)
        else:
            start = None
        if k.stop is not None:
            stop = int(k.stop)
        else:
            stop = None
        qs.query.set_limits(start, stop)
        return list(qs)[::k.step] if k.step else qs
    qs = self._chain()
    qs.query.set_limits(k, k + 1)
    qs._fetch_all()
    return qs._result_cache[0]

def iterator(self, chunk_size=None):
    if chunk_size is None:
        if self._prefetch_related_lookups:
            raise ValueError('chunk_size must be provided when using QuerySet.iterator() after prefetch_related().')
    elif chunk_size <= 0:
        raise ValueError('Chunk size must be strictly positive.')
    use_chunked_fetch = not connections[self.db].settings_dict.get('DISABLE_SERVER_SIDE_CURSORS')
    return self._iterator(use_chunked_fetch, chunk_size)

async def aiterator(self, chunk_size=None):
    if chunk_size is None:
        if self._prefetch_related_lookups:
            warnings.warn('Using QuerySet.aiterator() after prefetch_related() without providing a chunk_size is deprecated and will raise a ValueError in Django 7.1.', category=RemovedInDjango71Warning, skip_file_prefixes=django_file_prefixes())
            chunk_size = 2000
    elif chunk_size <= 0:
        raise ValueError('Chunk size must be strictly positive.')
    use_chunked_fetch = not connections[self.db].settings_dict.get('DISABLE_SERVER_SIDE_CURSORS')
    iterable = self._iterable_class(self, chunked_fetch=use_chunked_fetch, chunk_size=chunk_size or 2000)
    if self._prefetch_related_lookups:
        results = []
        async for item in iterable:
            results.append(item)
            if len(results) >= chunk_size:
                await aprefetch_related_objects(results, *self._prefetch_related_lookups)
                for result in results:
                    yield result
                results.clear()
        if results:
            await aprefetch_related_objects(results, *self._prefetch_related_lookups)
            for result in results:
                yield result
    else:
        async for item in iterable:
            yield item

def aggregate(self, *args, **kwargs):
    if self.query.distinct_fields:
        raise NotImplementedError('aggregate() + distinct(fields) not implemented.')
    self._validate_values_are_expressions((*args, *kwargs.values()), method_name='aggregate')
    for arg in args:
        try:
            arg.default_alias
        except (AttributeError, TypeError):
            raise TypeError('Complex aggregates require an alias')
        kwargs[arg.default_alias] = arg
    return self.query.chain().get_aggregation(self.db, kwargs)

def count(self):
    if self._result_cache is not None:
        return len(self._result_cache)
    return self.query.get_count(using=self.db)

def get(self, *args, **kwargs):
    if self.query.combinator and (args or kwargs):
        raise NotSupportedError('Calling QuerySet.get(...) with filters after %s() is not supported.' % self.query.combinator)
    clone = self._chain() if self.query.combinator else self.filter(*args, **kwargs)
    if self.query.can_filter() and (not self.query.distinct_fields):
        clone = clone.order_by()
    limit = None
    if not clone.query.select_for_update or connections[clone.db].features.supports_select_for_update_with_limit:
        limit = MAX_GET_RESULTS
        clone.query.set_limits(high=limit)
    num = len(clone)
    if num == 1:
        return clone._result_cache[0]
    if not num:
        raise self.model.DoesNotExist('%s matching query does not exist.' % self.model._meta.object_name)
    raise self.model.MultipleObjectsReturned('get() returned more than one %s -- it returned %s!' % (self.model._meta.object_name, num if not limit or num < limit else 'more than %s' % (limit - 1)))

def bulk_create(self, objs, batch_size=None, ignore_conflicts=False, update_conflicts=False, update_fields=None, unique_fields=None):
    if batch_size is not None and batch_size <= 0:
        raise ValueError('Batch size must be a positive integer.')
    for parent in self.model._meta.all_parents:
        if parent._meta.concrete_model is not self.model._meta.concrete_model:
            raise ValueError("Can't bulk create a multi-table inherited model")
    if not objs:
        return objs
    opts = self.model._meta
    if unique_fields:
        unique_fields = [self.model._meta.get_field(opts.pk.name if name == 'pk' else name) for name in unique_fields]
    if update_fields:
        update_fields = [self.model._meta.get_field(name) for name in update_fields]
    on_conflict = self._check_bulk_create_options(ignore_conflicts, update_conflicts, update_fields, unique_fields)
    self._for_write = True
    fields = [f for f in opts.concrete_fields if not f.generated]
    objs = list(objs)
    objs_with_pk, objs_without_pk = self._prepare_for_bulk_create(objs)
    if objs_with_pk and objs_without_pk:
        context = transaction.atomic(using=self.db, savepoint=False)
    else:
        context = nullcontext()
    with context:
        self._handle_order_with_respect_to(objs)
        if objs_with_pk:
            returned_columns = self._batched_insert(objs_with_pk, fields, batch_size, on_conflict=on_conflict, update_fields=update_fields, unique_fields=unique_fields)
            for obj_with_pk, results in zip(objs_with_pk, returned_columns):
                for result, field in zip(results, opts.db_returning_fields):
                    setattr(obj_with_pk, field.attname, result)
            for obj_with_pk in objs_with_pk:
                obj_with_pk._state.adding = False
                obj_with_pk._state.db = self.db
        if objs_without_pk:
            fields = [f for f in fields if not isinstance(f, AutoField)]
            returned_columns = self._batched_insert(objs_without_pk, fields, batch_size, on_conflict=on_conflict, update_fields=update_fields, unique_fields=unique_fields)
            connection = connections[self.db]
            if connection.features.can_return_rows_from_bulk_insert and on_conflict is None:
                assert len(returned_columns) == len(objs_without_pk)
            for obj_without_pk, results in zip(objs_without_pk, returned_columns):
                for result, field in zip(results, opts.db_returning_fields):
                    setattr(obj_without_pk, field.attname, result)
                obj_without_pk._state.adding = False
                obj_without_pk._state.db = self.db
    return objs

def bulk_update(self, objs, fields, batch_size=None):
    if batch_size is not None and batch_size <= 0:
        raise ValueError('Batch size must be a positive integer.')
    if not fields:
        raise ValueError('Field names must be given to bulk_update().')
    objs = tuple(objs)
    if not all((obj._is_pk_set() for obj in objs)):
        raise ValueError('All bulk_update() objects must have a primary key set.')
    opts = self.model._meta
    fields = [opts.get_field(name) for name in fields]
    if any((not f.concrete for f in fields)):
        raise ValueError('bulk_update() can only be used with concrete fields.')
    all_pk_fields = set(opts.pk_fields)
    for parent in opts.all_parents:
        all_pk_fields.update(parent._meta.pk_fields)
    if any((f in all_pk_fields for f in fields)):
        raise ValueError('bulk_update() cannot be used with primary key fields.')
    if not objs:
        return 0
    for obj in objs:
        obj._prepare_related_fields_for_save(operation_name='bulk_update', fields=fields)
    self._for_write = True
    connection = connections[self.db]
    max_batch_size = connection.ops.bulk_batch_size([opts.pk, opts.pk, *fields], objs)
    batch_size = min(batch_size, max_batch_size) if batch_size else max_batch_size
    requires_casting = connection.features.requires_casted_case_in_updates
    batches = (objs[i:i + batch_size] for i in range(0, len(objs), batch_size))
    updates = []
    for batch_objs in batches:
        update_kwargs = {}
        for field in fields:
            when_statements = []
            for obj in batch_objs:
                attr = getattr(obj, field.attname)
                if not hasattr(attr, 'resolve_expression'):
                    attr = Value(attr, output_field=field)
                when_statements.append(When(pk=obj.pk, then=attr))
            case_statement = Case(*when_statements, output_field=field)
            if requires_casting:
                case_statement = Cast(case_statement, output_field=field)
            update_kwargs[field.attname] = case_statement
        updates.append(([obj.pk for obj in batch_objs], update_kwargs))
    rows_updated = 0
    queryset = self.using(self.db)
    with transaction.atomic(using=self.db, savepoint=False):
        for pks, update_kwargs in updates:
            rows_updated += queryset.filter(pk__in=pks).update(**update_kwargs)
    return rows_updated

def get_or_create(self, defaults=None, **kwargs):
    self._for_write = True
    try:
        return (self.get(**kwargs), False)
    except self.model.DoesNotExist:
        params = self._extract_model_params(defaults, **kwargs)
        try:
            with transaction.atomic(using=self.db):
                params = dict(resolve_callables(params))
                return (self.create(**params), True)
        except IntegrityError:
            try:
                return (self.get(**kwargs), False)
            except self.model.DoesNotExist:
                pass
            raise

def update_or_create(self, defaults=None, create_defaults=None, **kwargs):
    update_defaults = defaults or {}
    if create_defaults is None:
        create_defaults = update_defaults
    self._for_write = True
    with transaction.atomic(using=self.db):
        obj, created = self.select_for_update().get_or_create(create_defaults, **kwargs)
        if created:
            return (obj, created)
        for k, v in resolve_callables(update_defaults):
            setattr(obj, k, v)
        update_fields = set(update_defaults)
        concrete_field_names = self.model._meta._non_pk_concrete_field_names
        if concrete_field_names.issuperset(update_fields):
            pk_fields = self.model._meta.pk_fields
            for field in self.model._meta.local_concrete_fields:
                if not (field in pk_fields or field.__class__.pre_save is Field.pre_save):
                    update_fields.add(field.name)
                    if field.name != field.attname:
                        update_fields.add(field.attname)
            obj.save(using=self.db, update_fields=update_fields)
        else:
            obj.save(using=self.db)
    return (obj, False)

def _extract_model_params(self, defaults, **kwargs):
    defaults = defaults or {}
    params = {k: v for k, v in kwargs.items() if LOOKUP_SEP not in k}
    params.update(defaults)
    property_names = self.model._meta._property_names
    invalid_params = []
    for param in params:
        try:
            self.model._meta.get_field(param)
        except exceptions.FieldDoesNotExist:
            if not (param in property_names and getattr(self.model, param).fset):
                invalid_params.append(param)
    if invalid_params:
        raise exceptions.FieldError("Invalid field name(s) for model %s: '%s'." % (self.model._meta.object_name, "', '".join(sorted(invalid_params))))
    return params

def _earliest(self, *fields):
    if fields:
        order_by = fields
    else:
        order_by = getattr(self.model._meta, 'get_latest_by')
        if order_by and (not isinstance(order_by, (tuple, list))):
            order_by = (order_by,)
    if order_by is None:
        raise ValueError("earliest() and latest() require either fields as positional arguments or 'get_latest_by' in the model's Meta.")
    obj = self._chain()
    obj.query.set_limits(high=1)
    obj.query.clear_ordering(force=True)
    obj.query.add_ordering(*order_by)
    return obj.get()

def latest(self, *fields):
    if self.query.is_sliced:
        raise TypeError('Cannot change a query once a slice has been taken.')
    return self.reverse()._earliest(*fields)

def first(self):
    if self.ordered or not self.query.default_ordering:
        queryset = self
    else:
        self._check_ordering_first_last_queryset_aggregation(method='first')
        queryset = self.order_by('pk')
    for obj in queryset[:1]:
        return obj

def last(self):
    if self.ordered or not self.query.default_ordering:
        queryset = self.reverse()
    else:
        self._check_ordering_first_last_queryset_aggregation(method='last')
        queryset = self.order_by('-pk')
    for obj in queryset[:1]:
        return obj

def in_bulk(self, id_list=None, *, field_name='pk'):
    if self.query.is_sliced:
        raise TypeError("Cannot use 'limit' or 'offset' with in_bulk().")
    if id_list is not None and (not id_list):
        return {}
    opts = self.model._meta
    unique_fields = [constraint.fields[0] for constraint in opts.total_unique_constraints if len(constraint.fields) == 1]
    if field_name != 'pk' and (not opts.get_field(field_name).unique) and (field_name not in unique_fields) and (self.query.distinct_fields != (field_name,)):
        raise ValueError("in_bulk()'s field_name must be a unique field but %r isn't." % field_name)
    qs = self

    def get_obj(obj):
        return obj
    if issubclass(self._iterable_class, ModelIterable):
        get_key = operator.attrgetter(field_name)
    elif issubclass(self._iterable_class, ValuesIterable):
        if field_name not in self.query.values_select:
            qs = qs.values(field_name, *self.query.values_select)

            def get_obj(obj):
                del obj[field_name]
                return obj
        get_key = operator.itemgetter(field_name)
    elif issubclass(self._iterable_class, ValuesListIterable):
        try:
            field_index = self.query.values_select.index(field_name)
        except ValueError:
            field_index = 0
            if issubclass(self._iterable_class, NamedValuesListIterable):
                kwargs = {'named': True}
            else:
                kwargs = {}
                get_obj = operator.itemgetter(slice(1, None))
            qs = qs.values_list(field_name, *self.query.values_select, **kwargs)
        get_key = operator.itemgetter(field_index)
    elif issubclass(self._iterable_class, FlatValuesListIterable):
        if self.query.values_select == (field_name,):
            get_key = get_obj
        else:
            qs = qs.values_list(field_name, *self.query.values_select)
            get_key = operator.itemgetter(0)
            get_obj = operator.itemgetter(1)
    else:
        raise TypeError(f'in_bulk() cannot be used with {self._iterable_class.__name__}.')
    if id_list is not None:
        filter_key = '{}__in'.format(field_name)
        id_list = tuple(id_list)
        batch_size = connections[self.db].ops.bulk_batch_size([opts.pk], id_list)
        if batch_size and batch_size < len(id_list):
            results = ()
            for offset in range(0, len(id_list), batch_size):
                batch = id_list[offset:offset + batch_size]
                results += tuple(qs.filter(**{filter_key: batch}))
            qs = results
        else:
            qs = qs.filter(**{filter_key: id_list})
    else:
        qs = qs._chain()
    return {get_key(obj): get_obj(obj) for obj in qs}

def _raw_delete(self, using):
    query = self.query.clone()
    query.__class__ = sql.DeleteQuery
    return query.get_compiler(using).execute_sql(ROW_COUNT)

def update(self, **kwargs):
    self._not_support_combined_queries('update')
    if self.query.is_sliced:
        raise TypeError('Cannot update a query once a slice has been taken.')
    if self.query.distinct_fields:
        raise TypeError('Cannot call update() after .distinct(*fields).')
    self._for_write = True
    query = self.query.chain(sql.UpdateQuery)
    query.add_update_values(kwargs)
    new_order_by = []
    for col in query.order_by:
        alias = col
        descending = False
        if isinstance(alias, str) and alias.startswith('-'):
            alias = alias.removeprefix('-')
            descending = True
        if (annotation := query.annotations.get(alias)):
            if getattr(annotation, 'contains_aggregate', False):
                raise exceptions.FieldError(f'Cannot update when ordering by an aggregate: {annotation}')
            if descending:
                annotation = annotation.desc()
            new_order_by.append(annotation)
        else:
            new_order_by.append(col)
    query.order_by = tuple(new_order_by)
    query.clear_select_clause()
    with transaction.mark_for_rollback_on_error(using=self.db):
        rows = query.get_compiler(self.db).execute_sql(ROW_COUNT)
    self._result_cache = None
    return rows

def _update(self, values, returning_fields=None):
    if self.query.is_sliced:
        raise TypeError('Cannot update a query once a slice has been taken.')
    query = self.query.chain(sql.UpdateQuery)
    query.add_update_fields(values)
    query.annotations = {}
    self._result_cache = None
    if returning_fields is None:
        return query.get_compiler(self.db).execute_sql(ROW_COUNT)
    return query.get_compiler(self.db).execute_returning_sql(returning_fields)

def exists(self):
    if self._result_cache is None:
        return self.query.has_results(using=self.db)
    return bool(self._result_cache)

def contains(self, obj):
    self._not_support_combined_queries('contains')
    if self._fields is not None:
        raise TypeError('Cannot call QuerySet.contains() after .values() or .values_list().')
    try:
        if obj._meta.concrete_model != self.model._meta.concrete_model:
            return False
    except AttributeError:
        raise TypeError("'obj' must be a model instance.")
    if not obj._is_pk_set():
        raise ValueError('QuerySet.contains() cannot be used on unsaved objects.')
    if self._result_cache is not None:
        return obj in self._result_cache
    return self.filter(pk=obj.pk).exists()

def dates(self, field_name, kind, order='ASC'):
    if kind not in ('year', 'month', 'week', 'day'):
        raise ValueError("'kind' must be one of 'year', 'month', 'week', or 'day'.")
    if order not in ('ASC', 'DESC'):
        raise ValueError("'order' must be either 'ASC' or 'DESC'.")
    return self.annotate(datefield=Trunc(field_name, kind, output_field=DateField()), plain_field=F(field_name)).values_list('datefield', flat=True).distinct().filter(plain_field__isnull=False).order_by(('-' if order == 'DESC' else '') + 'datefield')

def datetimes(self, field_name, kind, order='ASC', tzinfo=None):
    if kind not in ('year', 'month', 'week', 'day', 'hour', 'minute', 'second'):
        raise ValueError("'kind' must be one of 'year', 'month', 'week', 'day', 'hour', 'minute', or 'second'.")
    if order not in ('ASC', 'DESC'):
        raise ValueError("'order' must be either 'ASC' or 'DESC'.")
    if settings.USE_TZ:
        if tzinfo is None:
            tzinfo = timezone.get_current_timezone()
    else:
        tzinfo = None
    return self.annotate(datetimefield=Trunc(field_name, kind, output_field=DateTimeField(), tzinfo=tzinfo), plain_field=F(field_name)).values_list('datetimefield', flat=True).distinct().filter(plain_field__isnull=False).order_by(('-' if order == 'DESC' else '') + 'datetimefield')

def filter(self, *args, **kwargs):
    self._not_support_combined_queries('filter')
    return self._filter_or_exclude(False, args, kwargs)

def exclude(self, *args, **kwargs):
    self._not_support_combined_queries('exclude')
    return self._filter_or_exclude(True, args, kwargs)

def complex_filter(self, filter_obj):
    if isinstance(filter_obj, Q):
        clone = self._chain()
        clone.query.add_q(filter_obj)
        return clone
    else:
        return self._filter_or_exclude(False, args=(), kwargs=filter_obj)

def select_related(self, *fields):
    self._not_support_combined_queries('select_related')
    if self._fields is not None:
        raise TypeError('Cannot call select_related() after .values() or .values_list()')
    obj = self._chain()
    if fields == (None,):
        obj.query.select_related = False
    elif fields:
        obj.query.add_select_related(fields)
    else:
        warn_about_external_use('Calling select_related() with no arguments is deprecated. Specify the fields to fetch instead.', category=RemovedInDjango70Warning, skip_name_prefixes=('django.db.models',))
        obj.query.select_related = True
    return obj

def prefetch_related(self, *lookups):
    self._not_support_combined_queries('prefetch_related')
    clone = self._chain()
    if lookups == (None,):
        clone._prefetch_related_lookups = ()
    else:
        for lookup in lookups:
            if isinstance(lookup, Prefetch):
                lookup = lookup.prefetch_to
            lookup = lookup.split(LOOKUP_SEP, 1)[0]
            if lookup in self.query._filtered_relations:
                raise ValueError('prefetch_related() is not supported with FilteredRelation.')
        clone._prefetch_related_lookups = clone._prefetch_related_lookups + lookups
    return clone

def annotate(self, *args, **kwargs):
    self._not_support_combined_queries('annotate')
    return self._annotate(args, kwargs, select=True)

def alias(self, *args, **kwargs):
    self._not_support_combined_queries('alias')
    return self._annotate(args, kwargs, select=False)

def reverse(self):
    if self.query.is_sliced:
        raise TypeError('Cannot reverse a query once a slice has been taken.')
    clone = self._chain()
    clone.query.standard_ordering = not clone.query.standard_ordering
    return clone

def defer(self, *fields):
    self._not_support_combined_queries('defer')
    if self._fields is not None:
        raise TypeError('Cannot call defer() after .values() or .values_list()')
    clone = self._chain()
    if fields == (None,):
        clone.query.clear_deferred_loading()
    else:
        clone.query.add_deferred_loading(fields)
    return clone

def only(self, *fields):
    self._not_support_combined_queries('only')
    if self._fields is not None:
        raise TypeError('Cannot call only() after .values() or .values_list()')
    if fields == (None,):
        raise TypeError('Cannot pass None as an argument to only().')
    for field in fields:
        field = field.split(LOOKUP_SEP, 1)[0]
        if field in self.query._filtered_relations:
            raise ValueError('only() is not supported with FilteredRelation.')
    clone = self._chain()
    clone.query.add_immediate_loading(fields)
    return clone

@property
def ordered(self):
    if isinstance(self, EmptyQuerySet):
        return True
    if self.query.extra_order_by or self.query.order_by:
        return True
    elif self.query.default_ordering and self.query.get_meta().ordering and (not self.query.group_by):
        return True
    else:
        return False

@property
def totally_ordered(self):
    if not self.ordered:
        return False
    ordering = self.query.order_by
    if not ordering and self.query.default_ordering:
        ordering = self.query.get_meta().ordering
    if not ordering:
        return False
    opts = self.model._meta
    pk_fields = {f.attname for f in opts.pk_fields}
    ordering_fields = set()
    for part in ordering:
        field_name = None
        if isinstance(part, str):
            field_name = part.lstrip('-')
        elif isinstance(part, F):
            field_name = part.name
        elif isinstance(part, OrderBy) and isinstance(part.expression, F):
            field_name = part.expression.name
        if field_name:
            if field_name == 'pk':
                return True
            try:
                field = opts.get_field(field_name)
            except exceptions.FieldDoesNotExist:
                continue
            if field.remote_field and field_name == field.name:
                continue
            if field.attname in pk_fields and len(pk_fields) == 1:
                return True
            if field.unique and (not field.null):
                return True
            ordering_fields.add(field.attname)
    if ordering_fields.issuperset(pk_fields):
        return True
    constraint_field_names = (*opts.unique_together, *(constraint.fields for constraint in opts.total_unique_constraints))
    for field_names in constraint_field_names:
        try:
            fields = [opts.get_field(field_name) for field_name in field_names]
        except exceptions.FieldDoesNotExist:
            continue
        if any((field.null for field in fields)):
            continue
        if ordering_fields.issuperset((field.attname for field in fields)):
            return True
    return False

@property
def db(self):
    if self._for_write:
        return self._db or router.db_for_write(self.model, **self._hints)
    return self._db or router.db_for_read(self.model, **self._hints)

def _insert(self, objs, fields, returning_fields=None, raw=False, using=None, on_conflict=None, update_fields=None, unique_fields=None):
    self._for_write = True
    if using is None:
        using = self.db
    query = sql.InsertQuery(self.model, on_conflict=on_conflict, update_fields=update_fields, unique_fields=unique_fields)
    query.insert_values(fields, objs, raw=raw)
    return query.get_compiler(using=using).execute_sql(returning_fields)

def _disable_cloning(self):
    self._cloning_enabled = False
    return self

def _enable_cloning(self):
    self._cloning_enabled = True
    return self

def _chain(self):
    if not self._cloning_enabled:
        obj = self
    else:
        obj = self._clone()
    if obj._sticky_filter:
        obj.query.filter_is_sticky = True
        obj._sticky_filter = False
    return obj

def _next_is_sticky(self):
    self._sticky_filter = True
    return self

def _merge_sanity_check(self, other):
    if self._fields is not None and (set(self.query.values_select) != set(other.query.values_select) or set(self.query.extra_select) != set(other.query.extra_select) or set(self.query.annotation_select) != set(other.query.annotation_select)):
        raise TypeError("Merging '%s' classes must involve the same values in each case." % self.__class__.__name__)

def _merge_known_related_objects(self, other):
    for field, objects in other._known_related_objects.items():
        self._known_related_objects.setdefault(field, {}).update(objects)

def prefetch_related(self, *lookups):
    clone = self._clone()
    if lookups == (None,):
        clone._prefetch_related_lookups = ()
    else:
        clone._prefetch_related_lookups = clone._prefetch_related_lookups + lookups
    return clone

@property
def db(self):
    return self._db or router.db_for_read(self.model, **self._hints)

@cached_property
def columns(self):
    columns = self.query.get_columns()
    for query_name, model_name in self.translations.items():
        try:
            index = columns.index(query_name)
        except ValueError:
            pass
        else:
            columns[index] = model_name
    return columns

@cached_property
def model_fields(self):
    converter = connections[self.db].introspection.identifier_converter
    return {converter(field.column): field for field in self.model._meta.fields if field.column}

def normalize_prefetch_lookups(lookups, prefix=None):
    ret = []
    for lookup in lookups:
        if not isinstance(lookup, Prefetch):
            lookup = Prefetch(lookup)
        if prefix:
            lookup.add_prefix(prefix)
        ret.append(lookup)
    return ret

def prefetch_related_objects(model_instances, *related_lookups):
    if not model_instances:
        return
    done_queries = {}
    auto_lookups = set()
    followed_descriptors = set()
    all_lookups = normalize_prefetch_lookups(reversed(related_lookups))
    while all_lookups:
        lookup = all_lookups.pop()
        if lookup.prefetch_to in done_queries:
            if lookup.queryset is not None:
                raise ValueError("'%s' lookup was already seen with a different queryset. You may need to adjust the ordering of your lookups." % lookup.prefetch_to)
            continue
        obj_list = model_instances
        through_attrs = lookup.prefetch_through.split(LOOKUP_SEP)
        for level, through_attr in enumerate(through_attrs):
            if not obj_list:
                break
            prefetch_to = lookup.get_current_prefetch_to(level)
            if prefetch_to in done_queries:
                obj_list = done_queries[prefetch_to]
                continue
            good_objects = True
            for obj in obj_list:
                if not hasattr(obj, '_prefetched_objects_cache'):
                    try:
                        obj._prefetched_objects_cache = {}
                    except (AttributeError, TypeError):
                        good_objects = False
                        break
            if not good_objects:
                break
            first_obj = next(iter(obj_list))
            to_attr = lookup.get_current_to_attr(level)[0]
            prefetcher, descriptor, attr_found, is_fetched = get_prefetcher(first_obj, through_attr, to_attr)
            if not attr_found:
                raise AttributeError("Cannot find '%s' on %s object, '%s' is an invalid parameter to prefetch_related()" % (through_attr, first_obj.__class__.__name__, lookup.prefetch_through))
            if level == len(through_attrs) - 1 and prefetcher is None:
                raise ValueError("'%s' does not resolve to an item that supports prefetching - this is an invalid parameter to prefetch_related()." % lookup.prefetch_through)
            obj_to_fetch = None
            if prefetcher is not None:
                obj_to_fetch = [obj for obj in obj_list if not is_fetched(obj)]
            if obj_to_fetch:
                obj_list, additional_lookups = prefetch_one_level(obj_to_fetch, prefetcher, lookup, level)
                if not (prefetch_to in done_queries and lookup in auto_lookups and (descriptor in followed_descriptors)):
                    done_queries[prefetch_to] = obj_list
                    new_lookups = normalize_prefetch_lookups(reversed(additional_lookups), prefetch_to)
                    auto_lookups.update(new_lookups)
                    all_lookups.extend(new_lookups)
                followed_descriptors.add(descriptor)
            else:
                new_obj_list = []
                for obj in obj_list:
                    if through_attr in getattr(obj, '_prefetched_objects_cache', ()):
                        new_obj = list(obj._prefetched_objects_cache.get(through_attr))
                    else:
                        try:
                            new_obj = getattr(obj, through_attr)
                        except exceptions.ObjectDoesNotExist:
                            continue
                    if new_obj is None:
                        continue
                    if isinstance(new_obj, list):
                        new_obj_list.extend(new_obj)
                    else:
                        new_obj_list.append(new_obj)
                obj_list = new_obj_list

def get_prefetcher(instance, through_attr, to_attr):

    def is_to_attr_fetched(model, to_attr):
        if isinstance(getattr(model, to_attr, None), cached_property):

            def has_cached_property(instance):
                return to_attr in instance.__dict__
            return has_cached_property

        def has_to_attr_attribute(instance):
            return hasattr(instance, to_attr)
        return has_to_attr_attribute
    prefetcher = None
    is_fetched = is_to_attr_fetched(instance.__class__, to_attr)
    rel_obj_descriptor = getattr(instance.__class__, through_attr, None)
    if rel_obj_descriptor is None:
        attr_found = hasattr(instance, through_attr)
    else:
        attr_found = True
        if rel_obj_descriptor:
            if hasattr(rel_obj_descriptor, 'get_prefetch_querysets'):
                prefetcher = rel_obj_descriptor
                if through_attr == to_attr:
                    is_fetched = rel_obj_descriptor.is_cached
            else:
                rel_obj = getattr(instance, through_attr)
                if hasattr(rel_obj, 'get_prefetch_querysets'):
                    prefetcher = rel_obj
                if through_attr == to_attr:

                    def in_prefetched_cache(instance):
                        return through_attr in instance._prefetched_objects_cache
                    is_fetched = in_prefetched_cache
    return (prefetcher, rel_obj_descriptor, attr_found, is_fetched)

def prefetch_one_level(instances, prefetcher, lookup, level):
    rel_qs, rel_obj_attr, instance_attr, single, cache_name, is_descriptor = prefetcher.get_prefetch_querysets(instances, lookup.get_current_querysets(level))
    additional_lookups = [copy.copy(additional_lookup) for additional_lookup in getattr(rel_qs, '_prefetch_related_lookups', ())]
    if additional_lookups:
        rel_qs._prefetch_related_lookups = ()
    all_related_objects = list(rel_qs)
    rel_obj_cache = {}
    for rel_obj in all_related_objects:
        rel_attr_val = rel_obj_attr(rel_obj)
        rel_obj_cache.setdefault(rel_attr_val, []).append(rel_obj)
    to_attr, as_attr = lookup.get_current_to_attr(level)
    if as_attr and instances:
        model = instances[0].__class__
        try:
            model._meta.get_field(to_attr)
        except exceptions.FieldDoesNotExist:
            pass
        else:
            msg = 'to_attr={} conflicts with a field on the {} model.'
            raise ValueError(msg.format(to_attr, model.__name__))
    leaf = len(lookup.prefetch_through.split(LOOKUP_SEP)) - 1 == level
    for obj in instances:
        instance_attr_val = instance_attr(obj)
        vals = rel_obj_cache.get(instance_attr_val, [])
        if single:
            val = vals[0] if vals else None
            if as_attr:
                setattr(obj, to_attr, val)
            elif is_descriptor:
                setattr(obj, cache_name, val)
            else:
                obj._state.fields_cache[cache_name] = val
        elif as_attr:
            setattr(obj, to_attr, vals)
        else:
            manager = getattr(obj, to_attr)
            if leaf and lookup.queryset is not None:
                qs = manager._apply_rel_filters(lookup.queryset._chain())
            else:
                qs = manager.get_queryset()
            qs._result_cache = vals
            qs._prefetch_done = True
            obj._prefetched_objects_cache[cache_name] = qs
    return (all_related_objects, additional_lookups)

def flatten(self):
    yield self
    for child in self.children:
        if isinstance(child, tuple):
            child = child[1]
        if hasattr(child, 'flatten'):
            yield from child.flatten()
        else:
            yield child

@cached_property
def referenced_base_fields(self):
    from django.db.models.sql import query
    return {child.split(LOOKUP_SEP, 1)[0] for child in query.get_children_from_q(self)}

def __get__(self, instance, cls=None):
    if instance is None:
        return self
    data = instance.__dict__
    field_name = self.field.attname
    if field_name not in data:
        val = self._check_parent_chain(instance)
        if val is None:
            if not instance._is_pk_set():
                raise AttributeError(f'Cannot retrieve deferred field {field_name!r} from an unsaved model.')
            instance._state.fetch_mode.fetch(self, instance)
        else:
            data[field_name] = val
    return data[field_name]

def _check_parent_chain(self, instance):
    opts = instance._meta
    link_field = opts.get_ancestor_link(self.field.model)
    if self.field.primary_key and self.field != link_field:
        return getattr(instance, link_field.attname)
    return None

@staticmethod
def merge_dicts(dicts):
    merged = {}
    for d in reversed(dicts):
        merged.update(d)
    return merged

def _unregister_class_lookup(cls, lookup, lookup_name=None):
    if lookup_name is None:
        lookup_name = lookup.lookup_name
    del cls.class_lookups[lookup_name]
    cls._clear_cached_class_lookups()

def _unregister_instance_lookup(self, lookup, lookup_name=None):
    if lookup_name is None:
        lookup_name = lookup.lookup_name
    del self.instance_lookups[lookup_name]

def select_related_descend(field, restricted, requested, select_mask):
    if not field.remote_field:
        return False
    if getattr(field.remote_field, 'parent_link', False):
        return False
    if not restricted:
        return not field.null
    if field.name not in requested:
        return False
    if select_mask and field not in select_mask:
        raise FieldError(f'Field {field.model._meta.object_name}.{field.name} cannot be both deferred and traversed using select_related at the same time.')
    return True

def refs_expression(lookup_parts, annotations):
    for n in range(1, len(lookup_parts) + 1):
        level_n_lookup = LOOKUP_SEP.join(lookup_parts[0:n])
        if annotations.get(level_n_lookup):
            return (level_n_lookup, lookup_parts[n:])
    return (None, ())

def check_rel_lookup_compatibility(model, target_opts, field):

    def check(opts):
        return model._meta.concrete_model == opts.concrete_model or opts.concrete_model in model._meta.all_parents or model in opts.all_parents
    return check(target_opts) or (getattr(field, 'primary_key', False) and check(field.model._meta))

def make_model_tuple(model):
    try:
        if isinstance(model, tuple):
            model_tuple = model
        elif isinstance(model, str):
            app_label, model_name = model.split('.')
            model_tuple = (app_label, model_name.lower())
        else:
            model_tuple = (model._meta.app_label, model._meta.model_name)
        assert len(model_tuple) == 2
        return model_tuple
    except (ValueError, AssertionError):
        raise ValueError("Invalid model reference '%s'. String model references must be of the form 'app_label.ModelName'." % model)

def resolve_callables(mapping):
    for k, v in mapping.items():
        yield (k, v() if callable(v) else v)

def generate_filename(self, instance, filename):
    if callable(self.upload_to):
        filename = self.upload_to(instance, filename)
    else:
        dirname = datetime.datetime.now().strftime(str(self.upload_to))
        filename = posixpath.join(dirname, filename)
    filename = validate_file_name(filename, allow_relative_path=True)
    return self.storage.generate_filename(filename)

def update_dimension_fields(self, instance, force=False, *args, **kwargs):
    has_dimension_fields = self.width_field or self.height_field
    if not has_dimension_fields or self.attname not in instance.__dict__:
        return
    file = getattr(instance, self.attname)
    if not file and (not force):
        return
    dimension_fields_filled = not (self.width_field and (not getattr(instance, self.width_field)) or (self.height_field and (not getattr(instance, self.height_field))))
    if dimension_fields_filled and (not force):
        return
    if file:
        width = file.width
        height = file.height
    else:
        width = None
        height = None
    if self.width_field:
        setattr(instance, self.width_field, width)
    if self.height_field:
        setattr(instance, self.height_field, height)

def resolve_relation(scope_model, relation):
    if relation == RECURSIVE_RELATIONSHIP_CONSTANT:
        relation = scope_model
    if isinstance(relation, str):
        if '.' not in relation:
            relation = '%s.%s' % (scope_model._meta.app_label, relation)
    return relation

def lazy_related_operation(function, model, *related_models, **kwargs):
    models = [model] + [resolve_relation(model, rel) for rel in related_models]
    model_keys = (make_model_tuple(m) for m in models)
    apps = model._meta.apps
    return apps.lazy_model_operation(partial(function, **kwargs), *model_keys)

def _check_clashes(self):
    from django.db.models.base import ModelBase
    errors = []
    opts = self.model._meta
    if not isinstance(self.remote_field.model, ModelBase):
        return []
    rel_opts = self.remote_field.model._meta
    rel_is_hidden = self.remote_field.hidden
    rel_name = self.remote_field.accessor_name
    rel_query_name = self.related_query_name()
    field_name = '%s.%s' % (opts.label, self.name)
    potential_clashes = rel_opts.fields + rel_opts.many_to_many
    for clash_field in potential_clashes:
        if not rel_is_hidden and clash_field.name == rel_name:
            clash_name = f'{rel_opts.label}.{clash_field.name}'
            errors.append(checks.Error(f"Reverse accessor '{rel_opts.object_name}.{rel_name}' for '{field_name}' clashes with field name '{clash_name}'.", hint="Rename field '%s', or add/change a related_name argument to the definition for field '%s'." % (clash_name, field_name), obj=self, id='fields.E302'))
        if clash_field.name == rel_query_name:
            clash_name = f'{rel_opts.label}.{clash_field.name}'
            errors.append(checks.Error("Reverse query name for '%s' clashes with field name '%s'." % (field_name, clash_name), hint="Rename field '%s', or add/change a related_name argument to the definition for field '%s'." % (clash_name, field_name), obj=self, id='fields.E303'))
    potential_clashes = (r for r in rel_opts.related_objects if r.field is not self)
    for clash_field in potential_clashes:
        if not rel_is_hidden and clash_field.accessor_name == rel_name:
            clash_name = f'{clash_field.related_model._meta.label}.{clash_field.field.name}'
            errors.append(checks.Error(f"Reverse accessor '{rel_opts.object_name}.{rel_name}' for '{field_name}' clashes with reverse accessor for '{clash_name}'.", hint="Add or change a related_name argument to the definition for '%s' or '%s'." % (field_name, clash_name), obj=self, id='fields.E304'))
        if clash_field.accessor_name == rel_query_name:
            clash_name = f'{clash_field.related_model._meta.label}.{clash_field.field.name}'
            errors.append(checks.Error("Reverse query name for '%s' clashes with reverse query name for '%s'." % (field_name, clash_name), hint="Add or change a related_name argument to the definition for '%s' or '%s'." % (field_name, clash_name), obj=self, id='fields.E305'))
    if not rel_is_hidden:
        manager_names = {m.name for m in rel_opts.managers}
        if rel_name in manager_names:
            errors.append(checks.Error(f"Related name '{rel_name}' for '{field_name}' clashes with the name of a model manager.", hint="Rename the model manager or change the related_name argument in the definition for field '%s'." % field_name, obj=self, id='fields.E348'))
    return errors

def get_reverse_related_filter(self, obj):
    base_q = Q.create([(rh_field.attname, getattr(obj, lh_field.attname)) for lh_field, rh_field in self.related_fields])
    descriptor_filter = self.get_extra_descriptor_filter(obj)
    if isinstance(descriptor_filter, dict):
        return base_q & Q(**descriptor_filter)
    elif descriptor_filter:
        return base_q & descriptor_filter
    return base_q

@property
def swappable_setting(self):
    if self.swappable:
        if isinstance(self.remote_field.model, str):
            to_string = self.remote_field.model
        else:
            to_string = self.remote_field.model._meta.label
        return apps.get_swappable_settings_name(to_string)
    return None

def get_limit_choices_to(self):
    if callable(self.remote_field.limit_choices_to):
        return self.remote_field.limit_choices_to()
    return self.remote_field.limit_choices_to

def formfield(self, **kwargs):
    defaults = {}
    if hasattr(self.remote_field, 'get_related_field'):
        limit_choices_to = self.remote_field.limit_choices_to
        defaults.update({'limit_choices_to': limit_choices_to})
    defaults.update(kwargs)
    return super().formfield(**defaults)

@property
def target_field(self):
    target_fields = self.path_infos[-1].target_fields
    if len(target_fields) > 1:
        raise exceptions.FieldError('The relation has multiple target fields, but only single target field was asked for')
    return target_fields[0]

def get_default(self):
    field_default = super().get_default()
    if isinstance(field_default, self.remote_field.model):
        return getattr(field_default, self.target_field.attname)
    return field_default

def _get_path_info(self, direct=False, filtered_relation=None):
    int_model = self.remote_field.through
    linkfield1 = int_model._meta.get_field(self.m2m_field_name())
    linkfield2 = int_model._meta.get_field(self.m2m_reverse_field_name())
    if direct:
        join1infos = linkfield1.reverse_path_infos
        if filtered_relation:
            join2infos = linkfield2.get_path_info(filtered_relation)
        else:
            join2infos = linkfield2.path_infos
    else:
        join1infos = linkfield2.reverse_path_infos
        if filtered_relation:
            join2infos = linkfield1.get_path_info(filtered_relation)
        else:
            join2infos = linkfield1.path_infos
    join1_final = join1infos[-1].to_opts
    join2_initial = join2infos[0].from_opts
    if join1_final is join2_initial:
        intermediate_infos = []
    elif issubclass(join1_final.model, join2_initial.model):
        intermediate_infos = join1_final.get_path_to_parent(join2_initial.model)
    else:
        intermediate_infos = join2_initial.get_path_from_parent(join1_final.model)
    return [*join1infos, *intermediate_infos, *join2infos]

def _get_m2m_db_table(self, opts):
    if self.remote_field.through is not None:
        return self.remote_field.through._meta.db_table
    elif self.db_table:
        return self.db_table
    else:
        m2m_table_name = '%s_%s' % (utils.strip_quotes(opts.db_table), self.name)
        return utils.truncate_name(m2m_table_name, connection.ops.max_name_length())

def _get_m2m_attr(self, related, attr):
    cache_attr = '_m2m_%s_cache' % attr
    if hasattr(self, cache_attr):
        return getattr(self, cache_attr)
    if self.remote_field.through_fields is not None:
        link_field_name = self.remote_field.through_fields[0]
    else:
        link_field_name = None
    for f in self.remote_field.through._meta.fields:
        if f.is_relation and f.remote_field.model == related.related_model and (link_field_name is None or link_field_name == f.name):
            setattr(self, cache_attr, getattr(f, attr))
            return getattr(self, cache_attr)

def _get_m2m_reverse_attr(self, related, attr):
    cache_attr = '_m2m_reverse_%s_cache' % attr
    if hasattr(self, cache_attr):
        return getattr(self, cache_attr)
    found = False
    if self.remote_field.through_fields is not None:
        link_field_name = self.remote_field.through_fields[1]
    else:
        link_field_name = None
    for f in self.remote_field.through._meta.fields:
        if f.is_relation and f.remote_field.model == related.model:
            if link_field_name is None and related.related_model == related.model:
                if found:
                    setattr(self, cache_attr, getattr(f, attr))
                    break
                else:
                    found = True
            elif link_field_name is None or link_field_name == f.name:
                setattr(self, cache_attr, getattr(f, attr))
                break
    return getattr(self, cache_attr)

def __get__(self, instance, cls=None):
    if instance is None:
        return self
    try:
        rel_obj = self.field.get_cached_value(instance)
    except KeyError:
        rel_obj = None
        has_value = None not in self.field.get_local_related_value(instance)
        if has_value:
            model = self.field.model
            for current_instance, ancestor in _traverse_ancestors(model, instance):
                if ancestor:
                    rel_obj = self.field.get_cached_value(ancestor, default=None)
                    if rel_obj is not None:
                        break
        if rel_obj is None and has_value:
            instance._state.fetch_mode.fetch(self, instance)
            return self.field.get_cached_value(instance)
        self.field.set_cached_value(instance, rel_obj)
    if rel_obj is None and (not self.field.null):
        raise self.RelatedObjectDoesNotExist('%s has no %s.' % (self.field.model.__name__, self.field.name))
    else:
        return rel_obj

def __set__(self, instance, value):
    if value is not None and (not isinstance(value, self.field.remote_field.model._meta.concrete_model)):
        raise ValueError('Cannot assign "%r": "%s.%s" must be a "%s" instance.' % (value, instance._meta.object_name, self.field.name, self.field.remote_field.model._meta.object_name))
    elif value is not None:
        if instance._state.db is None:
            instance._state.db = router.db_for_write(instance.__class__, instance=value)
        if value._state.db is None:
            value._state.db = router.db_for_write(value.__class__, instance=instance)
        if not router.allow_relation(value, instance):
            raise ValueError('Cannot assign "%r": the current database router prevents this relation.' % value)
    remote_field = self.field.remote_field
    if value is None:
        related = self.field.get_cached_value(instance, default=None)
        if related is not None:
            remote_field.set_cached_value(related, None)
        for lh_field, rh_field in self.field.related_fields:
            setattr(instance, lh_field.attname, None)
    else:
        for lh_field, rh_field in self.field.related_fields:
            setattr(instance, lh_field.attname, getattr(value, rh_field.attname))
    self.field.set_cached_value(instance, value)
    if value is not None and (not remote_field.multiple):
        remote_field.set_cached_value(value, instance)

def __get__(self, instance, cls=None):
    if instance is None:
        return self
    try:
        rel_obj = self.related.get_cached_value(instance)
    except KeyError:
        if not instance._is_pk_set():
            rel_obj = None
        else:
            instance._state.fetch_mode.fetch(self, instance)
            rel_obj = self.related.get_cached_value(instance)
        self.related.set_cached_value(instance, rel_obj)
    if rel_obj is None:
        raise self.RelatedObjectDoesNotExist('%s has no %s.' % (instance.__class__.__name__, self.related.accessor_name))
    else:
        return rel_obj

@property
def field(self):
    return self.related

def __set__(self, instance, value):
    if value is None:
        rel_obj = self.related.get_cached_value(instance, default=None)
        if rel_obj is not None:
            self.related.delete_cached_value(instance)
            setattr(rel_obj, self.related.field.name, None)
    elif not isinstance(value, self.related.related_model):
        raise ValueError('Cannot assign "%r": "%s.%s" must be a "%s" instance.' % (value, instance._meta.object_name, self.related.accessor_name, self.related.related_model._meta.object_name))
    else:
        if instance._state.db is None:
            instance._state.db = router.db_for_write(instance.__class__, instance=value)
        if value._state.db is None:
            value._state.db = router.db_for_write(value.__class__, instance=instance)
        if not router.allow_relation(value, instance):
            raise ValueError('Cannot assign "%r": the current database router prevents this relation.' % value)
        related_pk = tuple((getattr(instance, field.attname) for field in self.related.field.foreign_related_fields))
        for index, field in enumerate(self.related.field.local_related_fields):
            setattr(value, field.attname, related_pk[index])
        self.related.set_cached_value(instance, value)
        self.related.field.set_cached_value(value, instance)

def __get__(self, instance, cls=None):
    if instance is None:
        return self
    return self.related_manager_cls(instance)

def create_reverse_many_to_one_manager(superclass, rel):

    class RelatedManager(superclass, AltersData):

        def __init__(self, instance):
            super().__init__()
            self.instance = instance
            self.model = rel.related_model
            self.field = rel.field
            self.core_filters = {self.field.name: instance}

        def __call__(self, *, manager):
            manager = getattr(self.model, manager)
            manager_class = create_reverse_many_to_one_manager(manager.__class__, rel)
            return manager_class(self.instance)
        do_not_call_in_templates = True

        def _check_fk_val(self):
            for field in self.field.foreign_related_fields:
                if getattr(self.instance, field.attname) is None:
                    raise ValueError(f'"{self.instance!r}" needs to have a value for field "{field.attname}" before this relationship can be used.')

        def _apply_rel_filters(self, queryset):
            """
            Filter the queryset for the instance this manager is bound to.
            """
            db = self._db or router.db_for_read(self.model, instance=self.instance)
            empty_strings_as_null = connections[db].features.interprets_empty_strings_as_nulls
            with queryset._avoid_cloning():
                queryset._add_hints(instance=self.instance)
                if self._db:
                    queryset = queryset.using(self._db)
                queryset._fetch_mode = self.instance._state.fetch_mode
                queryset._defer_next_filter = True
                queryset = queryset.filter(**self.core_filters)
            for field in self.field.foreign_related_fields:
                val = getattr(self.instance, field.attname)
                if val is None or (val == '' and empty_strings_as_null):
                    return queryset.none()
            if self.field.many_to_one:
                try:
                    target_field = self.field.target_field
                except FieldError:
                    rel_obj_id = tuple([getattr(self.instance, target_field.attname) for target_field in self.field.path_infos[-1].target_fields])
                else:
                    rel_obj_id = getattr(self.instance, target_field.attname)
                queryset._known_related_objects = {self.field: {rel_obj_id: self.instance}}
            return queryset

        def _remove_prefetched_objects(self):
            try:
                self.instance._prefetched_objects_cache.pop(self.field.remote_field.cache_name)
            except (AttributeError, KeyError):
                pass

        def get_queryset(self):
            if not self.instance._is_pk_set():
                raise ValueError(f'{self.instance.__class__.__name__!r} instance needs to have a primary key value before this relationship can be used.')
            try:
                return self.instance._prefetched_objects_cache[self.field.remote_field.cache_name]
            except (AttributeError, KeyError):
                queryset = super().get_queryset()
                return self._apply_rel_filters(queryset)

        def get_prefetch_querysets(self, instances, querysets=None):
            _cloning_disabled = False
            if querysets:
                if len(querysets) != 1:
                    raise ValueError('querysets argument of get_prefetch_querysets() should have a length of 1.')
                queryset = querysets[0]
            else:
                _cloning_disabled = True
                queryset = super().get_queryset()._disable_cloning()
            queryset._add_hints(instance=instances[0])
            queryset = queryset.using(queryset._db or self._db)
            rel_obj_attr = self.field.get_local_related_value
            instance_attr = self.field.get_foreign_related_value
            instances_dict = {instance_attr(inst): inst for inst in instances}
            queryset = _filter_prefetch_queryset(queryset, self.field.name, instances)
            if _cloning_disabled:
                queryset._enable_cloning()
            for rel_obj in queryset:
                if not self.field.is_cached(rel_obj):
                    instance = instances_dict[rel_obj_attr(rel_obj)]
                    self.field.set_cached_value(rel_obj, instance)
            cache_name = self.field.remote_field.cache_name
            return (queryset, rel_obj_attr, instance_attr, False, cache_name, False)

        def add(self, *objs, bulk=True):
            self._check_fk_val()
            self._remove_prefetched_objects()
