def to_python(self, value):
    if value in self.empty_values:
        return None
    if isinstance(value, datetime.datetime):
        return value.date()
    if isinstance(value, datetime.date):
        return value
    return super().to_python(value)

def to_python(self, value):
    if value in self.empty_values:
        return None
    if isinstance(value, datetime.time):
        return value
    return super().to_python(value)

def to_python(self, value):
    if value in self.empty_values:
        return None
    if isinstance(value, datetime.datetime):
        return from_current_timezone(value)
    if isinstance(value, datetime.date):
        result = datetime.datetime(value.year, value.month, value.day)
        return from_current_timezone(result)
    try:
        result = parse_datetime(value.strip())
    except ValueError:
        raise ValidationError(self.error_messages['invalid'], code='invalid')
    if not result:
        result = super().to_python(value)
    return from_current_timezone(result)

def to_python(self, data):
    f = super().to_python(data)
    if f is None:
        return None
    from PIL import Image
    if hasattr(data, 'temporary_file_path'):
        file = data.temporary_file_path()
    elif hasattr(data, 'read'):
        file = BytesIO(data.read())
    else:
        file = BytesIO(data['content'])
    try:
        image = Image.open(file)
        image.verify()
        f.image = image
        f.content_type = Image.MIME.get(image.format)
    except Exception as exc:
        raise ValidationError(self.error_messages['invalid_image'], code='invalid_image') from exc
    if hasattr(f, 'seek') and callable(f.seek):
        f.seek(0)
    return f

def to_python(self, value):
    if isinstance(value, str) and value.lower() in ('false', '0'):
        value = False
    else:
        value = bool(value)
    return super().to_python(value)

def to_python(self, value):
    if value in (True, 'True', 'true', '1'):
        return True
    elif value in (False, 'False', 'false', '0'):
        return False
    else:
        return None

def to_python(self, value):
    if value in self.empty_values:
        return ''
    return str(value)

def validate(self, value):
    super().validate(value)
    if value and (not self.valid_value(value)):
        raise ValidationError(self.error_messages['invalid_choice'], code='invalid_choice', params={'value': value})

def valid_value(self, value):
    text_value = str(value)
    for k, v in self.choices:
        if isinstance(v, (list, tuple)):
            for k2, v2 in v:
                if value == k2 or text_value == str(k2):
                    return True
        elif value == k or text_value == str(k):
            return True
    return False

def _coerce(self, value):
    if value == self.empty_value or value in self.empty_values:
        return self.empty_value
    try:
        value = self.coerce(value)
    except (ValueError, TypeError, ValidationError):
        raise ValidationError(self.error_messages['invalid_choice'], code='invalid_choice', params={'value': value})
    return value

def validate(self, value):
    if self.required and (not value):
        raise ValidationError(self.error_messages['required'], code='required')
    for val in OrderedSet(value):
        if not self.valid_value(val):
            raise ValidationError(self.error_messages['invalid_choice'], code='invalid_choice', params={'value': val})

def _coerce(self, value):
    if value == self.empty_value or value in self.empty_values:
        return self.empty_value
    new_value = []
    for choice in value:
        try:
            new_value.append(self.coerce(choice))
        except (ValueError, TypeError, ValidationError):
            raise ValidationError(self.error_messages['invalid_choice'], code='invalid_choice', params={'value': choice})
    return new_value

def clean(self, value):
    super().clean(value)
    for field in self.fields:
        value = field.clean(value)
    return value

def clean(self, value):
    clean_data = []
    errors = []
    if self.disabled and (not isinstance(value, list)):
        value = self.widget.decompress(value)
    if not value or isinstance(value, (list, tuple)):
        if not value or not [v for v in value if v not in self.empty_values]:
            if self.required:
                raise ValidationError(self.error_messages['required'], code='required')
            else:
                return self.compress([])
    else:
        raise ValidationError(self.error_messages['invalid'], code='invalid')
    for i, field in enumerate(self.fields):
        try:
            field_value = value[i]
        except IndexError:
            field_value = None
        if field_value in self.empty_values:
            if self.require_all_fields:
                if self.required:
                    raise ValidationError(self.error_messages['required'], code='required')
            elif field.required:
                if field.error_messages['incomplete'] not in errors:
                    errors.append(field.error_messages['incomplete'])
                continue
        try:
            clean_data.append(field.clean(field_value))
        except ValidationError as e:
            errors.extend((m for m in e.error_list if m not in errors))
    if errors:
        raise ValidationError(errors)
    out = self.compress(clean_data)
    self.validate(out)
    self.run_validators(out)
    return out

def order_fields(self, field_order):
    if field_order is None:
        return
    fields = {}
    for key in field_order:
        try:
            fields[key] = self.fields.pop(key)
        except KeyError:
            pass
    fields.update(self.fields)
    self.fields = fields

def _bound_items(self):
    for name in self.fields:
        yield (name, self[name])

def __iter__(self):
    for name in self.fields:
        yield self[name]

def __getitem__(self, name):
    try:
        field = self.fields[name]
    except KeyError:
        raise KeyError("Key '%s' not found in '%s'. Choices are: %s." % (name, self.__class__.__name__, ', '.join(sorted(self.fields))))
    if name not in self._bound_fields_cache:
        self._bound_fields_cache[name] = field.get_bound_field(self, name)
    return self._bound_fields_cache[name]

@property
def errors(self):
    if self._errors is None:
        self.full_clean()
    return self._errors

def add_error(self, field, error):
    if not isinstance(error, ValidationError):
        error = ValidationError(error)
    if hasattr(error, 'error_dict'):
        if field is not None:
            raise TypeError('The argument `field` must be `None` when the `error` argument is a dictionary.')
        else:
            error = error.error_dict
    else:
        error = {field or NON_FIELD_ERRORS: error.error_list}
    for field, error_list in error.items():
        if field not in self.errors:
            if field != NON_FIELD_ERRORS and field not in self.fields:
                raise ValueError("'%s' has no field named '%s'." % (self.__class__.__name__, field))
            if field == NON_FIELD_ERRORS:
                self._errors[field] = self.error_class(error_class='nonfield', renderer=self.renderer)
            else:
                self._errors[field] = self.error_class(renderer=self.renderer, field_id=self[field].auto_id)
        self._errors[field].extend(error_list)
        if field in self.cleaned_data:
            del self.cleaned_data[field]

def full_clean(self):
    self._errors = ErrorDict(renderer=self.renderer)
    if not self.is_bound:
        return
    self.cleaned_data = {}
    if self.empty_permitted and (not self.has_changed()):
        return
    self._clean_fields()
    self._clean_form()
    self._post_clean()

@property
def media(self):
    media = Media()
    for field in self.fields.values():
        media += field.widget.media
    return media

def get_initial_for_field(self, field, field_name):
    value = self.initial.get(field_name, field.initial)
    if callable(value):
        value = value()
    if isinstance(value, (datetime.datetime, datetime.time)) and (not field.widget.supports_microseconds):
        value = value.replace(microsecond=0)
    return value

@cached_property
def management_form(self):
    if self.is_bound:
        form = ManagementForm(self.data, auto_id=self.auto_id, prefix=self.prefix, renderer=self.renderer)
        form.full_clean()
    else:
        form = ManagementForm(auto_id=self.auto_id, prefix=self.prefix, initial={TOTAL_FORM_COUNT: self.total_form_count(), INITIAL_FORM_COUNT: self.initial_form_count(), MIN_NUM_FORM_COUNT: self.min_num, MAX_NUM_FORM_COUNT: self.max_num}, renderer=self.renderer)
    return form

def total_form_count(self):
    if self.is_bound:
        return min(self.management_form.cleaned_data[TOTAL_FORM_COUNT], self.absolute_max)
    else:
        initial_forms = self.initial_form_count()
        total_forms = max(initial_forms, self.min_num) + self.extra
        if initial_forms > self.max_num >= 0:
            total_forms = initial_forms
        elif total_forms > self.max_num >= 0:
            total_forms = self.max_num
    return total_forms

def initial_form_count(self):
    if self.is_bound:
        return self.management_form.cleaned_data[INITIAL_FORM_COUNT]
    else:
        initial_forms = len(self.initial) if self.initial else 0
    return initial_forms

@cached_property
def forms(self):
    return [self._construct_form(i, **self.get_form_kwargs(i)) for i in range(self.total_form_count())]

def _construct_form(self, i, **kwargs):
    defaults = {'auto_id': self.auto_id, 'prefix': self.add_prefix(i), 'error_class': self.error_class, 'use_required_attribute': False, 'renderer': self.form_renderer}
    if self.is_bound:
        defaults['data'] = self.data
        defaults['files'] = self.files
    if self.initial and 'initial' not in kwargs:
        try:
            defaults['initial'] = self.initial[i]
        except IndexError:
            pass
    if i >= self.initial_form_count() and i >= self.min_num:
        defaults['empty_permitted'] = True
    defaults.update(kwargs)
    form = self.form(**defaults)
    self.add_fields(form, i)
    return form

@property
def initial_forms(self):
    return self.forms[:self.initial_form_count()]

@property
def extra_forms(self):
    return self.forms[self.initial_form_count():]

@property
def cleaned_data(self):
    if not self.is_valid():
        raise AttributeError("'%s' object has no attribute 'cleaned_data'" % self.__class__.__name__)
    return [form.cleaned_data for form in self.forms]

@property
def deleted_forms(self):
    if not self.is_valid() or not self.can_delete:
        return []
    if not hasattr(self, '_deleted_form_indexes'):
        self._deleted_form_indexes = []
        for i, form in enumerate(self.forms):
            if i >= self.initial_form_count() and (not form.has_changed()):
                continue
            if self._should_delete_form(form):
                self._deleted_form_indexes.append(i)
    return [self.forms[i] for i in self._deleted_form_indexes]

@property
def ordered_forms(self):
    if not self.is_valid() or not self.can_order:
        raise AttributeError("'%s' object has no attribute 'ordered_forms'" % self.__class__.__name__)
    if not hasattr(self, '_ordering'):
        self._ordering = []
        for i, form in enumerate(self.forms):
            if i >= self.initial_form_count() and (not form.has_changed()):
                continue
            if self.can_delete and self._should_delete_form(form):
                continue
            self._ordering.append((i, form.cleaned_data[ORDERING_FIELD_NAME]))

        def compare_ordering_key(k):
            if k[1] is None:
                return (1, 0)
            return (0, k[1])
        self._ordering.sort(key=compare_ordering_key)
    return [self.forms[i[0]] for i in self._ordering]

def non_form_errors(self):
    if self._non_form_errors is None:
        self.full_clean()
    return self._non_form_errors

@property
def errors(self):
    if self._errors is None:
        self.full_clean()
    return self._errors

def is_valid(self):
    if not self.is_bound:
        return False
    self.errors
    forms_valid = all([form.is_valid() for form in self.forms if not (self.can_delete and self._should_delete_form(form))])
    return forms_valid and (not self.non_form_errors())

def full_clean(self):
    self._errors = []
    self._non_form_errors = self.error_class(error_class='nonform', renderer=self.renderer)
    empty_forms_count = 0
    if not self.is_bound:
        return
    if not self.management_form.is_valid():
        error = ValidationError(self.error_messages['missing_management_form'], params={'field_names': ', '.join((self.management_form.add_prefix(field_name) for field_name in self.management_form.errors))}, code='missing_management_form')
        self._non_form_errors.append(error)
    for i, form in enumerate(self.forms):
        if not form.has_changed() and i >= self.initial_form_count():
            empty_forms_count += 1
        form_errors = form.errors
        if self.can_delete and self._should_delete_form(form):
            continue
        self._errors.append(form_errors)
    try:
        if self.validate_max and self.total_form_count() - len(self.deleted_forms) > self.max_num or self.management_form.cleaned_data[TOTAL_FORM_COUNT] > self.absolute_max:
            raise ValidationError(self.error_messages['too_many_forms'] % {'num': self.max_num}, code='too_many_forms')
        if self.validate_min and self.total_form_count() - len(self.deleted_forms) - empty_forms_count < self.min_num:
            raise ValidationError(self.error_messages['too_few_forms'] % {'num': self.min_num}, code='too_few_forms')
        self.clean()
    except ValidationError as e:
        self._non_form_errors = self.error_class(e.error_list, error_class='nonform', renderer=self.renderer)

def add_fields(self, form, index):
    initial_form_count = self.initial_form_count()
    if self.can_order:
        if index is not None and index < initial_form_count:
            form.fields[ORDERING_FIELD_NAME] = IntegerField(label=_('Order'), initial=index + 1, required=False, widget=self.get_ordering_widget())
        else:
            form.fields[ORDERING_FIELD_NAME] = IntegerField(label=_('Order'), required=False, widget=self.get_ordering_widget())
    if self.can_delete and (self.can_delete_extra or (index is not None and index < initial_form_count)):
        form.fields[DELETION_FIELD_NAME] = BooleanField(label=_('Delete'), required=False, widget=self.get_deletion_widget())

def is_multipart(self):
    if self.forms:
        return self.forms[0].is_multipart()
    else:
        return self.empty_form.is_multipart()

def formset_factory(form, formset=BaseFormSet, extra=1, can_order=False, can_delete=False, max_num=None, validate_max=False, min_num=None, validate_min=False, absolute_max=None, can_delete_extra=True, renderer=None):
    if min_num is None:
        min_num = DEFAULT_MIN_NUM
    if max_num is None:
        max_num = DEFAULT_MAX_NUM
    if absolute_max is None:
        absolute_max = max_num + DEFAULT_MAX_NUM
    if max_num > absolute_max:
        raise ValueError("'absolute_max' must be greater or equal to 'max_num'.")
    attrs = {'form': form, 'extra': extra, 'can_order': can_order, 'can_delete': can_delete, 'can_delete_extra': can_delete_extra, 'min_num': min_num, 'max_num': max_num, 'absolute_max': absolute_max, 'validate_min': validate_min, 'validate_max': validate_max, 'renderer': renderer}
    form_name = form.__name__
    if form_name.endswith('Form'):
        formset_name = form_name + 'Set'
    else:
        formset_name = form_name + 'FormSet'
    return type(formset_name, (formset,), attrs)

def construct_instance(form, instance, fields=None, exclude=None):
    from django.db import models
    opts = instance._meta
    cleaned_data = form.cleaned_data
    file_field_list = []
    for f in opts.fields:
        if not f.editable or isinstance(f, models.AutoField) or f.name not in cleaned_data:
            continue
        if fields is not None and f.name not in fields:
            continue
        if exclude and f.name in exclude:
            continue
        if f.has_default() and form[f.name].field.widget.value_omitted_from_data(form.data, form.files, form.add_prefix(f.name)) and (cleaned_data.get(f.name) in form[f.name].field.empty_values):
            continue
        if isinstance(f, models.FileField):
            file_field_list.append(f)
        else:
            f.save_form_data(instance, cleaned_data[f.name])
    for f in file_field_list:
        f.save_form_data(instance, cleaned_data[f.name])
    return instance

def model_to_dict(instance, fields=None, exclude=None):
    opts = instance._meta
    data = {}
    for f in chain(opts.concrete_fields, opts.private_fields, opts.many_to_many):
        if not getattr(f, 'editable', False):
            continue
        if fields is not None and f.name not in fields:
            continue
        if exclude and f.name in exclude:
            continue
        data[f.name] = f.value_from_object(instance)
    return data

def apply_limit_choices_to_to_formfield(formfield):
    from django.db.models import Exists, OuterRef, Q
    if hasattr(formfield, 'queryset') and hasattr(formfield, 'get_limit_choices_to'):
        limit_choices_to = formfield.get_limit_choices_to()
        if limit_choices_to:
            complex_filter = limit_choices_to
            if not isinstance(complex_filter, Q):
                complex_filter = Q(**limit_choices_to)
            complex_filter &= Q(pk=OuterRef('pk'))
            formfield.queryset = formfield.queryset.filter(Exists(formfield.queryset.model._base_manager.filter(complex_filter)))

def fields_for_model(model, fields=None, exclude=None, widgets=None, formfield_callback=None, localized_fields=None, labels=None, help_texts=None, error_messages=None, field_classes=None, *, apply_limit_choices_to=True, form_declared_fields=None):
    form_declared_fields = form_declared_fields or {}
    field_dict = {}
    ignored = []
    opts = model._meta
    from django.db.models import Field as ModelField
    sortable_private_fields = [f for f in opts.private_fields if isinstance(f, ModelField)]
    for f in sorted(chain(opts.concrete_fields, sortable_private_fields, opts.many_to_many)):
        if not getattr(f, 'editable', False):
            if fields is not None and f.name in fields and (exclude is None or f.name not in exclude):
                raise FieldError("'%s' cannot be specified for %s model form as it is a non-editable field" % (f.name, model.__name__))
            continue
        if fields is not None and f.name not in fields:
            continue
        if exclude and f.name in exclude:
            continue
        if f.name in form_declared_fields:
            field_dict[f.name] = form_declared_fields[f.name]
            continue
        kwargs = {}
        if widgets and f.name in widgets:
            kwargs['widget'] = widgets[f.name]
        if localized_fields == ALL_FIELDS or (localized_fields and f.name in localized_fields):
            kwargs['localize'] = True
        if labels and f.name in labels:
            kwargs['label'] = labels[f.name]
        if help_texts and f.name in help_texts:
            kwargs['help_text'] = help_texts[f.name]
        if error_messages and f.name in error_messages:
            kwargs['error_messages'] = error_messages[f.name]
        if field_classes and f.name in field_classes:
            kwargs['form_class'] = field_classes[f.name]
        if formfield_callback is None:
            formfield = f.formfield(**kwargs)
        elif not callable(formfield_callback):
            raise TypeError('formfield_callback must be a function or callable')
        else:
            formfield = formfield_callback(f, **kwargs)
        if formfield:
            if apply_limit_choices_to:
                apply_limit_choices_to_to_formfield(formfield)
            field_dict[f.name] = formfield
        else:
            ignored.append(f.name)
    if fields:
        field_dict = {f: field_dict.get(f) for f in fields if (not exclude or f not in exclude) and f not in ignored}
    return field_dict

def _get_validation_exclusions(self):
    exclude = set()
    for f in self.instance._meta.fields:
        field = f.name
        if field not in self.fields:
            exclude.add(f.name)
        elif self._meta.fields and field not in self._meta.fields:
            exclude.add(f.name)
        elif self._meta.exclude and field in self._meta.exclude:
            exclude.add(f.name)
        elif field in self._errors:
            exclude.add(f.name)
        else:
            form_field = self.fields[field]
            field_value = self.cleaned_data.get(field)
            if not f.blank and (not form_field.required) and (field_value in form_field.empty_values):
                exclude.add(f.name)
    return exclude

def validate_unique(self):
    exclude = self._get_validation_exclusions()
    try:
        self.instance.validate_unique(exclude=exclude)
    except ValidationError as e:
        self._update_errors(e)

def validate_constraints(self):
    exclude = self._get_validation_exclusions()
    try:
        self.instance.validate_constraints(exclude=exclude)
    except ValidationError as e:
        self._update_errors(e)

def _save_m2m(self):
    cleaned_data = self.cleaned_data
    exclude = self._meta.exclude
    fields = self._meta.fields
    opts = self.instance._meta
    for f in chain(opts.many_to_many, opts.private_fields):
        if not hasattr(f, 'save_form_data'):
            continue
        if fields and f.name not in fields:
            continue
        if exclude and f.name in exclude:
            continue
        if f.name in cleaned_data:
            f.save_form_data(self.instance, cleaned_data[f.name])

def save(self, commit=True):
    if self.errors:
        raise ValueError("The %s could not be %s because the data didn't validate." % (self.instance._meta.object_name, 'created' if self.instance._state.adding else 'changed'))
    if commit:
        self.instance.save()
        self._save_m2m()
    else:
        self.save_m2m = self._save_m2m
    return self.instance

def modelform_factory(model, form=ModelForm, fields=None, exclude=None, formfield_callback=None, widgets=None, localized_fields=None, labels=None, help_texts=None, error_messages=None, field_classes=None):
    attrs = {'model': model}
    if fields is not None:
        attrs['fields'] = fields
    if exclude is not None:
        attrs['exclude'] = exclude
    if widgets is not None:
        attrs['widgets'] = widgets
    if localized_fields is not None:
        attrs['localized_fields'] = localized_fields
    if labels is not None:
        attrs['labels'] = labels
    if help_texts is not None:
        attrs['help_texts'] = help_texts
    if error_messages is not None:
        attrs['error_messages'] = error_messages
    if field_classes is not None:
        attrs['field_classes'] = field_classes
    bases = (form.Meta,) if hasattr(form, 'Meta') else ()
    Meta = type('Meta', bases, attrs)
    if formfield_callback:
        Meta.formfield_callback = staticmethod(formfield_callback)
    class_name = model.__name__ + 'Form'
    form_class_attrs = {'Meta': Meta}
    if getattr(Meta, 'fields', None) is None and getattr(Meta, 'exclude', None) is None:
        raise ImproperlyConfigured("Calling modelform_factory without defining 'fields' or 'exclude' explicitly is prohibited.")
    return type(form)(class_name, (form,), form_class_attrs)

def initial_form_count(self):
    if not self.is_bound:
        return len(self.get_queryset())
    return super().initial_form_count()

def _get_to_python(self, field):
    while field.remote_field is not None:
        field = field.remote_field.get_related_field()
    return field.to_python

def delete_existing(self, obj, commit=True):
    if commit:
        obj.delete()

def save(self, commit=True):
    if not commit:
        self.saved_forms = []

        def save_m2m():
            for form in self.saved_forms:
                form.save_m2m()
        self.save_m2m = save_m2m
    if self.edit_only:
        return self.save_existing_objects(commit)
    else:
        return self.save_existing_objects(commit) + self.save_new_objects(commit)

def add_fields(self, form, index):
    from django.db.models import AutoField, ForeignKey, OneToOneField
    self._pk_field = pk = self.model._meta.pk

    def pk_is_not_editable(pk):
        return not pk.editable or (pk.auto_created or isinstance(pk, AutoField)) or (pk.remote_field and pk.remote_field.parent_link and pk_is_not_editable(pk.remote_field.model._meta.pk))
    if pk_is_not_editable(pk) or pk.name not in form.fields:
        if form.is_bound:
            pk_value = None if form.instance._state.adding else form.instance.pk
        else:
            try:
                if index is not None:
                    pk_value = self.get_queryset()[index].pk
                else:
                    pk_value = None
            except IndexError:
                pk_value = None
        if isinstance(pk, (ForeignKey, OneToOneField)):
            qs = pk.remote_field.model._default_manager.get_queryset()
        else:
            qs = self.model._default_manager.get_queryset()
        qs = qs.using(form.instance._state.db)
        if form._meta.widgets:
            widget = form._meta.widgets.get(self._pk_field.name, HiddenInput)
        else:
            widget = HiddenInput
        form.fields[self._pk_field.name] = ModelChoiceField(qs, initial=pk_value, required=False, widget=widget)
    super().add_fields(form, index)

def _get_foreign_key(parent_model, model, fk_name=None, can_fail=False):
    from django.db.models import ForeignKey
    opts = model._meta
    if fk_name:
        fks_to_parent = [f for f in opts.fields if f.name == fk_name]
        if len(fks_to_parent) == 1:
            fk = fks_to_parent[0]
            all_parents = (*parent_model._meta.all_parents, parent_model)
            if not isinstance(fk, ForeignKey) or (fk.remote_field.model._meta.proxy and fk.remote_field.model._meta.proxy_for_model not in all_parents) or (not fk.remote_field.model._meta.proxy and fk.remote_field.model != parent_model and (fk.remote_field.model not in all_parents)):
                raise ValueError("fk_name '%s' is not a ForeignKey to '%s'." % (fk_name, parent_model._meta.label))
        elif not fks_to_parent:
            raise ValueError("'%s' has no field named '%s'." % (model._meta.label, fk_name))
    else:
        all_parents = (*parent_model._meta.all_parents, parent_model)
        fks_to_parent = [f for f in opts.fields if isinstance(f, ForeignKey) and (f.remote_field.model == parent_model or f.remote_field.model in all_parents or (f.remote_field.model._meta.proxy and f.remote_field.model._meta.proxy_for_model in all_parents))]
        if len(fks_to_parent) == 1:
            fk = fks_to_parent[0]
        elif not fks_to_parent:
            if can_fail:
                return
            raise ValueError("'%s' has no ForeignKey to '%s'." % (model._meta.label, parent_model._meta.label))
        else:
            raise ValueError("'%s' has more than one ForeignKey to '%s'. You must specify a 'fk_name' attribute." % (model._meta.label, parent_model._meta.label))
    return fk

def get_limit_choices_to(self):
    if callable(self.limit_choices_to):
        return self.limit_choices_to()
    return self.limit_choices_to

def _check_values(self, value):
    key = self.to_field_name or 'pk'
    try:
        value = frozenset(value)
    except TypeError:
        raise ValidationError(self.error_messages['invalid_list'], code='invalid_list')
    for pk in value:
        self.validate_no_null_characters(pk)
        try:
            self.queryset.filter(**{key: pk})
        except (ValueError, TypeError, ValidationError):
            raise ValidationError(self.error_messages['invalid_pk_value'], code='invalid_pk_value', params={'pk': pk})
    qs = self.queryset.filter(**{'%s__in' % key: value})
    pks = {str(getattr(o, key)) for o in qs}
    for val in value:
        if str(val) not in pks:
            raise ValidationError(self.error_messages['invalid_choice'], code='invalid_choice', params={'value': val})
    return qs

def pretty_name(name):
    if not name:
        return ''
    return name.replace('_', ' ').capitalize()

def flatatt(attrs):
    key_value_attrs = []
    boolean_attrs = []
    for attr, value in attrs.items():
        if isinstance(value, bool):
            if value:
                boolean_attrs.append((attr,))
        elif value is not None:
            key_value_attrs.append((attr, value))
    return format_html_join('', ' {}="{}"', sorted(key_value_attrs)) + format_html_join('', ' {}', sorted(boolean_attrs))

def __str__(self):
    if self.field.show_hidden_initial:
        return self.as_widget() + self.as_hidden(only_initial=True)
    return self.as_widget()

def from_current_timezone(value):
    if settings.USE_TZ and value is not None and timezone.is_naive(value):
        current_timezone = timezone.get_current_timezone()
        try:
            if timezone._datetime_ambiguous_or_imaginary(value, current_timezone):
                raise ValueError('Ambiguous or non-existent time.')
            return timezone.make_aware(value, current_timezone)
        except Exception as exc:
            raise ValidationError(_('%(datetime)s couldn’t be interpreted in time zone %(current_timezone)s; it may be ambiguous or it may not exist.'), code='ambiguous_timezone', params={'datetime': value, 'current_timezone': current_timezone}) from exc
    return value

def to_current_timezone(value):
    if settings.USE_TZ and value is not None and timezone.is_aware(value):
        return timezone.make_naive(value)
    return value

@property
def path(self):
    if self._path.startswith(('http://', 'https://', '/')):
        return self._path
    return static(self._path)

def absolute_path(self, path):
    if path.startswith(('http://', 'https://', '/')):
        return path
    return static(path)

def __getitem__(self, name):
    if name in MEDIA_TYPES:
        return Media(**{str(name): getattr(self, '_' + name)})
    raise KeyError('Unknown media type "%s"' % name)

@staticmethod
def merge(*lists):
    ts = TopologicalSorter()
    for head, *tail in filter(None, lists):
        ts.add(head)
        for item in tail:
            if head != item:
                ts.add(item, head)
            head = item
    try:
        return list(ts.static_order())
    except CycleError:
        warnings.warn('Detected duplicate Media files in an opposite order: {}'.format(', '.join((repr(list_) for list_ in lists))), MediaOrderConflictWarning)
        return list(dict.fromkeys(chain.from_iterable(filter(None, lists))))

def format_value(self, value):
    from django.db.models.expressions import DatabaseDefault
    if value == '' or value is None or isinstance(value, DatabaseDefault):
        return None
    if self.is_localized:
        return formats.localize_input(value)
    return str(value)

def render(self, name, value, attrs=None, renderer=None):
    context = self.get_context(name, value, attrs)
    return self._render(self.template_name, context, renderer)

def value_from_datadict(self, data, files, name):
    getter = files.get
    if self.allow_multiple_selected:
        try:
            getter = files.getlist
        except AttributeError:
            pass
    return getter(name)

def format_value(self, value):
    if self.is_initial(value):
        return value

def format_value(self, value):
    if value is True or value is False or value is None or (value == ''):
        return
    return str(value)

def subwidgets(self, name, value, attrs=None):
    value = self.format_value(value)
    yield from self.options(name, value, attrs)

def options(self, name, value, attrs=None):
    for group in self.optgroups(name, value, attrs):
        yield from group[1]

def optgroups(self, name, value, attrs=None):
    groups = []
    has_selected = False
    for index, (option_value, option_label) in enumerate(self.choices):
        if option_value is None:
            option_value = ''
        subgroup = []
        if isinstance(option_label, (list, tuple)):
            group_name = option_value
            subindex = 0
            choices = option_label
        else:
            group_name = None
            subindex = None
            choices = [(option_value, option_label)]
        groups.append((group_name, subgroup, index))
        for subvalue, sublabel in choices:
            selected = (not has_selected or self.allow_multiple_selected) and str(subvalue) in value
            has_selected |= selected
            subgroup.append(self.create_option(name, subvalue, sublabel, selected, index, subindex=subindex, attrs=attrs))
            if subindex is not None:
                subindex += 1
    return groups

def id_for_label(self, id_, index='0'):
    if id_ and self.add_id_index:
        id_ = '%s_%s' % (id_, index)
    return id_

def format_value(self, value):
    if value is None and self.allow_multiple_selected:
        return []
    if not isinstance(value, (tuple, list)):
        value = [value]
    return [str(v) if v is not None else '' for v in value]

@staticmethod
def _choice_has_empty_value(choice):
    value, _ = choice
    return value is None or value == ''

def use_required_attribute(self, initial):
    use_required_attribute = super().use_required_attribute(initial)
    if self.allow_multiple_selected:
        return use_required_attribute
    first_choice = next(iter(self.choices), None)
    return use_required_attribute and first_choice is not None and self._choice_has_empty_value(first_choice)

def id_for_label(self, id_, index=None):
    if index is None:
        return ''
    return super().id_for_label(id_, index)

def _get_media(self):
    media = Media()
    for w in self.widgets:
        media += w.media
    return media

def format_value(self, value):
    year, month, day = (None, None, None)
    if isinstance(value, (datetime.date, datetime.datetime)):
        year, month, day = (value.year, value.month, value.day)
    elif isinstance(value, str):
        match = self.date_re.match(value)
        if match:
            year, month, day = [int(val) or '' for val in match.groups()]
        else:
            input_format = get_format('DATE_INPUT_FORMATS')[0]
            try:
                d = datetime.datetime.strptime(value, input_format)
            except ValueError:
                pass
            else:
                year, month, day = (d.year, d.month, d.day)
    return {'year': year, 'month': month, 'day': day}

def parse_cookie(cookie):
    cookiedict = {}
    for chunk in cookie.split(';'):
        if '=' in chunk:
            key, val = chunk.split('=', 1)
        else:
            key, val = ('', chunk)
        key, val = (key.strip(), val.strip())
        if key or val:
            cookiedict[key] = cookies._unquote(val)
    return cookiedict

def __init__(self, META, input_data, upload_handlers, encoding=None):
    content_type = META.get('CONTENT_TYPE', '')
    if not content_type.startswith('multipart/'):
        raise MultiPartParserError('Invalid Content-Type: %s' % content_type)
    try:
        content_type.encode('ascii')
    except UnicodeEncodeError:
        raise MultiPartParserError('Invalid non-ASCII Content-Type in multipart: %s' % force_str(content_type))
    _, opts = parse_header_parameters(content_type)
    boundary = opts.get('boundary')
    if not boundary or not self.boundary_re.fullmatch(boundary):
        raise MultiPartParserError('Invalid boundary in multipart: %s' % force_str(boundary))
    try:
        content_length = int(META.get('CONTENT_LENGTH', 0))
    except (ValueError, TypeError):
        content_length = 0
    if content_length < 0:
        raise MultiPartParserError('Invalid content length: %r' % content_length)
    self._boundary = boundary.encode('ascii')
    self._input_data = input_data
    possible_sizes = [x.chunk_size for x in upload_handlers if x.chunk_size]
    self._chunk_size = min([2 ** 31 - 4, *possible_sizes])
    self._meta = META
    self._encoding = encoding or settings.DEFAULT_CHARSET
    self._content_length = content_length
    self._upload_handlers = upload_handlers

def _parse(self):
    from django.http import QueryDict
    encoding = self._encoding
    handlers = self._upload_handlers
    if self._content_length == 0:
        return (QueryDict(encoding=self._encoding), MultiValueDict())
    for handler in handlers:
        result = handler.handle_raw_input(self._input_data, self._meta, self._content_length, self._boundary, encoding)
        if result is not None:
            return (result[0], result[1])
    self._post = QueryDict(mutable=True)
    self._files = MultiValueDict()
    stream = LazyStream(ChunkIter(self._input_data, self._chunk_size))
    old_field_name = None
    counters = [0] * len(handlers)
    num_bytes_read = 0
    num_post_keys = 0
    num_files = 0
    read_size = None
    uploaded_file = True
    try:
        for item_type, meta_data, field_stream in Parser(stream, self._boundary):
            if old_field_name:
                self.handle_file_complete(old_field_name, counters)
                old_field_name = None
                uploaded_file = True
            if item_type in FIELD_TYPES and settings.DATA_UPLOAD_MAX_NUMBER_FIELDS is not None:
                num_post_keys += 1
                if settings.DATA_UPLOAD_MAX_NUMBER_FIELDS + 2 < num_post_keys:
                    raise TooManyFieldsSent('The number of GET/POST parameters exceeded settings.DATA_UPLOAD_MAX_NUMBER_FIELDS.')
            try:
                disposition = meta_data['content-disposition'][1]
                field_name = disposition['name'].strip()
            except (KeyError, IndexError, AttributeError):
                continue
            transfer_encoding = meta_data.get('content-transfer-encoding')
            if transfer_encoding is not None:
                transfer_encoding = transfer_encoding[0].strip()
            field_name = force_str(field_name, encoding, errors='replace')
            if item_type == FIELD:
                if settings.DATA_UPLOAD_MAX_MEMORY_SIZE is not None:
                    read_size = settings.DATA_UPLOAD_MAX_MEMORY_SIZE - num_bytes_read
                if transfer_encoding == 'base64':
                    raw_data = field_stream.read(size=read_size)
                    num_bytes_read += len(raw_data)
                    try:
                        data = base64.b64decode(raw_data, validate=True)
                    except binascii.Error:
                        data = raw_data
                else:
                    data = field_stream.read(size=read_size)
                    num_bytes_read += len(data)
                num_bytes_read += len(field_name) + 2
                if settings.DATA_UPLOAD_MAX_MEMORY_SIZE is not None and num_bytes_read > settings.DATA_UPLOAD_MAX_MEMORY_SIZE:
                    raise RequestDataTooBig('Request body exceeded settings.DATA_UPLOAD_MAX_MEMORY_SIZE.')
                self._post.appendlist(field_name, force_str(data, encoding, errors='replace'))
            elif item_type == FILE:
                num_files += 1
                if settings.DATA_UPLOAD_MAX_NUMBER_FILES is not None and num_files > settings.DATA_UPLOAD_MAX_NUMBER_FILES:
                    raise TooManyFilesSent('The number of files exceeded settings.DATA_UPLOAD_MAX_NUMBER_FILES.')
                file_name = disposition.get('filename')
                if file_name:
                    file_name = force_str(file_name, encoding, errors='replace')
                    file_name = self.sanitize_file_name(file_name)
                if not file_name:
                    continue
                content_type, content_type_extra = meta_data.get('content-type', ('', {}))
                content_type = content_type.strip()
                charset = content_type_extra.get('charset')
                try:
                    content_length = int(meta_data.get('content-length')[0])
                except (IndexError, TypeError, ValueError):
                    content_length = None
                counters = [0] * len(handlers)
                uploaded_file = False
                try:
                    for handler in handlers:
                        try:
                            handler.new_file(field_name, file_name, content_type, content_length, charset, content_type_extra)
                        except StopFutureHandlers:
                            break
                    for chunk in field_stream:
                        if transfer_encoding == 'base64':
                            stripped_parts = [b''.join(chunk.split())]
                            stripped_length = len(stripped_parts[0])
                            while stripped_length % 4 != 0:
                                over_chunk = field_stream.read(self._chunk_size)
                                if not over_chunk:
                                    break
                                over_stripped = b''.join(over_chunk.split())
                                stripped_parts.append(over_stripped)
                                stripped_length += len(over_stripped)
                            stripped_chunk = b''.join(stripped_parts)
                            try:
                                chunk = base64.b64decode(stripped_chunk, validate=True)
                            except Exception as exc:
                                raise MultiPartParserError('Could not decode base64 data.') from exc
                        for i, handler in enumerate(handlers):
                            chunk_length = len(chunk)
                            chunk = handler.receive_data_chunk(chunk, counters[i])
                            counters[i] += chunk_length
                            if chunk is None:
                                break
                except SkipFile:
                    self._close_files()
                    exhaust(field_stream)
                else:
                    old_field_name = field_name
            else:
                exhaust(field_stream)
    except StopUpload as e:
        self._close_files()
        if not e.connection_reset:
            exhaust(self._input_data)
    else:
        if not uploaded_file:
            for handler in handlers:
                handler.upload_interrupted()
        exhaust(self._input_data)
    any((handler.upload_complete() for handler in handlers))
    self._post._mutable = False
    return (self._post, self._files)

def handle_file_complete(self, old_field_name, counters):
    for i, handler in enumerate(self._upload_handlers):
        file_obj = handler.file_complete(counters[i])
        if file_obj:
            self._files.appendlist(force_str(old_field_name, self._encoding, errors='replace'), file_obj)
            break

def __next__(self):
    if self._leftover:
        output = self._leftover
        self._leftover = b''
    else:
        output = next(self._producer)
        self._unget_history = []
    self.position += len(output)
    return output

def unget(self, bytes):
    if not bytes:
        return
    self._update_unget_history(len(bytes))
    self.position -= len(bytes)
    self._leftover = bytes + self._leftover

def _update_unget_history(self, num_bytes):
    self._unget_history = [num_bytes] + self._unget_history[:49]
    number_equal = len([current_number for current_number in self._unget_history if current_number == num_bytes])
    if number_equal > 40:
        raise SuspiciousMultipartForm("The multipart parser got stuck, which shouldn't happen with normal uploaded files. Check for malicious upload activity; if there is none, report this to the Django developers.")

def _find_boundary(self, data):
    index = data.find(self._boundary)
    if index < 0:
        return None
    else:
        end = index
        next = index + len(self._boundary)
        last = max(0, end - 1)
        if data[last:last + 1] == b'\n':
            end -= 1
        last = max(0, end - 1)
        if data[last:last + 1] == b'\r':
            end -= 1
        return (end, next)

def exhaust(stream_or_iterable):
    try:
        iterator = iter(stream_or_iterable)
    except TypeError:
        iterator = ChunkIter(stream_or_iterable, 16384)
    collections.deque(iterator, maxlen=0)

def parse_boundary_stream(stream, max_header_size):
    headers_chunk_size = 1024
    while True:
        if headers_chunk_size > max_header_size:
            raise MultiPartParserError('Request max total header size exceeded.')
        chunk = stream.read(headers_chunk_size)
        header_end = chunk.find(b'\r\n\r\n')
        if header_end != -1:
            break
        stream.unget(chunk)
        if len(chunk) < headers_chunk_size:
            return (RAW, {}, stream)
        headers_chunk_size *= 2
    header = chunk[:header_end]
    stream.unget(chunk[header_end + 4:])
    TYPE = RAW
    outdict = {}
    for line in header.split(b'\r\n'):
        try:
            header_name, value_and_params = line.decode().split(':', 1)
            name = header_name.lower().rstrip(' ')
            value, params = parse_header_parameters(value_and_params.lstrip(' '))
            params = {k: v.encode() for k, v in params.items()}
        except (ValueError, LookupError):
            continue
        if name == 'content-disposition':
            TYPE = FIELD
            if params.get('filename'):
                TYPE = FILE
        outdict[name] = (value, params)
    if TYPE == RAW:
        stream.unget(chunk)
    return (TYPE, outdict, stream)

@cached_property
def accepted_types(self):
    header_value = self.headers.get('Accept', '*/*')
    return sorted((media_type for token in header_value.split(',') if token.strip() and (media_type := MediaType(token)).quality != 0), key=operator.attrgetter('quality', 'specificity'), reverse=True)

@cached_property
def accepted_types_by_precedence(self):
    return sorted(self.accepted_types, key=operator.attrgetter('specificity', 'quality'), reverse=True)

def accepted_type(self, media_type):
    media_type = MediaType(media_type)
    return next((accepted_type for accepted_type in self.accepted_types_by_precedence if media_type.match(accepted_type)), None)

def get_preferred_type(self, media_types):
    if not media_types or not self.accepted_types:
        return None
    desired_types = [(accepted_type, media_type) for media_type in media_types if (accepted_type := self.accepted_type(media_type)) is not None]
    if not desired_types:
        return None
    return min(desired_types, key=lambda t: self.accepted_types.index(t[0]))[1]

def _set_content_type_params(self, meta):
    try:
        self.content_type, self.content_params = parse_header_parameters(meta.get('CONTENT_TYPE', ''))
    except ValueError as exc:
        raise BadRequest('Invalid Content-Type header.') from exc
    if 'charset' in self.content_params:
        try:
            codecs.lookup(self.content_params['charset'])
        except LookupError:
            pass
        else:
            self.encoding = self.content_params['charset']

def _get_raw_host(self):
    if settings.USE_X_FORWARDED_HOST and 'HTTP_X_FORWARDED_HOST' in self.META:
        host = self.META['HTTP_X_FORWARDED_HOST']
    elif 'HTTP_HOST' in self.META:
        host = self.META['HTTP_HOST']
    else:
        host = self.META['SERVER_NAME']
        server_port = self.get_port()
        if server_port != ('443' if self.is_secure() else '80'):
            host = '%s:%s' % (host, server_port)
    return host

def get_host(self):
    host = self._get_raw_host()
    allowed_hosts = settings.ALLOWED_HOSTS
    if settings.DEBUG and (not allowed_hosts):
        allowed_hosts = ['.localhost', '127.0.0.1', '[::1]']
    domain, port = split_domain_port(host)
    if domain and validate_host(domain, allowed_hosts):
        return host
    else:
        msg = 'Invalid HTTP_HOST header: %r.' % host
        if domain:
            msg += ' You may need to add %r to ALLOWED_HOSTS.' % domain
        else:
            msg += ' The domain name provided is not valid according to RFC 1034/1035.'
        raise DisallowedHost(msg)

def get_port(self):
    if settings.USE_X_FORWARDED_PORT and 'HTTP_X_FORWARDED_PORT' in self.META:
        port = self.META['HTTP_X_FORWARDED_PORT']
    else:
        port = self.META['SERVER_PORT']
    return str(port)

def get_signed_cookie(self, key, default=RAISE_ERROR, salt='', max_age=None):
    try:
        cookie_value = self.COOKIES[key]
    except KeyError:
        if default is not RAISE_ERROR:
            return default
        else:
            raise
    try:
        value = signing._unsign_cookie(cookie_value, cookie_name=key, salt=salt, max_age=max_age)
    except signing.BadSignature:
        if default is not RAISE_ERROR:
            return default
        else:
            raise
    return value

def build_absolute_uri(self, location=None):
    if location is None:
        location = '//%s' % self.get_full_path()
    else:
        location = str(location)
    bits = urlsplit(location)
    if not (bits.scheme and bits.netloc):
        if bits.path.startswith('/') and (not bits.scheme) and (not bits.netloc) and ('/./' not in bits.path) and ('/../' not in bits.path):
            location = self._current_scheme_host + location.removeprefix('//')
        else:
            location = urljoin(self._current_scheme_host + self.path, location)
    return iri_to_uri(location)

@encoding.setter
def encoding(self, val):
    self._encoding = val
    if hasattr(self, 'GET'):
        del self.GET
    if hasattr(self, '_post'):
        del self._post

def parse_file_upload(self, META, post_data):
    self.upload_handlers = ImmutableList(self.upload_handlers, warning='You cannot alter upload handlers after the upload has been processed.')
    parser = self.multipart_parser_class(META, post_data, self.upload_handlers, self.encoding)
    return parser.parse()

def _load_post_and_files(self):
    if self.method != 'POST':
        self._post, self._files = (QueryDict(encoding=self._encoding), MultiValueDict())
        return
    if self._read_started and (not hasattr(self, '_body')):
        self._mark_post_parse_error()
        return
    if self.content_type == 'multipart/form-data':
        if hasattr(self, '_body'):
            data = BytesIO(self._body)
        else:
            data = self
        try:
            self._post, self._files = self.parse_file_upload(self.META, data)
        except (MultiPartParserError, TooManyFilesSent):
            self._mark_post_parse_error()
            raise
    elif self.content_type == 'application/x-www-form-urlencoded':
        if self._encoding is not None and self._encoding.lower() != 'utf-8':
            raise BadRequest("HTTP requests with the 'application/x-www-form-urlencoded' content type must be UTF-8 encoded.")
        self._post = QueryDict(self.body, encoding='utf-8')
        self._files = MultiValueDict()
    else:
        self._post, self._files = (QueryDict(encoding=self._encoding), MultiValueDict())

@classmethod
def fromkeys(cls, iterable, value='', mutable=False, encoding=None):
    q = cls('', mutable=True, encoding=encoding)
    for key in iterable:
        q.appendlist(key, value)
    if not mutable:
        q._mutable = False
    return q

def urlencode(self, safe=None):
    output = []
    if safe:
        safe = safe.encode(self.encoding)

        def encode(k, v):
            return '%s=%s' % (quote(k, safe), quote(v, safe))
    else:

        def encode(k, v):
            return urlencode({k: v})
    for k, list_ in self.lists():
        output.extend((encode(k.encode(self.encoding), str(v).encode(self.encoding)) for v in list_))
    return '&'.join(output)

@property
def specificity(self):
    if self.main_type == '*':
        return 0
    elif self.sub_type == '*':
        return 1
    elif not self.range_params:
        return 2
    return 3

def bytes_to_text(s, encoding):
    if isinstance(s, bytes):
        return str(s, encoding, 'replace')
    else:
        return s

def split_domain_port(host):
    if (match := host_validation_re.fullmatch(host.lower())):
        domain, port = match.groups(default='')
        return (domain.removesuffix('.'), port)
    return ('', '')

def __init__(self, data):
    self._store = {}
    if data:
        for header, value in self._unpack_items(data):
            self[header] = value

def _convert_to_charset(self, value, charset, mime_encode=False):
    try:
        if isinstance(value, str):
            value.encode(charset)
        elif isinstance(value, bytes):
            value = value.decode(charset)
        else:
            value = str(value)
            value.encode(charset)
        if '\n' in value or '\r' in value:
            raise BadHeaderError(f"Header values can't contain newlines (got {value!r})")
    except UnicodeError as e:
        if isinstance(value, bytes) and (b'\n' in value or b'\r' in value) or (isinstance(value, str) and ('\n' in value or '\r' in value)):
            raise BadHeaderError(f"Header values can't contain newlines (got {value!r})") from e
        if mime_encode:
            value = Header(value, 'utf-8', maxlinelen=sys.maxsize).encode()
        else:
            e.reason += ', HTTP response headers must be in %s format' % charset
            raise
    return value

def set_cookie(self, key, value='', max_age=None, expires=None, path='/', domain=None, secure=False, httponly=False, samesite=None):
    self.cookies[key] = value
    if expires is not None:
        if isinstance(expires, datetime.datetime):
            if timezone.is_naive(expires):
                expires = timezone.make_aware(expires, datetime.UTC)
            delta = expires - datetime.datetime.now(tz=datetime.UTC)
            delta += datetime.timedelta(seconds=1)
            expires = None
            if max_age is not None:
                raise ValueError("'expires' and 'max_age' can't be used together.")
            max_age = max(0, delta.days * 86400 + delta.seconds)
        else:
            self.cookies[key]['expires'] = expires
    else:
        self.cookies[key]['expires'] = ''
    if max_age is not None:
        if isinstance(max_age, datetime.timedelta):
            max_age = max_age.total_seconds()
        self.cookies[key]['max-age'] = int(max_age)
        if not expires:
            self.cookies[key]['expires'] = http_date(time.time() + max_age)
    if path is not None:
        self.cookies[key]['path'] = path
    if domain is not None:
        self.cookies[key]['domain'] = domain
    if secure:
        self.cookies[key]['secure'] = True
    if httponly:
        self.cookies[key]['httponly'] = True
    if samesite:
        if samesite.lower() not in ('lax', 'none', 'strict'):
            raise ValueError('samesite must be "lax", "none", or "strict".')
        self.cookies[key]['samesite'] = samesite

def make_bytes(self, value):
    if isinstance(value, (bytes, memoryview)):
        return bytes(value)
    if isinstance(value, str):
        return bytes(value.encode(self.charset))
    return str(value).encode(self.charset)

def set_headers(self, filelike):
    filename = getattr(filelike, 'name', '')
    filename = filename if isinstance(filename, str) else ''
    seekable = hasattr(filelike, 'seek') and (not hasattr(filelike, 'seekable') or filelike.seekable())
    if hasattr(filelike, 'tell'):
        if seekable:
            initial_position = filelike.tell()
            filelike.seek(0, io.SEEK_END)
            self.headers['Content-Length'] = filelike.tell() - initial_position
            filelike.seek(initial_position)
        elif hasattr(filelike, 'getbuffer'):
            self.headers['Content-Length'] = filelike.getbuffer().nbytes - filelike.tell()
        elif os.path.exists(filename):
            self.headers['Content-Length'] = os.path.getsize(filename) - filelike.tell()
    elif seekable:
        self.headers['Content-Length'] = sum(iter(lambda: len(filelike.read(self.block_size)), 0))
        filelike.seek(-int(self.headers['Content-Length']), io.SEEK_END)
    filename = os.path.basename(self.filename or filename)
    if self._no_explicit_content_type:
        if filename:
            content_type, encoding = mimetypes.guess_type(filename)
            content_type = {'br': 'application/x-brotli', 'bzip2': 'application/x-bzip', 'compress': 'application/x-compress', 'gzip': 'application/gzip', 'xz': 'application/x-xz'}.get(encoding, content_type)
            self.headers['Content-Type'] = content_type or 'application/octet-stream'
        else:
            self.headers['Content-Type'] = 'application/octet-stream'
    if (content_disposition := content_disposition_header(self.as_attachment, filename)):
        self.headers['Content-Disposition'] = content_disposition

def process_response(self, request, response):
    if not self._should_update_cache(request, response):
        return response
    if response.streaming or response.status_code not in (200, 304):
        return response
    if response.cookies and has_vary_header(response, 'Cookie'):
        return response
    cache_control_parts = set(split_directive_names(response.get('Cache-Control', '')))
    if cache_control_parts.intersection({'private', 'no-cache', 'no-store'}):
        return response
    if has_vary_header(response, '*'):
        return response
    timeout = self.page_timeout
    if timeout is None:
        timeout = get_max_age(response)
        if timeout is None:
            timeout = self.cache_timeout
        elif timeout == 0:
            return response
    patch_response_headers(response, timeout)
    if request.headers.get('Authorization') and 'public' not in cache_control_parts:
        patch_vary_headers(response, ('Authorization',))
    if timeout and response.status_code == 200:
        cache_key = learn_cache_key(request, response, timeout, self.key_prefix, cache=self.cache)
        if hasattr(response, 'render') and callable(response.render):
            response.add_post_render_callback(lambda r: self.cache.set(cache_key, r, timeout))
        else:
            self.cache.set(cache_key, response, timeout)
    return response

def process_request(self, request):
    user_agent = request.META.get('HTTP_USER_AGENT')
    if user_agent is not None:
        for user_agent_regex in settings.DISALLOWED_USER_AGENTS:
            if user_agent_regex.search(user_agent):
                raise PermissionDenied('Forbidden user agent')
    host = request.get_host()
    if settings.PREPEND_WWW and host and (not host.startswith('www.')):
        if self.should_redirect_with_slash(request):
            path = self.get_full_path_with_slash(request)
        else:
            path = request.get_full_path()
        return self.response_redirect_class(f'{request.scheme}://www.{host}{path}')

def should_redirect_with_slash(self, request):
    if settings.APPEND_SLASH and (not request.path_info.endswith('/')):
        urlconf = getattr(request, 'urlconf', None)
        if not is_valid_path(request.path_info, urlconf):
            match = is_valid_path('%s/' % request.path_info, urlconf)
            if match:
                view = match.func
                return getattr(view, 'should_append_slash', True)
    return False

def get_full_path_with_slash(self, request):
    new_path = request.get_full_path(force_append_slash=True)
    new_path = escape_leading_slashes(new_path)
    if settings.DEBUG and request.method in ('DELETE', 'POST', 'PUT', 'PATCH'):
        raise RuntimeError("You called this URL via %(method)s, but the URL doesn't end in a slash and you have APPEND_SLASH set. Django can't redirect to the slash URL while maintaining %(method)s data. Change your form to point to %(url)s (note the trailing slash), or set APPEND_SLASH=False in your Django settings." % {'method': request.method, 'url': request.get_host() + new_path})
    return new_path

def process_response(self, request, response):
    if response.status_code == 404 and self.should_redirect_with_slash(request):
        response = self.response_redirect_class(self.get_full_path_with_slash(request))
    if not response.streaming and (not response.has_header('Content-Length')):
        response.headers['Content-Length'] = str(len(response.content))
    return response

def process_response(self, request, response):
    if response.status_code == 404 and (not settings.DEBUG):
        domain = request.get_host()
        path = request.get_full_path()
        referer = request.META.get('HTTP_REFERER', '')
        if not self.is_ignorable_request(request, path, domain, referer):
            ua = request.META.get('HTTP_USER_AGENT', '<none>')
            ip = request.META.get('REMOTE_ADDR', '<none>')
            self.send_mail('Broken %slink on %s' % ('INTERNAL ' if self.is_internal_request(domain, referer) else '', domain), 'Referrer: %s\nRequested URL: %s\nUser agent: %s\nIP address: %s\n' % (referer, path, ua, ip))
    return response

def is_ignorable_request(self, request, uri, domain, referer):
    if not referer:
        return True
    if settings.APPEND_SLASH and uri.endswith('/') and (referer == uri[:-1]):
        return True
    if not self.is_internal_request(domain, referer) and '?' in referer:
        return True
    parsed_referer = urlsplit(referer)
    if parsed_referer.netloc in ['', domain] and parsed_referer.path == uri:
        return True
    return any((pattern.search(uri) for pattern in settings.IGNORABLE_404_URLS))

def _unmask_cipher_token(token):
    mask = token[:CSRF_SECRET_LENGTH]
    token = token[CSRF_SECRET_LENGTH:]
    chars = CSRF_ALLOWED_CHARS
    pairs = zip((chars.index(x) for x in token), (chars.index(x) for x in mask))
    return ''.join((chars[x - y] for x, y in pairs))

def get_token(request):
    if 'CSRF_COOKIE' in request.META:
        csrf_secret = request.META['CSRF_COOKIE']
        request.META['CSRF_COOKIE_NEEDS_UPDATE'] = True
    else:
        csrf_secret = _add_new_csrf_cookie(request)
    return _mask_cipher_secret(csrf_secret)

def _check_token_format(token):
    if len(token) not in (CSRF_TOKEN_LENGTH, CSRF_SECRET_LENGTH):
        raise InvalidTokenFormat(REASON_INCORRECT_LENGTH)
    if invalid_token_chars_re.search(token):
        raise InvalidTokenFormat(REASON_INVALID_CHARACTERS)

def _does_token_match(request_csrf_token, csrf_secret):
    if len(request_csrf_token) == CSRF_TOKEN_LENGTH:
        request_csrf_token = _unmask_cipher_token(request_csrf_token)
    assert len(request_csrf_token) == CSRF_SECRET_LENGTH
    return constant_time_compare(request_csrf_token, csrf_secret)

@cached_property
def allowed_origin_subdomains(self):
    allowed_origin_subdomains = defaultdict(list)
    for parsed in (urlsplit(origin) for origin in settings.CSRF_TRUSTED_ORIGINS if '*' in origin):
        allowed_origin_subdomains[parsed.scheme].append(parsed.netloc.lstrip('*'))
    return allowed_origin_subdomains

def _get_secret(self, request):
    if settings.CSRF_USE_SESSIONS:
        try:
            csrf_secret = request.session.get(CSRF_SESSION_KEY)
        except AttributeError:
            raise ImproperlyConfigured('CSRF_USE_SESSIONS is enabled, but request.session is not set. SessionMiddleware must appear before CsrfViewMiddleware in MIDDLEWARE.')
    else:
        try:
            csrf_secret = request.COOKIES[settings.CSRF_COOKIE_NAME]
        except KeyError:
            csrf_secret = None
        else:
            _check_token_format(csrf_secret)
    if csrf_secret is None:
        return None
    if len(csrf_secret) == CSRF_TOKEN_LENGTH:
        csrf_secret = _unmask_cipher_token(csrf_secret)
    return csrf_secret

def needs_etag(self, response):
    directives = split_directive_names(response.get('Cache-Control', ''))
    return 'no-store' not in directives

def using(self, *, priority=None, queue_name=None, run_after=None, backend=None):
    changes = {}
    if priority is not None:
        changes['priority'] = priority
    if queue_name is not None:
        changes['queue_name'] = queue_name
    if run_after is not None:
        changes['run_after'] = run_after
    if backend is not None:
        changes['backend'] = backend
    return replace(self, **changes)

def get_result(self, result_id):
    result = self.get_backend().get_result(result_id)
    if result.task.func != self.func:
        raise TaskResultMismatch(f'Task does not match (received {result.task.module_path!r})')
    return result

@property
def return_value(self):
    if self.status == TaskResultStatus.SUCCESSFUL:
        return self._return_value
    elif self.status == TaskResultStatus.FAILED:
        raise ValueError('Task failed')
    else:
        raise ValueError('Task has not finished yet')

def refresh(self):
    refreshed_task = self.task.get_backend().get_result(self.id)
    for attr in TASK_REFRESH_ATTRS:
        object.__setattr__(self, attr, getattr(refreshed_task, attr))

@checks.register
def check_tasks(app_configs=None, **kwargs):
    from . import task_backends
    for backend in task_backends.all():
        yield from backend.check()

@receiver(setting_changed)
def clear_tasks_handlers(*, setting, **kwargs):
    if setting == 'TASKS':
        from . import task_backends
        task_backends._settings = task_backends.settings = task_backends.configure_settings(None)
        task_backends._connections = Local()

def validate_task(self, task):
    if not is_module_level_function(task.func):
        raise InvalidTask('Task function must be defined at a module level.')
    if not self.supports_async_task and iscoroutinefunction(task.func):
        raise InvalidTask('Backend does not support async Tasks.')
    task_func_args = get_func_args(task.func)
    if task.takes_context and (not task_func_args or task_func_args[0] != 'context'):
        raise InvalidTask("Task takes context but does not have a first argument of 'context'.")
    if not self.supports_priority and task.priority != DEFAULT_TASK_PRIORITY:
        raise InvalidTask('Backend does not support setting priority of tasks.')
    if task.priority < TASK_MIN_PRIORITY or task.priority > TASK_MAX_PRIORITY or int(task.priority) != task.priority:
        raise InvalidTask(f'priority must be a whole number between {TASK_MIN_PRIORITY} and {TASK_MAX_PRIORITY}.')
    if not self.supports_defer and task.run_after is not None:
        raise InvalidTask('Backend does not support run_after.')
    if settings.USE_TZ and task.run_after is not None and (not timezone.is_aware(task.run_after)):
        raise InvalidTask('run_after must be an aware datetime.')
    if self.queues and task.queue_name not in self.queues:
        raise InvalidTask(f"Queue '{task.queue_name}' is not valid for backend.")

@abstractmethod
def enqueue(self, task, args, kwargs):
    pass

def render(self, context):
    with context.render_context.push_state(self):
        if context.template is None:
            with context.bind_template(self):
                context.template_name = self.name
                return self._render(context)
        else:
            return self._render(context)

def compile_nodelist(self):
    if self.engine.debug:
        lexer = DebugLexer(self.source)
    else:
        lexer = Lexer(self.source)
    tokens = lexer.tokenize()
    parser = Parser(tokens, self.engine.template_libraries, self.engine.template_builtins, self.origin)
    try:
        nodelist = parser.parse()
        self.extra_data = parser.extra_data
        return nodelist
    except Exception as e:
        if self.engine.debug:
            e.template_debug = self.get_exception_info(e, e.token)
        if isinstance(e, TemplateSyntaxError) and self.origin.name != UNKNOWN_SOURCE and e.args:
            raw_message = e.args[0]
            e.raw_error_message = raw_message
            e.args = (f'Template: {self.origin.name}, {raw_message}', *e.args[1:])
        raise

def tokenize(self):
    in_tag = False
    lineno = 1
    result = []
    for token_string in tag_re.split(self.template_string):
        if token_string:
            result.append(self.create_token(token_string, None, lineno, in_tag))
            lineno += token_string.count('\n')
        in_tag = not in_tag
    return result

def create_token(self, token_string, position, lineno, in_tag):
    if in_tag:
        token_start = token_string[0:2]
        if token_start == BLOCK_TAG_START:
            content = token_string[2:-2].strip()
            if self.verbatim:
                if content != self.verbatim:
                    return Token(TokenType.TEXT, token_string, position, lineno)
                self.verbatim = False
            elif content[:9] in ('verbatim', 'verbatim '):
                self.verbatim = 'end%s' % content
            return Token(TokenType.BLOCK, content, position, lineno)
        if not self.verbatim:
            content = token_string[2:-2].strip()
            if token_start == VARIABLE_TAG_START:
                return Token(TokenType.VAR, content, position, lineno)
            assert token_start == COMMENT_TAG_START
            return Token(TokenType.COMMENT, content, position, lineno)
    return Token(TokenType.TEXT, token_string, position, lineno)

def tokenize(self):
    in_tag = False
    lineno = 1
    result = []
    for token_string, position in self._tag_re_split():
        if token_string:
            result.append(self.create_token(token_string, position, lineno, in_tag))
            lineno += token_string.count('\n')
        in_tag = not in_tag
    return result

def parse(self, parse_until=None):
    if parse_until is None:
        parse_until = []
    nodelist = NodeList()
    while self.tokens:
        token = self.next_token()
        token_type = token.token_type.value
        if token_type == 0:
            self.extend_nodelist(nodelist, TextNode(token.contents), token)
        elif token_type == 1:
            if not token.contents:
                raise self.error(token, 'Empty variable tag on line %d' % token.lineno)
            try:
                filter_expression = self.compile_filter(token.contents)
            except TemplateSyntaxError as e:
                raise self.error(token, e)
            var_node = VariableNode(filter_expression)
            if '..' in str(filter_expression.var):
                warnings.warn(f"Support for double-dot lookups '..' which maps to a lookup of the empty string is deprecated.\n  Template: {self.origin.name}\n  Line: {token.lineno}", RemovedInDjango70Warning, skip_file_prefixes=django_file_prefixes())
            self.extend_nodelist(nodelist, var_node, token)
        elif token_type == 2:
            try:
                command = token.contents.split()[0]
            except IndexError:
                raise self.error(token, 'Empty block tag on line %d' % token.lineno)
            if command in parse_until:
                self.prepend_token(token)
                return nodelist
            self.command_stack.append((command, token))
            try:
                compile_func = self.tags[command]
            except KeyError:
                self.invalid_block_tag(token, command, parse_until)
            try:
                compiled_result = compile_func(self, token)
            except Exception as e:
                raise self.error(token, e)
            self.extend_nodelist(nodelist, compiled_result, token)
            self.command_stack.pop()
    if parse_until:
        self.unclosed_block_tag(parse_until)
    return nodelist

def error(self, token, e):
    if not isinstance(e, Exception):
        e = TemplateSyntaxError(e)
    if not hasattr(e, 'token'):
        e.token = token
    return e

def resolve(self, context):
    if self.lookups is not None:
        value = self._resolve_lookup(context)
    else:
        value = self.literal
    if self.translate:
        is_safe = isinstance(value, SafeData)
        msgid = value.replace('%', '%%')
        msgid = mark_safe(msgid) if is_safe else msgid
        if self.message_context:
            return pgettext_lazy(self.message_context, msgid)
        else:
            return gettext_lazy(msgid)
    return value

def _resolve_lookup(self, context):
    current = context
    try:
        for bit in self.lookups:
            try:
                if not hasattr(type(current), '__getitem__'):
                    raise TypeError
                current = current[bit]
            except (TypeError, AttributeError, KeyError, ValueError, IndexError):
                try:
                    if isinstance(current, BaseContext) and getattr(type(current), bit):
                        raise AttributeError
                    current = getattr(current, bit)
                except (TypeError, AttributeError):
                    if not isinstance(current, BaseContext) and bit in dir(current):
                        raise
                    try:
                        current = current[int(bit)]
                    except (IndexError, ValueError, KeyError, TypeError):
                        raise VariableDoesNotExist('Failed lookup for key [%s] in %r', (bit, current))
            if callable(current):
                if getattr(current, 'do_not_call_in_templates', False):
                    pass
                elif getattr(current, 'alters_data', False):
                    current = context.template.engine.string_if_invalid
                else:
                    try:
                        current = current()
                    except TypeError:
                        try:
                            current_signature = signature(current)
                        except ValueError:
                            current = context.template.engine.string_if_invalid
                        else:
                            try:
                                current_signature.bind()
                            except TypeError:
                                current = context.template.engine.string_if_invalid
                            else:
                                raise
    except Exception as e:
        template_name = getattr(context, 'template_name', None) or 'unknown'
        logger.debug("Exception while resolving variable '%s' in template '%s'.", bit, template_name, exc_info=True)
        if getattr(e, 'silent_variable_failure', False):
            current = context.template.engine.string_if_invalid
        else:
            raise
    return current

