def simple_block_tag(self, func=None, takes_context=None, name=None, end_name=None):

    def dec(func):
        nonlocal end_name
        params, varargs, varkw, defaults, kwonly, kwonly_defaults, _ = getfullargspec(unwrap(func))
        function_name = name or func.__name__
        if end_name is None:
