def __getstate__(self):
    obj_dict = self.__dict__.copy()
    if not self._is_rendered:
        raise ContentNotRenderedError('The response content must be rendered before it can be pickled.')
    for attr in self.rendering_attrs:
        if attr in obj_dict:
            del obj_dict[attr]
    return obj_dict

def resolve_template(self, template):
    if isinstance(template, (list, tuple)):
        return select_template(template, using=self.using)
    elif isinstance(template, str):
        return get_template(template, using=self.using)
    else:
        return template

@property
def rendered_content(self):
    template = self.resolve_template(self.template_name)
    context = self.resolve_context(self.context_data)
    return template.render(context, self._request)

def add_post_render_callback(self, callback):
    if self._is_rendered:
        callback(self)
    else:
        self._post_render_callbacks.append(callback)

def render(self):
    retval = self
    if not self._is_rendered:
        self.content = self.rendered_content
        for post_callback in self._post_render_callbacks:
            newretval = post_callback(retval)
            if newretval is not None:
                retval = newretval
    return retval

@content.setter
def content(self, value):
    HttpResponse.content.fset(self, value)
    self._is_rendered = True

def infix(bp, func):

    class Operator(TokenBase):
        lbp = bp

        def led(self, left, parser):
            self.first = left
            self.second = parser.expression(bp)
            return self

        def eval(self, context):
            try:
                return func(context, self.first, self.second)
            except Exception:
                return False
    return Operator

def prefix(bp, func):

    class Operator(TokenBase):
        lbp = bp

        def nud(self, parser):
            self.first = parser.expression(bp)
            self.second = None
            return self

        def eval(self, context):
            try:
                return func(context, self.first)
            except Exception:
                return False
    return Operator

def __init__(self, templates=None):
    self._templates = templates
    self._engines = {}

@functools.lru_cache
def get_app_template_dirs(dirname):
    return tuple((path for app_config in apps.get_app_configs() if app_config.path and (path := (Path(app_config.path) / dirname)).is_dir()))

@cached_property
def template_dirs(self):
    template_dirs = tuple(self.dirs)
    if self.app_dirs:
        template_dirs += get_app_template_dirs(self.app_dirname)
    return template_dirs

def iter_template_filenames(self, template_name):
    for template_dir in self.template_dirs:
        try:
            yield safe_join(template_dir, template_name)
        except SuspiciousFileOperation:
            pass

def copy_exception(exc, backend=None):
    backend = backend or exc.backend
    new = exc.__class__(*exc.args, tried=exc.tried, backend=backend, chain=exc.chain)
    if hasattr(exc, 'template_debug'):
        new.template_debug = exc.template_debug
    return new

def reraise(exc, backend):
    new = copy_exception(exc, backend)
    raise new from exc

def get_template_tag_modules():
    candidates = ['django.templatetags']
    candidates.extend((f'{app_config.name}.templatetags' for app_config in apps.get_app_configs()))
    for candidate in candidates:
        try:
            pkg = import_module(candidate)
        except ImportError:
            continue
        if hasattr(pkg, '__path__'):
            for name in get_package_libraries(pkg):
                yield (name.removeprefix(candidate).lstrip('.'), name)

def get_package_libraries(pkg):
    for entry in walk_packages(pkg.__path__, pkg.__name__ + '.'):
        try:
            module = import_module(entry[1])
        except ImportError as e:
            raise InvalidTemplateLibrary("Invalid template library specified. ImportError raised when trying to load '%s': %s" % (entry[1], e)) from e
        if hasattr(module, 'register'):
            yield entry[1]

def get_exception_info(exception):
    context_lines = 10
    lineno = exception.lineno
    source = exception.source
    if source is None:
        exception_file = Path(exception.filename)
        if exception_file.exists():
            source = exception_file.read_text()
    if source is not None:
        lines = list(enumerate(source.strip().split('\n'), start=1))
        during = lines[lineno - 1][1]
        total = len(lines)
        top = max(0, lineno - context_lines - 1)
        bottom = min(total, lineno + context_lines)
    else:
        during = ''
        lines = []
        total = top = bottom = 0
    return {'name': exception.filename, 'message': exception.message, 'source_lines': lines[top:bottom], 'line': lineno, 'before': '', 'during': during, 'after': '', 'total': total, 'top': top, 'bottom': bottom}

def get_template(self, template_name, skip=None):
    tried = []
    for origin in self.get_template_sources(template_name):
        if skip is not None and origin in skip:
            tried.append((origin, 'Skipped to avoid recursion'))
            continue
        try:
            contents = self.get_contents(origin)
        except TemplateDoesNotExist:
            tried.append((origin, 'Source does not exist'))
            continue
        else:
            return Template(contents, origin, origin.template_name, self.engine)
    raise TemplateDoesNotExist(template_name, tried=tried)

def get_template(self, template_name, skip=None):
    key = self.cache_key(template_name, skip)
    cached = self.get_template_cache.get(key)
    if cached:
        if isinstance(cached, type) and issubclass(cached, TemplateDoesNotExist):
            raise cached(template_name)
        elif isinstance(cached, TemplateDoesNotExist):
            raise copy_exception(cached)
        return cached
    try:
        template = super().get_template(template_name, skip)
    except TemplateDoesNotExist as e:
        self.get_template_cache[key] = copy_exception(e) if self.engine.debug else TemplateDoesNotExist
        raise
    else:
        self.get_template_cache[key] = template
    return template

def cache_key(self, template_name, skip=None):
    skip_prefix = ''
    if skip:
        matching = [origin.name for origin in skip if origin.template_name == template_name]
        if matching:
            skip_prefix = self.generate_hash(matching)
    return '-'.join((s for s in (str(template_name), skip_prefix) if s))

def get_template_sources(self, template_name):
    for template_dir in self.get_dirs():
        try:
            name = safe_join(template_dir, template_name)
        except SuspiciousFileOperation:
            continue
        yield Origin(name=name, template_name=template_name, loader=self)

@register.tag('cache')
def do_cache(parser, token):
    nodelist = parser.parse(('endcache',))
    parser.delete_first_token()
    tokens = token.split_contents()
    if len(tokens) < 3:
        raise TemplateSyntaxError("'%r' tag requires at least 2 arguments." % tokens[0])
    if len(tokens) > 3 and tokens[-1].startswith('using='):
        cache_name = parser.compile_filter(tokens[-1].removeprefix('using='))
        tokens = tokens[:-1]
    else:
        cache_name = None
    return CacheNode(nodelist, parser.compile_filter(tokens[1]), tokens[2], [parser.compile_filter(t) for t in tokens[3:]], cache_name)

