    return True

def html_safe(klass):
    if '__html__' in klass.__dict__:
        raise ValueError("can't apply @html_safe to %s because it defines __html__()." % klass.__name__)
    if '__str__' not in klass.__dict__:
        raise ValueError("can't apply @html_safe to %s because it doesn't define __str__()." % klass.__name__)
    klass_str = klass.__str__
    klass.__str__ = lambda self: mark_safe(klass_str(self))
    klass.__html__ = lambda self: str(self)
    return klass

def urlencode(query, doseq=False):
    if isinstance(query, MultiValueDict):
        query = query.lists()
    elif hasattr(query, 'items'):
        query = query.items()
    query_params = []
    for key, value in query:
        if value is None:
            raise TypeError("Cannot encode None for key '%s' in a query string. Did you mean to pass an empty string or omit the value?" % key)
        elif not doseq or isinstance(value, (str, bytes)):
            query_val = value
        else:
            try:
                itr = iter(value)
            except TypeError:
                query_val = value
            else:
                query_val = []
                for item in itr:
                    if item is None:
                        raise TypeError("Cannot encode None for key '%s' in a query string. Did you mean to pass an empty string or omit the value?" % key)
                    elif not isinstance(item, bytes):
                        item = str(item)
                    query_val.append(item)
        query_params.append((key, query_val))
    return original_urlencode(query_params, doseq)

def parse_http_date(date):
    for regex in (RFC1123_DATE, RFC850_DATE, ASCTIME_DATE):
        m = regex.match(date)
        if m is not None:
            break
    else:
        raise ValueError('%r is not in a valid HTTP date format' % date)
    try:
        year = int(m['year'])
        if year < 100:
            current_year = datetime.now(tz=UTC).year
            current_century = current_year - current_year % 100
            if year - current_year % 100 > 50:
                year += current_century - 100
            else:
                year += current_century
        month = MONTHS.index(m['mon'].lower()) + 1
        day = int(m['day'])
        hour = int(m['hour'])
        min = int(m['min'])
        sec = int(m['sec'])
        result = datetime(year, month, day, hour, min, sec, tzinfo=UTC)
        return int(result.timestamp())
    except Exception as exc:
        raise ValueError('%r is not a valid date' % date) from exc

def parse_http_date_safe(date):
    try:
        return parse_http_date(date)
    except Exception:
        pass

def base36_to_int(s):
    if len(s) > 13:
        raise ValueError('Base36 input too large')
    return int(s, 36)

def int_to_base36(i):
    char_set = '0123456789abcdefghijklmnopqrstuvwxyz'
    if i < 0:
        raise ValueError('Negative base36 conversion input.')
    if i < 36:
        return char_set[i]
    b36_parts = []
    while i != 0:
        i, n = divmod(i, 36)
        b36_parts.append(char_set[n])
    return ''.join(reversed(b36_parts))

def urlsafe_base64_decode(s):
    s = s.encode()
    try:
        return base64.urlsafe_b64decode(s.ljust(len(s) + len(s) % 4, b'='))
    except (LookupError, BinasciiError) as e:
        raise ValueError(e)

def split_header_value(value, sep=','):
    for part in value.split(sep):
        if (stripped := part.strip()):
            yield stripped

def split_directive_names(value):
    for part in split_header_value(value):
        yield part.split('=', 1)[0].strip().lower()

def parse_etags(etag_str):
    if etag_str.strip() == '*':
        return ['*']
    else:
        etag_matches = (ETAG_MATCH.match(etag) for etag in split_header_value(etag_str))
        return [match[1] for match in etag_matches if match]

def quote_etag(etag_str):
    if ETAG_MATCH.match(etag_str):
        return etag_str
    else:
        return '"%s"' % etag_str

def is_same_domain(host, pattern):
    if not pattern:
        return False
    pattern = pattern.lower()
    return pattern[0] == '.' and (host.endswith(pattern) or host == pattern[1:]) or pattern == host

def url_has_allowed_host_and_scheme(url, allowed_hosts, require_https=False):
    if url is not None:
        url = url.strip()
    if not url:
        return False
    if allowed_hosts is None:
        allowed_hosts = set()
    elif isinstance(allowed_hosts, str):
        allowed_hosts = {allowed_hosts}
    return _url_has_allowed_host_and_scheme(url, allowed_hosts, require_https=require_https) and _url_has_allowed_host_and_scheme(url.replace('\\', '/'), allowed_hosts, require_https=require_https)

def escape_leading_slashes(url):
    if url.startswith('//'):
        url = '/%2F{}'.format(url.removeprefix('//'))
    return url

def parse_header_parameters(line, max_length=MAX_HEADER_LENGTH):
    if not line:
        return ('', {})
    if max_length is not None and len(line) > max_length:
        raise ValueError('Unable to parse header parameters (value too long).')
    if ';' not in line:
        return (line.strip().lower(), {})
    parts = _parseparam(';' + line)
    key = parts.__next__().lower()
    pdict = {}
    for p in parts:
        i = p.find('=')
        if i >= 0:
            has_encoding = False
            name = p[:i].strip().lower()
            if name.endswith('*'):
                name = name[:-1]
                if p.count("'") == 2:
                    has_encoding = True
            value = p[i + 1:].strip()
            if len(value) >= 2 and value[0] == value[-1] == '"':
                value = value[1:-1]
                value = value.replace('\\\\', '\\').replace('\\"', '"')
            if has_encoding:
                encoding, lang, value = value.split("'")
                try:
                    value = unquote(value, encoding=encoding)
                except (LookupError, UnicodeDecodeError):
                    msg = f'Invalid encoding {encoding!r} for RFC 2231 param.'
                    raise ValueError(msg)
            pdict[name] = value
    return (key, pdict)

def content_disposition_header(as_attachment, filename):
    if filename:
        disposition = 'attachment' if as_attachment else 'inline'
        try:
            filename.encode('ascii')
            is_ascii = True
        except UnicodeEncodeError:
            is_ascii = False
        quotable_characters = '^[\\t \\x21-\\x7e]*$'
        if is_ascii and re.match(quotable_characters, filename):
            file_expr = 'filename="{}"'.format(filename.replace('\\', '\\\\').replace('"', '\\"'))
        else:
            file_expr = "filename*=utf-8''{}".format(quote(filename))
        return f'{disposition}; {file_expr}'
    elif as_attachment:
        return 'attachment'
    else:
        return None

def get_func_full_args(func):
    params = _get_callable_parameters(func)
    args = []
    for param in params:
        name = param.name
        if name == 'self':
            continue
        if param.kind == inspect.Parameter.VAR_POSITIONAL:
            name = '*' + name
        elif param.kind == inspect.Parameter.VAR_KEYWORD:
            name = '**' + name
        if param.default != inspect.Parameter.empty:
            args.append((name, param.default))
        else:
            args.append((name,))
    return args

def method_has_no_args(meth):
    count = len([p for p in _get_callable_parameters(meth) if p.kind in ARG_KINDS])
    return count == 0 if inspect.ismethod(meth) else count == 1

@contextmanager
def lazy_annotations():
    if PY315 or not PY314:
        yield
        return
    with lock:
        original_helper = inspect._signature_from_callable
        inspect._signature_from_callable = safe_signature_from_callable
        try:
            yield
        finally:
            inspect._signature_from_callable = original_helper

def getfullargspec(*args, annotation_format=None, **kwargs):
    if PY315:
        return inspect.getfullargspec(*args, **kwargs, annotation_format=annotationlib.Format.FORWARDREF)
    if PY314:
        with lazy_annotations():
            return inspect.getfullargspec(*args, **kwargs)
    else:
        return inspect.getfullargspec(*args, **kwargs)

def signature(obj):
    if PY314:
        return inspect.signature(obj, annotation_format=annotationlib.Format.FORWARDREF)
    else:
        return inspect.signature(obj)

def clean_ipv6_address(ip_str, unpack_ipv4=False, error_message=_('This is not a valid IPv6 address.'), max_length=MAX_IPV6_ADDRESS_LENGTH):
    try:
        addr = _ipv6_address_from_str(ip_str, max_length)
    except ValueError:
        raise ValidationError(error_message, code='invalid', params={'protocol': _('IPv6')})
    if unpack_ipv4 and addr.ipv4_mapped:
        return str(addr.ipv4_mapped)
    elif addr.ipv4_mapped:
        return '::ffff:%s' % str(addr.ipv4_mapped)
    return str(addr)

def is_valid_ipv6_address(ip_addr):
    if isinstance(ip_addr, ipaddress.IPv6Address):
        return True
    try:
        _ipv6_address_from_str(ip_addr)
    except (TypeError, ValueError):
        return False
    return True

def normalize_json(obj):
    match obj:
        case Mapping():
            return {normalize_json(k): normalize_json(v) for k, v in obj.items()}
        case bytes():
            try:
                return obj.decode('utf-8')
            except UnicodeDecodeError:
                raise ValueError(f'Unsupported value: {type(obj)}')
        case str() | int() | float() | bool() | None:
            return obj
        case Sequence():
            return [normalize_json(v) for v in obj]
        case _:
            raise TypeError(f'Unsupported type: {type(obj)}')

def log_message(logger, message, *args, level=None, status_code=None, request=None, exception=None, **extra):
    extra = {'request': request, **extra}
    if status_code is not None:
        extra['status_code'] = status_code
        if level is None:
            if status_code >= 500:
                level = 'error'
            elif status_code >= 400:
                level = 'warning'
    escaped_args = tuple((a.encode('unicode_escape').decode('ascii') if isinstance(a, str) else a for a in args))
    getattr(logger, level or 'info')(message, *escaped_args, extra=extra, exc_info=exception)

def log_response(message, *args, response=None, request=None, logger=request_logger, level=None, exception=None):
    if getattr(response, '_has_been_logged', False):
        return
    log_message(logger, message, *args, level=level, status_code=response.status_code, request=request, exception=exception)
    response._has_been_logged = True

def sentence():
    sections = [' '.join(random.sample(WORDS, random.randint(3, 12))) for i in range(random.randint(1, 5))]
    s = ', '.join(sections)
    return '%s%s%s' % (s[0].upper(), s[1:], random.choice('?.'))

def paragraphs(count, common=True):
    paras = []
    for i in range(count):
        if common and i == 0:
            paras.append(COMMON_P)
        else:
            paras.append(paragraph())
    return paras

def words(count, common=True):
    word_list = list(COMMON_WORDS) if common else []
    c = len(word_list)
    if count > c:
        count -= c
        while count > 0:
            c = min(count, len(WORDS))
            count -= c
            word_list += random.sample(WORDS, c)
    else:
        word_list = word_list[:count]
    return ' '.join(word_list)

def import_string(dotted_path):
    if '.' not in dotted_path:
        return cached_import(dotted_path)
    else:
        try:
            cached_import(dotted_path)
        except ImportError:
            pass
        module_path, class_name = dotted_path.rsplit('.', 1)
        module = cached_import(module_path)
        try:
            import_target = getattr(module, class_name)
        except AttributeError:
            try:
                import_target = cached_import(dotted_path)
            except ImportError as err:
                raise ImportError('Module "%s" does not define a "%s" attribute/class' % (module_path, class_name)) from err
        return import_target

def autodiscover_modules(*args, **kwargs):
    from django.apps import apps
    register_to = kwargs.get('register_to')
    for app_config in apps.get_app_configs():
        for module_to_search in args:
            try:
                if register_to:
                    before_import_registry = copy.copy(register_to._registry)
                import_module('%s.%s' % (app_config.name, module_to_search))
            except Exception:
                if register_to:
                    register_to._registry = before_import_registry
                if module_has_submodule(app_config.module, module_to_search):
                    raise

def module_has_submodule(package, module_name):
    try:
        package_name = package.__name__
        package_path = package.__path__
    except AttributeError:
        return False
    full_module_name = package_name + '.' + module_name
    try:
        return importlib_find(full_module_name, package_path) is not None
    except ModuleNotFoundError:
        return False

def module_dir(module):
    paths = list(getattr(module, '__path__', []))
    if len(paths) == 1:
        return paths[0]
    else:
        filename = getattr(module, '__file__', None)
        if filename is not None:
            return os.path.dirname(filename)
    raise ValueError('Cannot determine directory containing %s' % module)

def format(number, decimal_sep, decimal_pos=None, grouping=0, thousand_sep='', force_grouping=False, use_l10n=None):
    if number is None or number == '':
        return mark_safe(number)
    if use_l10n is None:
        use_l10n = True
    use_grouping = use_l10n and settings.USE_THOUSAND_SEPARATOR
    use_grouping = use_grouping or force_grouping
    use_grouping = use_grouping and grouping != 0
    if isinstance(number, int) and (not use_grouping) and (not decimal_pos):
        return mark_safe(number)
    sign = ''
    if isinstance(number, float) and 'e' in str(number).lower():
        number = Decimal(str(number))
    if isinstance(number, Decimal):
        if decimal_pos is not None:
            cutoff = Decimal('0.' + '1'.rjust(decimal_pos, '0'))
            if abs(number) < cutoff:
                number = Decimal('0')
        if not number.is_finite():
            return str(number)
        _, digits, exponent = number.as_tuple()
        if abs(exponent) + len(digits) > 200:
            number = '{:e}'.format(number)
            coefficient, exponent = number.split('e')
            coefficient = format(coefficient, decimal_sep, decimal_pos, grouping, thousand_sep, force_grouping, use_l10n)
            return '{}e{}'.format(coefficient, exponent)
        else:
            str_number = '{:f}'.format(number)
    else:
        str_number = str(number)
    if str_number[0] == '-':
        sign = '-'
        str_number = str_number[1:]
    if '.' in str_number:
        int_part, dec_part = str_number.split('.')
        if decimal_pos is not None:
            dec_part = dec_part[:decimal_pos]
    else:
        int_part, dec_part = (str_number, '')
    if decimal_pos is not None:
        dec_part += '0' * (decimal_pos - len(dec_part))
    dec_part = dec_part and decimal_sep + dec_part
    if use_grouping:
        try:
            intervals = list(grouping)
        except TypeError:
            intervals = [grouping, 0]
        active_interval = intervals.pop(0)
        int_part_gd = []
        cnt = 0
        for digit in int_part[::-1]:
            if cnt and cnt == active_interval:
                if intervals:
                    active_interval = intervals.pop(0) or active_interval
                int_part_gd.append(thousand_sep[::-1])
                cnt = 0
            int_part_gd.append(digit)
            cnt += 1
        int_part = ''.join(int_part_gd)[::-1]
    return sign + int_part + dec_part

def normalize(pattern):
    result = []
    non_capturing_groups = []
    consume_next = True
    pattern_iter = next_char(iter(pattern))
    num_args = 0
    try:
        ch, escaped = next(pattern_iter)
    except StopIteration:
        return [('', [])]
    try:
        while True:
            if escaped:
                result.append(ch)
            elif ch == '.':
                result.append('.')
            elif ch == '|':
                raise NotImplementedError('Awaiting Implementation')
            elif ch == '^':
                pass
            elif ch == '$':
                break
            elif ch == ')':
                start = non_capturing_groups.pop()
                inner = NonCapture(result[start:])
                result = result[:start] + [inner]
            elif ch == '[':
                ch, escaped = next(pattern_iter)
                result.append(ch)
                ch, escaped = next(pattern_iter)
                while escaped or ch != ']':
                    ch, escaped = next(pattern_iter)
            elif ch == '(':
                ch, escaped = next(pattern_iter)
                if ch != '?' or escaped:
                    name = '_%d' % num_args
                    num_args += 1
                    result.append(Group(('%%(%s)s' % name, name)))
                    walk_to_end(ch, pattern_iter)
                else:
                    ch, escaped = next(pattern_iter)
                    if ch in '!=<':
                        walk_to_end(ch, pattern_iter)
                    elif ch == ':':
                        non_capturing_groups.append(len(result))
                    elif ch != 'P':
                        raise ValueError("Non-reversible reg-exp portion: '(?%s'" % ch)
                    else:
                        ch, escaped = next(pattern_iter)
                        if ch not in ('<', '='):
                            raise ValueError("Non-reversible reg-exp portion: '(?P%s'" % ch)
                        if ch == '<':
                            terminal_char = '>'
                        else:
                            terminal_char = ')'
                        name = []
                        ch, escaped = next(pattern_iter)
                        while ch != terminal_char:
                            name.append(ch)
                            ch, escaped = next(pattern_iter)
                        param = ''.join(name)
                        if terminal_char != ')':
                            result.append(Group(('%%(%s)s' % param, param)))
                            walk_to_end(ch, pattern_iter)
                        else:
                            result.append(Group(('%%(%s)s' % param, None)))
            elif ch in '*?+{':
                count, ch = get_quantifier(ch, pattern_iter)
                if ch:
                    consume_next = False
                if count == 0:
                    if contains(result[-1], Group):
                        result[-1] = Choice([None, result[-1]])
                    else:
                        result.pop()
                elif count > 1:
                    result.extend([result[-1]] * (count - 1))
            else:
                result.append(ch)
            if consume_next:
                ch, escaped = next(pattern_iter)
            consume_next = True
    except StopIteration:
        pass
    except NotImplementedError:
        return [('', [])]
    return list(zip(*flatten_result(result)))

def next_char(input_iter):
    for ch in input_iter:
        if ch != '\\':
            yield (ch, False)
            continue
        ch = next(input_iter)
        representative = ESCAPE_MAPPINGS.get(ch, ch)
        if representative is None:
            continue
        yield (representative, True)

def walk_to_end(ch, input_iter):
    if ch == '(':
        nesting = 1
    else:
        nesting = 0
    for ch, escaped in input_iter:
        if escaped:
            continue
        elif ch == '(':
            nesting += 1
        elif ch == ')':
            if not nesting:
                return
            nesting -= 1

def get_quantifier(ch, input_iter):
    if ch in '*?+':
        try:
            ch2, escaped = next(input_iter)
        except StopIteration:
            ch2 = None
        if ch2 == '?':
            ch2 = None
        if ch == '+':
            return (1, ch2)
        return (0, ch2)
    quant = []
    while ch != '}':
        ch, escaped = next(input_iter)
        quant.append(ch)
    quant = quant[:-1]
    values = ''.join(quant).split(',')
    try:
        ch, escaped = next(input_iter)
    except StopIteration:
        ch = None
    if ch == '?':
        ch = None
    return (int(values[0]), ch)

def contains(source, inst):
    if isinstance(source, inst):
        return True
    if isinstance(source, NonCapture):
        for elt in source:
            if contains(elt, inst):
                return True
    return False

def flatten_result(source):
    if source is None:
        return ([''], [[]])
    if isinstance(source, Group):
        if source[1] is None:
            params = []
        else:
            params = [source[1]]
        return ([source[0]], [params])
    result = ['']
    result_args = [[]]
    pos = last = 0
    for pos, elt in enumerate(source):
        if isinstance(elt, str):
            continue
        piece = ''.join(source[last:pos])
        if isinstance(elt, Group):
            piece += elt[0]
            param = elt[1]
        else:
            param = None
        last = pos + 1
        for i in range(len(result)):
            result[i] += piece
            if param:
                result_args[i].append(param)
        if isinstance(elt, (Choice, NonCapture)):
            if isinstance(elt, NonCapture):
                elt = [elt]
            inner_result, inner_args = ([], [])
            for item in elt:
                res, args = flatten_result(item)
                inner_result.extend(res)
                inner_args.extend(args)
            new_result = []
            new_args = []
            for item, args in zip(result, result_args):
                for i_item, i_args in zip(inner_result, inner_args):
                    new_result.append(item + i_item)
                    new_args.append(args[:] + i_args)
            result = new_result
            result_args = new_args
    if pos >= last:
        piece = ''.join(source[last:])
        for i in range(len(result)):
            result[i] += piece
    return (result, result_args)

def _lazy_re_compile(regex, flags=0):

    def _compile():
        if isinstance(regex, (str, bytes)):
            return re.compile(regex, flags)
        else:
            assert not flags, 'flags must be empty if regex is passed pre-compiled'
            return regex
    return SimpleLazyObject(_compile)

