def template_localtime(value, use_tz=None):
    should_convert = isinstance(value, datetime) and (settings.USE_TZ if use_tz is None else use_tz) and (not is_naive(value)) and getattr(value, 'convert_to_local_time', True)
    return localtime(value) if should_convert else value

def localtime(value=None, timezone=None):
    if value is None:
        value = now()
    if timezone is None:
        timezone = get_current_timezone()
    if is_naive(value):
        raise ValueError('localtime() cannot be applied to a naive datetime')
    return value.astimezone(timezone)

def make_aware(value, timezone=None):
    if timezone is None:
        timezone = get_current_timezone()
    if is_aware(value):
        raise ValueError('make_aware expects a naive datetime, got %s' % value)
    return value.replace(tzinfo=timezone)

def make_naive(value, timezone=None):
    if timezone is None:
        timezone = get_current_timezone()
    if is_naive(value):
        raise ValueError('make_naive() cannot be applied to a naive datetime')
    return value.astimezone(timezone).replace(tzinfo=None)

@classmethod
def create(cls, children=None, connector=None, negated=False):
    obj = Node(children, connector or cls.default, negated)
    obj.__class__ = cls
    return obj

def add(self, data, conn_type):
    if self.connector != conn_type:
        obj = self.copy()
        self.connector = conn_type
        self.children = [obj, data]
        return data
    elif isinstance(data, Node) and (not data.negated) and (data.connector == conn_type or len(data) == 1):
        self.children.extend(data.children)
        return self
    else:
        self.children.append(data)
        return data

def get_version(version=None):
    version = get_complete_version(version)
    main = get_main_version(version)
    sub = ''
    if version[3] == 'alpha' and version[4] == 0:
        git_changeset = get_git_changeset()
        if git_changeset:
            sub = '.dev%s' % git_changeset
    elif version[3] != 'final':
        mapping = {'alpha': 'a', 'beta': 'b', 'rc': 'rc'}
        sub = mapping[version[3]] + str(version[4])
    return main + sub

def get_main_version(version=None):
    version = get_complete_version(version)
    parts = 2 if version[2] == 0 else 3
    return '.'.join((str(x) for x in version[:parts]))

def get_complete_version(version=None):
    if version is None:
        from django import VERSION as version
    else:
        assert len(version) == 5
        assert version[3] in ('alpha', 'beta', 'rc', 'final')
    return version

@functools.lru_cache
def get_git_changeset():
    if '__file__' not in globals():
        return None
    repo_dir = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
    git_log = subprocess.run('git log --pretty=format:%ct --quiet -1 HEAD', capture_output=True, shell=True, cwd=repo_dir, text=True)
    timestamp = git_log.stdout
    tz = datetime.UTC
    try:
        timestamp = datetime.datetime.fromtimestamp(int(timestamp), tz=tz)
    except ValueError:
        return None
    return timestamp.strftime('%Y%m%d%H%M%S')

def get_version_tuple(version):
    version_numbers = []
    for item in version_component_re.split(version):
        if item and item != '.':
            try:
                component = int(item)
            except ValueError:
                break
            else:
                version_numbers.append(component)
    return tuple(version_numbers)

def addQuickElement(self, name, contents=None, attrs=None):
