    self.endElement(name)

def makedirs(name, mode=511, exist_ok=False, *, parent_mode=None):
    head, tail = os.path.split(name)
    if not tail:
        head, tail = os.path.split(head)
    if head and tail and (not os.path.exists(head)):
        try:
            if parent_mode is not None:
                makedirs(head, mode=parent_mode, exist_ok=exist_ok, parent_mode=parent_mode)
            else:
                makedirs(head, exist_ok=exist_ok)
        except FileExistsError:
            pass
        cdir = curdir
        if isinstance(tail, bytes):
            cdir = bytes(curdir, 'ASCII')
        if tail == cdir:
            return
    try:
        os.mkdir(name, mode)
        os.chmod(name, mode)
    except OSError:
        if not exist_ok or not os.path.isdir(name):
            raise

def safe_join(base, *paths):
    final_path = abspath(join(base, *paths))
    base_path = abspath(base)
    if not normcase(final_path).startswith(normcase(base_path + sep)) and normcase(final_path) != normcase(base_path) and (dirname(normcase(base_path)) != normcase(base_path)):
        raise SuspiciousFileOperation('The joined path ({}) is located outside of the base path component ({})'.format(final_path, base_path))
    return final_path

def to_path(value):
    if isinstance(value, Path):
