        return True
    trap_bad_request = self.config['TRAP_BAD_REQUEST_ERRORS']
    if trap_bad_request is None and self.debug and isinstance(e, BadRequestKeyError):
        return True
    if trap_bad_request:
        return isinstance(e, BadRequest)
    return False

