    return {'real floating': dtype(float64), 'complex floating': dtype(complex128), 'integral': dtype(intp), 'indexing': dtype(intp)}

def dtypes(self, *, device=None, kind=None):
    if device not in ['cpu', None]:
        raise ValueError(f'Device not understood. Only "cpu" is allowed, but received: {device}')
    if kind is None:
        return {'bool': dtype(bool), 'int8': dtype(int8), 'int16': dtype(int16), 'int32': dtype(int32), 'int64': dtype(int64), 'uint8': dtype(uint8), 'uint16': dtype(uint16), 'uint32': dtype(uint32), 'uint64': dtype(uint64), 'float32': dtype(float32), 'float64': dtype(float64), 'complex64': dtype(complex64), 'complex128': dtype(complex128)}
    if kind == 'bool':
        return {'bool': bool}
    if kind == 'signed integer':
        return {'int8': dtype(int8), 'int16': dtype(int16), 'int32': dtype(int32), 'int64': dtype(int64)}
    if kind == 'unsigned integer':
        return {'uint8': dtype(uint8), 'uint16': dtype(uint16), 'uint32': dtype(uint32), 'uint64': dtype(uint64)}
    if kind == 'integral':
        return {'int8': dtype(int8), 'int16': dtype(int16), 'int32': dtype(int32), 'int64': dtype(int64), 'uint8': dtype(uint8), 'uint16': dtype(uint16), 'uint32': dtype(uint32), 'uint64': dtype(uint64)}
    if kind == 'real floating':
        return {'float32': dtype(float32), 'float64': dtype(float64)}
    if kind == 'complex floating':
        return {'complex64': dtype(complex64), 'complex128': dtype(complex128)}
    if kind == 'numeric':
        return {'int8': dtype(int8), 'int16': dtype(int16), 'int32': dtype(int32), 'int64': dtype(int64), 'uint8': dtype(uint8), 'uint16': dtype(uint16), 'uint32': dtype(uint32), 'uint64': dtype(uint64), 'float32': dtype(float32), 'float64': dtype(float64), 'complex64': dtype(complex64), 'complex128': dtype(complex128)}
    if isinstance(kind, tuple):
        res = {}
        for k in kind:
            res.update(self.dtypes(kind=k))
        return res
    raise ValueError(f'unsupported kind: {kind!r}')

def __call__(self, label='fast', verbose=1, extra_argv=None, doctests=False, coverage=False, durations=-1, tests=None):
    import pytest
    module = sys.modules[self.module_name]
    module_path = os.path.abspath(module.__path__[0])
    pytest_args = ['-l']
    pytest_args += ['-q']
    pytest_args += ['-W ignore:Not importing directory', '-W ignore:numpy.dtype size changed', '-W ignore:numpy.ufunc size changed', '-W ignore::UserWarning:cpuinfo']
    pytest_args += ['-W ignore:the matrix subclass is not', '-W ignore:Importing from numpy.matlib is']
    if doctests:
        pytest_args += ['--doctest-modules']
    if extra_argv:
        pytest_args += list(extra_argv)
    if verbose > 1:
        pytest_args += ['-' + 'v' * (verbose - 1)]
    if coverage:
        pytest_args += ['--cov=' + module_path]
    if label == 'fast':
        pytest_args += ['-m', 'not slow']
    elif label != 'full':
        pytest_args += ['-m', label]
    if durations >= 0:
        pytest_args += [f'--durations={durations}']
    if tests is None:
        tests = [self.module_name]
    pytest_args += ['--pyargs'] + list(tests)
    _show_numpy_info()
    try:
        code = pytest.main(pytest_args)
    except SystemExit as exc:
        code = exc.code
    return code == 0

@property
def contents(self):
    full_dtype = np.dtype((self._dtype_, self._shape_))
    full_ctype = ctypes.c_char * full_dtype.itemsize
    buffer = ctypes.cast(self, ctypes.POINTER(full_ctype)).contents
    return np.frombuffer(buffer, dtype=full_dtype).squeeze(axis=0)

@set_module('numpy.ctypeslib')
def ndpointer(dtype=None, ndim=None, shape=None, flags=None):
    if dtype is not None:
        dtype = np.dtype(dtype)
    num = None
    if flags is not None:
        if isinstance(flags, str):
            flags = flags.split(',')
        elif isinstance(flags, (int, np.integer)):
            num = flags
            flags = _flags_fromnum(num)
        elif isinstance(flags, mu.flagsobj):
            num = flags.num
            flags = _flags_fromnum(num)
        if num is None:
            try:
                flags = [x.strip().upper() for x in flags]
            except Exception as e:
                raise TypeError('invalid flags specification') from e
            num = _num_fromflags(flags)
    if shape is not None:
        try:
            shape = tuple(shape)
        except TypeError:
            shape = (shape,)
    cache_key = (dtype, ndim, shape, num)
    try:
        return _pointer_type_cache[cache_key]
    except KeyError:
        pass
    if dtype is None:
        name = 'any'
    elif dtype.names is not None:
        name = str(id(dtype))
    else:
        name = dtype.str
    if ndim is not None:
        name += f'_{ndim}d'
    if shape is not None:
        name += '_' + 'x'.join((str(x) for x in shape))
    if flags is not None:
        name += '_' + '_'.join(flags)
    if dtype is not None and shape is not None:
        base = _concrete_ndptr
    else:
        base = _ndptr
    klass = type(f'ndpointer_{name}', (base,), {'_dtype_': dtype, '_shape_': shape, '_ndim_': ndim, '_flags_': num})
    _pointer_type_cache[cache_key] = klass
    return klass

def process_f2cmap_dict(f2cmap_all, new_map, c2py_map, verbose=False):
    f2cmap_mapped = []
    new_map_lower = {}
    for k, d1 in new_map.items():
        d1_lower = {k1.lower(): v1 for k1, v1 in d1.items()}
        new_map_lower[k.lower()] = d1_lower
    for k, d1 in new_map_lower.items():
        if k not in f2cmap_all:
            f2cmap_all[k] = {}
        for k1, v1 in d1.items():
            if v1 in c2py_map:
                if k1 in f2cmap_all[k]:
                    outmess(f"\tWarning: redefinition of {{'{k}':{{'{k1}':'{f2cmap_all[k][k1]}'->'{v1}'}}}}\n")
                f2cmap_all[k][k1] = v1
                if verbose:
                    outmess(f'\tMapping "{k}(kind={k1})" to "{v1}"\n')
                f2cmap_mapped.append(v1)
            elif verbose:
                c2py_map_keys = list(c2py_map.keys())
                errmess(f"\tIgnoring map {{'{k}':{{'{k1}':'{v1}'}}}}: '{v1}' must be in {c2py_map_keys}\n")
    return (f2cmap_all, f2cmap_mapped)

def getctype(var):
    ctype = 'void'
    if isfunction(var):
        if 'result' in var:
            a = var['result']
        else:
            a = var['name']
        if a in var['vars']:
            return getctype(var['vars'][a])
        else:
            errmess(f'getctype: function {a} has no return value?!\n')
    elif issubroutine(var):
        return ctype
    elif ischaracter_or_characterarray(var):
        return 'character'
    elif isstring_or_stringarray(var):
        return 'string'
    elif 'typespec' in var and var['typespec'].lower() in f2cmap_all:
        typespec = var['typespec'].lower()
        f2cmap = f2cmap_all[typespec]
        ctype = f2cmap['']
        if 'kindselector' in var:
            if '*' in var['kindselector']:
                try:
                    ctype = f2cmap[var['kindselector']['*']]
                except KeyError:
                    raw_typespec = var['typespec']
                    star = var['kindselector']['*']
                    errmess(f'getctype: "{raw_typespec} * {star}" not supported.\n')
            elif 'kind' in var['kindselector']:
                if typespec + 'kind' in f2cmap_all:
                    f2cmap = f2cmap_all[typespec + 'kind']
                try:
                    ctype = f2cmap[var['kindselector']['kind']]
                except KeyError:
                    if typespec in f2cmap_all:
                        f2cmap = f2cmap_all[typespec]
                    try:
                        ctype = f2cmap[str(var['kindselector']['kind'])]
                    except KeyError:
                        kind = var['kindselector']['kind']
                        errmess(f'getctype: "{typespec}(kind={kind!r})" is mapped to C "{ctype}" (to override define {{{typespec!r}: {{{kind!r}: "<C typespec>"}}}} in {os.getcwd()}/.f2py_f2cmap file).\n')
    elif not isexternal(var):
        errmess(f'getctype: No C-type found in "{var}", assuming void.\n')
    return ctype

def f2cexpr(expr):
