@array_function_dispatch(_intersect1d_dispatcher)
def intersect1d(ar1, ar2, assume_unique=False, return_indices=False):
    ar1 = np.asanyarray(ar1)
    ar2 = np.asanyarray(ar2)
    if not assume_unique:
        if return_indices:
            ar1, ind1 = unique(ar1, return_index=True)
            ar2, ind2 = unique(ar2, return_index=True)
        else:
            ar1 = unique(ar1)
            ar2 = unique(ar2)
    else:
        ar1 = ar1.ravel()
        ar2 = ar2.ravel()
    aux = np.concatenate((ar1, ar2))
    if return_indices:
        aux_sort_indices = np.argsort(aux, kind='mergesort')
        aux = aux[aux_sort_indices]
    else:
        aux.sort()
    mask = aux[1:] == aux[:-1]
    int1d = aux[:-1][mask]
    if return_indices:
        ar1_indices = aux_sort_indices[:-1][mask]
        ar2_indices = aux_sort_indices[1:][mask] - ar1.size
        if not assume_unique:
            ar1_indices = ind1[ar1_indices]
            ar2_indices = ind2[ar2_indices]
        return (int1d, ar1_indices, ar2_indices)
    else:
        return int1d

@array_function_dispatch(_setxor1d_dispatcher)
def setxor1d(ar1, ar2, assume_unique=False):
    if not assume_unique:
        ar1 = unique(ar1)
        ar2 = unique(ar2)
    aux = np.concatenate((ar1, ar2), axis=None)
    if aux.size == 0:
        return aux
    aux.sort()
    flag = np.concatenate(([True], aux[1:] != aux[:-1], [True]))
    return aux[flag[1:] & flag[:-1]]

@array_function_dispatch(_isin_dispatcher)
def isin(element, test_elements, assume_unique=False, invert=False, *, kind=None):
    element = np.asarray(element)
    return _isin(element, test_elements, assume_unique=assume_unique, invert=invert, kind=kind).reshape(element.shape)

@array_function_dispatch(_union1d_dispatcher)
def union1d(ar1, ar2):
    return unique(np.concatenate((ar1, ar2), axis=None))

@array_function_dispatch(_setdiff1d_dispatcher)
def setdiff1d(ar1, ar2, assume_unique=False):
    if assume_unique:
        ar1 = np.asarray(ar1).ravel()
    else:
        ar1 = unique(ar1)
        ar2 = unique(ar2)
    return ar1[_isin(ar1, ar2, assume_unique=True, invert=True)]

def __getitem__(self, index):
    if not isinstance(index, tuple):
        index = (index,)
    fixed = []
    length, dims = (len(index), self.ndim)
    for slice_ in index:
        if slice_ is Ellipsis:
            fixed.extend([slice(None)] * (dims - length + 1))
            length = len(fixed)
        elif isinstance(slice_, int):
            fixed.append(slice(slice_, slice_ + 1, 1))
        else:
            fixed.append(slice_)
    index = tuple(fixed)
    if len(index) < dims:
        index += (slice(None),) * (dims - len(index))
    out = self.__class__(self.var, self.buf_size)
    for i, (start, stop, step, slice_) in enumerate(zip(self.start, self.stop, self.step, index)):
        out.start[i] = start + (slice_.start or 0)
        out.step[i] = step * (slice_.step or 1)
        out.stop[i] = start + (slice_.stop or stop - start)
        out.stop[i] = min(stop, out.stop[i])
    return out

def __array__(self, dtype=None, copy=None):
    slice_ = tuple((slice(*t) for t in zip(self.start, self.stop, self.step)))
    return self.var[slice_]

@property
def flat(self):
    for block in self:
        yield from block.flat

@property
def shape(self):
    return tuple(((stop - start - 1) // step + 1 for start, stop, step in zip(self.start, self.stop, self.step)))

@set_module('numpy.lib.array_utils')
def byte_bounds(a):
    ai = a.__array_interface__
    a_data = ai['data'][0]
    astrides = ai['strides']
    ashape = ai['shape']
    bytes_a = asarray(a).dtype.itemsize
    a_low = a_high = a_data
    if astrides is None:
        a_high += a.size * bytes_a
    else:
        for shape, stride in zip(ashape, astrides):
            if stride < 0:
                a_low += (shape - 1) * stride
            else:
                a_high += (shape - 1) * stride
        a_high += bytes_a
    return (a_low, a_high)

def _check_mode(mode, encoding, newline):
    if 't' in mode:
        if 'b' in mode:
            raise ValueError(f'Invalid mode: {mode!r}')
    else:
        if encoding is not None:
            raise ValueError("Argument 'encoding' not supported in binary mode")
        if newline is not None:
            raise ValueError("Argument 'newline' not supported in binary mode")

def keys(self):
    self._load()
    return list(self._file_openers.keys())

def open(path, mode='r', destpath=os.curdir, encoding=None, newline=None):
    ds = DataSource(destpath)
    return ds.open(path, mode, encoding=encoding, newline=newline)

def __init__(self, destpath=os.curdir):
    if destpath:
        self._destpath = os.path.abspath(destpath)
        self._istmpdest = False
    else:
        import tempfile
        self._destpath = tempfile.mkdtemp()
        self._istmpdest = True

def _iszip(self, filename):
    fname, ext = os.path.splitext(filename)
    return ext in _file_openers.keys()

def _iswritemode(self, mode):
    _writemodes = ('w', '+')
    return any((c in _writemodes for c in mode))

def _splitzipext(self, filename):
    if self._iszip(filename):
        return os.path.splitext(filename)
    else:
        return (filename, None)

def _possible_names(self, filename):
    names = [filename]
    if not self._iszip(filename):
        for zipext in _file_openers.keys():
            if zipext:
                names.append(filename + zipext)
    return names

def _isurl(self, path):
    from urllib.parse import urlparse
    scheme, netloc, upath, uparams, uquery, ufrag = urlparse(path)
    return bool(scheme and netloc)

def _cache(self, path):
    import shutil
    from urllib.request import urlopen
    upath = self.abspath(path)
    if not os.path.exists(os.path.dirname(upath)):
        os.makedirs(os.path.dirname(upath))
    if self._isurl(path):
        with urlopen(path) as openedurl:
            with _open(upath, 'wb') as f:
                shutil.copyfileobj(openedurl, f)
    else:
        shutil.copyfile(path, upath)
    return upath

def _findfile(self, path):
    if not self._isurl(path):
        filelist = self._possible_names(path)
        filelist += self._possible_names(self.abspath(path))
    else:
        filelist = self._possible_names(self.abspath(path))
        filelist = filelist + self._possible_names(path)
    for name in filelist:
        if self.exists(name):
            if self._isurl(name):
                name = self._cache(name)
            return name
    return None

def abspath(self, path):
    from urllib.parse import urlparse
    splitpath = path.split(self._destpath, 2)
    if len(splitpath) > 1:
        path = splitpath[1]
    scheme, netloc, upath, uparams, uquery, ufrag = urlparse(path)
    netloc = self._sanitize_relative_path(netloc)
    upath = self._sanitize_relative_path(upath)
    return os.path.join(self._destpath, netloc, upath)

def exists(self, path):
    if os.path.exists(path):
        return True
    from urllib.error import URLError
    from urllib.request import urlopen
    upath = self.abspath(path)
    if os.path.exists(upath):
        return True
    if self._isurl(path):
        try:
            netfile = urlopen(path)
            netfile.close()
            del netfile
            return True
        except URLError:
            return False
    return False

def open(self, path, mode='r', encoding=None, newline=None):
    if self._isurl(path) and self._iswritemode(mode):
        raise ValueError('URLs are not writeable')
    found = self._findfile(path)
    if found:
        _fname, ext = self._splitzipext(found)
        if ext == 'bz2':
            mode.replace('+', '')
        return _file_openers[ext](found, mode=mode, encoding=encoding, newline=newline)
    else:
        raise FileNotFoundError(f'{path} not found.')

def __init__(self, baseurl, destpath=os.curdir):
    DataSource.__init__(self, destpath=destpath)
    self._baseurl = baseurl

def _fullpath(self, path):
    splitpath = path.split(self._baseurl, 2)
    if len(splitpath) == 1:
        result = os.path.join(self._baseurl, path)
    else:
        result = path
    return result

def listdir(self):
    if self._isurl(self._baseurl):
        raise NotImplementedError('Directory listing of URLs, not supported yet.')
    else:
        return os.listdir(self._baseurl)

