def __float__(self):
    if self.size > 1:
        raise TypeError('Only length-1 arrays can be converted to Python scalars')
    elif self._mask:
        warnings.warn('Warning: converting a masked element to nan.', stacklevel=2)
        return np.nan
    return float(self.item())

