    if out is None:
        d = self.filled(True).all(axis=axis, **kwargs).view(type(self))
        if d.ndim:
            d.__setmask__(mask)
        elif mask:
            return masked
        return d
    self.filled(True).all(axis=axis, out=out, **kwargs)
    if isinstance(out, MaskedArray):
        if out.ndim or mask:
            out.__setmask__(mask)
    return out

