    if isinstance(out, MaskedArray):
        out.__setmask__(self._mask)
    return out

def argsort(self, axis=np._NoValue, kind=None, order=None, endwith=True, fill_value=None, *, stable=False, descending=False):
    if stable:
        raise ValueError('`stable` parameter is not supported for masked arrays.')
    if descending:
        raise ValueError('`descending` parameter is not supported for masked arrays.')
    if axis is np._NoValue:
        axis = _deprecate_argsort_axis(self)
    if fill_value is None:
        if endwith:
            if np.issubdtype(self.dtype, np.floating):
                fill_value = np.nan
            else:
                fill_value = minimum_fill_value(self)
        else:
            fill_value = maximum_fill_value(self)
    filled = self.filled(fill_value)
    return filled.argsort(axis=axis, kind=kind, order=order)

