def get_api_versions(apiversion):
    sys.path.insert(0, os.path.abspath(os.path.dirname(__file__)))
    try:
        m = __import__('genapi')
        numpy_api = __import__('numpy_api')
        curapi_hash = m.fullapi_hash(numpy_api.full_api)
        apis_hash = m.get_versions_hash()
    finally:
        del sys.path[0]
    return (curapi_hash, apis_hash[apiversion])

def check_api_version(apiversion):
    curapi_hash, api_hash = get_api_versions(apiversion)
    if not curapi_hash == api_hash:
        msg = f'API mismatch detected, the C API version numbers have to be updated. Current C api version is {apiversion}, with checksum {curapi_hash}, but recorded checksum in _core/codegen_dir/cversions.txt is {api_hash}. If functions were added in the C API, you have to update C_API_VERSION in numpy/core/meson.build.'
        raise MismatchCAPIError(msg)

def _parse_docstrings() -> str:
    type_list_ret = []
    for name, value, doc in _docstrings_list:
        s = textwrap.dedent(doc).replace('\n', '\n    ')
        lines = s.split('\n')
        new_lines = []
        indent = ''
        for line in lines:
            m = re.match('^(\\s+)[-=]+\\s*$', line)
            if m and new_lines:
                prev = textwrap.dedent(new_lines.pop())
                if prev == 'Examples':
                    indent = ''
                    new_lines.append(f'{m.group(1)}.. rubric:: {prev}')
                else:
                    indent = 4 * ' '
                    new_lines.append(f'{m.group(1)}.. admonition:: {prev}')
                new_lines.append('')
            else:
                new_lines.append(f'{indent}{line}')
        s = '\n'.join(new_lines)
        s_block = f'.. data:: {name}\n    :value: {value}\n    {s}'
        type_list_ret.append(s_block)
    return '\n'.join(type_list_ret)

def getargs(co):
    if not iscode(co):
        raise TypeError('arg is not a code object')
    nargs = co.co_argcount
    names = co.co_varnames
    args = list(names[:nargs])
