@contextlib.contextmanager
def patch_pickle() -> Generator[None]:
    orig_loads = pickle.loads
    try:
        setattr(pickle, 'loads', loads)
        yield
    finally:
        setattr(pickle, 'loads', orig_loads)

def _safe_fill_null(arr: pa.Array | pa.ChunkedArray, fill_value: Any) -> pa.Array | pa.ChunkedArray:
    import pyarrow.compute as pc
    is_windows = sys.platform in ['win32', 'cygwin']
    use_fallback = HAS_PYARROW and is_windows and (not pa_version_under21p0) and pa_version_under22p0
    if not use_fallback or isinstance(fill_value, (pa.Array, pa.ChunkedArray)):
        return pc.fill_null(arr, fill_value)
    fill_scalar = pa.scalar(fill_value, type=arr.type)
    if pa.types.is_duration(arr.type):

        def fill_null_duration(arr: pa.Array, fill_scalar: pa.Scalar) -> pa.Array:
            mask = pc.is_null(arr)
            zero_duration = pa.scalar(0, type=arr.type)
            arr_zeroed = pc.if_else(mask, zero_duration, arr)
            return pc.if_else(mask, fill_scalar, arr_zeroed)
        if isinstance(arr, pa.ChunkedArray):
            return pa.chunked_array([fill_null_duration(chunk, fill_scalar) for chunk in arr.chunks])
        return fill_null_duration(arr, fill_scalar)
    if isinstance(arr, pa.ChunkedArray):
        return pa.chunked_array([pc.if_else(pc.is_null(chunk), fill_scalar, chunk) for chunk in arr.chunks])
    return pc.if_else(pc.is_null(arr), fill_scalar, arr)

def import_optional_dependency(name: str, extra: str='', min_version: str | None=None, *, errors: Literal['raise', 'warn', 'ignore']='raise') -> types.ModuleType | None:
    assert errors in {'warn', 'raise', 'ignore'}
    package_name = INSTALL_MAPPING.get(name)
    install_name = package_name if package_name is not None else name
    msg = f'`Import {install_name}` failed. {extra} Use pip, conda, or your preferred package management tool to install the {install_name} package.'
    try:
        module = importlib.import_module(name)
    except ImportError as err:
        if errors == 'raise':
            raise ImportError(msg) from err
        return None
    parent = name.split('.', maxsplit=1)[0]
    if parent != name:
        install_name = parent
        module_to_get = sys.modules[install_name]
    else:
        module_to_get = module
    minimum_version = min_version if min_version is not None else VERSIONS.get(parent)
    if minimum_version:
        version = get_version(module_to_get)
        if version and Version(version) < Version(minimum_version):
            msg = f"Pandas requires version '{minimum_version}' or newer of '{parent}' (version '{version}' currently installed)."
            if errors == 'warn':
                warnings.warn(msg, UserWarning, stacklevel=find_stack_level())
                return None
            elif errors == 'raise':
                raise ImportError(msg)
            else:
                return None
    return module

def validate_clip_with_axis(axis: ndarray | AxisNoneT, args: tuple[Any, ...], kwargs: dict[str, Any]) -> AxisNoneT | None:
    if isinstance(axis, ndarray):
        args = (axis, *args)
        axis = None
    validate_clip(args, kwargs)
    return axis

def validate_cum_func_with_skipna(skipna: bool, args: tuple[Any, ...], kwargs: dict[str, Any], name: str) -> bool:
    if not is_bool(skipna):
        args = (skipna, *args)
        skipna = True
    elif isinstance(skipna, np.bool_):
        skipna = bool(skipna)
    validate_cum_func(args, kwargs, fname=name)
    return skipna

def validate_groupby_func(name: str, args: tuple[Any, ...], kwargs: dict[str, Any], allowed: list[str] | None=None) -> None:
    if allowed is None:
        allowed = []
    extra_kwargs = set(kwargs) - set(allowed)
    if len(args) + len(extra_kwargs) > 0:
        raise UnsupportedFunctionCall(f'numpy operations are not valid with groupby. Use .groupby(...).{name}() instead')

def validate_minmax_axis(axis: AxisInt | None, ndim: int=1) -> None:
    if axis is None:
        return
    if axis >= ndim or (axis < 0 and ndim + axis < 0):
        raise ValueError(f'`axis` must be fewer than the number of dimensions ({ndim})')

@final
def _dir_deletions(self) -> set[str]:
    return self._accessors | self._hidden_attrs

def __dir__(self) -> list[str]:
    rv = set(super().__dir__())
    rv = rv - self._dir_deletions() | self._dir_additions()
    return sorted(rv)

@classmethod
def _add_delegate_accessors(cls, delegate, accessors: list[str], typ: str, overwrite: bool=False, accessor_mapping: Callable[[str], str]=lambda x: x, raise_on_missing: bool=True) -> None:

    def _create_delegator_property(name: str):

        def _getter(self):
            return self._delegate_property_get(name)

        def _setter(self, new_values):
            return self._delegate_property_set(name, new_values)
        _getter.__name__ = name
        _setter.__name__ = name
        return property(fget=_getter, fset=_setter, doc=getattr(delegate, accessor_mapping(name)).__doc__)

    def _create_delegator_method(name: str):
        method = getattr(delegate, accessor_mapping(name))

        @functools.wraps(method)
        def f(self, *args, **kwargs):
            return self._delegate_method(name, *args, **kwargs)
        return f
    for name in accessors:
        if not raise_on_missing and getattr(delegate, accessor_mapping(name), None) is None:
            continue
        if typ == 'property':
            f = _create_delegator_property(name)
        else:
            f = _create_delegator_method(name)
        if overwrite or not hasattr(cls, name):
            setattr(cls, name, f)

def delegate_names(delegate, accessors: list[str], typ: str, overwrite: bool=False, accessor_mapping: Callable[[str], str]=lambda x: x, raise_on_missing: bool=True):

    def add_delegate_accessors(cls):
        cls._add_delegate_accessors(delegate, accessors, typ, overwrite=overwrite, accessor_mapping=accessor_mapping, raise_on_missing=raise_on_missing)
        return cls
    return add_delegate_accessors

def _register_accessor(name: str, cls: type[NDFrame | Index]) -> Callable[[TypeT], TypeT]:

    def decorator(accessor: TypeT) -> TypeT:
        if hasattr(cls, name):
            warnings.warn(f'registration of accessor {accessor!r} under name {name!r} for type {cls!r} is overriding a preexisting attribute with the same name.', UserWarning, stacklevel=find_stack_level())
        setattr(cls, name, Accessor(name, accessor))
        cls._accessors.add(name)
        return accessor
    return decorator

