    selection = None
    if subset.ndim == 2 and (lib.is_scalar(key) and key in subset or lib.is_list_like(key)):
        selection = key
    elif subset.ndim == 1 and lib.is_scalar(key) and (key == subset.name):
        selection = key
    return selection

