        raise ValueError(msg)
    res = self.eval(expr, level=level + 1, parser=parser, target=None, engine=engine, local_dict=local_dict, global_dict=global_dict, resolvers=resolvers or ())
    try:
        result = self.loc[res]
    except ValueError:
        result = self[res]
    if inplace:
        self._update_inplace(result)
        return None
    else:
        return result

def select_dtypes(self, include=None, exclude=None) -> DataFrame:
    if not is_list_like(include):
        include = (include,) if include is not None else ()
    if not is_list_like(exclude):
        exclude = (exclude,) if exclude is not None else ()
    selection = (frozenset(include), frozenset(exclude))
    if not any(selection):
        raise ValueError('at least one of include or exclude must be nonempty')

    def check_int_infer_dtype(dtypes):
        converted_dtypes: list[type] = []
        for dtype in dtypes:
            if isinstance(dtype, str) and dtype == 'int' or dtype is int:
                converted_dtypes.append(np.int32)
                converted_dtypes.append(np.int64)
            elif dtype == 'float' or dtype is float:
                converted_dtypes.extend([np.float64, np.float32])
            else:
                converted_dtypes.append(infer_dtype_from_object(dtype))
        return frozenset(converted_dtypes)
    include = check_int_infer_dtype(include)
    exclude = check_int_infer_dtype(exclude)
    for dtypes in (include, exclude):
        invalidate_string_dtypes(dtypes)
    if not include.isdisjoint(exclude):
        raise ValueError(f'include and exclude overlap on {include & exclude}')

    def dtype_predicate(dtype: DtypeObj, dtypes_set) -> bool:
        dtype = dtype if not isinstance(dtype, ArrowDtype) else dtype.numpy_dtype
        return issubclass(dtype.type, tuple(dtypes_set)) or (np.number in dtypes_set and getattr(dtype, '_is_numeric', False) and (not is_bool_dtype(dtype))) or (isinstance(dtype, StringDtype) and dtype.na_value is np.nan and (np.object_ in dtypes_set))

    def predicate(arr: ArrayLike) -> bool:
        dtype = arr.dtype
        if include:
            if not dtype_predicate(dtype, include):
                return False
        if exclude:
            if dtype_predicate(dtype, exclude):
                return False
        return True
    blk_dtypes = [blk.dtype for blk in self._mgr.blocks]
    if np.object_ in include and str not in include and (str not in exclude) and any((isinstance(dtype, StringDtype) and dtype.na_value is np.nan for dtype in blk_dtypes)):
        warnings.warn("For backward compatibility, 'str' dtypes are included by select_dtypes when 'object' dtype is specified. This behavior is deprecated and will be removed in a future version. Explicitly pass 'str' to `include` to select them, or to `exclude` to remove them and silence this warning.\nSee https://pandas.pydata.org/docs/user_guide/migration-3-strings.html#string-migration-select-dtypes for details on how to write code that works with pandas 2 and 3.", Pandas4Warning, stacklevel=find_stack_level())
    mgr = self._mgr._get_data_subset(predicate).copy(deep=False)
    return self._constructor_from_mgr(mgr, axes=mgr.axes).__finalize__(self)

def _select_dtypes_indices(self, dtype_class) -> np.ndarray:

    def predicate(arr: ArrayLike) -> bool:
        return isinstance(arr.dtype, dtype_class)
    return self._mgr._get_data_subset_indices(predicate)

def insert(self, loc: int, column: Hashable, value: object, allow_duplicates: bool=False) -> None:
    if allow_duplicates and (not self.flags.allows_duplicate_labels):
        raise ValueError("Cannot specify 'allow_duplicates=True' when 'self.flags.allows_duplicate_labels' is False.")
    if not allow_duplicates and column in self.columns:
        raise ValueError(f'cannot insert {column}, already exists')
    if not is_integer(loc):
        raise TypeError('loc must be int')
    loc = int(loc)
    if isinstance(value, DataFrame) and len(value.columns) > 1:
        raise ValueError(f'Expected a one-dimensional object, got a DataFrame with {len(value.columns)} columns instead.')
    elif isinstance(value, DataFrame):
        value = value.iloc[:, 0]
    value, refs = self._sanitize_column(value)
    self._mgr.insert(loc, column, value, refs=refs)

def assign(self, **kwargs) -> DataFrame:
    data = self.copy(deep=False)
    for k, v in kwargs.items():
        data[k] = com.apply_if_callable(v, data)
