    axis = self._get_axis_number(axis)
    idx = self._get_axis(axis).set_names(name)
    inplace = validate_bool_kwarg(inplace, 'inplace')
    renamed = self if inplace else self.copy(deep=False)
    if axis == 0:
        renamed.index = idx
    else:
        renamed.columns = idx
    if not inplace:
        return renamed
    return None

