            dtypes = [self.dtype, self.index.dtype]
        if any((dtype.kind in 'mM' for dtype in dtypes)):
            warnings.warn("The default 'epoch' date format is deprecated and will be removed in a future version, please use 'iso' date format instead.", Pandas4Warning, stacklevel=find_stack_level())
    elif date_format == 'epoch':
        warnings.warn("'epoch' date format is deprecated and will be removed in a future version, please use 'iso' date format instead.", Pandas4Warning, stacklevel=find_stack_level())
    cf.is_nonnegative_int(indent)
    indent = indent or 0
    return json.to_json(path_or_buf=path_or_buf, obj=self, orient=orient, date_format=date_format, double_precision=double_precision, force_ascii=force_ascii, date_unit=date_unit, default_handler=default_handler, lines=lines, compression=compression, index=index, indent=indent, storage_options=storage_options, mode=mode)

