@disallow('M8', 'm8')
@maybe_operate_rowwise
def nanprod(values: np.ndarray, *, axis: AxisInt | None=None, skipna: bool=True, min_count: int=0, mask: npt.NDArray[np.bool_] | None=None) -> float:
    mask = _maybe_get_mask(values, skipna, mask)
    if skipna and mask is not None:
        values = values.copy()
        values[mask] = 1
    result = values.prod(axis)
    return _maybe_null_out(result, axis, mask, values.shape, min_count=min_count)

def _get_counts(values_shape: Shape, mask: npt.NDArray[np.bool_] | None, axis: AxisInt | None, dtype: np.dtype[np.floating]=np.dtype(np.float64)) -> np.floating | npt.NDArray[np.floating]:
    if axis is None:
        if mask is not None:
            n = mask.size - mask.sum()
        else:
            n = np.prod(values_shape)
        return dtype.type(n)
    if mask is not None:
        count = mask.shape[axis] - mask.sum(axis)
    else:
        count = values_shape[axis]
    if is_integer(count):
        return dtype.type(count)
    return count.astype(dtype, copy=False)

def _maybe_null_out(result: np.ndarray | float | NaTType, axis: AxisInt | None, mask: npt.NDArray[np.bool_] | None, shape: tuple[int, ...], min_count: int=1, datetimelike: bool=False) -> np.ndarray | float | NaTType:
    if mask is None and min_count == 0:
        return result
    if axis is not None and isinstance(result, np.ndarray):
        if mask is not None:
            null_mask = mask.shape[axis] - mask.sum(axis) - min_count < 0
        else:
            below_count = shape[axis] - min_count < 0
            new_shape = shape[:axis] + shape[axis + 1:]
            null_mask = np.broadcast_to(below_count, new_shape)
        if np.any(null_mask):
            if datetimelike:
                result[null_mask] = iNaT
            elif is_numeric_dtype(result):
                if np.iscomplexobj(result):
                    result = result.astype('c16')
                elif not is_float_dtype(result):
                    result = result.astype('f8', copy=False)
                result[null_mask] = np.nan
            else:
                result[null_mask] = None
    elif result is not NaT:
        if check_below_min_count(shape, mask, min_count):
            result_dtype = getattr(result, 'dtype', None)
            if is_float_dtype(result_dtype):
                result = result_dtype.type('nan')
            else:
                result = np.nan
    return result

def check_below_min_count(shape: tuple[int, ...], mask: npt.NDArray[np.bool_] | None, min_count: int) -> bool:
    if min_count > 0:
        if mask is None:
            non_nulls = np.prod(shape)
        else:
            non_nulls = mask.size - mask.sum()
        if non_nulls < min_count:
            return True
    return False

@disallow('M8', 'm8')
def nancorr(a: np.ndarray, b: np.ndarray, *, method: CorrelationMethod='pearson', min_periods: int | None=None) -> float:
    if len(a) != len(b):
        raise AssertionError('Operands to nancorr must have same size')
    if min_periods is None:
        min_periods = 1
    valid = notna(a) & notna(b)
    if not valid.all():
        a = a[valid]
        b = b[valid]
    if len(a) < min_periods:
        return np.nan
    a = _ensure_numeric(a)
    b = _ensure_numeric(b)
    f = get_corr_func(method)
    return f(a, b)

@final
def __str__(self) -> str:
    attrs = (f'{k}={getattr(self._timegrouper, k)}' for k in self._attributes if getattr(self._timegrouper, k, None) is not None)
    return f"{type(self).__name__} [{', '.join(attrs)}]"

@final
@property
def _from_selection(self) -> bool:
    return self._timegrouper is not None and (self._timegrouper.key is not None or self._timegrouper.level is not None)

@final
def _get_binner(self):
    binner, bins, binlabels = self._get_binner_for_time()
    assert len(bins) == len(binlabels)
    if self._timegrouper._arrow_dtype is not None:
        binlabels = binlabels.astype(self._timegrouper._arrow_dtype)
    bin_grouper = BinGrouper(bins, binlabels, indexer=self._indexer)
    bin_grouper._is_resample = True
    return (binner, bin_grouper)

@final
def pipe(self, func: Callable[Concatenate[Self, P], T] | tuple[Callable[..., T], str], *args: Any, **kwargs: Any) -> T:
    return super().pipe(func, *args, **kwargs)

@final
def aggregate(self, func=None, *args, **kwargs):
    result = ResamplerWindowApply(self, func, args=args, kwargs=kwargs).agg()
    if result is None:
        how = func
        result = self._groupby_and_aggregate(how, *args, **kwargs)
    return result

@final
def transform(self, arg, *args, **kwargs):
    return self._selected_obj.groupby(self._timegrouper).transform(arg, *args, **kwargs)

def _gotitem(self, key, ndim: int, subset=None):
    grouper = self._grouper
    if subset is None:
        subset = self.obj
        if key is not None:
            subset = subset[key]
        else:
            assert subset.ndim == 1
    if ndim == 1:
        assert subset.ndim == 1
    grouped = get_groupby(subset, by=None, grouper=grouper, group_keys=self.group_keys)
    return grouped

def _groupby_and_aggregate(self, how, *args, **kwargs):
    grouper = self._grouper
    obj = self._obj_with_exclusions
    grouped = get_groupby(obj, by=None, grouper=grouper, group_keys=self.group_keys)
    try:
        if callable(how):
            func = lambda x: how(x, *args, **kwargs)
            result = grouped.aggregate(func)
        else:
            result = grouped.aggregate(how, *args, **kwargs)
    except (AttributeError, KeyError):
        result = grouped.apply(how, *args, **kwargs)
    except ValueError as err:
        if 'Must produce aggregated value' in str(err):
            pass
        else:
            raise
        result = grouped.apply(how, *args, **kwargs)
    return self._wrap_result(result)

@final
def _get_resampler_for_grouping(self, groupby: GroupBy, key):
    return self._resampler_for_grouping(groupby=groupby, key=key, parent=self)

def _wrap_result(self, result):
    if isinstance(result, ABCSeries) and self._selection is not None:
        result.name = self._selection
    if isinstance(result, ABCSeries) and result.empty:
        obj = self.obj
        result.index = _asfreq_compat(obj.index[:0], freq=self.freq)
        result.name = getattr(obj, 'name', None)
    if self._timegrouper._arrow_dtype is not None:
        result.index = result.index.astype(self._timegrouper._arrow_dtype)
    return result

@final
def ffill(self, limit: int | None=None):
    return self._upsample('ffill', limit=limit)

@final
def nearest(self, limit: int | None=None):
    return self._upsample('nearest', limit=limit)

@final
def bfill(self, limit: int | None=None):
    return self._upsample('bfill', limit=limit)

@final
def interpolate(self, method: InterpolateOptions='linear', *, axis: Axis=0, limit: int | None=None, limit_direction: Literal['forward', 'backward', 'both']='forward', limit_area=None, **kwargs):
    if 'inplace' in kwargs:
        warnings.warn(f"The 'inplace' keyword in {type(self).__name__}.interpolate is deprecated and will be removed in a future version. resample(...).interpolate is never inplace.", Pandas4Warning, stacklevel=find_stack_level())
        inplace = kwargs.pop('inplace')
        if inplace:
            raise ValueError('Cannot interpolate inplace on a resampled object.')
    result = self._upsample('asfreq')
    obj = self._selected_obj
    is_period_index = isinstance(obj.index, PeriodIndex)
    if not is_period_index:
        final_index = result.index
        if isinstance(final_index, MultiIndex):
            raise NotImplementedError('Direct interpolation of MultiIndex data frames is not supported. If you tried to resample and interpolate on a grouped data frame, please use:\n`df.groupby(...).apply(lambda x: x.resample(...).interpolate(...))`\ninstead, as resampling and interpolation has to be performed for each group independently.')
        missing_data_points_index = obj.index.difference(final_index)
        if len(missing_data_points_index) > 0:
            result = concat([result, obj.loc[missing_data_points_index]]).sort_index()
    result_interpolated = result.interpolate(method=method, axis=axis, limit=limit, inplace=False, limit_direction=limit_direction, limit_area=limit_area, **kwargs)
    if is_period_index:
        return result_interpolated
    result_interpolated = result_interpolated.loc[final_index]
    result_interpolated.index = final_index
    return result_interpolated

