    if using_string_dtype():
        from pandas import StringDtype, array as pd_array
        return pd_array(result, dtype=StringDtype(na_value=np.nan))
    return result

def _to_local_pa_timestamp(self) -> pa.Array:
    import pyarrow as pa
    values = self._local_timestamps()
    mask = self._isnan
    return pa.array(values, mask=mask, type=pa.timestamp(self.unit))

@staticmethod
def _wrap_pa_str_result(pa_arr: pa.Array) -> ArrowStringArray:
    from pandas.core.arrays.string_ import StringDtype
    dtype = StringDtype(na_value=np.nan)
    cls = dtype.construct_array_type()
    return cls(pa_arr, dtype=dtype)

@property
def time(self) -> npt.NDArray[np.object_]:
    timestamps = self._local_timestamps()
    return ints_to_pydatetime(timestamps, box='time', reso=self._creso)

