def sequence_to_td64ns(data, copy: bool=False, unit=None, errors: DateTimeErrorChoices='raise') -> np.ndarray:
    assert unit not in ['Y', 'y', 'M']
    if unit is not None:
        unit = parse_timedelta_unit(unit)
    data, copy = dtl.ensure_arraylike_for_datetimelike(data, copy, cls_name='TimedeltaArray')
    if data.dtype == object or is_string_dtype(data.dtype):
        data = _objects_to_td64ns(data, unit=unit, errors=errors)
        copy = False
    elif is_integer_dtype(data.dtype):
        try:
            data, copy_made = _ints_to_td64ns(data, unit=unit)
        except OutOfBoundsTimedelta:
            if errors == 'raise':
                raise
            data = _objects_to_td64ns(data.astype(object), unit=unit, errors=errors)
            copy_made = True
        copy = copy and (not copy_made)
    elif is_float_dtype(data.dtype):
        if isinstance(data.dtype, ExtensionDtype):
            mask = data._mask
            data = data._data
        else:
            mask = np.isnan(data)
        if unit is not None and unit != 'ns':
            with np.errstate(invalid='ignore'):
                int_data = data.astype(np.int64)
            i64 = np.iinfo(np.int64)
            in_int64_range = (data >= np.float64(i64.min)) & (data < np.float64(i64.max))
            all_round = (mask | in_int64_range & (data == int_data)).all()
            if all_round:
                result = sequence_to_td64ns(int_data, copy=False, unit=unit, errors=errors)
                result[mask] = iNaT
                return result
        data = data.astype(np.float64, copy=False)
        try:
            data = cast_from_unit_vectorized(data, unit or 'ns')
        except OutOfBoundsDatetime as err:
            raise OutOfBoundsTimedelta(*err.args) from err
        data[mask] = iNaT
        data = data.view('m8[ns]')
        copy = False
    elif lib.is_np_dtype(data.dtype, 'm'):
        if not is_supported_dtype(data.dtype):
            new_dtype = get_supported_dtype(data.dtype)
            data = astype_overflowsafe(data, dtype=new_dtype, copy=False)
            copy = False
    else:
        raise TypeError(f'dtype {data.dtype} cannot be converted to timedelta64[ns]')
    if not copy:
        data = np.asarray(data)
    else:
        data = np.array(data, copy=copy)
    assert data.dtype.kind == 'm'
    assert data.dtype != 'm8'
    return data

def _ints_to_td64ns(data, unit: str='ns') -> tuple[np.ndarray, bool]:
    copy_made = False
    unit = unit if unit is not None else 'ns'
    if data.dtype != np.int64:
        if data.dtype == np.dtype('uint64') and (data > np.iinfo(np.int64).max).any():
            raise OutOfBoundsTimedelta(f"Cannot convert input with unit '{unit}'")
        data = data.astype(np.int64)
        copy_made = True
    if unit != 'ns':
        dtype_str = f'timedelta64[{unit}]'
        data = data.view(dtype_str)
        new_dtype = get_supported_dtype(data.dtype)
        if new_dtype != data.dtype:
            data = astype_overflowsafe(data, dtype=new_dtype)
            copy_made = True
    else:
        data = data.view('timedelta64[ns]')
    return (data, copy_made)

@staticmethod
def _has_unsupported_regex(pat: str | re.Pattern) -> bool:
    try:
        from re import _parser
        regex_parser = _parser.parse
    except Exception as err:
        raise type(err)('Incompatible version for regex; you will need to upgrade pandas or downgrade Python') from err

    def has_unsupported_code(tokens):
        for op_code, argument in tokens:
            if op_code == _parser.SUBPATTERN and has_unsupported_code(argument[3]) or (op_code == _parser.BRANCH and any((has_unsupported_code(tokens) for tokens in argument[1]))) or op_code in [_parser.ASSERT_NOT, _parser.ASSERT, _parser.GROUPREF]:
                return True
        return False
    str_pat = pat.pattern if isinstance(pat, re.Pattern) else pat
    try:
        tokens = regex_parser(str_pat)
    except re.error:
        return False
    return has_unsupported_code(tokens)

def ravel_compat(meth: F) -> F:

    @wraps(meth)
    def method(self, *args, **kwargs):
        if self.ndim == 1:
            return meth(self, *args, **kwargs)
        flags = self._ndarray.flags
        flat = self.ravel('K')
        result = meth(flat, *args, **kwargs)
        order = 'F' if flags.f_contiguous else 'C'
        return result.reshape(self.shape, order=order)
    return cast('F', method)

@classmethod
