def _maybe_convert_timedelta(self, other) -> int | npt.NDArray[np.int64]:
    if isinstance(other, (timedelta, np.timedelta64, Tick, np.ndarray)):
        if isinstance(self.freq, (Tick, Day)):
            delta = self._data._check_timedeltalike_freq_compat(other)
            return delta
    elif isinstance(other, BaseOffset):
        if other.base == self.freq.base:
            return other.n
        raise raise_on_incompatible(self, other)
    elif is_integer(other):
        assert isinstance(other, int)
        return other
    raise raise_on_incompatible(self, None)

def asof_locs(self, where: Index, mask: npt.NDArray[np.bool_]) -> np.ndarray:
    if isinstance(where, DatetimeIndex):
        where = PeriodIndex(where._values, freq=self.freq, copy=False)
    elif not isinstance(where, PeriodIndex):
        raise TypeError('asof_locs `where` must be DatetimeIndex or PeriodIndex')
    return super().asof_locs(where, mask)

@property
def is_full(self) -> bool:
    if len(self) == 0:
        return True
    if not self.is_monotonic_increasing:
        raise ValueError('Index is not monotonic')
    values = self.asi8
    return bool((values[1:] - values[:-1] < 2).all())

def get_loc(self, key):
    orig_key = key
    self._check_indexing_error(key)
    if is_valid_na_for_dtype(key, self.dtype):
        key = NaT
    elif isinstance(key, str):
        try:
            parsed, reso = self._parse_with_reso(key)
        except ValueError as err:
            raise KeyError(f"Cannot interpret '{key}' as period") from err
        if self._can_partial_date_slice(reso):
            try:
                return self._partial_date_slice(reso, parsed)
            except KeyError as err:
                raise KeyError(key) from err
        if reso == self._resolution_obj:
            key = self._cast_partial_indexing_scalar(parsed)
        else:
            raise KeyError(key)
    elif isinstance(key, Period):
        self._disallow_mismatched_indexing(key)
    elif isinstance(key, datetime):
        key = self._cast_partial_indexing_scalar(key)
    else:
        raise KeyError(key)
    try:
        return Index.get_loc(self, key)
    except KeyError as err:
        raise KeyError(orig_key) from err

def _maybe_cast_slice_bound(self, label, side: str):
    if isinstance(label, datetime):
        label = self._cast_partial_indexing_scalar(label)
    return super()._maybe_cast_slice_bound(label, side)

def shift(self, periods: int=1, freq=None) -> Self:
    if freq is not None:
        raise TypeError(f'`freq` argument is not supported for {type(self).__name__}.shift')
    return self + periods

@set_module('pandas')
def period_range(start=None, end=None, periods: int | None=None, freq=None, name: Hashable | None=None) -> PeriodIndex:
    if com.count_not_none(start, end, periods) != 2:
        raise ValueError('Of the three parameters: start, end, and periods, exactly two must be specified')
    if freq is None and (not isinstance(start, Period) and (not isinstance(end, Period))):
        freq = 'D'
    data, freq = PeriodArray._generate_range(start, end, periods, freq)
    dtype = PeriodDtype(freq)
    data = PeriodArray(data, dtype=dtype)
    return PeriodIndex(data, name=name, copy=False)

def min_fitting_element(start: int, step: int, lower_limit: int) -> int:
    no_steps = -(-(lower_limit - start) // abs(step))
    return start + abs(step) * no_steps

@classmethod
def from_range(cls, data: range, name: Hashable | None=None, dtype: Dtype | None=None) -> Self:
    if not isinstance(data, range):
        raise TypeError(f'{cls.__name__}(...) must be called with object coercible to a range, {data!r} was passed')
    cls._validate_dtype(dtype)
    return cls._simple_new(data, name=name)

@cache_readonly
def _constructor(self) -> type[Index]:
    return Index

@cache_readonly
def _data(self) -> np.ndarray:
    return np.arange(self.start, self.stop, self.step, dtype=np.int64)

def _get_data_as_items(self) -> list[tuple[str, int]]:
    rng = self._range
    return [('start', rng.start), ('stop', rng.stop), ('step', rng.step)]

def _format_attrs(self) -> list[tuple[str, str | int]]:
    attrs = cast('list[tuple[str, str | int]]', self._get_data_as_items())
    if self._name is not None:
        attrs.append(('name', ibase.default_pprint(self._name)))
    return attrs

@property
def start(self) -> int:
    return self._range.start

@property
def stop(self) -> int:
    return self._range.stop

@property
def step(self) -> int:
    return self._range.step

@cache_readonly
def nbytes(self) -> int:
    rng = self._range
    objsize = 24
    return getsizeof(rng, objsize) + sum((getsizeof(getattr(rng, attr_name), objsize) for attr_name in ['start', 'stop', 'step']))

@property
def is_unique(self) -> bool:
    return True

def get_loc(self, key: int) -> int:
    if is_integer(key) or (is_float(key) and key.is_integer()):
        new_key = int(key)
        try:
            return self._range.index(new_key)
        except ValueError as err:
            raise KeyError(key) from err
    if isinstance(key, Hashable):
        raise KeyError(key)
    self._check_indexing_error(key)
    raise KeyError(key)

@cache_readonly
def _should_fallback_to_positional(self) -> bool:
    return False

def _shallow_copy(self, values: ArrayLike, name: Hashable=no_default) -> Index:
    name = self._name if name is no_default else name
    if values.dtype.kind == 'f':
        return Index(values, name=name, dtype=np.float64, copy=False)
    if values.dtype.kind == 'i' and values.ndim == 1:
        if len(values) == 1:
            start = values[0]
            new_range = range(start, start + self.step, self.step)
            return type(self)._simple_new(new_range, name=name)
        maybe_range = ibase.maybe_sequence_to_range(values)
        if isinstance(maybe_range, range):
            return type(self)._simple_new(maybe_range, name=name)
    return self._constructor._simple_new(values, name=name)

def min(self, axis: AxisInt | None=None, skipna: bool=True, *args: Any, **kwargs: Any) -> int | float:
    nv.validate_minmax_axis(axis)
    nv.validate_min(args, kwargs)
    return self._minmax('min')

def max(self, axis: AxisInt | None=None, skipna: bool=True, *args: Any, **kwargs: Any) -> int | float:
    nv.validate_minmax_axis(axis)
    nv.validate_max(args, kwargs)
    return self._minmax('max')

def argsort(self, *args: Any, **kwargs: Any) -> npt.NDArray[np.intp]:
    ascending = kwargs.pop('ascending', True)
    kwargs.pop('kind', None)
    nv.validate_argsort(args, kwargs)
    start, stop, step = (None, None, None)
    if self._range.step > 0:
        if ascending:
            start = len(self)
        else:
            start, stop, step = (len(self) - 1, -1, -1)
    elif ascending:
        start, stop, step = (len(self) - 1, -1, -1)
    else:
        start = len(self)
    return np.arange(start, stop, step, dtype=np.intp)

def equals(self, other: object) -> bool:
    if isinstance(other, RangeIndex):
        return self._range == other._range
    return super().equals(other)

def _extended_gcd(self, a: int, b: int) -> tuple[int, int, int]:
    s, old_s = (0, 1)
    t, old_t = (1, 0)
    r, old_r = (b, a)
    while r:
        quotient = old_r // r
        old_r, r = (r, old_r - quotient * r)
        old_s, s = (s, old_s - quotient * s)
        old_t, t = (t, old_t - quotient * t)
    return (old_r, old_s, old_t)

def _range_in_self(self, other: range) -> bool:
    if not other:
        return True
    if not self._range:
        return False
    if len(other) > 1 and other.step % self._range.step:
        return False
    return other.start in self._range and other[-1] in self._range

def _union(self, other: Index, sort: bool | None) -> Index:
    if isinstance(other, RangeIndex):
        if sort in (None, True) or (sort is False and self.step > 0 and self._range_in_self(other._range)):
            start_s, step_s = (self.start, self.step)
            end_s = self.start + self.step * (len(self) - 1)
            start_o, step_o = (other.start, other.step)
            end_o = other.start + other.step * (len(other) - 1)
            if self.step < 0:
                start_s, step_s, end_s = (end_s, -step_s, start_s)
            if other.step < 0:
                start_o, step_o, end_o = (end_o, -step_o, start_o)
            if len(self) == 1 and len(other) == 1:
                step_s = step_o = abs(self.start - other.start)
            elif len(self) == 1:
                step_s = step_o
            elif len(other) == 1:
                step_o = step_s
            start_r = min(start_s, start_o)
            end_r = max(end_s, end_o)
            if step_o == step_s:
                if (start_s - start_o) % step_s == 0 and start_s - end_o <= step_s and (start_o - end_s <= step_s):
                    return type(self)(start_r, end_r + step_s, step_s)
                if step_s % 2 == 0 and abs(start_s - start_o) == step_s / 2 and (abs(end_s - end_o) == step_s / 2):
                    return type(self)(start_r, end_r + step_s / 2, step_s / 2)
            elif step_o % step_s == 0:
                if (start_o - start_s) % step_s == 0 and start_o + step_s >= start_s and (end_o - step_s <= end_s):
                    return type(self)(start_r, end_r + step_s, step_s)
            elif step_s % step_o == 0:
                if (start_s - start_o) % step_o == 0 and start_s + step_o >= start_o and (end_s - step_o <= end_o):
                    return type(self)(start_r, end_r + step_o, step_o)
    return super()._union(other, sort=sort)

def _concat(self, indexes: list[Index], name: Hashable) -> Index:
    if not all((isinstance(x, RangeIndex) for x in indexes)):
        result = super()._concat(indexes, name)
        if result.dtype.kind == 'i':
            return self._shallow_copy(result._values)
        return result
    elif len(indexes) == 1:
        return indexes[0]
    rng_indexes = cast('list[RangeIndex]', indexes)
    start = step = next_ = None
    non_empty_indexes = []
    all_same_index = True
    prev: RangeIndex | None = None
    for obj in rng_indexes:
        if len(obj):
            non_empty_indexes.append(obj)
            if all_same_index:
                if prev is not None:
                    all_same_index = prev.equals(obj)
                else:
                    prev = obj
    for obj in non_empty_indexes:
        rng = obj._range
        if start is None:
            start = rng.start
            if step is None and len(rng) > 1:
                step = rng.step
        elif step is None:
            if rng.start == start:
                if all_same_index:
                    values = np.tile(non_empty_indexes[0]._values, len(non_empty_indexes))
                else:
                    values = np.concatenate([x._values for x in rng_indexes])
                result = self._constructor(values, copy=False)
                return result.rename(name)
            step = rng.start - start
        non_consecutive = step != rng.step and len(rng) > 1 or (next_ is not None and rng.start != next_)
        if non_consecutive:
            if all_same_index:
                values = np.tile(non_empty_indexes[0]._values, len(non_empty_indexes))
            else:
                values = np.concatenate([x._values for x in rng_indexes])
            result = self._constructor(values, copy=False)
            return result.rename(name)
        if step is not None:
            next_ = rng[-1] + step
    if non_empty_indexes:
        stop = non_empty_indexes[-1].stop if next_ is None else next_
        if len(non_empty_indexes) == 1:
            step = non_empty_indexes[0].step
        return RangeIndex(start, stop, step, name=name)
    return RangeIndex(_empty_range, name=name)

def __getitem__(self, key: Any) -> Any:
    key = lib.item_from_zerodim(key)
    if key is Ellipsis:
        key = slice(None)
    if isinstance(key, slice):
        return self._getitem_slice(key)
    elif is_integer(key):
        new_key = int(key)
        try:
            return self._range[new_key]
        except IndexError as err:
            raise IndexError(f'index {key} is out of bounds for axis 0 with size {len(self)}') from err
    elif is_scalar(key):
        raise IndexError('only integers, slices (`:`), ellipsis (`...`), numpy.newaxis (`None`) and integer or boolean arrays are valid indices')
    elif com.is_bool_indexer(key):
        if isinstance(getattr(key, 'dtype', None), ExtensionDtype):
            key = key.to_numpy(dtype=bool, na_value=False)
        else:
            key = np.asarray(key, dtype=bool)
        check_array_indexer(self._range, key)
        key = np.flatnonzero(key)
    try:
        return self.take(key)
    except (TypeError, ValueError):
        return super().__getitem__(key)

def _getitem_slice(self, slobj: slice) -> Self:
    res = self._range[slobj]
    return type(self)._simple_new(res, name=self._name)

def round(self, decimals: int=0) -> Self | Index:
    if decimals >= 0:
        return self.copy()
    elif self.start % 10 ** (-decimals) == 0 and self.step % 10 ** (-decimals) == 0:
        return self.copy()
    else:
        return super().round(decimals=decimals)

def _arith_method(self, other: object, op: Callable) -> Index:
    if isinstance(other, ABCTimedeltaIndex):
        return NotImplemented
    elif isinstance(other, (timedelta, np.timedelta64)):
        return super()._arith_method(other, op)
    elif lib.is_np_dtype(getattr(other, 'dtype', None), 'm'):
        return super()._arith_method(other, op)
    if op in [operator.pow, ops.rpow, operator.mod, ops.rmod, operator.floordiv, ops.rfloordiv, divmod, ops.rdivmod]:
        return super()._arith_method(other, op)
    step: Callable | None = None
    if op in [operator.mul, ops.rmul, operator.truediv, ops.rtruediv]:
        step = op
    right = extract_array(other, extract_numpy=True, extract_range=True)
    left = self
    try:
        if step:
            with np.errstate(all='ignore'):
                rstep = step(left.step, right)
            if not is_integer(rstep) or not rstep:
                raise ValueError
        else:
            rstep = -left.step if op == ops.rsub else left.step
        with np.errstate(all='ignore'):
            rstart = op(left.start, right)
            rstop = op(left.stop, right)
        res_name = ops.get_op_result_name(self, other)
        result = type(self)(rstart, rstop, rstep, name=res_name)
        if not all((is_integer(x) for x in [rstart, rstop, rstep])):
            result = result.astype('float64')
        return result
    except (ValueError, TypeError, ZeroDivisionError):
        return super()._arith_method(other, op)

def _new_TimedeltaIndex(cls, d):
    if 'data' in d and (not isinstance(d['data'], TimedeltaIndex)):
        data = d.pop('data')
        if isinstance(data, TimedeltaArray):
            tdarr = data
        else:
            tdarr = TimedeltaArray._simple_new(data, dtype=data.dtype)
        legacy_freq = vars(tdarr).pop('_freq', None)
        freq = d.pop('freq', legacy_freq)
        result = cls._simple_new(tdarr, **d)
        result._freq = freq
    else:
        with warnings.catch_warnings():
            warnings.simplefilter('ignore')
            result = cls.__new__(cls, **d)
    return result

def _is_comparable_dtype(self, dtype: DtypeObj) -> bool:
    if isinstance(dtype, ArrowDtype):
        return dtype.kind == 'm'
    return lib.is_np_dtype(dtype, 'm')

def _get_arith_result_freq(self, other: object, op: Callable) -> Day | Tick | None:
    freq = self.freq
    assert freq is not None
    if op in (operator.mul, rmul):
        if bool(isna(other)):
            return None
        new_freq = freq * other
        if new_freq.n == 0:
            return None
        return new_freq
    if op in (operator.truediv, operator.floordiv):
        if isinstance(freq, Day):
            if freq.n % other == 0:
                new_freq = Day(freq.n // other)
            else:
                new_freq = to_offset(Timedelta(days=freq.n)) / other
        else:
            new_freq = freq / other
        if new_freq.nanos == 0 and freq.nanos != 0:
            return None
        return new_freq
    if op is rsub:
        return -freq
    return None

def _get_rsub_datetime_result_freq(self, other: object) -> Day | Tick | None:
    freq = self.freq
    assert freq is not None
    if isinstance(freq, Tick):
        return -freq
    if isinstance(other, Timestamp):
        tz = other.tz
    else:
        tz = Timestamp(other).tz
    if tz is None or timezones.is_utc(tz):
        return -freq
    return None

def get_loc(self, key):
    self._check_indexing_error(key)
    try:
        key = self._data._validate_scalar(key, unbox=False)
    except TypeError as err:
        raise KeyError(key) from err
    return Index.get_loc(self, key)

@set_module('pandas')
def timedelta_range(start=None, end=None, periods: int | None=None, freq=None, name=None, closed=None, *, unit: TimeUnit | None=None) -> TimedeltaIndex:
    if freq is None and com.any_none(periods, start, end):
        freq = 'D'
    freq = to_offset(freq)
    if com.count_not_none(start, end, periods, freq) != 3:
        raise ValueError('Of the four parameters: start, end, periods, and freq, exactly three must be specified')
    if unit is None:
        if start is not None and end is not None:
            start = Timedelta(start)
            end = Timedelta(end)
            start = cast('Timedelta', start)
            end = cast('Timedelta', end)
            if abbrev_to_npy_unit(start.unit) > abbrev_to_npy_unit(end.unit):
                unit = cast('TimeUnit', start.unit)
            else:
                unit = cast('TimeUnit', end.unit)
        elif start is not None:
            start = Timedelta(start)
            start = cast('Timedelta', start)
            unit = cast('TimeUnit', start.unit)
        else:
            end = Timedelta(end)
            end = cast('Timedelta', end)
            unit = cast('TimeUnit', end.unit)
        if freq is not None:
            freq = cast('Tick | Day', freq)
            creso = abbrev_to_npy_unit(unit)
            if freq._creso > creso:
                unit = cast('TimeUnit', freq.base.freqstr)
    tdarr = TimedeltaArray._generate_range(start, end, periods, freq, closed=closed, unit=unit)
    result = TimedeltaIndex._simple_new(tdarr, name=name)
    result._freq = freq
    return result

