    warnings.warn("set_eng_float_format is deprecated and will be removed in a future version. Use pd.set_option('display.precision', N) to control decimal precision, or pass a custom callable to pd.set_option('display.float_format', func).", Pandas4Warning, stacklevel=find_stack_level())
