def _windowsconsoleio_workaround(stream: TextIO) -> None:
    if not sys.platform.startswith('win32') or hasattr(sys, 'pypy_version_info'):
        return
    if not hasattr(stream, 'buffer'):
        return
    raw_stdout = stream.buffer.raw if hasattr(stream.buffer, 'raw') else stream.buffer
    if not isinstance(raw_stdout, io._WindowsConsoleIO):
        return

    def _reopen_stdio(f, mode):
        if not hasattr(stream.buffer, 'raw') and mode[0] == 'w':
            buffering = 0
        else:
            buffering = -1
        return io.TextIOWrapper(open(os.dup(f.fileno()), mode, buffering), f.encoding, f.errors, f.newlines, f.line_buffering)
    sys.stdin = _reopen_stdio(sys.stdin, 'rb')
    sys.stdout = _reopen_stdio(sys.stdout, 'wb')
    sys.stderr = _reopen_stdio(sys.stderr, 'wb')

def done(self) -> None:
    self._assert_state('done', ('initialized', 'started', 'suspended', 'done'))
    if self._state == 'done':
        return
    os.dup2(self.targetfd_save, self.targetfd)
    os.close(self.targetfd_save)
    if self.targetfd_invalid is not None:
        if self.targetfd_invalid != self.targetfd:
            os.close(self.targetfd)
        os.close(self.targetfd_invalid)
    self.syscapture.done()
    self.tmpfile.close()
    self._state = 'done'

def writeorg(self, data: bytes) -> None:
    self._assert_state('writeorg', ('started', 'suspended'))
    os.write(self.targetfd_save, data)

def writeorg(self, data: str) -> None:
    self._assert_state('writeorg', ('started', 'suspended'))
    os.write(self.targetfd_save, data.encode('utf-8'))

def pop_outerr_to_orig(self) -> tuple[AnyStr, AnyStr]:
