        from _pytest.outcomes import fail
        fail(f'Could not determine arguments of {function!r}: {e}', pytrace=False)
    arg_names = tuple((p.name for p in parameters if (p.kind is Parameter.POSITIONAL_OR_KEYWORD or p.kind is Parameter.KEYWORD_ONLY) and p.default is Parameter.empty))
    if not name:
        name = function.__name__
    if not any((p.kind is Parameter.POSITIONAL_ONLY for p in parameters)) and (cls and (not isinstance(inspect.getattr_static(cls, name, default=None), staticmethod))):
        arg_names = arg_names[1:]
    if hasattr(function, '__wrapped__'):
        arg_names = arg_names[num_mock_patch_args(function):]
    return arg_names

