    try:
        result: FixtureValue = ihook.pytest_fixture_setup(fixturedef=self, request=request)
    finally:
        request.node.addfinalizer(finalizer)
    return result

def resolve_fixture_function(fixturedef: FixtureDef[FixtureValue], request: FixtureRequest) -> _FixtureFunc[FixtureValue]:
    fixturefunc = fixturedef.func
    instance = request.instance
    if fixturedef._scope is Scope.Class:
        if hasattr(fixturefunc, '__self__'):
            bound_to = fixturefunc.__self__
            if not isinstance(bound_to, type):
                warnings.warn(CLASS_FIXTURE_INSTANCE_METHOD, stacklevel=2)
    if instance is not None:
        if hasattr(fixturefunc, '__self__') and (not isinstance(instance, fixturefunc.__self__.__class__)):
            return fixturefunc
        fixturefunc = getimfunc(fixturedef.func)
        if fixturefunc != fixturedef.func:
            fixturefunc = fixturefunc.__get__(instance)
    return fixturefunc

def pytest_fixture_setup(fixturedef: FixtureDef[FixtureValue], request: SubRequest) -> FixtureValue:
    kwargs = {}
    for argname in fixturedef.argnames:
        kwargs[argname] = request.getfixturevalue(argname)
    fixturefunc = resolve_fixture_function(fixturedef, request)
    my_cache_key = fixturedef.cache_key(request)
    if inspect.isasyncgenfunction(fixturefunc) or inspect.iscoroutinefunction(fixturefunc):
        auto_str = ' with autouse=True' if fixturedef._autouse else ''
        fail(f'{request.node.name!r} requested an async fixture {request.fixturename!r}{auto_str}, with no plugin or hook that handled it. This is an error, as pytest does not natively support it.\nSee: https://docs.pytest.org/en/stable/deprecations.html#sync-test-depending-on-async-fixture', pytrace=False)
    try:
        result = call_fixture_func(fixturefunc, request, kwargs)
    except TEST_OUTCOME as e:
        if isinstance(e, skip.Exception):
            e._use_item_location = True
        fixturedef.cached_result = (None, my_cache_key, (e, e.__traceback__))
        raise
    fixturedef.cached_result = (result, my_cache_key, None)
    return result

