    for marker_node, mark in node.iter_markers_with_node(name='usefixtures'):
        if not mark.args:
            marker_node.warn(PytestWarning(f'usefixtures() in {node.nodeid} without arguments has no effect'))
        yield from mark.args

def pytest_generate_tests(self, metafunc: Metafunc) -> None:

    def get_parametrize_mark_argnames(mark: Mark) -> Sequence[str]:
        args, _ = ParameterSet._parse_parametrize_args(*mark.args, **mark.kwargs)
        return args
    for argname in metafunc.fixturenames:
        fixture_defs = metafunc._arg2fixturedefs.get(argname, ())
        if any((argname in get_parametrize_mark_argnames(mark) for mark in metafunc.definition.iter_markers('parametrize'))):
            continue
        for fixturedef in reversed(fixture_defs):
            if fixturedef.params is not None:
                metafunc.parametrize(argname, fixturedef.params, indirect=True, scope=fixturedef.scope, ids=fixturedef.ids)
                break
            if argname not in fixturedef.argnames:
                break

def _register_fixture(self, *, name: str, func: _FixtureFunc[object], nodeid: str | None | NotSetType=NOTSET, scope: Scope | ScopeName | Callable[[str, Config], ScopeName]='function', params: Sequence[object] | None=None, ids: tuple[object | None, ...] | Callable[[Any], object | None] | None=None, autouse: bool=False, node: nodes.Node | NotSetType=NOTSET) -> None:
    if nodeid is not NOTSET or node is NOTSET:
        warnings.warn(FIXTURE_NODEID_DEPRECATED, stacklevel=2)
    fixture_def = FixtureDef(config=self.config, baseid=nodeid, argname=name, func=func, scope=scope, params=params, ids=ids, _ispytest=True, _autouse=autouse, node=node)
    faclist = self._arg2fixturedefs.setdefault(name, [])
    for i, existing in enumerate(faclist):
        if is_visibility_more_specific(existing, fixture_def):
            faclist.insert(i, fixture_def)
            break
    else:
        faclist.append(fixture_def)
    if autouse:
        if node is not NOTSET:
            self._node_autousenames.setdefault(node, []).append(name)
        elif nodeid is not NOTSET and nodeid is not None:
            self._nodeid_autousenames.setdefault(nodeid, []).append(name)
        else:
            self._node_autousenames.setdefault(self.session, []).append(name)

def _lookup_in_type_dict(self, owner: type | types.ModuleType, name: str) -> object | None:
    if isinstance(owner, types.ModuleType):
        return owner.__dict__.get(name)
    for base in owner.__mro__:
        try:
            return cast(object, base.__dict__[name])
        except KeyError:
            continue
    return None

def _find_wrapped_fixture_def(self, obj: object) -> FixtureFunctionDefinition | None:
    if safe_getattr(obj, '_mock_name', None) is not None:
        return None
    try:
        unwrapped = inspect.unwrap(cast(Callable[..., Any], obj), stop=lambda o: type(o) is FixtureFunctionDefinition)
    except Exception:
        return None
    if type(unwrapped) is FixtureFunctionDefinition:
        return unwrapped
    return None

def _check_for_wrapped_fixture(self, name: str, obj: object) -> None:
    fixture_def = self._find_wrapped_fixture_def(obj)
    if fixture_def is None or fixture_def is obj:
        return
    fixture_func: object = fixture_def._get_wrapped_function()
    if type(fixture_func) is classmethod or type(fixture_func) is staticmethod:
        fixture_func = fixture_func.__func__
    if not isinstance(fixture_func, types.FunctionType):
        return
    if type(obj) is classmethod:
        msg = f'cannot discover fixture {name!r} because it is wrapped by @classmethod; place @pytest.fixture above @classmethod'
    elif type(obj) is staticmethod:
        msg = f'fixture {name!r} is wrapped by @staticmethod above @pytest.fixture; place @pytest.fixture above @staticmethod'
    else:
        msg = f'cannot discover fixture {name!r} due to being wrapped in decorators'
    warn_explicit_for(fixture_func, PytestWarning(msg))

def parsefactories(self, node_or_obj: nodes.Node | object | NotSetType=NOTSET, nodeid: str | None | NotSetType=NOTSET, *, holder: object | NotSetType=NOTSET, node: nodes.Node | NotSetType=NOTSET) -> None:
    effective_node: nodes.Node | NotSetType = NOTSET
    effective_nodeid: str | None | NotSetType = NOTSET
    if holder is not NOTSET:
        holderobj = holder
        effective_node = node
    elif node_or_obj is NOTSET:
        raise TypeError('parsefactories() requires holder or node_or_obj')
    elif nodeid is not NOTSET:
        warnings.warn(PARSEFACTORIES_NODEID_DEPRECATED, stacklevel=2)
        holderobj = node_or_obj
        effective_nodeid = nodeid
    else:
        assert isinstance(node_or_obj, nodes.Node)
        holderobj = cast(object, node_or_obj.obj)
        effective_node = node_or_obj
    holderobj_tp: type | types.ModuleType
    if not safe_isclass(holderobj) and (not isinstance(holderobj, types.ModuleType)):
        holderobj_tp = type(holderobj)
    else:
        holderobj_tp = cast('type | types.ModuleType', holderobj)
    for name in dir(holderobj):
        raw_obj = self._lookup_in_type_dict(holderobj_tp, name)
        if raw_obj is not None:
            self._check_for_wrapped_fixture(name, raw_obj)
        obj_ub = safe_getattr(holderobj_tp, name, None)
        if type(obj_ub) is FixtureFunctionDefinition:
            if type(raw_obj) is classmethod:
                continue
            marker = obj_ub._fixture_function_marker
            if marker.name:
                fixture_name = marker.name
            else:
                fixture_name = name
            try:
                obj = getattr(holderobj, name)
            except AttributeError:
                obj = obj_ub
            func = obj._get_wrapped_function()
            self._register_fixture(name=fixture_name, func=func, scope=marker.scope, params=marker.params, ids=marker.ids, autouse=marker.autouse, node=effective_node, nodeid=effective_nodeid)

def getfixturedefs(self, argname: str, node: nodes.Node) -> Sequence[FixtureDef[Any]] | None:
    try:
        fixturedefs = self._arg2fixturedefs[argname]
    except KeyError:
        return None
    return tuple(self._matchfactories(fixturedefs, node))

def _get_fixtures_per_test(test: nodes.Item) -> Iterator[FixtureDef[object]]:
    from _pytest.python import DirectParamFixtureDef
    fixture_info: FuncFixtureInfo | None = getattr(test, '_fixtureinfo', None)
    if fixture_info is None:
        return
    for argname, fixturedefs in sorted(fixture_info.name2fixturedefs.items()):
        if not fixturedefs:
            continue
        fixturedef = fixturedefs[-1]
        if isinstance(fixturedef, DirectParamFixtureDef):
            continue
        yield fixturedef

def _iter_all_modules(package: str | types.ModuleType, prefix: str='') -> Iterator[str]:
    import os
    import pkgutil
    if isinstance(package, str):
        path = package
    else:
        package_path = package.__path__
        path, prefix = (package_path[0], package.__name__ + '.')
    for _, name, is_package in pkgutil.iter_modules([path]):
        if is_package:
            for m in _iter_all_modules(os.path.join(path, name), prefix=name + '.'):
                yield (prefix + m)
        else:
            yield (prefix + name)

