def bin_xml_escape(arg: object) -> str:

    def repl(matchobj: re.Match[str]) -> str:
        i = ord(matchobj.group())
        if i <= 255:
            return f'#x{i:02X}'
        else:
            return f'#x{i:04X}'
    illegal_xml_re = '[^\t\n\r -~\x80-\ud7ff\ue000-�𐀀-\U0010ffff]'
    return re.sub(illegal_xml_re, repl, str(arg))

