def pytest_runtest_logreport(self, report: TestReport) -> None:
    close_report = None
    if report.passed:
        if report.when == 'call':
            reporter = self._opentestcase(report)
            reporter.append_pass(report)
    elif report.failed:
        if report.when == 'teardown':
            report_wid = getattr(report, 'worker_id', None)
            report_ii = getattr(report, 'item_index', None)
            close_report = next((rep for rep in self.open_reports if rep.nodeid == report.nodeid and getattr(rep, 'item_index', None) == report_ii and (getattr(rep, 'worker_id', None) == report_wid)), None)
            if close_report:
                self.finalize(close_report)
            else:
                self.cnt_double_fail_tests += int((report.nodeid, getattr(report, 'node', None)) in self.node_reporters)
        reporter = self._opentestcase(report)
        if report.when == 'call':
            reporter.append_failure(report)
            self.open_reports.append(report)
            if not self.log_passing_tests:
                reporter.write_captured_output(report)
        else:
            reporter.append_error(report)
    elif report.skipped:
        reporter = self._opentestcase(report)
        reporter.append_skipped(report)
    self.update_testcase_duration(report)
    if report.when == 'teardown':
        reporter = self._opentestcase(report)
        reporter.write_captured_output(report)
        self.finalize(report)
        report_wid = getattr(report, 'worker_id', None)
        report_ii = getattr(report, 'item_index', None)
        close_report = next((rep for rep in self.open_reports if rep.nodeid == report.nodeid and getattr(rep, 'item_index', None) == report_ii and (getattr(rep, 'worker_id', None) == report_wid)), None)
        if close_report:
            self.open_reports.remove(close_report)

def update_testcase_duration(self, report: TestReport) -> None:
    if self.report_duration in {'total', report.when}:
        reporter = self.node_reporter(report)
        reporter.duration += getattr(report, 'duration', 0.0)

