def add_color_level(self, level: int, *color_opts: str) -> None:
    assert self._fmt is not None
    levelname_fmt_match = self.LEVELNAME_FMT_REGEX.search(self._fmt)
    if not levelname_fmt_match:
        return
    levelname_fmt = levelname_fmt_match.group()
    formatted_levelname = levelname_fmt % {'levelname': logging.getLevelName(level)}
    color_kwargs = {name: True for name in color_opts}
    colorized_formatted_levelname = self._terminalwriter.markup(formatted_levelname, **color_kwargs)
    self._level_to_fmt_mapping[level] = self.LEVELNAME_FMT_REGEX.sub(colorized_formatted_levelname, self._fmt)

@staticmethod
def _get_auto_indent(auto_indent_option: int | str | bool | None) -> int:
    match auto_indent_option:
        case None | False:
            return 0
        case True:
            return -1
        case int():
            return auto_indent_option
        case str():
            try:
                return int(auto_indent_option)
            except ValueError:
                pass
            try:
                if _strtobool(auto_indent_option):
                    return -1
            except ValueError:
                return 0
            return 0

def __init__(self) -> None:
