    if with_parents:
        return path_ in self._initialpaths_with_parents
    else:
        return path_ in self._initialpaths

def _collect_path(self, path: Path, path_cache: dict[Path, Sequence[nodes.Collector]]) -> Sequence[nodes.Collector]:
    if path in path_cache:
        return path_cache[path]
    if path.is_dir():
        ihook = self.gethookproxy(path.parent)
        col: nodes.Collector | None = ihook.pytest_collect_directory(path=path, parent=self)
        cols: Sequence[nodes.Collector] = (col,) if col is not None else ()
    elif path.is_file():
        ihook = self.gethookproxy(path)
        cols = ihook.pytest_collect_file(file_path=path, parent=self)
    else:
        cols = ()
    path_cache[path] = cols
    return cols

def perform_collect(self, args: Sequence[str] | None=None, genitems: bool=True) -> Sequence[nodes.Item | nodes.Collector]:
    if args is None:
        args = self.config.args
    self.trace('perform_collect', self, args)
    self.trace.root.indent += 1
    hook = self.config.hook
    self._notfound = []
    self._initial_parts = []
    self._collection_cache = {}
    self.items = []
    items: Sequence[nodes.Item | nodes.Collector] = self.items
    consider_namespace_packages: bool = self.config.getini('consider_namespace_packages')
    try:
        initialpaths: list[Path] = []
        initialpaths_with_parents: list[Path] = []
        collection_args = [resolve_collection_argument(self.config.invocation_params.dir, arg, i, as_pypath=self.config.option.pyargs, consider_namespace_packages=consider_namespace_packages) for i, arg in enumerate(args)]
        if not self.config.getoption('keepduplicates'):
            self._initial_parts = normalize_collection_arguments(collection_args)
        else:
            self._initial_parts = collection_args
        for collection_argument in self._initial_parts:
            initialpaths.append(collection_argument.path)
            initialpaths_with_parents.append(collection_argument.path)
            initialpaths_with_parents.extend(collection_argument.path.parents)
        self._initialpaths = frozenset(initialpaths)
        self._initialpaths_with_parents = frozenset(initialpaths_with_parents)
        rep = collect_one_node(self)
        self.ihook.pytest_collectreport(report=rep)
        self.trace.root.indent -= 1
        if self._notfound:
            errors = []
            for arg, collectors in self._notfound:
                if collectors:
                    errors.append(f'not found: {arg}\n(no match in any of {collectors!r})')
                else:
                    errors.append(f'found no collectors for {arg}')
            raise UsageError(*errors)
        if not genitems:
            items = rep.result
        elif rep.passed:
            for node in rep.result:
                self.items.extend(self.genitems(node))
        self.config.pluginmanager.check_pending()
        hook.pytest_collection_modifyitems(session=self, config=self.config, items=items)
    finally:
        self._notfound = []
        self._initial_parts = []
        self._collection_cache = {}
        hook.pytest_collection_finish(session=self)
    if genitems:
        self.testscollected = len(items)
    return items

def search_pypath(module_name: str, *, consider_namespace_packages: bool=False) -> str | None:
    try:
        spec = importlib.util.find_spec(module_name)
    except (AttributeError, ImportError, ValueError):
        return None
    if spec is None:
        return None
    if spec.submodule_search_locations is None or len(spec.submodule_search_locations) == 0:
        return spec.origin
    if consider_namespace_packages:
        return spec.submodule_search_locations[0]
    if spec.origin is None:
        return None
    return os.path.dirname(spec.origin)

def resolve_collection_argument(invocation_path: Path, arg: str, arg_index: int, *, as_pypath: bool=False, consider_namespace_packages: bool=False) -> CollectionArgument:
    base, squacket, rest = arg.partition('[')
    strpath, *parts = base.split('::')
    if squacket and (not parts):
        raise UsageError(f'path cannot contain [] parametrization: {arg}')
    parametrization = f'{squacket}{rest}' if squacket else None
    module_name = None
    if as_pypath:
        pyarg_strpath = search_pypath(strpath, consider_namespace_packages=consider_namespace_packages)
        if pyarg_strpath is not None:
            module_name = strpath
            strpath = pyarg_strpath
    fspath = invocation_path / strpath
    fspath = absolutepath(fspath)
    if not safe_exists(fspath):
        msg = 'module or package not found: {arg} (missing __init__.py?)' if as_pypath else 'file or directory not found: {arg}'
        raise UsageError(msg.format(arg=arg))
    if parts and fspath.is_dir():
        msg = 'package argument cannot contain :: selection parts: {arg}' if as_pypath else 'directory argument cannot contain :: selection parts: {arg}'
        raise UsageError(msg.format(arg=arg))
    return CollectionArgument(path=fspath, parts=parts, parametrization=parametrization, module_name=module_name, original_index=arg_index)

def is_collection_argument_subsumed_by(arg: CollectionArgument, by: CollectionArgument) -> bool:
    if by.path != arg.path:
        if not by.parts:
            return arg.path.is_relative_to(by.path)
        return False
    if len(by.parts) > len(arg.parts) or arg.parts[:len(by.parts)] != by.parts:
        return False
    if by.parametrization is not None and by.parametrization != arg.parametrization:
        return False
    return True

def normalize_collection_arguments(collection_args: Sequence[CollectionArgument]) -> list[CollectionArgument]:
    collection_args_sorted = sorted(collection_args, key=lambda arg: (arg.path, arg.parts, arg.parametrization or ''))
    normalized: list[CollectionArgument] = []
    last_kept = None
    for arg in collection_args_sorted:
        if last_kept is None or not is_collection_argument_subsumed_by(arg, last_kept):
            normalized.append(arg)
            last_kept = arg
    normalized.sort(key=lambda arg: arg.original_index)
    return normalized

@fixture
def monkeypatch() -> Generator[MonkeyPatch]:
    mpatch = MonkeyPatch()
    yield mpatch
    mpatch.undo()

@classmethod
@contextmanager
def context(cls) -> Generator[MonkeyPatch]:
    m = cls()
    try:
        yield m
    finally:
        m.undo()

def setattr(self, target: str | object, name: object | str, value: object=NOTSET, raising: bool=True) -> None:
    __tracebackhide__ = True
    import inspect
    if value is NOTSET:
        if not isinstance(target, str):
            raise TypeError('use setattr(target, name, value) or setattr(target, value) with target being a dotted import string')
        value = name
        name, target = derive_importpath(target, raising)
    elif not isinstance(name, str):
        raise TypeError('use setattr(target, name, value) with name being a string or setattr(target, value) with target being a dotted import string')
    oldval = getattr(target, name, NOTSET)
    if raising and oldval is NOTSET:
        raise AttributeError(f'{target!r} has no attribute {name!r}')
    if inspect.isclass(target):
        oldval = target.__dict__.get(name, NOTSET)
    setattr(target, name, value)
    self._setattr.append((target, name, oldval))

def delattr(self, target: object | str, name: str | NotSetType=NOTSET, raising: bool=True) -> None:
    __tracebackhide__ = True
    import inspect
    if name is NOTSET:
        if not isinstance(target, str):
            raise TypeError('use delattr(target, name) or delattr(target) with target being a dotted import string')
        name, target = derive_importpath(target, raising)
    if not hasattr(target, name):
        if raising:
            raise AttributeError(name)
    else:
        oldval = getattr(target, name, NOTSET)
        if inspect.isclass(target):
            oldval = target.__dict__.get(name, NOTSET)
        self._setattr.append((target, name, oldval))
        delattr(target, name)

def setitem(self, dic: Mapping[K, V], name: K, value: V) -> None:
    self._setitem.append((dic, name, dic.get(name, NOTSET)))
    dic[name] = value

def delitem(self, dic: Mapping[K, V], name: K, raising: bool=True) -> None:
    if name not in dic:
        if raising:
            raise KeyError(name)
    else:
        self._setitem.append((dic, name, dic.get(name, NOTSET)))
        del dic[name]

def setenv(self, name: str, value: str, prepend: str | None=None) -> None:
    if not isinstance(value, str):
        warnings.warn(PytestWarning(f'Value of environment variable {name} type should be str, but got {value!r} (type: {type(value).__name__}); converted to str implicitly'), stacklevel=2)
        value = str(value)
    if prepend and name in os.environ:
        value = value + prepend + os.environ[name]
    self.setitem(os.environ, name, value)

def delenv(self, name: str, raising: bool=True) -> None:
    environ: MutableMapping[str, str] = os.environ
    self.delitem(environ, name, raising=raising)

def syspath_prepend(self, path) -> None:
    if self._savesyspath is None:
        self._savesyspath = sys.path[:]
    sys.path.insert(0, str(path))
    if 'pkg_resources' in sys.modules:
        import pkg_resources
        from pkg_resources import fixup_namespace_packages
        if hasattr(pkg_resources, '_namespace_packages') and pkg_resources._namespace_packages:
            path_obj = Path(str(path))
            for ns_pkg in pkg_resources._namespace_packages:
                if ns_pkg is None:
                    continue
                ns_pkg_path = path_obj / ns_pkg.replace('.', os.sep)
                if ns_pkg_path.is_dir():
                    warnings.warn(MONKEYPATCH_LEGACY_NAMESPACE_PACKAGES, stacklevel=2)
                    break
        fixup_namespace_packages(str(path))
    from importlib import invalidate_caches
    invalidate_caches()

def chdir(self, path: str | os.PathLike[str]) -> None:
    if self._cwd is None:
        self._cwd = os.getcwd()
    os.chdir(path)

def undo(self) -> None:
    for obj, name, value in reversed(self._setattr):
        if value is not NOTSET:
            setattr(obj, name, value)
        else:
            delattr(obj, name)
    self._setattr[:] = []
    for dictionary, key, value in reversed(self._setitem):
        if value is NOTSET:
            try:
                del dictionary[key]
            except KeyError:
                pass
        else:
            dictionary[key] = value
    self._setitem[:] = []
    if self._savesyspath is not None:
        sys.path[:] = self._savesyspath
        self._savesyspath = None
    if self._cwd is not None:
        os.chdir(self._cwd)
        self._cwd = None

@classmethod
