def importorskip(modname: str, minversion: str | None=None, reason: str | None=None, *, exc_type: type[ImportError] | None=None) -> Any:
    import warnings
    __tracebackhide__ = True
    compile(modname, '', 'eval')
    if exc_type is None:
        exc_type = ModuleNotFoundError
    skipped: Skipped | None = None
    with warnings.catch_warnings():
        warnings.simplefilter('ignore')
        try:
            importlib.import_module(modname)
        except exc_type as exc:
            if reason is None:
                reason = f'could not import {modname!r}: {exc}'
            skipped = Skipped(reason, allow_module_level=True)
    if skipped:
        raise skipped
    mod = sys.modules[modname]
    if minversion is None:
        return mod
    verattr = getattr(mod, '__version__', None)
    if minversion is not None:
        from packaging.version import Version
        if verattr is None or Version(verattr) < Version(minversion):
            raise Skipped(f'module {modname!r} has __version__ {verattr!r}, required is: {minversion!r}', allow_module_level=True)
    return mod

def create_new_paste(contents: str | bytes) -> str:
    import re
    from urllib.error import HTTPError
    from urllib.parse import urlencode
    from urllib.request import urlopen
    params = {'code': contents, 'lexer': 'text', 'expiry': '1week'}
    url = 'https://bpa.st'
    try:
        response: str = urlopen(url, data=urlencode(params).encode('ascii')).read().decode('utf-8')
    except HTTPError as e:
        with e:
            return f'bad response: {e}'
    except OSError as e:
        return f'bad response: {e}'
    m = re.search('href="/raw/(\\w+)"', response)
    if m:
        return f'{url}/show/{m.group(1)}'
    else:
        return "bad response: invalid format ('" + response + "')"

def _chmod_rwx(p: str) -> bool:
    try:
        old_mode = os.stat(p).st_mode
    except OSError:
        return False
    perm_mode = stat.S_IMODE(old_mode)
    bits = stat.S_IRWXU if stat.S_ISDIR(old_mode) else stat.S_IRUSR | stat.S_IWUSR
    new_mode = perm_mode | bits
    if perm_mode == new_mode:
        return False
    try:
        os.chmod(p, new_mode)
    except OSError:
        return False
    return True

def on_rm_rf_error(func: Callable[..., Any] | None, path: str, excinfo: BaseException | tuple[type[BaseException], BaseException, types.TracebackType | None], *, start_path: Path) -> bool:
    if isinstance(excinfo, BaseException):
        exc = excinfo
    else:
        exc = excinfo[1]
    if isinstance(exc, FileNotFoundError):
        return False
    if not isinstance(exc, PermissionError):
        warnings.warn(PytestWarning(f'(rm_rf) error removing {path}\n{type(exc)}: {exc}'))
        return False
    p = Path(path)
    if func in (os.open, os.scandir):
        parent_changed = False
        parent = p.parent
        if parent not in (p, start_path):
            parent_changed = _chmod_rwx(str(parent))
        path_changed = _chmod_rwx(str(p))
        if not (parent_changed or path_changed):
            return False
        if p.is_dir():
            rm_rf(p)
        else:
            try:
                os.unlink(str(p))
            except OSError:
                return False
        return True
    if func not in (os.rmdir, os.remove, os.unlink):
        warnings.warn(PytestWarning(f'(rm_rf) unknown function {func} when removing {path}:\n{type(exc)}: {exc}'))
        return False
    if p.is_file():
        for parent in p.parents:
            _chmod_rwx(str(parent))
            if parent == start_path:
                break
    _chmod_rwx(str(path))
    func(path)
    return True

def ensure_extended_length_path(path: Path) -> Path:
    if sys.platform.startswith('win32'):
        path = path.resolve()
        path = Path(get_extended_length_path_str(str(path)))
    return path

def get_extended_length_path_str(path: str) -> str:
    long_path_prefix = '\\\\?\\'
    unc_long_path_prefix = '\\\\?\\UNC\\'
    if path.startswith((long_path_prefix, unc_long_path_prefix)):
        return path
    if path.startswith('\\\\'):
        return unc_long_path_prefix + path[2:]
    return long_path_prefix + path

def rm_rf(path: Path) -> None:
    path = ensure_extended_length_path(path)
    onerror = partial(on_rm_rf_error, start_path=path)
    if sys.version_info >= (3, 12):
        shutil.rmtree(str(path), onexc=onerror)
    else:
        shutil.rmtree(str(path), onerror=onerror)

def find_prefixed(root: Path, prefix: str) -> Iterator[os.DirEntry[str]]:
    l_prefix = prefix.lower()
    for x in os.scandir(root):
        if x.name.lower().startswith(l_prefix):
            yield x

def extract_suffixes(iter: Iterable[os.DirEntry[str]], prefix: str) -> Iterator[str]:
    p_len = len(prefix)
    for entry in iter:
        yield entry.name[p_len:]

def parse_num(maybe_num: str) -> int:
    try:
        return int(maybe_num)
    except ValueError:
        return -1

def _force_symlink(root: Path, target: str | PurePath, link_to: str | Path) -> None:
    current_symlink = root.joinpath(target)
    try:
        current_symlink.unlink()
    except OSError:
        pass
    try:
        current_symlink.symlink_to(link_to)
    except Exception:
        pass

def make_numbered_dir(root: Path, prefix: str, mode: int=448) -> Path:
    for i in range(10):
        max_existing = max(map(parse_num, find_suffixes(root, prefix)), default=-1)
        new_number = max_existing + 1
        new_path = root.joinpath(f'{prefix}{new_number}')
        try:
            new_path.mkdir(mode=mode)
        except Exception:
            pass
        else:
            _force_symlink(root, prefix + 'current', new_path)
            return new_path
    else:
        raise OSError(f'could not create numbered dir with prefix {prefix} in {root} after 10 tries')

def create_cleanup_lock(p: Path) -> Path:
    lock_path = get_lock_path(p)
    try:
        fd = os.open(str(lock_path), os.O_WRONLY | os.O_CREAT | os.O_EXCL, 420)
    except FileExistsError as e:
        raise OSError(f'cannot create lockfile in {p}') from e
    else:
        pid = os.getpid()
        spid = str(pid).encode()
        os.write(fd, spid)
        os.close(fd)
        if not lock_path.is_file():
            raise OSError('lock path got renamed after successful creation')
        return lock_path

def register_cleanup_lock_removal(lock_path: Path, register: Any) -> Any:
    pid = os.getpid()

    def cleanup_on_exit(lock_path: Path=lock_path, original_pid: int=pid) -> None:
        current_pid = os.getpid()
        if current_pid != original_pid:
            return
        try:
            lock_path.unlink()
        except OSError:
            pass
    return register(cleanup_on_exit)

def maybe_delete_a_numbered_dir(path: Path) -> None:
    path = ensure_extended_length_path(path)
    lock_path = None
    try:
        lock_path = create_cleanup_lock(path)
        parent = path.parent
        garbage = parent.joinpath(f'garbage-{uuid.uuid4()}')
        path.rename(garbage)
        rm_rf(garbage)
    except OSError:
        return
    finally:
        if lock_path is not None:
            try:
                lock_path.unlink()
            except OSError:
                pass

def ensure_deletable(path: Path, consider_lock_dead_if_created_before: float) -> bool:
    if path.is_symlink():
        return False
    lock = get_lock_path(path)
    try:
        if not lock.is_file():
            return True
    except OSError:
        return False
    try:
        lock_time = lock.stat().st_mtime
    except Exception:
        return False
    else:
        if lock_time < consider_lock_dead_if_created_before:
            with contextlib.suppress(OSError):
                lock.unlink()
                return True
        return False

def try_cleanup(path: Path, consider_lock_dead_if_created_before: float) -> None:
    if ensure_deletable(path, consider_lock_dead_if_created_before):
        maybe_delete_a_numbered_dir(path)

def cleanup_candidates(root: Path, prefix: str, keep: int) -> Iterator[Path]:
    max_existing = max(map(parse_num, find_suffixes(root, prefix)), default=-1)
    max_delete = max_existing - keep
    entries = find_prefixed(root, prefix)
    entries, entries2 = itertools.tee(entries)
    numbers = map(parse_num, extract_suffixes(entries2, prefix))
    for entry, number in zip(entries, numbers, strict=True):
        if number <= max_delete:
            yield Path(entry)

def cleanup_numbered_dir(root: Path, prefix: str, keep: int, consider_lock_dead_if_created_before: float) -> None:
    if not root.exists():
        return
    for path in cleanup_candidates(root, prefix, keep):
        try_cleanup(path, consider_lock_dead_if_created_before)
    for path in root.glob('garbage-*'):
        try_cleanup(path, consider_lock_dead_if_created_before)
    cleanup_dead_symlinks(root)

def make_numbered_dir_with_cleanup(*, root: Path, prefix: str, mode: int, keep: int, lock_timeout: float, register: Any) -> Path:
    e = None
    for i in range(10):
        try:
            p = make_numbered_dir(root, prefix, mode)
            if keep != 0:
                lock_path = create_cleanup_lock(p)
                register_cleanup_lock_removal(lock_path, register)
        except Exception as exc:
            e = exc
        else:
            consider_lock_dead_if_created_before = p.stat().st_mtime - lock_timeout
            register(cleanup_numbered_dir, root, prefix, keep, consider_lock_dead_if_created_before)
            return p
    assert e is not None
    raise e

def fnmatch_ex(pattern: str, path: str | os.PathLike[str]) -> bool:
    path = PurePath(path)
    iswin32 = sys.platform.startswith('win')
    if iswin32 and sep not in pattern and (posix_sep in pattern):
        pattern = pattern.replace(posix_sep, sep)
    if sep not in pattern:
        name = path.name
    else:
        name = str(path)
        if path.is_absolute() and (not os.path.isabs(pattern)):
            pattern = f'*{os.sep}{pattern}'
    return fnmatch.fnmatch(name, pattern)

def symlink_or_skip(src: os.PathLike[str] | str, dst: os.PathLike[str] | str, **kwargs: Any) -> None:
    try:
        os.symlink(src, dst, **kwargs)
    except OSError as e:
        skip(f'symlinks not supported: {e}')

def import_path(path: str | os.PathLike[str], *, mode: str | ImportMode=ImportMode.prepend, root: Path, consider_namespace_packages: bool) -> ModuleType:
    path = Path(path)
    mode = ImportMode(mode)
    if not path.exists():
        raise ImportError(path)
    if mode is ImportMode.importlib:
        try:
            _, module_name = resolve_pkg_root_and_module_name(path, consider_namespace_packages=consider_namespace_packages)
        except CouldNotResolvePathError:
            pass
        else:
            with contextlib.suppress(KeyError):
                return sys.modules[module_name]
            mod = _import_module_using_spec(module_name, path, insert_modules=False)
            if mod is not None:
                return mod
        module_name = module_name_from_path(path, root)
        with contextlib.suppress(KeyError):
            return sys.modules[module_name]
        mod = _import_module_using_spec(module_name, path, insert_modules=True)
        if mod is None:
            raise ImportError(f"Can't find module {module_name} at location {path}")
        return mod
    try:
        pkg_root, module_name = resolve_pkg_root_and_module_name(path, consider_namespace_packages=consider_namespace_packages)
    except CouldNotResolvePathError:
        pkg_root, module_name = (path.parent, path.stem)
    if mode is ImportMode.append:
        if str(pkg_root) not in sys.path:
            sys.path.append(str(pkg_root))
    elif mode is ImportMode.prepend:
        if str(pkg_root) != sys.path[0]:
            sys.path.insert(0, str(pkg_root))
    else:
        assert_never(mode)
    importlib.import_module(module_name)
    mod = sys.modules[module_name]
    if path.name == '__init__.py':
        return mod
    ignore = os.environ.get('PY_IGNORE_IMPORTMISMATCH', '')
    if ignore != '1':
        module_file = mod.__file__
        if module_file is None:
            raise ImportPathMismatchError(module_name, module_file, path)
        if module_file.endswith(('.pyc', '.pyo')):
            module_file = module_file[:-1]
        if module_file.endswith(os.sep + '__init__.py'):
            module_file = module_file[:-len(os.sep + '__init__.py')]
        try:
            is_same = _is_same(str(path), module_file)
        except FileNotFoundError:
            is_same = False
        if not is_same:
            raise ImportPathMismatchError(module_name, module_file, path)
    return mod

def _import_module_using_spec(module_name: str, module_path: Path, *, insert_modules: bool) -> ModuleType | None:
    parent_module_name, _, name = module_name.rpartition('.')
    parent_module: ModuleType | None = None
    if parent_module_name:
        parent_module = sys.modules.get(parent_module_name)
        need_reimport = not hasattr(parent_module, '__path__')
        if parent_module is None or need_reimport:
            if module_path.name == '__init__.py':
                parent_module_path = module_path.parent.parent
            else:
                parent_module_path = module_path.parent
            if (parent_module_path / '__init__.py').is_file():
                parent_module_path = parent_module_path / '__init__.py'
            parent_module = _import_module_using_spec(parent_module_name, parent_module_path, insert_modules=insert_modules)
    find_spec_path = [str(module_path.parent)]
    for meta_importer in sys.meta_path:
        spec = meta_importer.find_spec(module_name, find_spec_path)
        if spec_matches_module_path(spec, module_path):
            break
    else:
        loader = None
        if module_path.is_dir():
            loader = NamespaceLoader(name, module_path, PathFinder())
        spec = importlib.util.spec_from_file_location(module_name, str(module_path), loader=loader)
    if spec_matches_module_path(spec, module_path):
        assert spec is not None
        mod = importlib.util.module_from_spec(spec)
        sys.modules[module_name] = mod
        spec.loader.exec_module(mod)
        if parent_module is not None:
            setattr(parent_module, name, mod)
        if insert_modules:
            insert_missing_modules(sys.modules, module_name)
        return mod
    return None

def spec_matches_module_path(module_spec: ModuleSpec | None, module_path: Path) -> bool:
    if module_spec is None:
        return False
    if module_spec.origin:
        return Path(module_spec.origin) == module_path
    if module_spec.submodule_search_locations:
        for path in module_spec.submodule_search_locations:
            if Path(path) == module_path:
                return True
    return False

def module_name_from_path(path: Path, root: Path) -> str:
    path = path.with_suffix('')
    try:
        relative_path = path.relative_to(root)
    except ValueError:
        path_parts = path.parts[1:]
    else:
        path_parts = relative_path.parts
    if len(path_parts) >= 2 and path_parts[-1] == '__init__':
        path_parts = path_parts[:-1]
    path_parts = tuple((x.replace('.', '_') for x in path_parts))
    return '.'.join(path_parts)

def insert_missing_modules(modules: dict[str, ModuleType], module_name: str) -> None:
    module_parts = module_name.split('.')
    while module_name:
        parent_module_name, _, child_name = module_name.rpartition('.')
        if parent_module_name:
            parent_module = modules.get(parent_module_name)
            if parent_module is None:
                try:
                    if not sys.meta_path:
                        raise ModuleNotFoundError
                    parent_module = importlib.import_module(parent_module_name)
                except ModuleNotFoundError:
                    parent_module = ModuleType(module_name, doc="Empty module created by pytest's importmode=importlib.")
                modules[parent_module_name] = parent_module
            if not hasattr(parent_module, child_name):
                setattr(parent_module, child_name, modules[module_name])
        module_parts.pop(-1)
        module_name = '.'.join(module_parts)

def resolve_package_path(path: Path) -> Path | None:
    result = None
    for parent in itertools.chain((path,), path.parents):
        if parent.is_dir():
            if not (parent / '__init__.py').is_file():
                break
            if not parent.name.isidentifier():
                break
            result = parent
    return result

def resolve_pkg_root_and_module_name(path: Path, *, consider_namespace_packages: bool=False) -> tuple[Path, str]:
    pkg_root: Path | None = None
    pkg_path = resolve_package_path(path)
    if pkg_path is not None:
        pkg_root = pkg_path.parent
    if consider_namespace_packages:
        start = pkg_root if pkg_root is not None else path.parent
        for candidate in (start, *start.parents):
            module_name = compute_module_name(candidate, path)
            if module_name and is_importable(module_name, path):
                pkg_root = candidate
                break
    if pkg_root is not None:
        module_name = compute_module_name(pkg_root, path)
        if module_name:
            return (pkg_root, module_name)
    raise CouldNotResolvePathError(f'Could not resolve for {path}')

def is_importable(module_name: str, module_path: Path) -> bool:
    try:
        spec = importlib.util.find_spec(module_name)
    except (ImportError, ValueError, ImportWarning):
        return False
    else:
        return spec_matches_module_path(spec, module_path)

def compute_module_name(root: Path, module_path: Path) -> str | None:
    try:
        path_without_suffix = module_path.with_suffix('')
    except ValueError:
        return None
    try:
        relative = path_without_suffix.relative_to(root)
    except ValueError:
        return None
    names = list(relative.parts)
    if not names:
        return None
    if names[-1] == '__init__':
        names.pop()
    return '.'.join(names)

def scandir(path: str | os.PathLike[str], sort_key: Callable[[os.DirEntry[str]], object]=lambda entry: entry.name) -> list[os.DirEntry[str]]:
    entries = []
    try:
        scandir_iter = os.scandir(path)
    except FileNotFoundError:
        return []
    with scandir_iter as s:
        for entry in s:
            try:
                entry.is_file()
            except OSError as err:
                if _ignore_error(err):
                    continue
                raise
            entries.append(entry)
    entries.sort(key=sort_key)
    return entries

def visit(path: str | os.PathLike[str], recurse: Callable[[os.DirEntry[str]], bool]) -> Iterator[os.DirEntry[str]]:
    entries = scandir(path)
    yield from entries
    for entry in entries:
        if entry.is_dir() and recurse(entry):
            yield from visit(entry.path, recurse)

def commonpath(path1: Path, path2: Path) -> Path | None:
    try:
        return Path(os.path.commonpath((str(path1), str(path2))))
    except ValueError:
        return None

def bestrelpath(directory: Path, dest: Path) -> str:
    assert isinstance(directory, Path)
    assert isinstance(dest, Path)
    if dest == directory:
        return os.curdir
    base = commonpath(directory, dest)
    if not base:
        return str(dest)
    reldirectory = directory.relative_to(base)
    reldest = dest.relative_to(base)
    return os.path.join(*[os.pardir] * len(reldirectory.parts), *reldest.parts)

def safe_exists(p: Path) -> bool:
