def inline_run(self, *args: str | os.PathLike[str], plugins=(), no_reraise_ctrlc: bool=False) -> HookRecorder:
    from _pytest.unraisableexception import gc_collect_iterations_key
    importlib.invalidate_caches()
    plugins = list(plugins)
    finalizers = []
    try:
        finalizers.append(self.__take_sys_modules_snapshot().restore)
        finalizers.append(SysPathsSnapshot().restore)
        rec = []

        class PytesterHelperPlugin:

            @staticmethod
            def pytest_configure(config: Config) -> None:
                rec.append(self.make_hook_recorder(config.pluginmanager))
                config.stash[gc_collect_iterations_key] = 0
        plugins.append(PytesterHelperPlugin())
        ret = main([str(x) for x in args], plugins=plugins)
        if len(rec) == 1:
            reprec = rec.pop()
        else:

            class reprec:
                pass
        reprec.ret = ret
        if ret == ExitCode.INTERRUPTED and (not no_reraise_ctrlc):
            calls = reprec.getcalls('pytest_keyboard_interrupt')
            if calls and calls[-1].excinfo.type == KeyboardInterrupt:
                raise KeyboardInterrupt()
        return reprec
    finally:
        for finalizer in finalizers:
            finalizer()

def runpytest_inprocess(self, *args: str | os.PathLike[str], **kwargs: Any) -> RunResult:
    syspathinsert = kwargs.pop('syspathinsert', False)
    if syspathinsert:
        self.syspathinsert()
    instant = timing.Instant()
    capture = _get_multicapture('sys')
    capture.start_capturing()
    try:
        try:
            reprec = self.inline_run(*args, **kwargs)
        except SystemExit as e:
            ret = e.args[0]
            try:
                ret = ExitCode(e.args[0])
            except ValueError:
                pass

            class reprec:
                ret = ret
        except Exception:
            traceback.print_exc()

            class reprec:
                ret = ExitCode(3)
    finally:
        out, err = capture.readouterr()
        capture.stop_capturing()
        sys.stdout.write(out)
        sys.stderr.write(err)
    assert reprec.ret is not None
    res = RunResult(reprec.ret, out.splitlines(), err.splitlines(), instant.elapsed().seconds)
    res.reprec = reprec
    return res

