def _resolve_ids(self) -> Iterable[str | _HiddenParam]:
    for idx, parameterset in enumerate(self.parametersets):
        if parameterset.id is not None:
            if parameterset.id is HIDDEN_PARAM:
                yield HIDDEN_PARAM
            else:
                yield _ascii_escaped_by_config(parameterset.id, self.config)
        elif self.ids and idx < len(self.ids) and (self.ids[idx] is not None):
            if self.ids[idx] is HIDDEN_PARAM:
                yield HIDDEN_PARAM
            else:
                yield self._idval_from_value_required(self.ids[idx], idx)
        else:
            yield '-'.join((self._idval(val, argname, idx) for val, argname in zip(parameterset.values, self.argnames, strict=True)))

def _idval(self, val: object, argname: str, idx: int) -> str:
    idval = self._idval_from_function(val, argname, idx)
    if idval is not None:
        return idval
    idval = self._idval_from_hook(val, argname)
    if idval is not None:
        return idval
    if isinstance(val, str | bytes):
        idval = self._apply_long_str_strategy(val, argname, idx)
        if idval is not None:
            return idval
    else:
        idval = self._idval_from_value(val)
        if idval is not None:
            return idval
    return self._idval_from_argname(argname, idx)

def _apply_long_str_strategy(self, val: str | bytes, argname: str, idx: int) -> str | None:
    if len(val) <= 100:
        return _ascii_escaped_by_config(val, self.config)
    match self._get_long_str_strategy():
        case 'legacy':
            return _ascii_escaped_by_config(val, self.config)
        case 'short':
            return None
        case 'sha256':
            encoded = val.encode('utf-8') if isinstance(val, str) else val
            return hashlib.sha256(encoded).hexdigest()
        case 'disallow':
            prefix = self._make_error_prefix()
            fail(f"{prefix}parametrize value for '{argname}' at index {idx} is too long for an auto-generated ID ({len(val)} characters). Use pytest.param(..., id=...) or parametrize(..., ids=...) to set an explicit ID, or change parametrize_long_str_id_strategy.", pytrace=False)

def _idval_from_function(self, val: object, argname: str, idx: int) -> str | None:
    if self.idfn is None:
        return None
    try:
        id = self.idfn(val)
    except Exception as e:
        prefix = f'{self.nodeid}: ' if self.nodeid is not None else ''
        msg = "error raised while trying to determine id of parameter '{}' at position {}"
        msg = prefix + msg.format(argname, idx)
        raise ValueError(msg) from e
    if id is None:
        return None
    return self._idval_from_value(id)

def _idval_from_hook(self, val: object, argname: str) -> str | None:
    if self.config:
        id: str | None = self.config.hook.pytest_make_parametrize_id(config=self.config, val=val, argname=argname)
        return id
    return None

def _idval_from_value(self, val: object) -> str | None:
    if isinstance(val, str | bytes):
        return _ascii_escaped_by_config(val, self.config)
    elif val is None or isinstance(val, float | int | bool | complex):
        return str(val)
    elif isinstance(val, re.Pattern):
        return ascii_escaped(val.pattern)
    elif val is NOTSET:
        pass
    elif isinstance(val, enum.Enum):
        return str(val)
    elif isinstance(getattr(val, '__name__', None), str):
        name: str = getattr(val, '__name__')
        return name
    return None

@staticmethod
def _idval_from_argname(argname: str, idx: int) -> str:
    return str(argname) + str(idx)

def parametrize(self, argnames: str | Sequence[str], argvalues: Iterable[ParameterSet | Sequence[object] | object], *, indirect: bool | Sequence[str]=False, ids: Iterable[object | None] | Callable[[Any], object | None] | None=None, scope: ScopeName | None=None, _param_mark: Mark | None=None) -> None:
    nodeid = self.definition.nodeid
    argnames, parametersets = ParameterSet._for_parametrize(argnames, argvalues, self.function, self.config, nodeid=self.definition.nodeid)
    del argvalues
    if 'request' in argnames:
        fail(f"{nodeid}: 'request' is a reserved name and cannot be used in @pytest.mark.parametrize", pytrace=False)
    if scope is not None:
        scope_ = Scope.from_user(scope, descr=f'parametrize() call in {self.function.__name__}')
    else:
        scope_ = _infer_parametrize_scope(argnames, self._arg2fixturedefs, indirect)
    self._validate_if_using_arg_names(argnames, indirect)
    if _param_mark and _param_mark._param_ids_from:
        generated_ids = _param_mark._param_ids_from._param_ids_generated
        if generated_ids is not None:
            ids = generated_ids
    ids = self._resolve_parameter_set_ids(argnames, ids, parametersets, nodeid=self.definition.nodeid)
    if _param_mark and _param_mark._param_ids_from and (generated_ids is None):
        object.__setattr__(_param_mark._param_ids_from, '_param_ids_generated', ids)
    arg_directness = _resolve_args_directness(argnames, indirect, self.definition.nodeid)
    self._params_directness.update(arg_directness)
    node = None
    if scope_ is Scope.Function:
        name2directparamfixturedef = None
    else:
        collector = self.definition.parent
        assert collector is not None
        node = get_scope_node(collector, scope_)
        if node is None:
            if scope_ is Scope.Class:
                assert isinstance(collector, Module)
                node = collector
            elif scope_ is Scope.Package:
                node = collector.session
            else:
                assert False, f'Unhandled missing scope: {scope}'
        default: dict[str, DirectParamFixtureDef[object]] = {}
        name2directparamfixturedef = node.stash.setdefault(name2directparamfixturedef_key, default)
    for argname in argnames:
        if arg_directness[argname] == 'indirect':
            continue
        if name2directparamfixturedef is not None and argname in name2directparamfixturedef:
            fixturedef = name2directparamfixturedef[argname]
        else:
            fixturedef = DirectParamFixtureDef(node=self.definition.session, argname=argname, scope=scope_)
            if name2directparamfixturedef is not None:
                name2directparamfixturedef[argname] = fixturedef
        self._arg2fixturedefs[argname] = [fixturedef]
    newcalls = []
    for callspec in self._calls or [CallSpec()]:
        for param_index, (param_id, param_set) in enumerate(zip(ids, parametersets, strict=True)):
            newcallspec = callspec.setmulti(argnames=argnames, valset=param_set.values, id=param_id, marks=param_set.marks, scope=scope_, param_index=param_index, nodeid=nodeid)
            newcalls.append(newcallspec)
    self._calls = newcalls

def _resolve_parameter_set_ids(self, argnames: Sequence[str], ids: Iterable[object | None] | Callable[[Any], object | None] | None, parametersets: Sequence[ParameterSet], nodeid: str) -> list[str | _HiddenParam]:
    if ids is None:
        idfn = None
        ids_ = None
    elif callable(ids):
        idfn = ids
        ids_ = None
    else:
        idfn = None
        ids_ = self._validate_ids(ids, parametersets)
    id_maker = IdMaker(argnames, parametersets, idfn, ids_, self.config, nodeid=nodeid)
    return id_maker.make_unique_parameterset_ids()

def _validate_if_using_arg_names(self, argnames: Sequence[str], indirect: bool | Sequence[str]) -> None:
    default_arg_names = set(get_default_arg_names(self.function))
    nodeid = self.definition.nodeid
    for arg in argnames:
        if arg not in self.fixturenames:
            if arg in default_arg_names:
                fail(f"In {nodeid}: function already takes an argument '{arg}' with a default value", pytrace=False)
            else:
                if isinstance(indirect, Sequence):
                    name = 'fixture' if arg in indirect else 'argument'
                else:
                    name = 'fixture' if indirect else 'argument'
                fail(f"In {nodeid}: function uses no {name} '{arg}'", pytrace=False)

def _infer_parametrize_scope(argnames: Sequence[str], arg2fixturedefs: Mapping[str, Sequence[fixtures.FixtureDef[object]]], indirect: bool | Sequence[str]) -> Scope:
    if isinstance(indirect, Sequence):
        all_arguments_are_fixtures = len(indirect) == len(argnames)
    else:
        all_arguments_are_fixtures = bool(indirect)
    if all_arguments_are_fixtures:
        used_scopes = (arg2fixturedefs[argname][-1]._scope for argname in argnames if argname in arg2fixturedefs)
        return min(used_scopes, default=Scope.Function)
    return Scope.Function

