def raises(expected_exception: type[E] | tuple[type[E], ...] | None=None, func: Callable[P, object] | None=None, *args: Any, **kwargs: Any) -> RaisesExc[BaseException] | ExceptionInfo[E]:
    __tracebackhide__ = True
    if func is None and (not args):
        if set(kwargs) - {'match', 'check', 'expected_exception'}:
            msg = 'Unexpected keyword arguments passed to pytest.raises: '
            msg += ', '.join(sorted(kwargs))
            msg += '\nUse context-manager form instead?'
            raise TypeError(msg)
        if expected_exception is None:
            return RaisesExc(**kwargs)
        return RaisesExc(expected_exception, **kwargs)
    if not expected_exception:
        raise ValueError(f"Expected an exception type or a tuple of exception types, but got `{expected_exception!r}`. Raising exceptions is already understood as failing the test, so you don't need any special code to say 'this should never raise an exception'.")
    if not callable(func):
        raise TypeError(f'{func!r} object (type: {type(func)}) must be callable')
    with RaisesExc(expected_exception) as excinfo:
        func(*args, **kwargs)
    try:
        return excinfo
    finally:
        del excinfo

@property
def fail_reason(self) -> str | None:
    return self._fail_reason

@abstractmethod
def matches(self: AbstractRaises[BaseExcT_1], exception: BaseException) -> TypeGuard[BaseExcT_1]:
    pass

def matches(self, exception: BaseException | None) -> TypeGuard[BaseExcT_co_default]:
    self._just_propagate = False
    if exception is None:
        self._fail_reason = 'exception is None'
        return False
    if not self._check_type(exception):
        self._just_propagate = True
        return False
    if not self._check_match(exception):
        return False
    return self._check_check(exception)

def _unroll_exceptions(self, exceptions: Sequence[BaseException]) -> Sequence[BaseException]:
    res: list[BaseException] = []
    for exc in exceptions:
        if isinstance(exc, BaseExceptionGroup):
            res.extend(self._unroll_exceptions(exc.exceptions))
        else:
            res.append(exc)
    return res

def matches(self, exception: BaseException | None) -> bool:
    self._fail_reason = None
    if exception is None:
        self._fail_reason = 'exception is None'
        return False
    if not isinstance(exception, BaseExceptionGroup):
        not_group_msg = f'`{type(exception).__name__}()` is not an exception group'
        if len(self.expected_exceptions) > 1:
            self._fail_reason = not_group_msg
            return False
        res = self._check_expected(self.expected_exceptions[0], exception)
        if res is None and self.allow_unwrapped:
            return True
        if res is None:
            self._fail_reason = f'{not_group_msg}, but would match with `allow_unwrapped=True`'
        elif self.allow_unwrapped:
            self._fail_reason = res
        else:
            self._fail_reason = not_group_msg
        return False
    actual_exceptions: Sequence[BaseException] = exception.exceptions
    if self.flatten_subgroups:
        actual_exceptions = self._unroll_exceptions(actual_exceptions)
    if not self._check_match(exception):
        self._fail_reason = cast(str, self._fail_reason)
        old_reason = self._fail_reason
        if len(actual_exceptions) == len(self.expected_exceptions) == 1 and isinstance((expected := self.expected_exceptions[0]), type) and isinstance((actual := actual_exceptions[0]), expected) and self._check_match(actual):
            assert self.match is not None, "can't be None if _check_match failed"
            assert self._fail_reason is old_reason is not None
            self._fail_reason += f'\n but matched the expected `{self._repr_expected(expected)}`.\n You might want `RaisesGroup(RaisesExc({expected.__name__}, match={_match_pattern(self.match)!r}))`'
        else:
            self._fail_reason = old_reason
        return False
    if not self._check_exceptions(exception, actual_exceptions):
        self._fail_reason = cast(str, self._fail_reason)
        assert self._fail_reason is not None
        old_reason = self._fail_reason
        if not self.flatten_subgroups and (not any((isinstance(e, RaisesGroup) for e in self.expected_exceptions))) and any((isinstance(e, BaseExceptionGroup) for e in actual_exceptions)) and self._check_exceptions(exception, self._unroll_exceptions(exception.exceptions)):
            indent = '  ' if '\n' not in self._fail_reason else ''
            self._fail_reason = old_reason + f'\n{indent}Did you mean to use `flatten_subgroups=True`?'
        else:
            self._fail_reason = old_reason
        return False
    if not self._check_check(exception):
        reason = cast(str, self._fail_reason) + f' on the {type(exception).__name__}'
        if len(actual_exceptions) == len(self.expected_exceptions) == 1 and isinstance((expected := self.expected_exceptions[0]), type) and self._check_check(actual_exceptions[0]):
            self._fail_reason = reason + f', but did return True for the expected {self._repr_expected(expected)}. You might want RaisesGroup(RaisesExc({expected.__name__}, check=<...>))'
        else:
            self._fail_reason = reason
        return False
    return True

@staticmethod
def _check_expected(expected_type: type[BaseException] | RaisesExc[BaseException] | RaisesGroup[BaseException], exception: BaseException) -> str | None:
    if isinstance(expected_type, type):
        return _check_raw_type(expected_type, exception)
    res = expected_type.matches(exception)
    if res:
        return None
    assert expected_type.fail_reason is not None
    if expected_type.fail_reason.startswith('\n'):
        return f"\n{expected_type!r}: {indent(expected_type.fail_reason, '  ')}"
    return f'{expected_type!r}: {expected_type.fail_reason}'

@staticmethod
def _repr_expected(e: type[BaseException] | AbstractRaises[BaseException]) -> str:
    if isinstance(e, type):
        return _exception_type_name(e)
    return repr(e)

def _check_exceptions(self, _exception: BaseException, actual_exceptions: Sequence[BaseException]) -> bool:
    results = ResultHolder(self.expected_exceptions, actual_exceptions)
    remaining_actual = list(range(len(actual_exceptions)))
    failed_expected: list[int] = []
    matches: dict[int, int] = {}
    for i_exp, expected in enumerate(self.expected_exceptions):
        for i_rem in remaining_actual:
            res = self._check_expected(expected, actual_exceptions[i_rem])
            results.set_result(i_exp, i_rem, res)
            if res is None:
                remaining_actual.remove(i_rem)
                matches[i_exp] = i_rem
                break
        else:
            failed_expected.append(i_exp)
    if not remaining_actual and (not failed_expected):
        return True
    if 1 == len(actual_exceptions) == len(self.expected_exceptions):
        assert not matches
        self._fail_reason = res
        return False
    for i_exp, expected in enumerate(self.expected_exceptions):
        for i_actual, actual in enumerate(actual_exceptions):
            if results.has_result(i_exp, i_actual):
                continue
            results.set_result(i_exp, i_actual, self._check_expected(expected, actual))
    successful_str = f"{len(matches)} matched exception{('s' if len(matches) > 1 else '')}. " if matches else ''
    if not failed_expected and results.no_match_for_actual(remaining_actual):
        self._fail_reason = f'{successful_str}Unexpected exception(s): {[actual_exceptions[i] for i in remaining_actual]!r}'
        return False
    if not remaining_actual and results.no_match_for_expected(failed_expected):
        no_match_for_str = ', '.join((self._repr_expected(self.expected_exceptions[i]) for i in failed_expected))
        self._fail_reason = f'{successful_str}Too few exceptions raised, found no match for: [{no_match_for_str}]'
        return False
    if 1 == len(remaining_actual) == len(failed_expected) and results.no_match_for_actual(remaining_actual) and results.no_match_for_expected(failed_expected):
        self._fail_reason = f'{successful_str}{results.get_result(failed_expected[0], remaining_actual[0])}'
        return False
    s = ''
    if matches:
        s += f'\n{successful_str}'
    indent_1 = ' ' * 2
    indent_2 = ' ' * 4
    if not remaining_actual:
        s += '\nToo few exceptions raised!'
    elif not failed_expected:
        s += '\nUnexpected exception(s)!'
    if failed_expected:
        s += '\nThe following expected exceptions did not find a match:'
        rev_matches = {v: k for k, v in matches.items()}
    for i_failed in failed_expected:
        s += f'\n{indent_1}{self._repr_expected(self.expected_exceptions[i_failed])}'
        for i_actual, actual in enumerate(actual_exceptions):
            if results.get_result(i_failed, i_actual) is None:
                s += f'\n{indent_2}It matches {backquote(repr(actual))} which was paired with ' + backquote(self._repr_expected(self.expected_exceptions[rev_matches[i_actual]]))
    if remaining_actual:
        s += '\nThe following raised exceptions did not find a match'
    for i_actual in remaining_actual:
        s += f'\n{indent_1}{actual_exceptions[i_actual]!r}:'
        for i_exp, expected in enumerate(self.expected_exceptions):
            res = results.get_result(i_exp, i_actual)
            if i_exp in failed_expected:
                assert res is not None
                if res[0] != '\n':
                    s += '\n'
                s += indent(res, indent_2)
            if res is None:
                s += f'\n{indent_2}It matches {backquote(self._repr_expected(expected))} which was paired with {backquote(repr(actual_exceptions[matches[i_exp]]))}'
    if len(self.expected_exceptions) == len(actual_exceptions) and possible_match(results):
        s += '\nThere exist a possible match when attempting an exhaustive check, but RaisesGroup uses a greedy algorithm. Please make your expected exceptions more stringent with `RaisesExc` etc so the greedy algorithm can function.'
    self._fail_reason = s
    return False

