def warns(expected_warning: type[Warning] | tuple[type[Warning], ...]=Warning, func: Callable[..., object] | None=None, *args: Any, **kwargs: Any) -> WarningsChecker | Any:
    __tracebackhide__ = True
    if func is None and (not args):
        match: str | re.Pattern[str] | None = kwargs.pop('match', None)
        if kwargs:
            argnames = ', '.join(sorted(kwargs))
            raise TypeError(f'Unexpected keyword arguments passed to pytest.warns: {argnames}\nUse context-manager form instead?')
        return WarningsChecker(expected_warning, match_expr=match, _ispytest=True)
    else:
        if not callable(func):
            raise TypeError(f'{func!r} object (type: {type(func)}) must be callable')
        with WarningsChecker(expected_warning, _ispytest=True):
            return func(*args, **kwargs)

@property
def list(self) -> list[warnings.WarningMessage]:
    return self._list

def pop(self, cls: type[Warning]=Warning) -> warnings.WarningMessage:
    best_idx: int | None = None
    for i, w in enumerate(self._list):
        if w.category == cls:
            return self._list.pop(i)
        if issubclass(w.category, cls) and (best_idx is None or not issubclass(w.category, self._list[best_idx].category)):
            best_idx = i
    if best_idx is not None:
        return self._list.pop(best_idx)
    __tracebackhide__ = True
    raise AssertionError(f'{cls!r} not found in warning list')

