@classmethod
def from_config(cls, config: Config, *, _ispytest: bool=False) -> TempPathFactory:
    check_ispytest(_ispytest)
    count = int(config.getini('tmp_path_retention_count'))
    if count < 0:
        raise ValueError(f'tmp_path_retention_count must be >= 0. Current input: {count}.')
    policy = config.getini('tmp_path_retention_policy')
    if policy not in ('all', 'failed', 'none'):
        raise ValueError(f'tmp_path_retention_policy must be either all, failed, none. Current input: {policy}.')
    return cls(given_basetemp=config.option.basetemp, trace=config.trace.get('tmpdir'), retention_count=count, retention_policy=policy, _ispytest=True)

def mktemp(self, basename: str, numbered: bool=True) -> Path:
    basename = self._ensure_relative_to_basetemp(basename)
    if not numbered:
        p = self.getbasetemp().joinpath(basename)
        p.mkdir(mode=448)
    else:
        p = make_numbered_dir(root=self.getbasetemp(), prefix=basename, mode=448)
        self._trace('mktemp', p)
    return p

def getbasetemp(self) -> Path:
    if self._basetemp is not None:
        return self._basetemp
    if self._given_basetemp is not None:
        basetemp = self._given_basetemp
        if basetemp.exists():
            rm_rf(basetemp)
        basetemp.mkdir(mode=448)
        basetemp = basetemp.resolve()
    else:
        from_env = os.environ.get('PYTEST_DEBUG_TEMPROOT')
        temproot = Path(from_env or tempfile.gettempdir()).resolve()
        user = get_user() or 'unknown'
        rootdir = temproot.joinpath(f'pytest-of-{user}')
        try:
            rootdir.mkdir(mode=448, exist_ok=True)
        except OSError:
            rootdir = temproot.joinpath('pytest-of-unknown')
            rootdir.mkdir(mode=448, exist_ok=True)
        uid = get_user_id()
        if uid is not None:
            stat_follow_symlinks = False if os.stat in os.supports_follow_symlinks else True
            rootdir_stat = rootdir.stat(follow_symlinks=stat_follow_symlinks)
            if stat.S_ISLNK(rootdir_stat.st_mode):
                raise OSError(f'The temporary directory {rootdir} is a symbolic link. Fix this and try again.')
            if rootdir_stat.st_uid != uid:
                raise OSError(f'The temporary directory {rootdir} is not owned by the current user. Fix this and try again.')
            if rootdir_stat.st_mode & 63 != 0:
                chmod_follow_symlinks = False if os.chmod in os.supports_follow_symlinks else True
                rootdir.chmod(rootdir_stat.st_mode & ~63, follow_symlinks=chmod_follow_symlinks)
        keep = self._retention_count
        if self._retention_policy == 'none':
            keep = 0
        basetemp = make_numbered_dir_with_cleanup(prefix='pytest-', root=rootdir, keep=keep, lock_timeout=LOCK_TIMEOUT, mode=448, register=self._exit_stack.callback)
        atexit.register(self._exit_stack.close)
        self._exit_stack.callback(atexit.unregister, self._exit_stack.close)
    assert basetemp is not None, basetemp
    self._basetemp = basetemp
    self._trace('new basetemp', basetemp)
    return basetemp

def get_user() -> str | None:
    try:
        import getpass
        return getpass.getuser()
    except (ImportError, OSError, KeyError):
        return None

