    result_dict = request.node.stash[tmppath_result_key]
    if policy == 'failed' and result_dict.get('call', True):
        rmtree(path, ignore_errors=True)
    del request.node.stash[tmppath_result_key]

def pytest_sessionfinish(session, exitstatus: int | ExitCode):
    tmp_path_factory: TempPathFactory = session.config._tmp_path_factory
    basetemp = tmp_path_factory._basetemp
    if basetemp is None:
        return
    policy = tmp_path_factory._retention_policy
    if exitstatus == 0 and policy == 'failed' and (tmp_path_factory._given_basetemp is None):
        if basetemp.is_dir():
            rmtree(basetemp, ignore_errors=True)
    if basetemp.is_dir():
        cleanup_dead_symlinks(basetemp)
    tmp_path_factory._exit_stack.close()

def _register_unittest_setup_class_fixture(self, cls: type) -> None:
    setup = getattr(cls, 'setUpClass', None)
    teardown = getattr(cls, 'tearDownClass', None)
    if setup is None and teardown is None:
        return None
    cleanup = getattr(cls, 'doClassCleanups', lambda: None)

    def process_teardown_exceptions() -> None:
        exc_infos = getattr(cls, 'tearDown_exceptions', None)
        if not exc_infos:
            return
        exceptions = [exc for _, exc, _ in exc_infos]
        if len(exceptions) == 1:
            raise exceptions[0]
        else:
            raise ExceptionGroup('Unittest class cleanup errors', exceptions)

    def unittest_setup_class_fixture(request: FixtureRequest) -> Generator[None]:
        cls = request.cls
        if _is_skipped(cls):
            reason = cls.__unittest_skip_why__
            raise skip.Exception(reason, _use_item_location=True)
        if setup is not None:
            try:
                setup()
            except Exception:
                cleanup()
                process_teardown_exceptions()
                raise
        yield
        try:
            if teardown is not None:
                teardown()
        finally:
            cleanup()
            process_teardown_exceptions()
    fixtures.register_fixture(name=f'_unittest_setUpClass_fixture_{cls.__qualname__}', func=unittest_setup_class_fixture, node=self, scope='class', autouse=True)

def _register_unittest_skip_fixture(self, cls: type) -> None:

    def unittest_skip_fixture(request: FixtureRequest) -> None:
        reason = getattr(cls, '__unittest_skip_why__', '')
        raise skip.Exception(reason, _use_item_location=True)
    fixtures.register_fixture(name=f'_unittest_skip_fixture_{cls.__qualname__}', func=unittest_skip_fixture, node=self, scope='class', autouse=True)

def _register_unittest_setup_method_fixture(self, cls: type) -> None:
    setup = getattr(cls, 'setup_method', None)
    teardown = getattr(cls, 'teardown_method', None)
    if setup is None and teardown is None:
        return None

    def unittest_setup_method_fixture(request: FixtureRequest) -> Generator[None]:
        self = request.instance
        if _is_skipped(self):
            reason = self.__unittest_skip_why__
            raise skip.Exception(reason, _use_item_location=True)
        if setup is not None:
            setup(self, request.function)
        yield
        if teardown is not None:
            teardown(self, request.function)
    fixtures.register_fixture(name=f'_unittest_setup_method_fixture_{cls.__qualname__}', func=unittest_setup_method_fixture, node=self, scope='function', autouse=True)

def _obtain_errors_and_skips(self) -> tuple[list[Any], list[Any]]:
    from unittest.case import _SubTest
    assert sys.version_info < (3, 11), 'This workaround only should be used in Python 3.10'
    if self._cached_errors_and_skips is not None:
        return self._cached_errors_and_skips
    subtest_errors = [(x, y) for x, y in self.instance._outcome.errors if isinstance(x, _SubTest) and y is not None]
    non_subtest_skips = [(x, y) for x, y in self.instance._outcome.skipped if not isinstance(x, _SubTest)]
    self._cached_errors_and_skips = (subtest_errors, non_subtest_skips)
    return (subtest_errors, non_subtest_skips)

def pytest_configure() -> None:
    if _get_twisted_version() is not TwistedVersion.NotInstalled:
        from twisted.trial.itrial import IReporter
        from zope.interface import classImplements
        classImplements(TestCaseFunction, IReporter)

def _handle_twisted_exc_info(rawexcinfo: _SysExcInfoType | BaseException) -> _SysExcInfoType:
    twisted_version = _get_twisted_version()
    if twisted_version is TwistedVersion.NotInstalled:
        return rawexcinfo
    elif twisted_version is TwistedVersion.Version24:
        if hasattr(rawexcinfo, TWISTED_RAW_EXCINFO_ATTR):
            saved_exc_info = getattr(rawexcinfo, TWISTED_RAW_EXCINFO_ATTR)
            delattr(rawexcinfo, TWISTED_RAW_EXCINFO_ATTR)
            return saved_exc_info
        return rawexcinfo
    elif twisted_version is TwistedVersion.Version25:
        if isinstance(rawexcinfo, BaseException):
            import twisted.python.failure
            if isinstance(rawexcinfo, twisted.python.failure.Failure):
                tb = rawexcinfo.__traceback__
                if tb is None:
                    tb = sys.exc_info()[2]
                return (type(rawexcinfo.value), rawexcinfo.value, tb)
        return rawexcinfo
    else:
        assert False, f'Unexpected Twisted version: {twisted_version}'

@contextmanager
def catch_warnings_for_item(config: Config, ihook, when: Literal['config', 'collect', 'runtest'], item: Item | None, *, record: bool=True) -> Generator[None]:
    with config._catch_configured_warnings(record=record) as log:
        nodeid = '' if item is None else item.nodeid
        if item is not None:
            for mark in item.iter_markers(name='filterwarnings'):
                for arg in mark.args:
                    warnings.filterwarnings(*parse_warning_filter(arg, escape=False))
        try:
            yield
        finally:
            if record:
                assert log is not None
                for warning_message in log:
                    ihook.pytest_warning_recorded.call_historic(kwargs=dict(warning_message=warning_message, nodeid=nodeid, when=when, location=None))

def warn_explicit_for(method: FunctionType, message: PytestWarning) -> None:
    lineno = method.__code__.co_firstlineno
    filename = inspect.getfile(method)
    module = method.__module__
    mod_globals = method.__globals__
    try:
        warnings.warn_explicit(message, type(message), filename=filename, module=module, registry=mod_globals.setdefault('__warningregistry__', {}), lineno=lineno)
    except Warning as w:
        raise type(w)(f'{w}\n at {filename}:{lineno}') from None

def _diff_text(left: str, right: str, highlighter: _HighlightFunc, verbose: int=0) -> Iterator[str]:
    from difflib import ndiff
    if verbose < 1:
        i = 0
        for i in range(min(len(left), len(right))):
            if left[i] != right[i]:
                break
        if i > 42:
            i -= 10
            yield f'Skipping {i} identical leading characters in diff, use -v to show'
            left = left[i:]
            right = right[i:]
        if len(left) == len(right):
            for i in range(1, len(left) + 1):
                if left[-i] != right[-i]:
                    break
            if i > 42:
                i -= 10
                yield f'Skipping {i} identical trailing characters in diff, use -v to show'
                left = left[:-i]
                right = right[:-i]
    keepends = True
    if left.isspace() or right.isspace():
        left = repr(str(left))
        right = repr(str(right))
        yield 'Strings contain only whitespace, escaping them using repr()'
    yield from highlighter('\n'.join((line.strip('\n') for line in ndiff(right.splitlines(keepends), left.splitlines(keepends)))), lexer='diff').splitlines()

def _early_rewrite_bailout(self, name: str, state: AssertionState) -> bool:
    if self.session is not None and (not self._session_paths_checked):
        self._session_paths_checked = True
        for initial_path in self.session._initialpaths:
            parts = str(initial_path).split(os.sep)
            self._basenames_to_check_rewrite.add(os.path.splitext(parts[-1])[0])
    parts = name.split('.')
    if parts[-1] in self._basenames_to_check_rewrite:
        return False
    path = PurePath(*parts).with_suffix('.py')
    for pat in self.fnpats:
        if os.path.dirname(pat):
            return False
        if fnmatch_ex(pat, path):
            return False
    if self._is_marked_for_rewrite(name, state):
        return False
    state.trace(f'early skip of rewriting module: {name}')
    return True

def mark_rewrite(self, *names: str) -> None:
    already_imported = set(names).intersection(sys.modules).difference(self._rewritten_names)
    for name in already_imported:
        mod = sys.modules[name]
        if not AssertionRewriter.is_rewrite_disabled(mod.__doc__ or '') and (not isinstance(mod.__loader__, type(self))):
            self._warn_already_imported(name)
    self._must_rewrite.update(names)
    self._marked_for_rewrite_cache.clear()

def get_data(self, pathname: str | bytes) -> bytes:
    with open(pathname, 'rb') as f:
        return f.read()

def _read_pyc(source: Path, pyc: Path, trace: Callable[[str], None]=lambda x: None) -> types.CodeType | None:
    try:
        fp = open(pyc, 'rb')
    except OSError:
        return None
    with fp:
        try:
            stat_result = os.stat(source)
            mtime = int(stat_result.st_mtime)
            size = stat_result.st_size
            data = fp.read(16)
        except OSError as e:
            trace(f'_read_pyc({source}): OSError {e}')
            return None
        if len(data) != 16:
            trace(f'_read_pyc({source}): invalid pyc (too short)')
            return None
        if data[:4] != importlib.util.MAGIC_NUMBER:
            trace(f'_read_pyc({source}): invalid pyc (bad magic number)')
            return None
        if data[4:8] != b'\x00\x00\x00\x00':
            trace(f'_read_pyc({source}): invalid pyc (unsupported flags)')
            return None
        mtime_data = data[8:12]
        if int.from_bytes(mtime_data, 'little') != mtime & 4294967295:
            trace(f'_read_pyc({source}): out of date')
            return None
        size_data = data[12:16]
        if int.from_bytes(size_data, 'little') != size & 4294967295:
            trace(f'_read_pyc({source}): invalid pyc (incorrect size)')
            return None
        try:
            co = marshal.load(fp)
        except Exception as e:
            trace(f'_read_pyc({source}): marshal.load error {e}')
            return None
        if not isinstance(co, types.CodeType):
            trace(f'_read_pyc({source}): not a code object')
            return None
        return co

def _saferepr(obj: object) -> str:
    if isinstance(obj, types.MethodType):
        return obj.__name__
    maxsize = _get_maxsize_for_saferepr(util._config)
    if not maxsize:
        return saferepr_unlimited(obj).replace('\n', '\\n')
    return saferepr(obj, maxsize=maxsize).replace('\n', '\\n')

def _get_maxsize_for_saferepr(config: Config | None) -> int | None:
    if config is None:
        verbosity = 0
    else:
        verbosity = config.get_verbosity(Config.VERBOSITY_ASSERTIONS)
    if verbosity >= 2:
        return None
    if verbosity >= 1:
        return DEFAULT_REPR_MAX_SIZE * 10
    return DEFAULT_REPR_MAX_SIZE

def _format_assertmsg(obj: object) -> str:
    replaces = [('\n', '\n~'), ('%', '%%')]
    if not isinstance(obj, str):
        obj = saferepr(obj, _get_maxsize_for_saferepr(util._config))
        replaces.append(('\\n', '\n~'))
    for r1, r2 in replaces:
        obj = obj.replace(r1, r2)
    return obj

def traverse_node(node: ast.AST) -> Iterator[ast.AST]:
    yield node
    for child in ast.iter_child_nodes(node):
        yield from traverse_node(child)

@functools.lru_cache(maxsize=1)
def _get_assertion_exprs(src: bytes) -> dict[int, str]:
    ret: dict[int, str] = {}
    depth = 0
    lines: list[str] = []
    assert_lineno: int | None = None
    seen_lines: set[int] = set()

    def _write_and_reset() -> None:
        nonlocal depth, lines, assert_lineno, seen_lines
        assert assert_lineno is not None
        ret[assert_lineno] = ''.join(lines).rstrip().rstrip('\\')
        depth = 0
        lines = []
        assert_lineno = None
        seen_lines = set()
    tokens = tokenize.tokenize(io.BytesIO(src).readline)
    for tp, source, (lineno, offset), _, line in tokens:
        if tp == tokenize.NAME and source == 'assert':
            assert_lineno = lineno
        elif assert_lineno is not None:
            if tp == tokenize.OP and source in '([{':
                depth += 1
            elif tp == tokenize.OP and source in ')]}':
                depth -= 1
            if not lines:
                lines.append(line[offset:])
                seen_lines.add(lineno)
            elif depth == 0 and tp == tokenize.OP and (source == ','):
                if lineno in seen_lines and len(lines) == 1:
                    offset_in_trimmed = offset + len(lines[-1]) - len(line)
                    lines[-1] = lines[-1][:offset_in_trimmed]
                elif lineno in seen_lines:
                    lines[-1] = lines[-1][:offset]
                else:
                    lines.append(line[:offset])
                _write_and_reset()
            elif tp in {tokenize.NEWLINE, tokenize.ENDMARKER}:
                _write_and_reset()
            elif lines and lineno not in seen_lines:
                lines.append(line)
                seen_lines.add(lineno)
    return ret

def run(self, mod: ast.Module) -> None:
    if not mod.body:
        return
    doc = getattr(mod, 'docstring', None)
    expect_docstring = doc is None
    if doc is not None and self.is_rewrite_disabled(doc):
        return
    pos = 0
    for item in mod.body:
        match item:
            case ast.Expr(value=ast.Constant(value=str() as doc)) if expect_docstring:
                if self.is_rewrite_disabled(doc):
                    return
                expect_docstring = False
            case ast.ImportFrom(level=0, module='__future__'):
                pass
            case _:
                break
        pos += 1
    if isinstance(item, ast.FunctionDef) and item.decorator_list:
        lineno = item.decorator_list[0].lineno
    else:
        lineno = item.lineno
    aliases = [ast.alias('builtins', '@py_builtins', lineno=lineno, col_offset=0), ast.alias('_pytest.assertion.rewrite', '@pytest_ar', lineno=lineno, col_offset=0)]
    imports = [ast.Import([alias], lineno=lineno, col_offset=0) for alias in aliases]
    mod.body[pos:pos] = imports
    self.scope = (mod,)
    nodes: list[ast.AST | Sentinel] = [mod]
    while nodes:
        node = nodes.pop()
        if isinstance(node, ast.FunctionDef | ast.AsyncFunctionDef | ast.ClassDef):
            self.scope = tuple((*self.scope, node))
            nodes.append(_SCOPE_END_MARKER)
        if node == _SCOPE_END_MARKER:
            self.scope = self.scope[:-1]
            continue
        assert isinstance(node, ast.AST)
        for name, field in ast.iter_fields(node):
            if isinstance(field, list):
                new: list[ast.AST] = []
                for i, child in enumerate(field):
                    if isinstance(child, ast.Assert):
                        new.extend(self.visit(child))
                    else:
                        new.append(child)
                        if isinstance(child, ast.AST):
                            nodes.append(child)
                setattr(node, name, new)
            elif isinstance(field, ast.AST) and (not isinstance(field, ast.expr)):
                nodes.append(field)

def assign(self, expr: ast.expr) -> ast.Name:
    name = self.variable()
    self.statements.append(ast.Assign([ast.Name(name, ast.Store())], expr))
    return ast.copy_location(ast.Name(name, ast.Load()), expr)

def helper(self, name: str, *args: ast.expr) -> ast.expr:
    py_name = ast.Name('@pytest_ar', ast.Load())
    attr = ast.Attribute(py_name, name, ast.Load())
    return ast.Call(attr, list(args), [])

def builtin(self, name: str) -> ast.Attribute:
    builtin_name = ast.Name('@py_builtins', ast.Load())
    return ast.Attribute(builtin_name, name, ast.Load())

def push_format_context(self) -> None:
    self.explanation_specifiers: dict[str, ast.expr] = {}
    self.stack.append(self.explanation_specifiers)

def pop_format_context(self, expl_expr: ast.expr) -> ast.Name:
    current = self.stack.pop()
    if self.stack:
        self.explanation_specifiers = self.stack[-1]
    keys: list[ast.expr | None] = [ast.Constant(key) for key in current.keys()]
    format_dict = ast.Dict(keys, list(current.values()))
    form = ast.BinOp(expl_expr, ast.Mod(), format_dict)
    name = '@py_format' + str(next(self.variable_counter))
    if self.enable_assertion_pass_hook:
        self.format_variables.append(name)
    self.expl_stmts.append(ast.Assign([ast.Name(name, ast.Store())], form))
    return ast.Name(name, ast.Load())

def generic_visit(self, node: ast.AST) -> tuple[ast.Name, str]:
    assert isinstance(node, ast.expr)
    res = self.assign(node)
    return (res, self.explanation_param(self.display(res)))

def try_makedirs(cache_dir: Path) -> bool:
    try:
        os.makedirs(cache_dir, exist_ok=True)
    except (FileNotFoundError, NotADirectoryError, FileExistsError):
        return False
    except PermissionError:
        return False
    except OSError as e:
        if e.errno in {errno.EROFS, errno.ENOSYS}:
            return False
        raise
    return True

def get_cache_dir(file_path: Path) -> Path:
    if sys.pycache_prefix:
        return Path(sys.pycache_prefix) / Path(*file_path.parts[1:-1])
    else:
        return file_path.parent / '__pycache__'

def truncate_if_required(explanation: list[str], item: Item) -> list[str]:
    should_truncate, budget = _get_truncation_parameters(item)
    if should_truncate:
        return _truncate_explanation(explanation, budget)
    return explanation

def _truncate_explanation(input_lines: list[str], budget: TruncationBudget) -> list[str]:
    tolerable_max_chars = budget.max_chars + 70
    if budget.max_lines == 0 or len(input_lines) <= budget.max_lines + 2:
        if budget.max_chars == 0 or sum((len(s) for s in input_lines)) <= tolerable_max_chars:
            return input_lines
        truncated_explanation = input_lines
    else:
        truncated_explanation = input_lines[:budget.max_lines]
    need_to_truncate_char = budget.max_chars > 0 and sum((len(e) for e in truncated_explanation)) > tolerable_max_chars
    if need_to_truncate_char:
        truncated_explanation = _truncate_by_char_count(truncated_explanation, budget.max_chars)
    truncated_explanation[-1] += '...'
    truncated_line_count = len(input_lines) - len(truncated_explanation) + int(need_to_truncate_char)
    return [*truncated_explanation, '', f"...Full output truncated ({truncated_line_count} line{('' if truncated_line_count == 1 else 's')} hidden), {USAGE_MSG}"]

def format_explanation(explanation: str) -> str:
    lines = _split_explanation(explanation)
    result = _format_lines(lines)
    return '\n'.join(result)

def _split_explanation(explanation: str) -> list[str]:
    raw_lines = (explanation or '').split('\n')
    lines = [raw_lines[0]]
    for values in raw_lines[1:]:
        if values and values[0] in ['{', '}', '~', '>']:
            lines.append(values)
        else:
            lines[-1] += '\\n' + values
    return lines

def assertrepr_compare(op: str, left: object, right: object, *, verbose: int, highlighter: _HighlightFunc, assertion_text_diff_style: _AssertionTextDiffStyle) -> Iterator[str]:
    use_ascii = isinstance(left, str) and isinstance(right, str) and (normalize('NFD', left) == normalize('NFD', right))
    if verbose > 1:
        left_repr = saferepr_unlimited(left, use_ascii=use_ascii)
        right_repr = saferepr_unlimited(right, use_ascii=use_ascii)
    else:
        maxsize = (80 - 15 - len(op) - 2) // 2
        left_repr = saferepr(left, maxsize=maxsize, use_ascii=use_ascii)
        right_repr = saferepr(right, maxsize=maxsize, use_ascii=use_ascii)
    summary = f'{left_repr} {op} {right_repr}'
    try:
        if op == '==':
            source = _compare_eq_any(left, right, highlighter, verbose, assertion_text_diff_style)
        elif op == 'not in' and istext(left) and istext(right):
            source = _notin_text(left, right, verbose)
        elif op in {'!=', '>=', '<=', '>', '<'} and isset(left) and isset(right):
            source = SET_COMPARISON_FUNCTIONS[op](left, right, highlighter, verbose)
        else:
            source = iter(())
        summary_yielded = False
        for line in source:
            if not summary_yielded:
                yield summary
                if line != '':
                    yield ''
                summary_yielded = True
            yield line
    except outcomes.Exit:
        raise
    except Exception:
        repr_crash = _pytest._code.ExceptionInfo.from_current()._getreprcrash()
        if not summary_yielded:
            yield summary
            yield ''
            summary_yielded = True
        yield f'(pytest_assertion plugin: representation of details failed: {repr_crash}.'
        yield ' Probably an object has a faulty __repr__.)'

def _compare_eq_any(left: object, right: object, highlighter: _HighlightFunc, verbose: int, assertion_text_diff_style: _AssertionTextDiffStyle) -> Iterator[str]:
    if istext(left) and istext(right):
        yield from _compare_eq_text(left, right, highlighter, verbose, assertion_text_diff_style)
    else:
        from _pytest.approx import Approx
        if isinstance(right, Approx):
            yield from right._repr_compare(left)
        elif isinstance(left, Approx):
            yield from left._repr_compare(right)
        elif type(left) is type(right) and (isdatacls(left) or isattrs(left) or isnamedtuple(left)):
            yield from _compare_eq_cls(left, right, highlighter, verbose, assertion_text_diff_style)
        elif issequence(left) and issequence(right):
            yield from _compare_eq_sequence(left, right, highlighter, verbose)
        elif isset(left) and isset(right):
            yield from _compare_eq_set(left, right, highlighter, verbose)
        elif ismapping(left) and ismapping(right):
            yield from _compare_eq_mapping(left, right, highlighter, verbose)
        if isiterable(left) and isiterable(right):
            yield from _compare_eq_iterable(left, right, highlighter, verbose)

def has_default_eq(obj: object) -> bool:
    if hasattr(obj.__eq__, '__code__') and hasattr(obj.__eq__.__code__, 'co_filename'):
        code_filename = obj.__eq__.__code__.co_filename
        if isattrs(obj):
            return 'attrs generated ' in code_filename
        return code_filename == '<string>'
    return True

def register_assert_rewrite(*names: str) -> None:
    for name in names:
        if not isinstance(name, str):
            msg = 'expected module names as *args, got {0} instead'
            raise TypeError(msg.format(repr(names)))
    rewrite_hook: RewriteHook
    for hook in sys.meta_path:
        if isinstance(hook, rewrite.AssertionRewritingHook):
            rewrite_hook = hook
            break
    else:
        rewrite_hook = DummyRewriteHook()
    rewrite_hook.mark_rewrite(*names)

def callbinrepr(op, left: object, right: object) -> str | None:
    hook_result = ihook.pytest_assertrepr_compare(config=item.config, op=op, left=left, right=right)
    for new_expl in hook_result:
        if new_expl:
            new_expl = truncate.truncate_if_required(new_expl, item)
            new_expl = [line.replace('\n', '\\n') for line in new_expl]
            res = '\n~'.join(new_expl)
            if item.config.getvalue('assertmode') == 'rewrite':
                res = res.replace('%', '%%')
            return res
    return None

def getgroup(self, name: str, description: str='', after: str | None=None) -> OptionGroup:
    for group in self._groups:
        if group.name == name:
            return group
    arggroup = self.optparser.add_argument_group(description or name)
    group = OptionGroup(arggroup, name, self, _ispytest=True)
    i = 0
    for i, grp in enumerate(self._groups):
        if grp.name == after:
            break
    self._groups.insert(i + 1, group)
    self.optparser._action_groups.insert(i + 1, self.optparser._action_groups.pop())
    return group

def parse(self, args: Sequence[str | os.PathLike[str]], namespace: argparse.Namespace | None=None) -> argparse.Namespace:
    from _pytest._argcomplete import try_argcomplete
    try_argcomplete(self.optparser)
    strargs = [os.fspath(x) for x in args]
    if namespace is None:
        namespace = argparse.Namespace()
    try:
        namespace._raise_print_help = True
        return self.optparser.parse_intermixed_args(strargs, namespace=namespace)
    finally:
        del namespace._raise_print_help

def parse_known_and_unknown_args(self, args: Sequence[str | os.PathLike[str]], namespace: argparse.Namespace | None=None) -> tuple[argparse.Namespace, list[str]]:
    strargs = [os.fspath(x) for x in args]
    if sys.version_info < (3, 12, 8) or (3, 13) <= sys.version_info < (3, 13, 1):
        namespace, unknown = self.optparser.parse_known_args(strargs, namespace)
        assert namespace is not None
        file_or_dir = getattr(namespace, FILE_OR_DIR)
        unknown_flags: list[str] = []
        for arg in unknown:
            (unknown_flags if arg.startswith('-') else file_or_dir).append(arg)
        return (namespace, unknown_flags)
    else:
        return self.optparser.parse_known_intermixed_args(strargs, namespace)

def addini(self, name: str, help: str, type: Literal['string', 'paths', 'pathlist', 'args', 'linelist', 'bool', 'int', 'float'] | None=None, default: Any=NOTSET, *, aliases: Sequence[str]=()) -> None:
    assert type in (None, 'string', 'paths', 'pathlist', 'args', 'linelist', 'bool', 'int', 'float')
    if type is None:
        type = 'string'
    if default is NOTSET:
        default = get_ini_default_for_type(type)
    self._inidict[name] = (help, type, default)
    for alias in aliases:
        if alias in self._inidict:
            raise ValueError(f'alias {alias!r} conflicts with existing configuration option')
        if (already := self._ini_aliases.get(alias)) is not None:
            raise ValueError(f'{alias!r} is already an alias of {already!r}')
        self._ini_aliases[alias] = name

def get_ini_default_for_type(type: Literal['string', 'paths', 'pathlist', 'args', 'linelist', 'bool', 'int', 'float']) -> Any:
    if type in ('paths', 'pathlist', 'args', 'linelist'):
        return []
    elif type == 'bool':
        return False
    elif type == 'int':
        return 0
    elif type == 'float':
        return 0.0
    else:
        return ''

def addoption(self, *opts: str, **attrs: Any) -> None:
    conflict = set(opts).intersection((name for opt in self.options for name in opt.names()))
    if conflict:
        raise ValueError(f'option names {conflict} already added')
    if self.parser and 'dest' not in attrs:
        dest = _get_argparse_dest(opts)
        for group in self.parser._groups:
            for option in group.options:
                if option.dest == dest:
                    raise ValueError(f'option dest {dest!r} already used by {option.names()!r} (this is the option that maps to dest {dest!r}); pass dest={dest!r} explicitly to share the destination')
    self._addoption_inner(opts, attrs, allow_reserved=False)

def error(self, message: str) -> NoReturn:
    msg = f'{self.prog}: error: {message}'
    if self.extra_info:
        msg += '\n' + '\n'.join((f'  {k}: {v}' for k, v in sorted(self.extra_info.items())))
    raise UsageError(self.format_usage() + msg)

def _split_lines(self, text: str, width: int) -> list[str]:
    lines = []
    for line in text.splitlines():
        lines.extend(textwrap.wrap(line.strip(), width))
    return lines

def _parse_ini_config(path: Path) -> iniconfig.IniConfig:
    try:
        return iniconfig.IniConfig(str(path))
    except iniconfig.ParseError as exc:
        raise UsageError(str(exc)) from exc

def load_config_dict_from_file(filepath: Path) -> ConfigDict | None:
    if filepath.suffix == '.ini':
        iniconfig = _parse_ini_config(filepath)
        if 'pytest' in iniconfig:
            return {k: ConfigValue(v, origin='file', mode='ini') for k, v in iniconfig['pytest'].items()}
        elif filepath.name in {'pytest.ini', '.pytest.ini'}:
            return {}
    elif filepath.suffix == '.cfg':
        iniconfig = _parse_ini_config(filepath)
        if 'tool:pytest' in iniconfig.sections:
            return {k: ConfigValue(v, origin='file', mode='ini') for k, v in iniconfig['tool:pytest'].items()}
        elif 'pytest' in iniconfig.sections:
            fail(CFG_PYTEST_SECTION.format(filename='setup.cfg'), pytrace=False)
    elif filepath.suffix == '.toml':
        if sys.version_info >= (3, 11):
            import tomllib
        else:
            import tomli as tomllib
        toml_text = filepath.read_text(encoding='utf-8')
        try:
            config = tomllib.loads(toml_text)
        except tomllib.TOMLDecodeError as exc:
            raise UsageError(f'{filepath}: {exc}') from exc
        if filepath.name in ('pytest.toml', '.pytest.toml'):
            if 'pytest' in config:
                return {k: ConfigValue(v, origin='file', mode='toml') for k, v in config['pytest'].items()}
            top_level_options = [key for key, value in config.items() if not isinstance(value, dict)]
            if top_level_options:
                raise UsageError(f"{filepath}: pytest configuration must be under a [pytest] table (found top-level options: {', '.join(top_level_options)})")
            return {}
        else:
            tool_pytest = config.get('tool', {}).get('pytest', {})
            toml_config = {k: v for k, v in tool_pytest.items() if k != 'ini_options'}
            ini_config = tool_pytest.get('ini_options', None)
            if toml_config and ini_config:
                raise UsageError(f'{filepath}: Cannot use both [tool.pytest] (native TOML types) and [tool.pytest.ini_options] (string-based INI format) simultaneously. Please use [tool.pytest] with native TOML types (recommended) or [tool.pytest.ini_options] for backwards compatibility.')
            if toml_config:
                return {k: ConfigValue(v, origin='file', mode='toml') for k, v in toml_config.items()}
            elif ini_config is not None:

                def make_scalar(v: object) -> str | list[str]:
                    return v if isinstance(v, list) else str(v)
                return {k: ConfigValue(make_scalar(v), origin='file', mode='ini') for k, v in ini_config.items()}
    return None

def locate_config(invocation_dir: Path, args: Iterable[Path]) -> tuple[Path | None, Path | None, ConfigDict, Sequence[str]]:
    config_names = ['pytest.toml', '.pytest.toml', 'pytest.ini', '.pytest.ini', 'pyproject.toml', 'tox.ini', 'setup.cfg']
    args = [x for x in args if not str(x).startswith('-')]
    if not args:
        args = [invocation_dir]
    found_pyproject_toml: Path | None = None
    ignored_config_files: list[str] = []
    for arg in args:
        argpath = absolutepath(arg)
        for base in (argpath, *argpath.parents):
            for config_name in config_names:
                p = base / config_name
                if p.is_file():
                    if p.name == 'pyproject.toml' and found_pyproject_toml is None:
                        found_pyproject_toml = p
                    ini_config = load_config_dict_from_file(p)
                    if ini_config is not None:
                        index = config_names.index(config_name)
                        for remainder in config_names[index + 1:]:
                            p2 = base / remainder
                            if p2.is_file() and load_config_dict_from_file(p2) is not None:
                                ignored_config_files.append(remainder)
                        return (base, p, ini_config, ignored_config_files)
    if found_pyproject_toml is not None:
        return (found_pyproject_toml.parent, found_pyproject_toml, {}, [])
    return (None, None, {}, [])

def parse_override_ini(override_ini: Sequence[str] | None) -> ConfigDict:
    overrides = {}
    for ini_config in override_ini or ():
        try:
            key, user_ini_value = ini_config.split('=', 1)
        except ValueError as e:
            raise UsageError(f'-o/--override-ini expects option=value style (got: {ini_config!r}).') from e
        else:
            overrides[key] = ConfigValue(user_ini_value, origin='override', mode='ini')
    return overrides

def determine_setup(*, inifile: str | None, override_ini: Sequence[str] | None, args: Sequence[str], rootdir_cmd_arg: str | None, invocation_dir: Path) -> tuple[Path, Path | None, ConfigDict, Sequence[str]]:
    rootdir = None
    dirs = get_dirs_from_args(args)
    ignored_config_files: Sequence[str] = []
    if inifile:
        inipath_ = absolutepath(inifile)
        inipath: Path | None = inipath_
        inicfg = load_config_dict_from_file(inipath_) or {}
        if rootdir_cmd_arg is None:
            rootdir = inipath_.parent
    else:
        ancestor = get_common_ancestor(invocation_dir, dirs)
        rootdir, inipath, inicfg, ignored_config_files = locate_config(invocation_dir, [ancestor])
        if rootdir is None and rootdir_cmd_arg is None:
            for possible_rootdir in (ancestor, *ancestor.parents):
                if (possible_rootdir / 'setup.py').is_file():
                    rootdir = possible_rootdir
                    break
            else:
                if dirs != [ancestor]:
                    rootdir, inipath, inicfg, _ = locate_config(invocation_dir, dirs)
                if rootdir is None:
                    rootdir = get_common_ancestor(invocation_dir, [invocation_dir, ancestor])
                    if is_fs_root(rootdir):
                        rootdir = ancestor
    if rootdir_cmd_arg:
        rootdir = absolutepath(os.path.expandvars(rootdir_cmd_arg))
        if not rootdir.is_dir():
            raise UsageError(f"Directory '{rootdir}' not found. Check your '--rootdir' option.")
    ini_overrides = parse_override_ini(override_ini)
    inicfg.update(ini_overrides)
    assert rootdir is not None
    return (rootdir, inipath, inicfg, ignored_config_files)

def _get_prog_name(argv: Sequence[str]) -> str:
    argv0 = argv[0] if argv else ''
    if os.path.basename(argv0) == '__main__.py':
        return 'python -m pytest'
    return 'pytest'

def _console_main() -> int:
    try:
        code = _main(prog=_get_prog_name(sys.argv))
        sys.stdout.flush()
        return code
    except BrokenPipeError:
        devnull = os.open(os.devnull, os.O_WRONLY)
        os.dup2(devnull, sys.stdout.fileno())
        return 1

def console_main() -> int:
    import warnings
    from _pytest.deprecated import CONSOLE_MAIN
    warnings.warn(CONSOLE_MAIN, stacklevel=2)
    return _console_main()

def filename_arg(path: str, optname: str) -> str:
    if os.path.isdir(path):
        raise UsageError(f'{optname} must be a filename, given: {path}')
    return path

def directory_arg(path: str, optname: str) -> str:
    if not os.path.isdir(path):
        raise UsageError(f'{optname} must be a directory, given: {path}')
    return path

def _get_directory(path: pathlib.Path) -> pathlib.Path:
    if path.is_file():
        return path.parent
    else:
        return path

def parse_hookimpl_opts(self, plugin: _PluggyPlugin, name: str) -> HookimplOpts | None:
    if not name.startswith('pytest_'):
        return None
    if name == 'pytest_plugins':
        return None
    opts = super().parse_hookimpl_opts(plugin, name)
    if opts is not None:
        return opts
    method = getattr(plugin, name)
    if not inspect.isroutine(method):
        return None
    legacy = _get_legacy_hook_marks(method, 'impl', ('tryfirst', 'trylast', 'optionalhook', 'hookwrapper'))
    return cast(HookimplOpts, legacy)

def parse_hookspec_opts(self, module_or_class, name: str) -> HookspecOpts | None:
    opts = super().parse_hookspec_opts(module_or_class, name)
    if opts is None:
        method = getattr(module_or_class, name)
        if name.startswith('pytest_'):
            legacy = _get_legacy_hook_marks(method, 'spec', ('firstresult', 'historic'))
            opts = cast(HookspecOpts, legacy)
    return opts

def _set_initial_conftests(self, args: Sequence[str | pathlib.Path], pyargs: bool, noconftest: bool, rootpath: pathlib.Path, confcutdir: pathlib.Path | None, invocation_dir: pathlib.Path, importmode: ImportMode | str, *, consider_namespace_packages: bool) -> None:
    self._confcutdir = absolutepath(invocation_dir / confcutdir) if confcutdir else None
    self._noconftest = noconftest
    self._using_pyargs = pyargs
    anchors = []
    for initial_path in args:
        path = str(initial_path)
        i = path.find('::')
        if i != -1:
            path = path[:i]
        anchor = absolutepath(invocation_dir / path)
        if not safe_exists(anchor):
            continue
        anchors.append(anchor)
        if anchor.is_dir():
            anchors.extend((x for x in anchor.glob('test*') if x.is_dir()))
    if not anchors:
        anchors.append(invocation_dir)
        anchors.extend((x for x in invocation_dir.glob('test*') if x.is_dir()))
    for anchor in anchors:
        self._loadconftestmodules(anchor, importmode, rootpath, consider_namespace_packages=consider_namespace_packages)

def _is_in_confcutdir(self, path: pathlib.Path) -> bool:
    if self._confcutdir is None:
        return True
    return path not in self._confcutdir.parents

def consider_preparse(self, args: Sequence[str], *, exclude_only: bool=False) -> None:
    i = 0
    n = len(args)
    while i < n:
        opt = args[i]
        i += 1
        if isinstance(opt, str):
            if opt == '-p':
                try:
                    parg = args[i]
                except IndexError:
                    return
                i += 1
            elif opt.startswith('-p'):
                parg = opt[2:]
            else:
                continue
            parg = parg.strip()
            if exclude_only and (not parg.startswith('no:')):
                continue
            self.consider_pluginarg(parg)

def consider_pluginarg(self, arg: str) -> None:
    if arg.startswith('no:'):
        name = arg[3:]
        if name in essential_plugins:
            raise UsageError(f'plugin {name} cannot be disabled')
        if name.endswith('conftest.py'):
            raise UsageError(f'Blocking conftest files using -p is not supported: -p no:{name}\nconftest.py files are not plugins and cannot be disabled via -p.\n')
        if name == 'cacheprovider':
            self.set_blocked('stepwise')
            self.set_blocked('pytest_stepwise')
        self.set_blocked(name)
        if not name.startswith('pytest_'):
            self.set_blocked('pytest_' + name)
    else:
        name = arg
        self.unblock(name)
        if not name.startswith('pytest_'):
            self.unblock('pytest_' + name)
        self.import_plugin(arg, consider_entry_points=True)

def import_plugin(self, modname: str, consider_entry_points: bool=False) -> None:
    assert isinstance(modname, str), f'module name as text required, got {modname!r}'
    if self.is_blocked(modname) or self.get_plugin(modname) is not None:
        return
    importspec = '_pytest.' + modname if modname in builtin_plugins else modname
    self.rewrite_hook.mark_rewrite(importspec)
    if consider_entry_points:
        loaded = self.load_setuptools_entrypoints('pytest11', name=modname)
        if loaded:
            return
    try:
        if sys.version_info >= (3, 11):
            mod = importlib.import_module(importspec)
        else:
            __import__(importspec)
            mod = sys.modules[importspec]
    except ImportError as e:
        raise ImportError(f'Error importing plugin "{modname}": {e.args[0]}').with_traceback(e.__traceback__) from e
    except Skipped as e:
        self.skipped_plugins.append((modname, e.msg or ''))
    else:
        self.register(mod, modname)

def _get_plugin_specs_as_list(specs: None | types.ModuleType | str | Sequence[str]) -> list[str]:
    if specs is None:
        return []
    if isinstance(specs, types.ModuleType):
        return []
    if isinstance(specs, str):
        return specs.split(',') if specs else []
    if isinstance(specs, collections.abc.Sequence):
        return list(specs)
    raise UsageError(f"Plugins may be specified as a sequence or a ','-separated string of plugin names. Got: {specs!r}")

def _iter_rewritable_modules(package_files: Iterable[str]) -> Iterator[str]:
    package_files = list(package_files)
    seen_some = False
    for fn in package_files:
        is_simple_module = '/' not in fn and fn.endswith('.py')
        is_package = fn.count('/') == 1 and fn.endswith('__init__.py')
        if is_simple_module:
            module_name, _ = os.path.splitext(fn)
            if module_name != 'setup' and (not module_name.startswith('__editable__')):
                seen_some = True
                yield module_name
        elif is_package:
            package_name = os.path.dirname(fn)
            seen_some = True
            yield package_name
    if not seen_some:
        new_package_files = []
        for fn in package_files:
            parts = fn.split('/')
            new_fn = '/'.join(parts[1:])
            if new_fn:
                new_package_files.append(new_fn)
        if new_package_files:
            yield from _iter_rewritable_modules(new_package_files)

@property
def rootpath(self) -> pathlib.Path:
    return self._rootpath

@property
def inipath(self) -> pathlib.Path | None:
    return self._inipath

@contextlib.contextmanager
def _catch_configured_warnings(self, *, record: bool) -> Generator[list[warnings.WarningMessage] | None]:
    config_filters = self.getini('filterwarnings')
    cmdline_filters = self.known_args_namespace.pythonwarnings or []
    with warnings.catch_warnings(record=record) as log:
        if not sys.warnoptions:
            warnings.filterwarnings('always', category=DeprecationWarning)
            warnings.filterwarnings('always', category=PendingDeprecationWarning)
        apply_warning_filters(config_filters, cmdline_filters)
        yield log

@classmethod
def fromdictargs(cls, option_dict: Mapping[str, Any], args: list[str]) -> Config:
    config = get_config(args)
    config.option.__dict__.update(option_dict)
    config.parse(args, addopts=False)
    for x in config.option.plugins:
        config.pluginmanager.consider_pluginarg(x)
    return config

def _consider_importhook(self) -> None:
    mode = getattr(self.known_args_namespace, 'assertmode', 'plain')
    disable_autoload = getattr(self.known_args_namespace, 'disable_plugin_autoload', False) or bool(os.environ.get('PYTEST_DISABLE_PLUGIN_AUTOLOAD'))
    if mode == 'rewrite':
        import _pytest.assertion
        try:
            hook = _pytest.assertion.install_importhook(self)
        except SystemError:
            mode = 'plain'
        else:
            self._mark_plugins_for_rewrite(hook, disable_autoload)
    self._warn_about_missing_assertion(mode)

def _mark_plugins_for_rewrite(self, hook: AssertionRewritingHook, disable_autoload: bool) -> None:
    self.pluginmanager.rewrite_hook = hook
    if disable_autoload:
        return
    package_files = (str(file) for dist in importlib.metadata.distributions() if any((ep.group == 'pytest11' for ep in dist.entry_points)) for file in dist.files or [])
    for name in _iter_rewritable_modules(package_files):
        hook.mark_rewrite(name)

def _decide_args(self, *, args: list[str], pyargs: bool, testpaths: list[str], invocation_dir: pathlib.Path, rootpath: pathlib.Path, warn: bool) -> tuple[list[str], ArgsSource]:
    if args:
        source = Config.ArgsSource.ARGS
        result = args
    else:
        if invocation_dir == rootpath:
            source = Config.ArgsSource.TESTPATHS
            if pyargs:
                result = testpaths
            else:
                result = []
                for path in testpaths:
                    result.extend(sorted(glob.iglob(path, recursive=True)))
                if testpaths and (not result):
                    if warn:
                        warning_text = 'No files were found in testpaths; consider removing or adjusting your testpaths configuration. Searching recursively from the current directory instead.'
                        self.issue_config_time_warning(PytestConfigWarning(warning_text), stacklevel=3)
        else:
            result = []
        if not result:
            source = Config.ArgsSource.INVOCATION_DIR
            result = [str(invocation_dir)]
    return (result, source)

def getini(self, name: str) -> Any:
    canonical_name = self._parser._ini_aliases.get(name, name)
    try:
        return self._inicache[canonical_name]
    except KeyError:
        pass
    self._inicache[canonical_name] = val = self._getini(canonical_name)
    return val

def _getini_ini(self, name: str, canonical_name: str, type: str, value: str | list[str], default: Any):
    if type == 'paths':
        dp = self.inipath.parent if self.inipath is not None else self.invocation_params.dir
        input_values = shlex.split(value) if isinstance(value, str) else value
        return [dp / x for x in input_values]
    elif type == 'args':
        return shlex.split(value) if isinstance(value, str) else value
    elif type == 'linelist':
        if isinstance(value, str):
            return [t for t in map(lambda x: x.strip(), value.split('\n')) if t]
        else:
            return value
    elif type == 'bool':
        return _strtobool(str(value).strip())
    elif type == 'string':
        return value
    elif type == 'int':
        if not isinstance(value, str):
            raise TypeError(f'Expected an int string for option {name} of type integer, but got: {value!r}') from None
        return int(value)
    elif type == 'float':
        if not isinstance(value, str):
            raise TypeError(f'Expected a float string for option {name} of type float, but got: {value!r}') from None
        return float(value)
    else:
        return self._getini_unknown_type(name, type, value)

def _getini_toml(self, name: str, canonical_name: str, type: str, value: object, default: Any):
    value_type = builtins.type(value).__name__
    if type == 'paths':
        if not isinstance(value, list):
            raise TypeError(f"{self.inipath}: config option '{name}' expects a list for type 'paths', got {value_type}: {value!r}")
        for i, item in enumerate(value):
            if not isinstance(item, str):
                item_type = builtins.type(item).__name__
                raise TypeError(f"{self.inipath}: config option '{name}' expects a list of strings, but item at index {i} is {item_type}: {item!r}")
        dp = self.inipath.parent if self.inipath is not None else self.invocation_params.dir
        return [dp / x for x in value]
    elif type in {'args', 'linelist'}:
        if not isinstance(value, list):
            raise TypeError(f"{self.inipath}: config option '{name}' expects a list for type '{type}', got {value_type}: {value!r}")
        for i, item in enumerate(value):
            if not isinstance(item, str):
                item_type = builtins.type(item).__name__
                raise TypeError(f"{self.inipath}: config option '{name}' expects a list of strings, but item at index {i} is {item_type}: {item!r}")
        return list(value)
    elif type == 'bool':
        if not isinstance(value, bool):
            raise TypeError(f"{self.inipath}: config option '{name}' expects a bool, got {value_type}: {value!r}")
        return value
    elif type == 'int':
        if not isinstance(value, int) or isinstance(value, bool):
            raise TypeError(f"{self.inipath}: config option '{name}' expects an int, got {value_type}: {value!r}")
        return value
    elif type == 'float':
        if not isinstance(value, (float, int)) or isinstance(value, bool):
            raise TypeError(f"{self.inipath}: config option '{name}' expects a float, got {value_type}: {value!r}")
        return value
    elif type == 'string':
        if not isinstance(value, str):
            raise TypeError(f"{self.inipath}: config option '{name}' expects a string, got {value_type}: {value!r}")
        return value
    else:
        return self._getini_unknown_type(name, type, value)

def getoption(self, name: str, default: Any=NOTSET, skip: bool=False):
    name = self._parser._opt2dest.get(name, name)
    try:
        val = getattr(self.option, name)
        if val is None and skip:
            raise AttributeError(name)
        return val
    except AttributeError as e:
        if default is not NOTSET:
            return default
        if skip:
            import pytest
            pytest.skip(f'no {name!r} option found')
        raise ValueError(f'no option named {name!r}') from e

def get_verbosity(self, verbosity_type: str | None=None) -> int:
    global_level = self.getoption('verbose', default=0)
    assert isinstance(global_level, int)
    if verbosity_type is None:
        return global_level
    ini_name = Config._verbosity_ini_name(verbosity_type)
    if ini_name not in self._parser._inidict:
        return global_level
    level = self.getini(ini_name)
    if level == Config._VERBOSITY_INI_DEFAULT:
        return global_level
    return int(level)

@staticmethod
def _add_verbosity_ini(parser: Parser, verbosity_type: str, help: str) -> None:
    parser.addini(Config._verbosity_ini_name(verbosity_type), help=help, type='string', default=Config._VERBOSITY_INI_DEFAULT)

def create_terminal_writer(config: Config, file: TextIO | None=None) -> TerminalWriter:
    tw = TerminalWriter(file=file)
    if config.option.color == 'yes':
        tw.hasmarkup = True
    elif config.option.color == 'no':
        tw.hasmarkup = False
    if config.option.code_highlight == 'yes':
        tw.code_highlight = True
    elif config.option.code_highlight == 'no':
        tw.code_highlight = False
    return tw

def _strtobool(val: str) -> bool:
    val = val.lower()
    if val in ('y', 'yes', 't', 'true', 'on', '1'):
        return True
    elif val in ('n', 'no', 'f', 'false', 'off', '0'):
        return False
    else:
        raise ValueError(f'invalid truth value {val!r}')

@lru_cache(maxsize=50)
def parse_warning_filter(arg: str, *, escape: bool) -> tuple[warnings._ActionKind, str, type[Warning], str, int]:
    __tracebackhide__ = True
    error_template = dedent(f'        while parsing the following warning configuration:\n\n          {arg}\n\n        This error occurred:\n\n        {{error}}\n        ')
    parts = arg.split(':')
    if len(parts) > 5:
        doc_url = 'https://docs.python.org/3/library/warnings.html#describing-warning-filters'
        error = dedent(f'            Too many fields ({len(parts)}), expected at most 5 separated by colons:\n\n              action:message:category:module:line\n\n            For more information please consult: {doc_url}\n            ')
        raise UsageError(error_template.format(error=error))
    while len(parts) < 5:
        parts.append('')
    action_, message, category_, module, lineno_ = (s.strip() for s in parts)
    try:
        action: warnings._ActionKind = warnings._getaction(action_)
    except warnings._OptionError as e:
        raise UsageError(error_template.format(error=str(e))) from None
    try:
        category: type[Warning] = _resolve_warning_category(category_)
    except ImportError:
        raise
    except Exception:
        exc_info = ExceptionInfo.from_current()
        exception_text = exc_info.getrepr(style='native')
        raise UsageError(error_template.format(error=exception_text)) from None
    if message and escape:
        message = re.escape(message)
    if module and escape:
        module = re.escape(module) + '\\Z'
    if lineno_:
        try:
            lineno = int(lineno_)
            if lineno < 0:
                raise ValueError('number is negative')
        except ValueError as e:
            raise UsageError(error_template.format(error=f'invalid lineno {lineno_!r}: {e}')) from None
    else:
        lineno = 0
    try:
        re.compile(message)
        re.compile(module)
    except re.error as e:
        raise UsageError(error_template.format(error=f'Invalid regex {e.pattern!r}: {e}')) from None
    return (action, message, category, module, lineno)

def _resolve_warning_category(category: str) -> type[Warning]:
    __tracebackhide__ = True
    if not category:
        return Warning
    if '.' not in category:
        import builtins as m
        klass = category
    else:
        module, _, klass = category.rpartition('.')
        m = importlib.import_module(module)
    cat = getattr(m, klass)
    if not issubclass(cat, Warning):
        raise UsageError(f'{cat} is not a Warning subclass')
    return cast(type[Warning], cat)

def apply_warning_filters(config_filters: Iterable[str], cmdline_filters: Iterable[str]) -> None:
    for arg in config_filters:
        try:
            warnings.filterwarnings(*parse_warning_filter(arg, escape=False))
        except ImportError as e:
            warnings.warn(f"Failed to import filter module '{e.name}': {arg}", PytestConfigWarning)
            continue
    for arg in cmdline_filters:
        try:
            warnings.filterwarnings(*parse_warning_filter(arg, escape=True))
        except ImportError as e:
            warnings.warn(f"Failed to import filter module '{e.name}': {arg}", PytestConfigWarning)
            continue

@classmethod
def compile(cls, input: str) -> Expression:
    astexpr = expression(Scanner(input))
    code = compile(astexpr, filename='<pytest match expression>', mode='eval')
    return Expression(input, code)

@classmethod
def extract_from(cls, parameterset: ParameterSet | Sequence[object] | object, force_tuple: bool=False) -> ParameterSet:
    if isinstance(parameterset, cls):
        return parameterset
    if force_tuple:
        return cls.param(parameterset)
    else:
        return cls(parameterset, marks=[], id=None)

def combined_with(self, other: Mark) -> Mark:
    assert self.name == other.name
    param_ids_from: Mark | None = None
    if self.name == 'parametrize':
        if other._has_param_ids():
            param_ids_from = other
        elif self._has_param_ids():
            param_ids_from = self
    return Mark(self.name, self.args + other.args, dict(self.kwargs, **other.kwargs), param_ids_from=param_ids_from, _ispytest=True)

def __init__(self, mark: Mark, *, _ispytest: bool=False) -> None:
    check_ispytest(_ispytest)
    self.mark = mark

@property
def name(self) -> str:
    return self.mark.name

@property
def args(self) -> tuple[Any, ...]:
    return self.mark.args

@property
def kwargs(self) -> Mapping[str, Any]:
    return self.mark.kwargs

@property
def markname(self) -> str:
    return self.name

def with_args(self, *args: object, **kwargs: object) -> MarkDecorator:
    mark = Mark(self.name, args, kwargs, _ispytest=True)
    return MarkDecorator(self.mark.combined_with(mark), _ispytest=True)

def __call__(self, *args: object, **kwargs: object):
    if args and (not kwargs):
        func = args[0]
        is_class = inspect.isclass(func)
        unwrapped_func = func
        if isinstance(func, staticmethod | classmethod):
            unwrapped_func = func.__func__
        if len(args) == 1 and (istestfunc(unwrapped_func) or is_class):
            store_mark(unwrapped_func, self.mark)
            return func
    return self.with_args(*args, **kwargs)

def get_unpacked_marks(obj: object | type, *, consider_mro: bool=True) -> list[Mark]:
    if isinstance(obj, type):
        if not consider_mro:
            mark_lists = [obj.__dict__.get('pytestmark', [])]
        else:
            mark_lists = [x.__dict__.get('pytestmark', []) for x in reversed(obj.__mro__)]
        mark_list = []
        for item in mark_lists:
            if isinstance(item, list):
                mark_list.extend(item)
            else:
                mark_list.append(item)
    else:
        mark_attribute = getattr(obj, 'pytestmark', [])
        if mark_attribute is None:
            warnings.warn("Module defines a `__getattr__` which returns None for 'pytestmark' instead of raising AttributeError. Make sure `__getattr__` raises AttributeError for attributes it does not provide. See https://github.com/pytest-dev/pytest/issues/8265", PytestCollectionWarning, stacklevel=2)
            mark_list = []
        elif isinstance(mark_attribute, list):
            mark_list = mark_attribute
        else:
            mark_list = [mark_attribute]
    return list(normalize_mark_list(mark_list))

def normalize_mark_list(mark_list: Iterable[Mark | MarkDecorator]) -> Iterable[Mark]:
    for mark in mark_list:
        mark_obj = getattr(mark, 'mark', mark)
        if not isinstance(mark_obj, Mark):
            raise TypeError(f'got {mark_obj!r} instead of Mark')
        yield mark_obj

def store_mark(obj, mark: Mark) -> None:
    assert isinstance(mark, Mark), mark
    from ..fixtures import getfixturemarker
    if getfixturemarker(obj) is not None:
        fail('Marks cannot be applied to fixtures.\nSee docs: https://docs.pytest.org/en/stable/deprecations.html#applying-a-mark-to-a-fixture-function')
    obj.pytestmark = [*get_unpacked_marks(obj, consider_mro=False), mark]

def __getattr__(self, name: str) -> MarkDecorator:
    if name[0] == '_':
        raise AttributeError('Marker name must NOT start with underscore')
    if self._config is not None:
        if name not in self._markers:
            for line in self._config.getini('markers'):
                marker = line.split(':')[0].split('(')[0].strip()
                self._markers.add(marker)
        if name not in self._markers:
            if name in ['parameterize', 'parametrise', 'parameterise']:
                __tracebackhide__ = True
                fail(f"Unknown '{name}' mark, did you mean 'parametrize'?")
            strict_markers = self._config.getini('strict_markers')
            if strict_markers is None:
                strict_markers = self._config.getini('strict')
            if strict_markers:
                fail(f'{name!r} not found in `markers` configuration option', pytrace=False)
            warnings.warn(f'Unknown pytest.mark.{name} - is this a typo?  You can register custom marks to avoid this warning - for details, see https://docs.pytest.org/en/stable/how-to/mark.html', PytestUnknownMarkWarning, 2)
    return MarkDecorator(Mark(name, (), {}, _ispytest=True), _ispytest=True)

@property
def path(self) -> Path | str:
    filename = inspect.getfile(self.raw)
    if not filename:
        return ''
    try:
        p = absolutepath(filename)
        if not p.exists():
            raise OSError('path check failed.')
        return p
    except OSError:
        return filename

@property
def fullsource(self) -> Source | None:
    full, _ = findsource(self.raw)
    return full

def getargs(self, var: bool=False) -> tuple[str, ...]:
    args, varargs, varkw = inspect.getargs(self.raw)
    if not var:
        return tuple(args[:self.raw.co_argcount])
    result = list(args)
    if varargs is not None:
        result.append(varargs)
    if varkw is not None:
        result.append(varkw)
    return tuple(result)

@property
def statement(self) -> Source:
    if self.code.fullsource is None:
        return Source('')
    return self.code.fullsource.getstatement(self.lineno)

def eval(self, code, **vars):
    f_locals = self.f_locals.copy()
    f_locals.update(vars)
    return eval(code, self.f_globals, f_locals)

def getargs(self, var: bool=False):
    retval = []
    for arg in self.code.getargs(var):
        try:
            retval.append((arg, self.f_locals[arg]))
        except KeyError:
            pass
    return retval

@property
def statement(self) -> Source:
    source = self.frame.code.fullsource
    assert source is not None
    return source.getstatement(self.lineno)

@property
def path(self) -> Path | str:
    return self.frame.code.path

@property
def locals(self) -> dict[str, Any]:
    return self.frame.f_locals

def getsource(self, astcache: dict[str | Path, ast.AST] | None=None) -> Source | None:
    source = self.frame.code.fullsource
    if source is None:
        return None
    key = astnode = None
    if astcache is not None:
        key = self.frame.code.path
        if key is not None:
            astnode = astcache.get(key, None)
    start = self.getfirstlinesource()
    try:
        astnode, _, end = getstatementrange_ast(self.lineno, source, astnode=astnode)
    except SyntaxError:
        end = self.lineno + 1
    else:
        if key is not None and astcache is not None:
            astcache[key] = astnode
    return source[start:end]

def ishidden(self, excinfo: ExceptionInfo[BaseException] | None) -> bool:
    tbh: bool | Callable[[ExceptionInfo[BaseException] | None], bool] = False
    for maybe_ns_dct in (self.frame.f_locals, self.frame.f_globals):
        try:
            tbh = maybe_ns_dct['__tracebackhide__']
        except Exception:
            pass
        else:
            break
    if tbh and callable(tbh):
        return tbh(excinfo)
    return tbh

@property
def name(self) -> str:
    return self.frame.code.raw.co_name

def __init__(self, tb: TracebackType | Iterable[TracebackEntry]) -> None:
    if isinstance(tb, TracebackType):

        def f(cur: TracebackType) -> Iterable[TracebackEntry]:
            cur_: TracebackType | None = cur
            while cur_ is not None:
                yield TracebackEntry(cur_)
                cur_ = cur_.tb_next
        super().__init__(f(tb))
    else:
        super().__init__(tb)

def cut(self, path: os.PathLike[str] | str | None=None, lineno: int | None=None, firstlineno: int | None=None, excludepath: os.PathLike[str] | None=None) -> Traceback:
    path_ = None if path is None else os.fspath(path)
    excludepath_ = None if excludepath is None else os.fspath(excludepath)
    for x in self:
        code = x.frame.code
        codepath = code.path
        if path is not None and str(codepath) != path_:
            continue
        if excludepath is not None and isinstance(codepath, Path) and (excludepath_ in (str(p) for p in codepath.parents)):
            continue
        if lineno is not None and x.lineno != lineno:
            continue
        if firstlineno is not None and x.frame.code.firstlineno != firstlineno:
            continue
        return Traceback(x._rawentry)
    return self

def filter(self, excinfo_or_fn: ExceptionInfo[BaseException] | Callable[[TracebackEntry], bool], /) -> Traceback:
    if isinstance(excinfo_or_fn, ExceptionInfo):
        fn = lambda x: not x.ishidden(excinfo_or_fn)
    else:
        fn = excinfo_or_fn
    return Traceback(filter(fn, self))

def recursionindex(self) -> int | None:
    cache: dict[tuple[Any, int, int], list[dict[str, Any]]] = {}
    for i, entry in enumerate(self):
        key = (entry.frame.code.path, id(entry.frame.code.raw), entry.lineno)
        values = cache.setdefault(key, [])
        loc = dict(entry.frame.f_locals)
        if values:
            for otherloc in values:
                if otherloc == loc:
                    return i
        values.append(loc)
    return None

@classmethod
def from_exception(cls, exception: E, exprinfo: str | None=None) -> ExceptionInfo[E]:
    assert exception.__traceback__, 'Exceptions passed to ExcInfo.from_exception(...) must have a non-None __traceback__.'
    exc_info = (type(exception), exception, exception.__traceback__)
    return cls.from_exc_info(exc_info, exprinfo)

@classmethod
def from_exc_info(cls, exc_info: tuple[type[E], E, TracebackType], exprinfo: str | None=None) -> ExceptionInfo[E]:
    _striptext = ''
    if exprinfo is None and isinstance(exc_info[1], AssertionError):
        exprinfo = getattr(exc_info[1], 'msg', None)
        if exprinfo is None:
            exprinfo = saferepr(exc_info[1])
        if exprinfo and exprinfo.startswith(cls._assert_start_repr):
            _striptext = 'AssertionError: '
    return cls(exc_info, _striptext, _ispytest=True)

@classmethod
def from_current(cls, exprinfo: str | None=None) -> ExceptionInfo[BaseException]:
    tup = sys.exc_info()
    assert tup[0] is not None, 'no current exception'
    assert tup[1] is not None, 'no current exception'
    assert tup[2] is not None, 'no current exception'
    exc_info = (tup[0], tup[1], tup[2])
    return ExceptionInfo.from_exc_info(exc_info, exprinfo)

@classmethod
def for_later(cls) -> ExceptionInfo[E]:
    return cls(None, _ispytest=True)

def fill_unfilled(self, exc_info: tuple[type[E], E, TracebackType]) -> None:
    assert self._excinfo is None, 'ExceptionInfo was already filled'
    self._excinfo = exc_info

@property
def type(self) -> type[E]:
    assert self._excinfo is not None, '.type can only be used after the context manager exits'
    return self._excinfo[0]

@property
def value(self) -> E:
    assert self._excinfo is not None, '.value can only be used after the context manager exits'
    return self._excinfo[1]

@property
def tb(self) -> TracebackType:
    assert self._excinfo is not None, '.tb can only be used after the context manager exits'
    return self._excinfo[2]

@property
def typename(self) -> str:
    assert self._excinfo is not None, '.typename can only be used after the context manager exits'
    return self.type.__name__

@property
def traceback(self) -> Traceback:
    if self._traceback is None:
        self._traceback = Traceback(self.tb)
    return self._traceback

def exconly(self, tryshort: bool=False) -> str:

    def _get_single_subexc(eg: BaseExceptionGroup[BaseException]) -> BaseException | None:
        if len(eg.exceptions) != 1:
            return None
        if isinstance((e := eg.exceptions[0]), BaseExceptionGroup):
            return _get_single_subexc(e)
        return e
    if tryshort and isinstance(self.value, BaseExceptionGroup) and ((subexc := _get_single_subexc(self.value)) is not None):
        return f'{subexc!r} [single exception in {type(self.value).__name__}]'
    lines = format_exception_only(self.value)
    text = ''.join(lines)
    text = text.rstrip()
    if tryshort:
        if text.startswith(self._striptext):
            text = text[len(self._striptext):]
    return text

def getrepr(self, showlocals: bool=False, style: TracebackStyle='long', abspath: bool=False, tbfilter: bool | Callable[[ExceptionInfo[BaseException]], Traceback]=True, funcargs: bool=False, truncate_locals: bool=True, truncate_args: bool=True, chain: bool=True) -> ReprExceptionInfo | ExceptionChainRepr:
    if style == 'native':
        return ReprExceptionInfo(reprtraceback=ReprTracebackNative(format_exception(self.type, self.value, self.traceback[0]._rawentry if self.traceback else None)), reprcrash=self._getreprcrash())
    fmt = ExceptionInfoFormatter(showlocals=showlocals, style=style, abspath=abspath, tbfilter=tbfilter, funcargs=funcargs, truncate_locals=truncate_locals, truncate_args=truncate_args, chain=chain)
    return fmt.repr_excinfo(self)

def _group_contains(self, exc_group: BaseExceptionGroup[BaseException], expected_exception: EXCEPTION_OR_MORE, match: str | re.Pattern[str] | None, target_depth: int | None=None, current_depth: int=1) -> bool:
    if target_depth is not None and current_depth > target_depth:
        return False
    for exc in exc_group.exceptions:
        if isinstance(exc, BaseExceptionGroup):
            if self._group_contains(exc, expected_exception, match, target_depth, current_depth + 1):
                return True
        if target_depth is not None and current_depth != target_depth:
            continue
        if not isinstance(exc, expected_exception):
            continue
        if match is not None:
            value = stringify_exception(exc)
            if not re.search(match, value):
                continue
        return True
    return False

def group_contains(self, expected_exception: EXCEPTION_OR_MORE, *, match: str | re.Pattern[str] | None=None, depth: int | None=None) -> bool:
    msg = 'Captured exception is not an instance of `BaseExceptionGroup`'
    assert isinstance(self.value, BaseExceptionGroup), msg
    msg = '`depth` must be >= 1 if specified'
    assert depth is None or depth >= 1, msg
    return self._group_contains(self.value, expected_exception, match, depth)

def get_source(self, source: Source | None, line_index: int=-1, excinfo: ExceptionInfo[BaseException] | None=None, short: bool=False, end_line_index: int | None=None, colno: int | None=None, end_colno: int | None=None) -> list[str]:
    lines = []
    if source is not None and line_index < 0:
        line_index += len(source)
    if source is None or line_index >= len(source.lines) or line_index < 0:
        source = Source('???')
        line_index = 0
    space_prefix = '    '
    if short:
        lines.append(space_prefix + source.lines[line_index].strip())
        lines.extend(self.get_highlight_arrows_for_line(raw_line=source.raw_lines[line_index], line=source.lines[line_index].strip(), lineno=line_index, end_lineno=end_line_index, colno=colno, end_colno=end_colno))
    else:
        for line in source.lines[:line_index]:
            lines.append(space_prefix + line)
        lines.append(self.flow_marker + '   ' + source.lines[line_index])
        lines.extend(self.get_highlight_arrows_for_line(raw_line=source.raw_lines[line_index], line=source.lines[line_index], lineno=line_index, end_lineno=end_line_index, colno=colno, end_colno=end_colno))
        for line in source.lines[line_index + 1:]:
            lines.append(space_prefix + line)
    if excinfo is not None:
        indent = 4 if short else self._getindent(source)
        lines.extend(self.get_exconly(excinfo, indent=indent, markall=True))
    return lines

def _truncate_recursive_traceback(self, traceback: Traceback) -> tuple[Traceback, str | None]:
    try:
        recursionindex = traceback.recursionindex()
    except Exception as e:
        max_frames = 10
        extraline: str | None = f'!!! Recursion error detected, but an error occurred locating the origin of recursion.\n  The following exception happened when comparing locals in the stack frame:\n    {type(e).__name__}: {e!s}\n  Displaying first and last {max_frames} stack frames out of {len(traceback)}.'
        traceback = traceback[:max_frames] + traceback[-max_frames:]
    else:
        if recursionindex is not None:
            extraline = '!!! Recursion detected (same locals & position)'
            traceback = traceback[:recursionindex + 1]
        else:
            extraline = None
    return (traceback, extraline)

def _write_entry_lines(self, tw: TerminalWriter) -> None:
    if not self.lines:
        return
    if self.style == 'value':
        for line in self.lines:
            tw.write(line)
            tw.write('\n')
        return
    fail_marker = f'{ExceptionInfoFormatter.fail_marker}   '
    indent_size = len(fail_marker)
    indents: list[str] = []
    source_lines: list[str] = []
    failure_lines: list[str] = []
    for index, line in enumerate(self.lines):
        is_failure_line = line.startswith(fail_marker)
        if is_failure_line:
            failure_lines.extend(self.lines[index:])
            break
        else:
            indents.append(line[:indent_size])
            source_lines.append(line[indent_size:])
    tw._write_source(source_lines, indents)
    for line in failure_lines:
        tw.line(line, bold=True, red=True)

def getfslineno(obj: object) -> tuple[str | Path, int]:
    obj = get_real_func(obj)
    if hasattr(obj, 'place_as'):
        obj = obj.place_as
    try:
        code = Code.from_function(obj)
    except TypeError:
        try:
            fn = inspect.getsourcefile(obj) or inspect.getfile(obj)
        except TypeError:
            return ('', -1)
        fspath = fn and absolutepath(fn) or ''
        lineno = -1
        if fspath:
            try:
                _, lineno = findsource(obj)
            except OSError:
                pass
        return (fspath, lineno)
    return (code.path, code.firstlineno)

def _byte_offset_to_character_offset(str, offset):
    as_utf8 = str.encode('utf-8')
    return len(as_utf8[:offset].decode('utf-8', errors='replace'))

def filter_traceback(entry: TracebackEntry) -> bool:
    raw_filename = entry.frame.code.raw.co_filename
    is_generated = '<' in raw_filename and '>' in raw_filename
    if is_generated:
        return False
    p = Path(entry.path)
    parents = p.parents
    if _PLUGGY_DIR in parents:
        return False
    if _PYTEST_DIR in parents:
        return False
    return True

def filter_excinfo_traceback(tbfilter: TracebackFilter, excinfo: ExceptionInfo[BaseException]) -> Traceback:
    if callable(tbfilter):
        return tbfilter(excinfo)
    elif tbfilter:
        return excinfo.traceback.filter(excinfo)
    else:
        return excinfo.traceback

def strip(self) -> Source:
    start, end = (0, len(self))
    while start < end and (not self.lines[start].strip()):
        start += 1
    while end > start and (not self.lines[end - 1].strip()):
        end -= 1
    source = Source()
    source.raw_lines = self.raw_lines
    source.lines[:] = self.lines[start:end]
    return source

def getstatement(self, lineno: int) -> Source:
    start, end = self.getstatementrange(lineno)
    return self[start:end]

def getstatementrange(self, lineno: int) -> tuple[int, int]:
    if not 0 <= lineno < len(self):
        raise IndexError('lineno out of range')
    _ast, start, end = getstatementrange_ast(lineno, self)
    return (start, end)

def getrawcode(obj: object, trycall: bool=True) -> types.CodeType:
    try:
        return obj.__code__
    except AttributeError:
        pass
    if trycall:
        call = getattr(obj, '__call__', None)
        if call and (not isinstance(obj, type)):
            return getrawcode(call, trycall=False)
    raise TypeError(f'could not get code object for {obj!r}')

def __init__(self, indent: int=4, width: int=80, depth: int | None=None) -> None:
    if indent < 0:
        raise ValueError('indent must be >= 0')
    if depth is not None and depth <= 0:
        raise ValueError('depth must be > 0')
    if not width:
        raise ValueError('width must be != 0')
    self._depth = depth
    self._indent_per_level = indent
    self._width = width

def pformat_lines(self, object: Any, *, max_lines: int | None=None, max_chars: int | None=None) -> list[str]:
    if max_lines is None and max_chars is None:
        return self.pformat(object).splitlines()
    n_lines = 0
    n_chars = 0
    chunks: list[str] = []
    for chunk in self._format(object, 0, 0, set(), 0):
        chunks.append(chunk)
        if max_chars is not None:
            n_chars += len(chunk)
        if max_lines is not None and '\n' in chunk:
            n_lines += chunk.count('\n')
        if max_lines is not None and n_lines >= max_lines or (max_chars is not None and n_chars >= max_chars):
            break
    return ''.join(chunks).splitlines()

def safeformat(obj: object) -> str:
    try:
        return pprint.pformat(obj)
    except Exception as exc:
        return _format_repr_exception(exc, obj)

def saferepr_unlimited(obj: object, use_ascii: bool=True) -> str:
    try:
        if use_ascii:
            return ascii(obj)
        return repr(obj)
    except Exception as exc:
        return _format_repr_exception(exc, obj)

