def _write_source(self, lines: Sequence[str], indents: Sequence[str]=()) -> None:
    if indents and len(indents) != len(lines):
        raise ValueError(f'indents size ({len(indents)}) should have same size as lines ({len(lines)})')
    if not indents:
        indents = [''] * len(lines)
    source = '\n'.join(lines)
    new_lines = self._highlight(source).splitlines()
    for indent, new_line in zip(indents, new_lines, strict=False):
        self.line(indent + new_line)

def _highlight(self, source: str, lexer: Literal['diff', 'python']='python') -> str:
    if not source or not self.hasmarkup or (not self.code_highlight):
        return source
    pygments_lexer = self._get_pygments_lexer(lexer)
    pygments_formatter = self._get_pygments_formatter()
    highlighted: str = pygments.highlight(source, pygments_lexer, pygments_formatter)
    if highlighted[-1] == '\n' and source[-1] != '\n':
        highlighted = highlighted[:-1]
    highlighted = '\x1b[0m' + highlighted
    return highlighted

@lru_cache(100)
def wcwidth(c: str) -> int:
    o = ord(c)
    if 32 <= o < 127:
        return 1
    if o == 0 or 8203 <= o <= 8207 or 8232 <= o <= 8238 or (8288 <= o <= 8291):
        return 0
    category = unicodedata.category(c)
    if category == 'Cc':
        return -1
    if category in ('Me', 'Mn'):
        return 0
    if unicodedata.east_asian_width(c) in ('F', 'W'):
        return 2
    return 1

def wcswidth(s: str) -> int:
    width = 0
    for c in unicodedata.normalize('NFC', s):
        wc = wcwidth(c)
        if wc < 0:
            return -1
        width += wc
    return width

def checked_call(self, func: Callable[P, R], *args: P.args, **kwargs: P.kwargs) -> R:
    __tracebackhide__ = True
    try:
        return func(*args, **kwargs)
    except Error:
        raise
    except OSError as value:
        if not hasattr(value, 'errno'):
            raise
        if sys.platform == 'win32':
            try:
                cls = self._geterrnoclass(_winerrnomap[value.errno])
            except KeyError:
                raise value
        elif value.errno is None:
            cls = type('UnknownErrnoNone', (Error,), {'__module__': 'py.error', '__doc__': None})
        else:
            cls = self._geterrnoclass(value.errno)
        raise cls(f'{func.__name__}{args!r}')

