@pytest.mark.keep_ci_var
@pytest.mark.parametrize('enabled', [pytest.param(True, marks=pytest.mark.skipif(bool(os.environ.get('CI')) and sys.platform == 'linux' and (sys.version_info >= (3, 14)), reason='sometimes crashes on CI because of truncated outputs (#7022)')), False])
def test_timeout(pytester: Pytester, enabled: bool) -> None:
    pytester.makepyfile('\n    import os, time\n    def test_timeout():\n        time.sleep(1 if "CI" in os.environ else 0.1)\n    ')
    pytester.makeini('\n        [pytest]\n        faulthandler_timeout = 0.01\n        ')
    args = ['-p', 'no:faulthandler'] if not enabled else []
    result = pytester.runpytest_subprocess(*args)
    tb_output = 'most recent call first'
    if enabled:
        result.stderr.fnmatch_lines([f'*{tb_output}*'])
    else:
        assert tb_output not in result.stderr.str()
    result.stdout.fnmatch_lines(['*1 passed*'])
    assert result.ret == 0

@pytest.mark.keep_ci_var
@pytest.mark.skipif('CI' in os.environ and sys.platform == 'linux' and (sys.version_info >= (3, 14)), reason='sometimes crashes on CI because of truncated outputs (#7022)')
@pytest.mark.parametrize('exit_on_timeout', [True, False])
def test_timeout_and_exit(pytester: Pytester, exit_on_timeout: bool) -> None:
    pytester.makepyfile('\n    import os, time\n    def test_long_sleep_and_raise():\n        time.sleep(1 if "CI" in os.environ else 0.1)\n        raise AssertionError(\n            "This test should have been interrupted before reaching this point."\n        )\n    ')
    pytester.makeini(f"\n        [pytest]\n        faulthandler_timeout = 0.01\n        faulthandler_exit_on_timeout = {('true' if exit_on_timeout else 'false')}\n        ")
    result = pytester.runpytest_subprocess()
    tb_output = 'most recent call first'
    result.stderr.fnmatch_lines([f'*{tb_output}*'])
    if exit_on_timeout:
        result.stdout.no_fnmatch_line('*1 failed*')
        result.stdout.no_fnmatch_line('*AssertionError*')
    else:
        result.stdout.fnmatch_lines(['*1 failed*'])
        result.stdout.fnmatch_lines(['*AssertionError*'])
    assert result.ret == 1

