    fn.write_text(dedent('\n                import pickle\n\n                def _action():\n                    return 42\n\n                def round_trip():\n                    s = pickle.dumps(_action)\n                    return pickle.loads(s)\n                '), encoding='utf-8')
    module = import_path(fn, mode='importlib', root=tmp_path, consider_namespace_packages=ns_param)
    round_trip = getattr(module, 'round_trip')
    action = round_trip()
    assert action() == 42
    module2 = import_path(fn, mode='importlib', root=tmp_path, consider_namespace_packages=ns_param)
    assert module is module2

