        parent.chmod(stat.S_IRUSR | stat.S_IXUSR | stat.S_IRGRP | stat.S_IXGRP | stat.S_IROTH | stat.S_IXOTH)
    exc_info = PermissionError()
    on_rm_rf_error(os.unlink, str(fn), exc_info, start_path=tmp_path)
    assert not fn.exists()

