def test_all_entries_hidden(pytester: Pytester, tbstyle: str, group: bool) -> None:
    pytester.makepyfile(f"""\n        import sys\n        if sys.version_info < (3, 11):\n            from exceptiongroup import ExceptionGroup\n        def test():\n            __tracebackhide__ = True\n            raise {('ExceptionGroup("", [ValueError("bar")])' if group else 'ValueError("bar")')}\n    """)
    result = pytester.runpytest('--tb', tbstyle)
    assert result.ret == 1
    if tbstyle != 'line':
        result.stdout.fnmatch_lines(['*ValueError: bar'])
    if tbstyle not in ('line', 'native'):
        result.stdout.fnmatch_lines(['All traceback entries are hidden.*'])

def test_hidden_entries_of_chained_exceptions_are_not_shown(pytester: Pytester) -> None:
    p = pytester.makepyfile('
        def g1():
            __tracebackhide__ = True
            str.does_not_exist

        def f3():
            __tracebackhide__ = True
            1 / 0

        def f2():
            try:
                f3()
            except Exception:
                g1()

        def f1():
            __tracebackhide__ = True
            f2()

        def test():
            f1()
        ')
    result = pytester.runpytest(str(p), '--tb=short')
    assert result.ret == 1
    result.stdout.fnmatch_lines(['*.py:11: in f2', '    f3()', 'E   ZeroDivisionError: division by zero', '', 'During handling of the above exception, another exception occurred:', '*.py:20: in test', '    f1()', '*.py:13: in f2', '    g1()', "E   AttributeError:*'does_not_exist'"], consecutive=True)

def add_note(err: BaseException, msg: str) -> None:
    if sys.version_info < (3, 11):
        err.__notes__ = [*getattr(err, '__notes__', []), msg]
    else:
        err.add_note(msg)

def test_source_with_decorator() -> None:

    @pytest.mark.foo
    def deco_mark():
        assert False
    src = inspect.getsource(deco_mark)
