def predict_proba(self, X):
    predictions, _ = _get_response_values(self.estimator, X, response_method=['decision_function', 'predict_proba'])
    if predictions.ndim == 1:
        predictions = predictions.reshape(-1, 1)
    n_classes = self.classes.shape[0]
    proba = np.zeros((_num_samples(X), n_classes))
    if self.method in ('sigmoid', 'isotonic'):
        label_encoder = LabelEncoder().fit(self.classes)
        pos_class_indices = label_encoder.transform(self.estimator.classes_)
        for class_idx, this_pred, calibrator in zip(pos_class_indices, predictions.T, self.calibrators):
            if n_classes == 2:
                class_idx += 1
            proba[:, class_idx] = calibrator.predict(this_pred)
        if n_classes == 2:
            proba[:, 0] = 1.0 - proba[:, 1]
        else:
            denominator = np.sum(proba, axis=1)[:, np.newaxis]
            uniform_proba = np.full_like(proba, 1 / n_classes)
            proba = np.divide(proba, denominator, out=uniform_proba, where=denominator != 0)
    elif self.method == 'temperature':
        xp, _ = get_namespace(predictions)
        if n_classes == 2 and predictions.shape[-1] == 1:
            response_method_name = _check_response_method(self.estimator, ['decision_function', 'predict_proba']).__name__
            if response_method_name == 'predict_proba':
                predictions = xp.concat([1 - predictions, predictions], axis=1)
        proba = self.calibrators[0].predict(predictions)
    proba[(1.0 < proba) & (proba <= 1.0 + 1e-05)] = 1.0
    return proba

def _convert_to_logits(decision_values, eps=1e-12, xp=None):
    xp, _, device_ = get_namespace_and_device(decision_values, xp=xp)
    decision_values = check_array(decision_values, dtype=[xp.float64, xp.float32], ensure_2d=False)
    if decision_values.ndim == 2 and decision_values.shape[1] > 1:
        entries_zero_to_one = xp.all((decision_values >= 0) & (decision_values <= 1))
        row_sums_to_one = xp.all(xpx.isclose(xp.sum(decision_values, axis=1), xp.asarray(1.0, device=device_, dtype=decision_values.dtype)))
        if entries_zero_to_one and row_sums_to_one:
            logits = xp.log(decision_values + eps)
        else:
            logits = decision_values
    elif decision_values.ndim == 2 and decision_values.shape[1] == 1:
        logits = xp.concat([-decision_values, decision_values], axis=1)
    elif decision_values.ndim == 1:
        decision_values = xp.reshape(decision_values, (-1, 1))
        logits = xp.concat([-decision_values, decision_values], axis=1)
    return logits

def predict(self, T):
    T = column_or_1d(T)
    return expit(-(self.a_ * T + self.b_))

def log_loss(log_beta=0.0):
    log_beta = xp.asarray(log_beta, dtype=dtype_, device=xp_device)
    raw_prediction = xp.exp(log_beta) * logits
    return multinomial_loss(labels, raw_prediction, sample_weight)

def predict(self, X):
    logits = _convert_to_logits(X)
    return softmax(self.beta_ * logits)

@validate_params({'y_true': ['array-like'], 'y_prob': ['array-like'], 'pos_label': [Real, str, 'boolean', None], 'n_bins': [Interval(Integral, 1, None, closed='left'), StrOptions({'cube_root'})], 'strategy': [StrOptions({'uniform', 'quantile'})]}, prefer_skip_nested_validation=True)
def calibration_curve(y_true, y_prob, *, pos_label=None, n_bins=5, strategy='uniform'):
    y_true = column_or_1d(y_true)
    y_prob = column_or_1d(y_prob)
    check_consistent_length(y_true, y_prob)
    pos_label = _check_pos_label_consistency(pos_label, y_true)
    if y_prob.min() < 0 or y_prob.max() > 1:
        raise ValueError('y_prob has values outside [0, 1].')
    labels = np.unique(y_true)
    if len(labels) > 2:
        raise ValueError(f'Only binary classification is supported. Provided labels {labels}.')
    y_true = y_true == pos_label
    if n_bins == 'cube_root':
        n_bins = ceil(len(y_true) ** (1 / 3))
    if strategy == 'quantile':
        quantiles = np.linspace(0, 1, n_bins + 1)
        bins = np.percentile(y_prob, quantiles * 100)
    elif strategy == 'uniform':
        bins = np.linspace(0.0, 1.0, n_bins + 1)
    else:
        raise ValueError("Invalid entry to 'strategy' input. Strategy must be either 'quantile' or 'uniform'.")
    binids = np.searchsorted(bins[1:-1], y_prob)
    bin_sums = np.bincount(binids, weights=y_prob, minlength=n_bins)
    bin_true = np.bincount(binids, weights=y_true, minlength=n_bins)
    bin_total = np.bincount(binids, minlength=n_bins)
    nonzero = bin_total != 0
    prob_true = bin_true[nonzero] / bin_total[nonzero]
    prob_pred = bin_sums[nonzero] / bin_total[nonzero]
    return (prob_true, prob_pred)

@classmethod
def from_estimator(cls, estimator, X, y, *, n_bins=5, strategy='uniform', pos_label=None, name=None, ax=None, ref_line=True, **kwargs):
    y_prob, pos_label, name = cls._validate_and_get_response_values(estimator, X, y, response_method='predict_proba', pos_label=pos_label, name=name)
    return cls.from_predictions(y, y_prob, n_bins=n_bins, strategy=strategy, pos_label=pos_label, name=name, ref_line=ref_line, ax=ax, **kwargs)

@classmethod
def from_predictions(cls, y_true, y_prob, *, n_bins=5, strategy='uniform', pos_label=None, name=None, ax=None, ref_line=True, **kwargs):
    pos_label_validated, name = cls._validate_from_predictions_params(y_true, y_prob, sample_weight=None, pos_label=pos_label, name=name)
    prob_true, prob_pred = calibration_curve(y_true, y_prob, n_bins=n_bins, strategy=strategy, pos_label=pos_label)
    disp = cls(prob_true=prob_true, prob_pred=prob_pred, y_prob=y_prob, estimator_name=name, pos_label=pos_label_validated)
    return disp.plot(ax=ax, ref_line=ref_line, **kwargs)

