        raise TypeError(msg)
    xp = array_namespace(x) if xp is None else xp
    y = xp.asarray(x)
    if is_cupy_namespace(xp) or is_jax_namespace(xp) or is_numpy_namespace(xp) or is_torch_namespace(xp):
