    return self._partial_fit(X, y, self.alpha, loss=self.loss, learning_rate=self.learning_rate, max_iter=1, sample_weight=sample_weight, coef_init=None, intercept_init=None)

@_fit_context(prefer_skip_nested_validation=True)
def fit(self, X, y, coef_init=None, intercept_init=None, sample_weight=None):
    self._more_validate_params()
    return self._fit(X, y, alpha=self.alpha, loss=self.loss, learning_rate=self.learning_rate, coef_init=coef_init, intercept_init=intercept_init, sample_weight=sample_weight)

def _decision_function(self, X):
    check_is_fitted(self)
    X = validate_data(self, X, accept_sparse='csr', reset=False)
    scores = safe_sparse_dot(X, self.coef_.T, dense_output=True) + self.intercept_
    return scores.ravel()

@_fit_context(prefer_skip_nested_validation=True)
def partial_fit(self, X, y=None, sample_weight=None):
    if not hasattr(self, 'coef_'):
        self._more_validate_params(for_partial_fit=True)
    alpha = self.nu
    return self._partial_fit(X, alpha, loss=self.loss, learning_rate=self.learning_rate, max_iter=1, sample_weight=sample_weight, coef_init=None, offset_init=None)

@_fit_context(prefer_skip_nested_validation=True)
def fit(self, X, y=None, coef_init=None, offset_init=None, sample_weight=None):
    self._more_validate_params()
    alpha = self.nu
    self._fit(X, alpha=alpha, loss=self.loss, learning_rate=self.learning_rate, coef_init=coef_init, offset_init=offset_init, sample_weight=sample_weight)
    return self

def decision_function(self, X):
    check_is_fitted(self, 'coef_')
    X = validate_data(self, X, accept_sparse='csr', reset=False)
    decisions = safe_sparse_dot(X, self.coef_.T, dense_output=True) - self.offset_
    return decisions.ravel()

def score_samples(self, X):
    score_samples = self.decision_function(X) + self.offset_
    return score_samples

def _spatial_median(X, max_iter=300, tol=0.001):
    if X.shape[1] == 1:
        return (1, np.median(X.ravel(), keepdims=True))
    tol **= 2
    spatial_median_old = np.mean(X, axis=0)
    for n_iter in range(max_iter):
        spatial_median = _modified_weiszfeld_step(X, spatial_median_old)
        if np.sum((spatial_median_old - spatial_median) ** 2) < tol:
            break
        else:
            spatial_median_old = spatial_median
    else:
        warnings.warn('Maximum number of iterations {max_iter} reached in spatial median for TheilSen regressor.'.format(max_iter=max_iter), ConvergenceWarning)
    return (n_iter, spatial_median)

def setup(self, X, y, sample_weight):
    _, _, self.raw_prediction = self.linear_loss.weight_intercept_raw(self.coef, X)
    self.loss_value = self.linear_loss.loss(coef=self.coef, X=X, y=y, sample_weight=sample_weight, l2_reg_strength=self.l2_reg_strength, n_threads=self.n_threads, raw_prediction=self.raw_prediction)

@abstractmethod
def update_gradient_hessian(self, X, y, sample_weight):
    pass

@abstractmethod
def inner_solve(self, X, y, sample_weight):
    pass

@abstractmethod
def compute_d2(self, X, sample_weight):
    pass

def check_convergence(self, X, y, sample_weight):
    if self.verbose:
        print('  Check Convergence')
    g_max_abs = np.max(np.abs(self.gradient))
    check = g_max_abs <= self.tol
    if self.verbose:
        print(f'    1. max |gradient| {g_max_abs} <= {self.tol} {check}')
    if not check:
        return
    d2 = self.compute_d2(X, sample_weight=sample_weight)
    check = 0.5 * d2 <= self.tol
    if self.verbose:
        print(f'    2. Newton decrement {0.5 * d2} <= {self.tol} {check}')
    if not check:
        return
    if self.verbose:
        loss_value = self.linear_loss.loss(coef=self.coef, X=X, y=y, sample_weight=sample_weight, l2_reg_strength=self.l2_reg_strength, n_threads=self.n_threads)
        print(f'  Solver did converge at loss = {loss_value}.')
    self.converged = True

def solve(self, X, y, sample_weight):
    self.setup(X=X, y=y, sample_weight=sample_weight)
    self.iteration = 1
    self.converged = False
    self.use_fallback_lbfgs_solve = False
    while self.iteration <= self.max_iter and (not self.converged):
        if self.verbose:
            print(f'Newton iter={self.iteration}')
        self.use_fallback_lbfgs_solve = False
        self.update_gradient_hessian(X=X, y=y, sample_weight=sample_weight)
        self.inner_solve(X=X, y=y, sample_weight=sample_weight)
        if self.use_fallback_lbfgs_solve:
            break
        self.line_search(X=X, y=y, sample_weight=sample_weight)
        if self.use_fallback_lbfgs_solve:
            break
        self.check_convergence(X=X, y=y, sample_weight=sample_weight)
        self.iteration += 1
    if not self.converged:
        if self.use_fallback_lbfgs_solve:
            self.fallback_lbfgs_solve(X=X, y=y, sample_weight=sample_weight)
        else:
            warnings.warn(f'Newton solver did not converge after {self.iteration - 1} iterations.', ConvergenceWarning)
    self.iteration -= 1
    self.finalize(X=X, y=y, sample_weight=sample_weight)
    return self.coef

def fit(self, X, y=None):
    self.fit_transform(X)
    return self

@_fit_context(prefer_skip_nested_validation=False)
def fit(self, X, y=None):
    self._fit_transform(X)
    return self

@_fit_context(prefer_skip_nested_validation=False)
def fit_transform(self, X, y=None):
    self._fit_transform(X)
    return self.embedding_

def transform(self, X):
    check_is_fitted(self)
    if self.n_neighbors is not None:
        distances, indices = self.nbrs_.kneighbors(X, return_distance=True)
    else:
        distances, indices = self.nbrs_.radius_neighbors(X, return_distance=True)
    n_samples_fit = self.nbrs_.n_samples_fit_
    n_queries = distances.shape[0]
    if hasattr(X, 'dtype') and X.dtype == np.float32:
        dtype = np.float32
    else:
        dtype = np.float64
    G_X = np.zeros((n_queries, n_samples_fit), dtype)
    for i in range(n_queries):
        G_X[i] = np.min(self.dist_matrix_[indices[i]] + distances[i][:, None], 0)
    G_X **= 2
    G_X *= -0.5
    return self.kernel_pca_.transform(G_X)

def null_space(M, k, k_skip=1, eigen_solver='arpack', tol=1e-06, max_iter=100, random_state=None):
    if eigen_solver == 'auto':
        if M.shape[0] > 200 and k + k_skip < 10:
            eigen_solver = 'arpack'
        else:
            eigen_solver = 'dense'
    if eigen_solver == 'arpack':
        v0 = _init_arpack_v0(M.shape[0], random_state)
        try:
            eigen_values, eigen_vectors = eigsh(M, k + k_skip, sigma=0.0, tol=tol, maxiter=max_iter, v0=v0)
        except RuntimeError as e:
            raise ValueError("Error in determining null-space with ARPACK. Error message: '%s'. Note that eigen_solver='arpack' can fail when the weight matrix is singular or otherwise ill-behaved. In that case, eigen_solver='dense' is recommended. See online documentation for more information." % e) from e
        return (eigen_vectors[:, k_skip:], np.sum(eigen_values[k_skip:]))
    elif eigen_solver == 'dense':
        if hasattr(M, 'toarray'):
            M = M.toarray()
        eigen_values, eigen_vectors = eigh(M, subset_by_index=(k_skip, k + k_skip - 1), overwrite_a=True)
        index = np.argsort(np.abs(eigen_values))
        return (eigen_vectors[:, index], np.sum(eigen_values))
    else:
        raise ValueError("Unrecognized eigen_solver '%s'" % eigen_solver)

