def _validate_shuffle_split(n_samples, test_size, train_size, default_test_size=None):
    if test_size is None and train_size is None:
        test_size = default_test_size
    test_size_type = np.asarray(test_size).dtype.kind
    train_size_type = np.asarray(train_size).dtype.kind
    if test_size_type == 'i' and (test_size >= n_samples or test_size <= 0) or (test_size_type == 'f' and (test_size <= 0 or test_size >= 1)):
        raise ValueError('test_size={0} should be either positive and smaller than the number of samples {1} or a float in the (0, 1) range'.format(test_size, n_samples))
    if train_size_type == 'i' and (train_size >= n_samples or train_size <= 0) or (train_size_type == 'f' and (train_size <= 0 or train_size >= 1)):
        raise ValueError('train_size={0} should be either positive and smaller than the number of samples {1} or a float in the (0, 1) range'.format(train_size, n_samples))
    if train_size is not None and train_size_type not in ('i', 'f'):
        raise ValueError('Invalid value for train_size: {}'.format(train_size))
    if test_size is not None and test_size_type not in ('i', 'f'):
        raise ValueError('Invalid value for test_size: {}'.format(test_size))
    if train_size_type == 'f' and test_size_type == 'f' and (train_size + test_size > 1):
        raise ValueError('The sum of test_size and train_size = {}, should be in the (0, 1) range. Reduce test_size and/or train_size.'.format(train_size + test_size))
    if test_size_type == 'f':
        n_test = ceil(test_size * n_samples)
    elif test_size_type == 'i':
        n_test = float(test_size)
    if train_size_type == 'f':
        n_train = floor(train_size * n_samples)
    elif train_size_type == 'i':
        n_train = float(train_size)
    if train_size is None:
        n_train = n_samples - n_test
    elif test_size is None:
        n_test = n_samples - n_train
    if n_train + n_test > n_samples:
        raise ValueError('The sum of train_size and test_size = %d, should be smaller than the number of samples %d. Reduce test_size and/or train_size.' % (n_train + n_test, n_samples))
    n_train, n_test = (int(n_train), int(n_test))
    if n_train == 0:
        raise ValueError('With n_samples={}, test_size={} and train_size={}, the resulting train set will be empty. Adjust any of the aforementioned parameters.'.format(n_samples, test_size, train_size))
    return (n_train, n_test)

def split(self, X=None, y=None, groups=None):
    if groups is not None:
        warnings.warn(f'The groups parameter is ignored by {self.__class__.__name__}', UserWarning)
    return self._split()

def _split(self):
    ind = np.arange(len(self.test_fold))
    for test_index in self._iter_test_masks():
        train_index = ind[np.logical_not(test_index)]
        test_index = ind[test_index]
        yield (train_index, test_index)

def _iter_test_masks(self):
    for f in self.unique_folds:
        test_index = np.where(self.test_fold == f)[0]
        test_mask = np.zeros(len(self.test_fold), dtype=bool)
        test_mask[test_index] = True
        yield test_mask

def split(self, X=None, y=None, groups=None):
    for train, test in self.cv:
        yield (train, test)

def check_cv(cv=5, y=None, *, classifier=False, shuffle=False, random_state=None):
    cv = 5 if cv is None else cv
    if isinstance(cv, numbers.Integral):
        if classifier and y is not None and (type_of_target(y, input_name='y') in ('binary', 'multiclass')):
            return StratifiedKFold(cv, shuffle=shuffle, random_state=random_state)
        else:
            return KFold(cv, shuffle=shuffle, random_state=random_state)
    if not hasattr(cv, 'split') or isinstance(cv, str):
        if not isinstance(cv, Iterable) or isinstance(cv, str):
            raise ValueError(f'Expected `cv` as an integer, a cross-validation object (from sklearn.model_selection), or an iterable yielding (train, test) splits as arrays of indices. Got {cv}.')
        return _CVIterableWrapper(cv)
    return cv

@validate_params({'test_size': [Interval(RealNotInt, 0, 1, closed='neither'), Interval(numbers.Integral, 1, None, closed='left'), None], 'train_size': [Interval(RealNotInt, 0, 1, closed='neither'), Interval(numbers.Integral, 1, None, closed='left'), None], 'random_state': ['random_state'], 'shuffle': ['boolean'], 'stratify': ['array-like', None]}, prefer_skip_nested_validation=True)
def train_test_split(*arrays, test_size=None, train_size=None, random_state=None, shuffle=True, stratify=None):
    n_arrays = len(arrays)
    if n_arrays == 0:
        raise ValueError('At least one array required as input')
    arrays = indexable(*arrays)
    n_samples = _num_samples(arrays[0])
    n_train, n_test = _validate_shuffle_split(n_samples, test_size, train_size, default_test_size=0.25)
    if shuffle is False:
        if stratify is not None:
            raise ValueError('Stratified train/test split is not implemented for shuffle=False')
        train = np.arange(n_train)
        test = np.arange(n_train, n_train + n_test)
    else:
        if stratify is not None:
            CVClass = StratifiedShuffleSplit
        else:
            CVClass = ShuffleSplit
        cv = CVClass(test_size=n_test, train_size=n_train, random_state=random_state)
        train, test = next(cv.split(X=arrays[0], y=stratify))
    xp, _, device = get_namespace_and_device(arrays[0])
    train, test = move_to(train, test, xp=xp, device=device)
    return list(chain.from_iterable(((_safe_indexing(a, train), _safe_indexing(a, test)) for a in arrays)))

def _pprint(params, offset=0, printer=repr):
    options = np.get_printoptions()
    np.set_printoptions(precision=5, threshold=64, edgeitems=2)
    params_list = list()
    this_line_length = offset
    line_sep = ',\n' + (1 + offset // 2) * ' '
    for i, (k, v) in enumerate(sorted(params.items())):
        if isinstance(v, float):
            this_repr = '%s=%s' % (k, str(v))
        else:
            this_repr = '%s=%s' % (k, printer(v))
        if len(this_repr) > 500:
            this_repr = this_repr[:300] + '...' + this_repr[-100:]
        if i > 0:
            if this_line_length + len(this_repr) >= 75 or '\n' in this_repr:
                params_list.append(line_sep)
                this_line_length = len(line_sep)
            else:
                params_list.append(', ')
                this_line_length += 2
        params_list.append(this_repr)
        this_line_length += len(this_repr)
    np.set_printoptions(**options)
    lines = ''.join(params_list)
    lines = '\n'.join((l.rstrip(' ') for l in lines.split('\n')))
    return lines

@validate_params({'estimator': [HasMethods('fit')], 'X': ['array-like', 'sparse matrix'], 'y': ['array-like', None], 'groups': ['array-like', None], 'scoring': [StrOptions(set(get_scorer_names())), callable, list, tuple, dict, None], 'cv': ['cv_object'], 'n_jobs': [Integral, None], 'verbose': ['verbose'], 'params': [dict, None], 'pre_dispatch': [Integral, str], 'return_train_score': ['boolean'], 'return_estimator': ['boolean'], 'return_indices': ['boolean'], 'error_score': [StrOptions({'raise'}), Real]}, prefer_skip_nested_validation=False)
def cross_validate(estimator, X, y=None, *, groups=None, scoring=None, cv=None, n_jobs=None, verbose=0, params=None, pre_dispatch='2*n_jobs', return_train_score=False, return_estimator=False, return_indices=False, error_score=np.nan):
    _check_groups_routing_disabled(groups)
    X, y = indexable(X, y)
    params = {} if params is None else params
    cv = check_cv(cv, y, classifier=is_classifier(estimator))
    scorers = check_scoring(estimator, scoring=scoring, raise_exc=error_score == 'raise')
    if _routing_enabled():
        router = MetadataRouter(owner='cross_validate').add(splitter=cv, method_mapping=MethodMapping().add(caller='fit', callee='split')).add(estimator=estimator, method_mapping=MethodMapping().add(caller='fit', callee='fit')).add(scorer=scorers, method_mapping=MethodMapping().add(caller='fit', callee='score'))
        try:
            routed_params = process_routing(router, 'fit', **params)
        except UnsetMetadataPassedError as e:
            raise UnsetMetadataPassedError(message=str(e).replace('cross_validate.fit', 'cross_validate'), unrequested_params=e.unrequested_params, routed_params=e.routed_params)
    else:
        routed_params = _manual_routing({'splitter': {'split': {'groups': groups}}, 'estimator': {'fit': params}, 'scorer': {}})
    indices = cv.split(X, y, **routed_params.splitter.split)
    if return_indices:
        indices = list(indices)
    parallel = Parallel(n_jobs=n_jobs, verbose=verbose, pre_dispatch=pre_dispatch)
    results = parallel((delayed(_fit_and_score)(clone(estimator), X, y, scorer=scorers, train=train, test=test, verbose=verbose, parameters=None, fit_params=routed_params.estimator.fit, score_params=routed_params.scorer.score, return_train_score=return_train_score, return_times=True, return_estimator=return_estimator, error_score=error_score) for train, test in indices))
    _warn_or_raise_about_fit_failures(results, error_score)
    if callable(scoring):
        _insert_error_scores(results, error_score)
    results = _aggregate_score_dicts(results)
    ret = {}
    ret['fit_time'] = results['fit_time']
    ret['score_time'] = results['score_time']
    if return_estimator:
        ret['estimator'] = results['estimator']
    if return_indices:
        ret['indices'] = {}
        ret['indices']['train'], ret['indices']['test'] = zip(*indices)
    test_scores_dict = _normalize_score_results(results['test_scores'])
    if return_train_score:
        train_scores_dict = _normalize_score_results(results['train_scores'])
    for name in test_scores_dict:
        ret['test_%s' % name] = test_scores_dict[name]
        if return_train_score:
            key = 'train_%s' % name
            ret[key] = train_scores_dict[name]
    return ret

def _insert_error_scores(results, error_score):
    successful_score = None
    failed_indices = []
    for i, result in enumerate(results):
        if result['fit_error'] is not None:
            failed_indices.append(i)
        elif successful_score is None:
            successful_score = result['test_scores']
    if isinstance(successful_score, dict):
        formatted_error = {name: error_score for name in successful_score}
        for i in failed_indices:
            results[i]['test_scores'] = formatted_error.copy()
            if 'train_scores' in results[i]:
                results[i]['train_scores'] = formatted_error.copy()

def _normalize_score_results(scores, scaler_score_key='score'):
    if isinstance(scores[0], dict):
        return _aggregate_score_dicts(scores)
    return {scaler_score_key: scores}

@validate_params({'estimator': [HasMethods('fit')], 'X': ['array-like', 'sparse matrix'], 'y': ['array-like', None], 'groups': ['array-like', None], 'scoring': [StrOptions(set(get_scorer_names())), callable, None], 'cv': ['cv_object'], 'n_jobs': [Integral, None], 'verbose': ['verbose'], 'params': [dict, None], 'pre_dispatch': [Integral, str, None], 'error_score': [StrOptions({'raise'}), Real]}, prefer_skip_nested_validation=False)
def cross_val_score(estimator, X, y=None, *, groups=None, scoring=None, cv=None, n_jobs=None, verbose=0, params=None, pre_dispatch='2*n_jobs', error_score=np.nan):
    scorer = check_scoring(estimator, scoring=scoring)
    cv_results = cross_validate(estimator=estimator, X=X, y=y, groups=groups, scoring={'score': scorer}, cv=cv, n_jobs=n_jobs, verbose=verbose, params=params, pre_dispatch=pre_dispatch, error_score=error_score)
    return cv_results['test_score']

def _fit_and_score(estimator, X, y, *, scorer, train, test, verbose, parameters, fit_params, score_params, return_train_score=False, return_parameters=False, return_n_test_samples=False, return_times=False, return_estimator=False, split_progress=None, candidate_progress=None, error_score=np.nan, caller=None, callback_ctx=None):
    xp, _ = get_namespace(X)
    X_device = device(X)
    train, test = (xp.asarray(train, device=X_device), xp.asarray(test, device=X_device))
    if not isinstance(error_score, numbers.Number) and error_score != 'raise':
        raise ValueError("error_score must be the string 'raise' or a numeric value. (Hint: if using 'raise', please make sure that it has been spelled correctly.)")
    progress_msg = ''
    if verbose > 2:
        if split_progress is not None:
            progress_msg = f' {split_progress[0] + 1}/{split_progress[1]}'
        if candidate_progress and verbose > 9:
            progress_msg += f'; {candidate_progress[0] + 1}/{candidate_progress[1]}'
    if verbose > 1:
        if parameters is None:
            params_msg = ''
        else:
            sorted_keys = sorted(parameters)
            params_msg = ', '.join((f'{k}={parameters[k]}' for k in sorted_keys))
    if verbose > 9:
        start_msg = f'[CV{progress_msg}] START {params_msg}'
        print(f"{start_msg}{(80 - len(start_msg)) * '.'}")
    fit_params = fit_params if fit_params is not None else {}
    fit_params = _check_method_params(X, params=fit_params, indices=train)
    score_params = score_params if score_params is not None else {}
    score_params_train = _check_method_params(X, params=score_params, indices=train)
    score_params_test = _check_method_params(X, params=score_params, indices=test)
    if parameters is not None:
        estimator = estimator.set_params(**clone(parameters, safe=False))
    start_time = time.time()
    X_train, y_train = _safe_split(estimator, X, y, train)
    X_test, y_test = _safe_split(estimator, X, y, test, train)
    if (sample_weight := fit_params.get('sample_weight')) is not None:
        metadata_callbacks = {'sample_weight': sample_weight}
    else:
        metadata_callbacks = None
    result = {}
    try:
        if callback_ctx is not None:
            with callback_ctx.propagate_callback_context(estimator):
                callback_ctx.call_on_fit_task_begin(estimator=caller, X=X_train, y=y_train, metadata=metadata_callbacks)
                if y_train is None:
                    estimator.fit(X_train, **fit_params)
                else:
                    estimator.fit(X_train, y_train, **fit_params)
        elif y_train is None:
            estimator.fit(X_train, **fit_params)
        else:
            estimator.fit(X_train, y_train, **fit_params)
    except Exception:
        fit_time = time.time() - start_time
        score_time = 0.0
        if error_score == 'raise':
            raise
        elif isinstance(error_score, numbers.Number):
            if isinstance(scorer, _MultimetricScorer):
                test_scores = {name: error_score for name in scorer._scorers}
                if return_train_score:
                    train_scores = test_scores.copy()
            else:
                test_scores = error_score
                if return_train_score:
                    train_scores = error_score
        result['fit_error'] = format_exc()
    else:
        result['fit_error'] = None
        fit_time = time.time() - start_time
        test_scores = _score(estimator, X_test, y_test, scorer, score_params_test, error_score)
        score_time = time.time() - start_time - fit_time
        if return_train_score:
            train_scores = _score(estimator, X_train, y_train, scorer, score_params_train, error_score)
    finally:
        if callback_ctx is not None:
            callback_ctx.call_on_fit_task_end(estimator=caller, X=X_train, y=y_train, metadata=metadata_callbacks)
    if verbose > 1:
        total_time = score_time + fit_time
        end_msg = f'[CV{progress_msg}] END '
        result_msg = params_msg + (';' if params_msg else '')
        if verbose > 2:
            if isinstance(test_scores, dict):
                for scorer_name in sorted(test_scores):
                    result_msg += f' {scorer_name}: ('
                    if return_train_score:
                        scorer_scores = train_scores[scorer_name]
                        result_msg += f'train={scorer_scores:.3f}, '
                    result_msg += f'test={test_scores[scorer_name]:.3f})'
            else:
                result_msg += ', score='
                if return_train_score:
                    result_msg += f'(train={train_scores:.3f}, test={test_scores:.3f})'
                else:
                    result_msg += f'{test_scores:.3f}'
        result_msg += f' total time={logger.short_format_time(total_time)}'
        end_msg += '.' * (80 - len(end_msg) - len(result_msg))
        end_msg += result_msg
        print(end_msg)
    result['test_scores'] = test_scores
    if return_train_score:
        result['train_scores'] = train_scores
    if return_n_test_samples:
        result['n_test_samples'] = _num_samples(X_test)
    if return_times:
        result['fit_time'] = fit_time
        result['score_time'] = score_time
    if return_parameters:
        result['parameters'] = parameters
    if return_estimator:
        result['estimator'] = estimator
    return result

def _score(estimator, X_test, y_test, scorer, score_params, error_score='raise'):
    score_params = {} if score_params is None else score_params
    try:
        if y_test is None:
            scores = scorer(estimator, X_test, **score_params)
        else:
            scores = scorer(estimator, X_test, y_test, **score_params)
    except Exception:
        if isinstance(scorer, _MultimetricScorer):
            raise
        elif error_score == 'raise':
            raise
        else:
            scores = error_score
            warnings.warn(f'Scoring failed. The score on this train-test partition for these parameters will be set to {error_score}. Details: \n{format_exc()}', UserWarning)
    if isinstance(scorer, _MultimetricScorer):
        exception_messages = [(name, str_e) for name, str_e in scores.items() if isinstance(str_e, str)]
        if exception_messages:
            for name, str_e in exception_messages:
                scores[name] = error_score
                warnings.warn(f'Scoring failed. The score on this train-test partition for these parameters will be set to {error_score}. Details: \n{str_e}', UserWarning)
    error_msg = 'scoring must return a number, got %s (%s) instead. (scorer=%s)'
    if isinstance(scores, dict):
        for name, score in scores.items():
            if hasattr(score, 'item'):
                with suppress(ValueError):
                    score = score.item()
            if not isinstance(score, numbers.Number):
                raise ValueError(error_msg % (score, type(score), name))
            scores[name] = score
    else:
        if hasattr(scores, 'item'):
            with suppress(ValueError):
                scores = scores.item()
        if not isinstance(scores, numbers.Number):
            raise ValueError(error_msg % (scores, type(scores), scorer))
    return scores

@validate_params({'estimator': [HasMethods(['fit', 'predict'])], 'X': ['array-like', 'sparse matrix'], 'y': ['array-like', 'sparse matrix', None], 'groups': ['array-like', None], 'cv': ['cv_object'], 'n_jobs': [Integral, None], 'verbose': ['verbose'], 'params': [dict, None], 'pre_dispatch': [Integral, str, None], 'method': [StrOptions({'predict', 'predict_proba', 'predict_log_proba', 'decision_function'})]}, prefer_skip_nested_validation=False)
def cross_val_predict(estimator, X, y=None, *, groups=None, cv=None, n_jobs=None, verbose=0, params=None, pre_dispatch='2*n_jobs', method='predict'):
    _check_groups_routing_disabled(groups)
    X, y = indexable(X, y)
    params = {} if params is None else params
    if _routing_enabled():
        router = MetadataRouter(owner='cross_val_predict').add(splitter=cv, method_mapping=MethodMapping().add(caller='fit', callee='split')).add(estimator=estimator, method_mapping=MethodMapping().add(caller='fit', callee='fit'))
        try:
            routed_params = process_routing(router, 'fit', **params)
        except UnsetMetadataPassedError as e:
            raise UnsetMetadataPassedError(message=str(e).replace('cross_val_predict.fit', 'cross_val_predict'), unrequested_params=e.unrequested_params, routed_params=e.routed_params)
    else:
        routed_params = _manual_routing({'splitter': {'split': {'groups': groups}}, 'estimator': {'fit': params}})
    cv = check_cv(cv, y, classifier=is_classifier(estimator))
    splits = list(cv.split(X, y, **routed_params.splitter.split))
    test_indices = np.concatenate([test for _, test in splits])
    if not _check_is_permutation(test_indices, _num_samples(X)):
        raise ValueError('cross_val_predict only works for partitions')
    encode = method in ['decision_function', 'predict_proba', 'predict_log_proba'] and y is not None
    xp, is_array_api, device_ = get_namespace_and_device(X)
    xp_y, _ = get_namespace(y)
    if encode:
        y = xp_y.asarray(y)
        if y.ndim == 1:
            le = LabelEncoder()
            y = le.fit_transform(y)
        elif y.ndim == 2:
            y_enc = np.zeros_like(y, dtype=int)
            for i_label in range(y.shape[1]):
                y_enc[:, i_label] = LabelEncoder().fit_transform(y[:, i_label])
            y = y_enc
    y = move_to(y, xp=xp, device=device_)
    parallel = Parallel(n_jobs=n_jobs, verbose=verbose, pre_dispatch=pre_dispatch)
    predictions = parallel((delayed(_fit_and_predict)(clone(estimator), X, y, train, test, routed_params.estimator.fit, method) for train, test in splits))
    inv_test_indices = np.empty(len(test_indices), dtype=int)
    inv_test_indices[test_indices] = np.arange(len(test_indices))
    if sp.issparse(predictions[0]):
        predictions = sp.vstack(predictions, format=predictions[0].format)
    elif encode and isinstance(predictions[0], list):
        n_labels = y.shape[1]
        concat_pred = []
        for i_label in range(n_labels):
            label_preds = np.concatenate([p[i_label] for p in predictions])
            concat_pred.append(label_preds)
        predictions = concat_pred
    else:
        inv_test_indices = xp.asarray(inv_test_indices, device=device(X))
        predictions = xp.concat(predictions)
    if isinstance(predictions, list):
        return [p[inv_test_indices] for p in predictions]
    elif is_array_api:
        return xp.take(predictions, inv_test_indices, axis=0)
    else:
        return predictions[inv_test_indices]

def _fit_and_predict(estimator, X, y, train, test, fit_params, method):
    fit_params = fit_params if fit_params is not None else {}
    fit_params = _check_method_params(X, params=fit_params, indices=train)
    X_train, y_train = _safe_split(estimator, X, y, train)
    X_test, _ = _safe_split(estimator, X, y, test, train)
    if y_train is None:
        estimator.fit(X_train, **fit_params)
    else:
        estimator.fit(X_train, y_train, **fit_params)
    func = getattr(estimator, method)
    predictions = func(X_test)
    encode = method in ['decision_function', 'predict_proba', 'predict_log_proba'] and y is not None
    if encode:
        if isinstance(predictions, list):
            predictions = [_enforce_prediction_order(estimator.classes_[i_label], predictions[i_label], n_classes=len(set(y[:, i_label])), method=method) for i_label in range(len(predictions))]
        else:
            xp, _ = get_namespace(X, y)
            n_classes = len(set(move_to(y, xp=np, device='cpu'))) if y.ndim == 1 else y.shape[1]
            predictions = _enforce_prediction_order(estimator.classes_, predictions, n_classes, method)
    return predictions

def _enforce_prediction_order(classes, predictions, n_classes, method):
    xp, _ = get_namespace(predictions, classes)
    classes_length = classes.shape[0]
    if n_classes != classes_length:
        recommendation = 'To fix this, use a cross-validation technique resulting in properly stratified folds'
        warnings.warn('Number of classes in training fold ({}) does not match total number of classes ({}). Results may not be appropriate for your use case. {}'.format(classes_length, n_classes, recommendation), RuntimeWarning)
        if method == 'decision_function':
            if predictions.ndim == 2 and predictions.shape[1] != classes_length:
                raise ValueError('Output shape {} of {} does not match number of classes ({}) in fold. Irregular decision_function outputs are not currently supported by cross_val_predict'.format(predictions.shape, method, classes_length))
            if classes_length <= 2:
                raise ValueError('Only {} class/es in training fold, but {} in overall dataset. This is not supported for decision_function with imbalanced folds. {}'.format(classes_length, n_classes, recommendation))
        float_min = xp.finfo(predictions.dtype).min
        default_values = {'decision_function': float_min, 'predict_log_proba': float_min, 'predict_proba': 0}
        predictions_for_all_classes = xp.full((_num_samples(predictions), n_classes), default_values[method], dtype=predictions.dtype)
        predictions_for_all_classes[:, classes] = predictions
        predictions = predictions_for_all_classes
    return predictions

def _check_is_permutation(indices, n_samples):
    if len(indices) != n_samples:
        return False
    hit = np.zeros(n_samples, dtype=bool)
    hit[indices] = True
    if not np.all(hit):
        return False
    return True

@validate_params({'estimator': [HasMethods('fit')], 'X': ['array-like', 'sparse matrix'], 'y': ['array-like', None], 'groups': ['array-like', None], 'cv': ['cv_object'], 'n_permutations': [Interval(Integral, 1, None, closed='left')], 'n_jobs': [Integral, None], 'random_state': ['random_state'], 'verbose': ['verbose'], 'scoring': [StrOptions(set(get_scorer_names())), callable, None], 'params': [dict, None]}, prefer_skip_nested_validation=False)
def permutation_test_score(estimator, X, y, *, groups=None, cv=None, n_permutations=100, n_jobs=None, random_state=0, verbose=0, scoring=None, params=None):
    _check_groups_routing_disabled(groups)
    params = {} if params is None else params
    X, y, groups = indexable(X, y, groups)
    cv = check_cv(cv, y, classifier=is_classifier(estimator))
    scorer = check_scoring(estimator, scoring=scoring)
    random_state = check_random_state(random_state)
    if _routing_enabled():
        router = MetadataRouter(owner='permutation_test_score').add(estimator=estimator, method_mapping=MethodMapping().add(caller='fit', callee='fit')).add(splitter=cv, method_mapping=MethodMapping().add(caller='fit', callee='split')).add(scorer=scorer, method_mapping=MethodMapping().add(caller='fit', callee='score'))
        try:
            routed_params = process_routing(router, 'fit', **params)
        except UnsetMetadataPassedError as e:
            raise UnsetMetadataPassedError(message=str(e).replace('permutation_test_score.fit', 'permutation_test_score'), unrequested_params=e.unrequested_params, routed_params=e.routed_params)
    else:
        routed_params = _manual_routing({'estimator': {'fit': params}, 'splitter': {'split': {'groups': groups}}, 'scorer': {}})
    score = _permutation_test_score(clone(estimator), X, y, cv, scorer, split_params=routed_params.splitter.split, fit_params=routed_params.estimator.fit, score_params=routed_params.scorer.score)
    permutation_scores = Parallel(n_jobs=n_jobs, verbose=verbose)((delayed(_permutation_test_score)(clone(estimator), X, _shuffle(y, groups, random_state), cv, scorer, split_params=routed_params.splitter.split, fit_params=routed_params.estimator.fit, score_params=routed_params.scorer.score) for _ in range(n_permutations)))
    permutation_scores = np.array(permutation_scores)
    pvalue = (np.sum(permutation_scores >= score) + 1.0) / (n_permutations + 1)
    return (score, permutation_scores, pvalue)

def _permutation_test_score(estimator, X, y, cv, scorer, split_params, fit_params, score_params):
    fit_params = fit_params if fit_params is not None else {}
    score_params = score_params if score_params is not None else {}
    avg_score = []
    for train, test in cv.split(X, y, **split_params):
        X_train, y_train = _safe_split(estimator, X, y, train)
        X_test, y_test = _safe_split(estimator, X, y, test, train)
        fit_params_train = _check_method_params(X, params=fit_params, indices=train)
        score_params_test = _check_method_params(X, params=score_params, indices=test)
        estimator.fit(X_train, y_train, **fit_params_train)
        avg_score.append(scorer(estimator, X_test, y_test, **score_params_test))
    return np.mean(avg_score)

def _shuffle(y, groups, random_state):
    if groups is None:
        indices = random_state.permutation(len(y))
    else:
        indices = np.arange(len(groups))
        for group in np.unique(groups):
            this_mask = groups == group
            indices[this_mask] = random_state.permutation(indices[this_mask])
    return _safe_indexing(y, indices)

@validate_params({'estimator': [HasMethods(['fit'])], 'X': ['array-like', 'sparse matrix'], 'y': ['array-like', None], 'groups': ['array-like', None], 'train_sizes': ['array-like'], 'cv': ['cv_object'], 'scoring': [StrOptions(set(get_scorer_names())), callable, None], 'exploit_incremental_learning': ['boolean'], 'n_jobs': [Integral, None], 'pre_dispatch': [Integral, str], 'verbose': ['verbose'], 'shuffle': ['boolean'], 'random_state': ['random_state'], 'error_score': [StrOptions({'raise'}), Real], 'return_times': ['boolean'], 'params': [dict, None]}, prefer_skip_nested_validation=False)
def learning_curve(estimator, X, y, *, groups=None, train_sizes=np.linspace(0.1, 1.0, 5), cv=None, scoring=None, exploit_incremental_learning=False, n_jobs=None, pre_dispatch='all', verbose=0, shuffle=False, random_state=None, error_score=np.nan, return_times=False, params=None):
    if exploit_incremental_learning and (not hasattr(estimator, 'partial_fit')):
        raise ValueError('An estimator must support the partial_fit interface to exploit incremental learning')
    _check_groups_routing_disabled(groups)
    params = {} if params is None else params
    X, y, groups = indexable(X, y, groups)
    cv = check_cv(cv, y, classifier=is_classifier(estimator))
    scorer = check_scoring(estimator, scoring=scoring)
    if _routing_enabled():
        router = MetadataRouter(owner='learning_curve').add(estimator=estimator, method_mapping=MethodMapping().add(caller='fit', callee='fit').add(caller='fit', callee='partial_fit')).add(splitter=cv, method_mapping=MethodMapping().add(caller='fit', callee='split')).add(scorer=scorer, method_mapping=MethodMapping().add(caller='fit', callee='score'))
        try:
            routed_params = process_routing(router, 'fit', **params)
        except UnsetMetadataPassedError as e:
            raise UnsetMetadataPassedError(message=str(e).replace('learning_curve.fit', 'learning_curve'), unrequested_params=e.unrequested_params, routed_params=e.routed_params)
    else:
        routed_params = _manual_routing({'estimator': {'fit': params, 'partial_fit': params}, 'splitter': {'split': {'groups': groups}}, 'scorer': {}})
    cv_iter = list(cv.split(X, y, **routed_params.splitter.split))
    n_max_training_samples = len(cv_iter[0][0])
    train_sizes_abs = _translate_train_sizes(train_sizes, n_max_training_samples)
    n_unique_ticks = train_sizes_abs.shape[0]
    if verbose > 0:
        print('[learning_curve] Training set sizes: ' + str(train_sizes_abs))
    parallel = Parallel(n_jobs=n_jobs, pre_dispatch=pre_dispatch, verbose=verbose)
    if shuffle:
        rng = check_random_state(random_state)
        cv_iter = ((rng.permutation(train), test) for train, test in cv_iter)
    if exploit_incremental_learning:
        classes = np.unique(y) if is_classifier(estimator) else None
        out = parallel((delayed(_incremental_fit_estimator)(clone(estimator), X, y, classes, train, test, train_sizes_abs, scorer, return_times, error_score=error_score, fit_params=routed_params.estimator.partial_fit, score_params=routed_params.scorer.score) for train, test in cv_iter))
        out = np.asarray(out).transpose((2, 1, 0))
    else:
        train_test_proportions = []
        for train, test in cv_iter:
            for n_train_samples in train_sizes_abs:
                train_test_proportions.append((train[:n_train_samples], test))
        results = parallel((delayed(_fit_and_score)(clone(estimator), X, y, scorer=scorer, train=train, test=test, verbose=verbose, parameters=None, fit_params=routed_params.estimator.fit, score_params=routed_params.scorer.score, return_train_score=True, error_score=error_score, return_times=return_times) for train, test in train_test_proportions))
        _warn_or_raise_about_fit_failures(results, error_score)
        results = _aggregate_score_dicts(results)
        train_scores = results['train_scores'].reshape(-1, n_unique_ticks).T
        test_scores = results['test_scores'].reshape(-1, n_unique_ticks).T
        out = [train_scores, test_scores]
        if return_times:
            fit_times = results['fit_time'].reshape(-1, n_unique_ticks).T
            score_times = results['score_time'].reshape(-1, n_unique_ticks).T
            out.extend([fit_times, score_times])
    ret = (train_sizes_abs, out[0], out[1])
    if return_times:
        ret = ret + (out[2], out[3])
    return ret

def _translate_train_sizes(train_sizes, n_max_training_samples):
    train_sizes_abs = np.asarray(train_sizes)
    n_ticks = train_sizes_abs.shape[0]
    n_min_required_samples = np.min(train_sizes_abs)
    n_max_required_samples = np.max(train_sizes_abs)
    if np.issubdtype(train_sizes_abs.dtype, np.floating):
        if n_min_required_samples <= 0.0 or n_max_required_samples > 1.0:
            raise ValueError('train_sizes has been interpreted as fractions of the maximum number of training samples and must be within (0, 1], but is within [%f, %f].' % (n_min_required_samples, n_max_required_samples))
        train_sizes_abs = (train_sizes_abs * n_max_training_samples).astype(dtype=int, copy=False)
        train_sizes_abs = np.clip(train_sizes_abs, 1, n_max_training_samples)
    elif n_min_required_samples <= 0 or n_max_required_samples > n_max_training_samples:
        raise ValueError('train_sizes has been interpreted as absolute numbers of training samples and must be within (0, %d], but is within [%d, %d].' % (n_max_training_samples, n_min_required_samples, n_max_required_samples))
    train_sizes_abs = np.unique(train_sizes_abs)
    if n_ticks > train_sizes_abs.shape[0]:
        warnings.warn("Removed duplicate entries from 'train_sizes'. Number of ticks will be less than the size of 'train_sizes': %d instead of %d." % (train_sizes_abs.shape[0], n_ticks), RuntimeWarning)
    return train_sizes_abs

@validate_params({'estimator': [HasMethods(['fit'])], 'X': ['array-like', 'sparse matrix'], 'y': ['array-like', None], 'param_name': [str], 'param_range': ['array-like'], 'groups': ['array-like', None], 'cv': ['cv_object'], 'scoring': [StrOptions(set(get_scorer_names())), callable, None], 'n_jobs': [Integral, None], 'pre_dispatch': [Integral, str], 'verbose': ['verbose'], 'error_score': [StrOptions({'raise'}), Real], 'params': [dict, None]}, prefer_skip_nested_validation=False)
