def inspect(subject: Any, raiseerr: bool=True) -> Any:
    type_ = type(subject)
    for cls in type_.__mro__:
        if cls in _registrars:
            reg = _registrars.get(cls, None)
            if reg is None:
                continue
            elif reg is True:
                return subject
            ret = reg(subject)
            if ret is not None:
                return ret
    else:
        reg = ret = None
    if raiseerr and (reg is None or ret is None):
        raise exc.NoInspectionAvailable('No inspection system is available for object of type %s' % type_)
    return ret

def exception(self, msg: str, *args: Any, **kwargs: Any) -> None:
    kwargs['exc_info'] = 1
    self.log(logging.ERROR, msg, *args, **kwargs)

def log(self, level: int, msg: str, *args: Any, **kwargs: Any) -> None:
    if self.logger.manager.disable >= level:
        return
    selected_level = self._echo_map[self.echo]
    if selected_level == logging.NOTSET:
        selected_level = self.logger.getEffectiveLevel()
    if level >= selected_level:
        if STACKLEVEL:
            kwargs['stacklevel'] = kwargs.get('stacklevel', 1) + STACKLEVEL_OFFSET
        self.logger._log(level, msg, args, **kwargs)

def isEnabledFor(self, level: int) -> bool:
    if self.logger.manager.disable >= level:
        return False
    return level >= self.getEffectiveLevel()

def getEffectiveLevel(self) -> int:
    level = self._echo_map[self.echo]
    if level == logging.NOTSET:
        level = self.logger.getEffectiveLevel()
    return level

def instance_logger(instance: Identified, echoflag: _EchoFlagType=None) -> None:
    if instance.logging_name:
        name = '%s.%s' % (_qual_logger_name_for_cls(instance.__class__), instance.logging_name)
    else:
        name = _qual_logger_name_for_cls(instance.__class__)
    instance._echo = echoflag
    logger: Union[logging.Logger, InstanceLogger]
    if echoflag in (False, None):
        logger = logging.getLogger(name)
    else:
        logger = InstanceLogger(echoflag, name)
    instance.logger = logger

