def _extend(self, spec, type_, length=None):
    if getattr(type_, 'collation', None):
        collation = 'COLLATE %s' % type_.collation
    else:
        collation = None
    if not length:
        length = type_.length
    if length:
        spec = spec + '(%s)' % length
    return ' '.join([c for c in (spec, collation) if c is not None])

def pre_exec(self):
    if self.isinsert:
        if TYPE_CHECKING:
            assert is_sql_compiler(self.compiled)
            assert isinstance(self.compiled.compile_state, DMLState)
            assert isinstance(self.compiled.compile_state.dml_table, TableClause)
        tbl = self.compiled.compile_state.dml_table
        id_column = tbl._autoincrement_column
        if id_column is not None and (not isinstance(id_column.default, Sequence)):
            insert_has_identity = True
            compile_state = self.compiled.dml_compile_state
            self._enable_identity_insert = id_column.key in self.compiled_parameters[0] or (compile_state._dict_parameters and id_column.key in compile_state._insert_col_keys)
        else:
            insert_has_identity = False
            self._enable_identity_insert = False
        self._select_lastrowid = not self.compiled.inline and insert_has_identity and (not self.compiled.effective_returning) and (not self._enable_identity_insert) and (not self.executemany)
        if self._enable_identity_insert:
            self.root_connection._cursor_execute(self.cursor, self._opt_encode('SET IDENTITY_INSERT %s ON' % self.identifier_preparer.format_table(tbl)), (), self)
        if self._select_lastrowid and self.dialect.scope_identity_must_be_embedded and self.dialect.use_scope_identity and len(self.parameters[0]):
            self._embedded_scope_identity = True
            self.statement += '; select scope_identity()'

def get_select_precolumns(self, select, **kw):
    s = super().get_select_precolumns(select, **kw)
    if select._has_row_limiting_clause and self._use_top(select):
        kw['literal_execute'] = True
        s += 'TOP %s ' % self.process(self._get_limit_or_fetch(select), **kw)
        if select._fetch_clause is not None:
            if select._fetch_clause_options['percent']:
                s += 'PERCENT '
            if select._fetch_clause_options['with_ties']:
                s += 'WITH TIES '
    return s

def _row_limit_clause(self, select, **kw):
    if self.dialect._supports_offset_fetch and (not self._use_top(select)):
        self._check_can_use_fetch_limit(select)
        return self.fetch_clause(select, fetch_clause=self._get_limit_or_fetch(select), require_offset=True, **kw)
    else:
        return ''

def visit_binary(self, binary, **kwargs):
    if isinstance(binary.left, expression.BindParameter) and binary.operator == operator.eq and (not isinstance(binary.right, expression.BindParameter)):
        return self.process(expression.BinaryExpression(binary.right, binary.left, binary.operator), **kwargs)
    return super().visit_binary(binary, **kwargs)

