    return result

def _partition_filter_names(self, connection, owner, filter_names, scope, kind):
    include_default = scope is not ObjectScope.TEMPORARY
    include_temp = scope is not ObjectScope.DEFAULT and ObjectKind.TABLE in kind
    if filter_names:
        if include_temp:
            temp_names = [n for n in filter_names if n.startswith('#')]
        else:
            temp_names = []
        if include_default:
            regular_names = [n for n in filter_names if not n.startswith('#')]
            run_bulk = bool(regular_names)
        else:
            regular_names = []
            run_bulk = False
    else:
        temp_names = []
        regular_names = []
        run_bulk = include_default
    if not run_bulk:
        return (regular_names, [], temp_names)
    type_filter = []
    if ObjectKind.TABLE in kind:
        type_filter.append("'U'")
    if ObjectKind.VIEW in kind:
        type_filter.append("'V'")
    if not type_filter:
        return (regular_names, [], temp_names)
    query = 'SELECT o.name FROM sys.objects o JOIN sys.schemas s ON o.schema_id = s.schema_id WHERE s.name = :owner AND o.type IN (%s)' % ', '.join(type_filter)
    params = [sql.bindparam('owner', owner, ischema.CoerceUnicode())]
    if regular_names:
        query += ' AND o.name IN :filter_names'
        params.append(sql.bindparam('filter_names', regular_names, expanding=True))
    rp = connection.execute(sql.text(query).bindparams(*params))
    multi_object_names = [row[0] for row in rp]
    return (regular_names, multi_object_names, temp_names)

@staticmethod
