def delete_extra_from_clause(self, delete_stmt: Delete, from_table: _DMLTableElement, extra_froms: list[selectable.FromClause], from_hints: Any, **kw: Any) -> str:
    kw['asfrom'] = True
    if any((from_table in elem._cloned_set for extra_from in extra_froms for elem in sql_util.surface_selectables_only(extra_from))):
        froms = extra_froms
    else:
        froms = [from_table] + extra_froms
    return 'USING ' + ', '.join((t._compiler_dispatch(self, fromhints=from_hints, **kw) for t in froms))

def post_create_table(self, table: sa_schema.Table) -> str:
    table_opts = []
    opts = {k[len(self.dialect.name) + 1:].upper(): v for k, v in table.kwargs.items() if k.startswith('%s_' % self.dialect.name)}
    if table.comment is not None:
        opts['COMMENT'] = table.comment
    partition_options = ['PARTITION_BY', 'PARTITIONS', 'SUBPARTITIONS', 'SUBPARTITION_BY']
    nonpart_options = set(opts).difference(partition_options)
    part_options = set(opts).intersection(partition_options)
    for opt in topological.sort([('DEFAULT_CHARSET', 'COLLATE'), ('DEFAULT_CHARACTER_SET', 'COLLATE'), ('CHARSET', 'COLLATE'), ('CHARACTER_SET', 'COLLATE')], nonpart_options):
        arg = opts[opt]
        if opt in _reflection._options_of_type_string:
            arg = self.sql_compiler.render_literal_value(arg, sqltypes.String())
        if opt in ('DATA_DIRECTORY', 'INDEX_DIRECTORY', 'DEFAULT_CHARACTER_SET', 'CHARACTER_SET', 'DEFAULT_CHARSET', 'DEFAULT_COLLATE'):
            opt = opt.replace('_', ' ')
        joiner = '='
        if opt in ('TABLESPACE', 'DEFAULT CHARACTER SET', 'CHARACTER SET', 'COLLATE'):
            joiner = ' '
        table_opts.append(joiner.join((opt, arg)))
    for opt in topological.sort([('PARTITION_BY', 'PARTITIONS'), ('PARTITION_BY', 'SUBPARTITION_BY'), ('PARTITION_BY', 'SUBPARTITIONS'), ('PARTITIONS', 'SUBPARTITIONS'), ('PARTITIONS', 'SUBPARTITION_BY'), ('SUBPARTITION_BY', 'SUBPARTITIONS')], part_options):
        arg = opts[opt]
        if opt in _reflection._options_of_type_string:
            arg = self.sql_compiler.render_literal_value(arg, sqltypes.String())
        opt = opt.replace('_', ' ')
        joiner = ' '
        table_opts.append(joiner.join((opt, arg)))
    return ' '.join(table_opts)

def _extend_numeric(self, type_: _NumericCommonType, spec: str) -> str:
    if not self._mysql_type(type_):
        return spec
    if type_.unsigned:
        spec += ' UNSIGNED'
    if type_.zerofill:
        spec += ' ZEROFILL'
    return spec

def _extend_string(self, type_: _StringType, defaults: dict[str, Any], spec: str) -> str:

    def attr(name: str) -> Any:
        return getattr(type_, name, defaults.get(name))
    if attr('charset'):
        charset = 'CHARACTER SET %s' % attr('charset')
    elif attr('ascii'):
        charset = 'ASCII'
    elif attr('unicode'):
        charset = 'UNICODE'
    else:
        charset = None
    if attr('collation'):
        collation = 'COLLATE %s' % type_.collation
    elif attr('binary'):
        collation = 'BINARY'
    else:
        collation = None
    if attr('national'):
        return ' '.join([c for c in ('NATIONAL', spec, collation) if c is not None])
    return ' '.join([c for c in (spec, charset, collation) if c is not None])

