def _detect_ansiquotes(self, connection: Connection) -> None:
    mode = self._sql_mode
    if not mode:
        mode = ''
    elif mode.isdigit():
        mode_no = int(mode)
        mode = mode_no | 4 == mode_no and 'ANSI_QUOTES' or ''
    self._server_ansiquotes = 'ANSI_QUOTES' in mode
    self._backslash_escapes = 'NO_BACKSLASH_ESCAPES' not in mode

def _show_create_table(self, connection: Connection, table: Optional[Table], charset: Optional[str]=None, full_name: Optional[str]=None) -> str:
    if full_name is None:
        assert table is not None
        full_name = self.identifier_preparer.format_table(table)
    st = 'SHOW CREATE TABLE %s' % full_name
    try:
        rp = connection.execution_options(skip_user_error_events=True).exec_driver_sql(st)
    except exc.DBAPIError as e:
        if self._extract_error_code(e.orig) == 1146:
            raise exc.NoSuchTableError(full_name) from e
        else:
            raise
    row = self._compat_first(rp, charset=charset)
    if not row:
        raise exc.NoSuchTableError(full_name)
    return cast(str, row[1]).strip()

def _describe_table(self, connection: Connection, table: Optional[Table], charset: Optional[str]=None, full_name: Optional[str]=None) -> Union[Sequence[Row[Unpack[TupleAny]]], Sequence[_DecodingRow]]:
    if full_name is None:
        assert table is not None
        full_name = self.identifier_preparer.format_table(table)
    st = 'DESCRIBE %s' % full_name
    rp, rows = (None, None)
    try:
        try:
            rp = connection.execution_options(skip_user_error_events=True).exec_driver_sql(st)
        except exc.DBAPIError as e:
            code = self._extract_error_code(e.orig)
            if code == 1146:
                raise exc.NoSuchTableError(full_name) from e
            elif code == 1356:
                raise exc.UnreflectableTableError('Table or view named %s could not be reflected: %s' % (full_name, e)) from e
            else:
                raise
        rows = self._compat_fetchall(rp, charset=charset)
    finally:
        if rp:
            rp.close()
    return rows

def result_processor(self, dialect: Dialect, coltype: object) -> Optional[_ResultProcessorType[Any]]:

    def process(value: Optional[Iterable[int]]) -> Optional[int]:
        if value is not None:
            v = 0
            for i in iter(value):
                v = v << 8 | i
            return v
        return value
    return process

