def __init__(self, *values: str, **kw: Any):
    self.retrieve_as_bitwise = kw.pop('retrieve_as_bitwise', False)
    self.values = tuple(values)
    if not self.retrieve_as_bitwise and '' in values:
        raise exc.ArgumentError("Can't use the blank value '' in a SET without setting retrieve_as_bitwise=True")
    if self.retrieve_as_bitwise:
        self._inversed_bitmap: dict[str, int] = {value: 2 ** idx for idx, value in enumerate(self.values)}
        self._bitmap: dict[int, str] = {2 ** idx: value for idx, value in enumerate(self.values)}
    length = max([len(v) for v in values] + [0])
    kw.setdefault('length', length)
    super().__init__(**kw)

