def _parse_error(hstore_str: str, pos: int) -> str:
    ctx = 20
    hslen = len(hstore_str)
    parsed_tail = hstore_str[max(pos - ctx - 1, 0):min(pos, hslen)]
    residual = hstore_str[min(pos, hslen):min(pos + ctx + 1, hslen)]
    if len(parsed_tail) > ctx:
        parsed_tail = '[...]' + parsed_tail[1:]
    if len(residual) > ctx:
        residual = residual[:-1] + '[...]'
    return 'After %r, could not parse residual at position %d: %r' % (parsed_tail, pos, residual)

def _parse_hstore(hstore_str: str) -> _HSTORE_VAL:
    result: _HSTORE_VAL = {}
    pos = 0
    pair_match = HSTORE_PAIR_RE.match(hstore_str)
    while pair_match is not None:
        key = pair_match.group('key').replace('\\"', '"').replace('\\\\', '\\')
        if pair_match.group('value_null'):
            value = None
        else:
            value = pair_match.group('value').replace('\\"', '"').replace('\\\\', '\\')
        result[key] = value
        pos += pair_match.end()
        delim_match = HSTORE_DELIMITER_RE.match(hstore_str[pos:])
        if delim_match is not None:
            pos += delim_match.end()
        pair_match = HSTORE_PAIR_RE.match(hstore_str[pos:])
    if pos != len(hstore_str):
        raise ValueError(_parse_error(hstore_str, pos))
    return result

def _serialize_hstore(val: _HSTORE_VAL) -> str:

    def esc(s: Optional[str], position: str) -> str:
        if position == 'value' and s is None:
            return 'NULL'
        elif isinstance(s, str):
            return '"%s"' % s.replace('\\', '\\\\').replace('"', '\\"')
        else:
            raise ValueError('%r in %s position is not a string.' % (s, position))
    return ', '.join(('%s=>%s' % (esc(k, 'key'), esc(v, 'value')) for k, v in val.items()))

