@prepare_for_drop_tables.for_db('postgresql')
def prepare_for_drop_tables(config, connection):
    result = connection.exec_driver_sql("select pid, state, wait_event_type, query from pg_stat_activity where usename=current_user and datname=current_database() and state='idle in transaction' and pid != pg_backend_pid()")
    rows = result.all()
    if rows:
        warn_test_suite('PostgreSQL may not be able to DROP tables due to idle in transaction: %s' % '; '.join((row._mapping['query'] for row in rows)))

@property
def isempty(self) -> bool:
    return self.empty

@property
def is_empty(self) -> bool:
    return self.empty

@property
def lower_inc(self) -> bool:
    return self.bounds[0] == '['

@property
def lower_inf(self) -> bool:
    return not self.empty and self.lower is None

@property
def upper_inc(self) -> bool:
    return self.bounds[1] == ']'

@property
def upper_inf(self) -> bool:
    return not self.empty and self.upper is None

def _contains_value(self, value: _T) -> bool:
    if self.empty:
        return False
    if self.lower is None:
        return self.upper is None or (value < self.upper if self.bounds[1] == ')' else value <= self.upper)
    if self.upper is None:
        return value > self.lower if self.bounds[0] == '(' else value >= self.lower
    return (value > self.lower if self.bounds[0] == '(' else value >= self.lower) and (value < self.upper if self.bounds[1] == ')' else value <= self.upper)

def _get_discrete_step(self) -> Any:
    if isinstance(self.lower, int) or isinstance(self.upper, int):
        return 1
    elif isinstance(self.lower, datetime) or isinstance(self.upper, datetime):
        return None
    elif isinstance(self.lower, date) or isinstance(self.upper, date):
        return timedelta(days=1)
    else:
        return None

def _compare_edges(self, value1: Optional[_T], bound1: str, value2: Optional[_T], bound2: str, only_values: bool=False) -> int:
    value1_is_lower_bound = bound1 in {'[', '('}
    value2_is_lower_bound = bound2 in {'[', '('}
    if value1 is value2 is None:
        if value1_is_lower_bound == value2_is_lower_bound:
            return 0
        else:
            return -1 if value1_is_lower_bound else 1
    elif value1 is None:
        return -1 if value1_is_lower_bound else 1
    elif value2 is None:
        return 1 if value2_is_lower_bound else -1
    if bound1 == bound2 and value1 == value2:
        return 0
    value1_inc = bound1 in {'[', ']'}
    value2_inc = bound2 in {'[', ']'}
    step = self._get_discrete_step()
    if step is not None:
        if value1_is_lower_bound:
            if not value1_inc:
                value1 += step
                value1_inc = True
        elif value1_inc:
            value1 += step
            value1_inc = False
        if value2_is_lower_bound:
            if not value2_inc:
                value2 += step
                value2_inc = True
        elif value2_inc:
            value2 += step
            value2_inc = False
    if value1 < value2:
        return -1
    elif value1 > value2:
        return 1
    elif only_values:
        return 0
    elif value1_inc and value2_inc:
        return 0
    elif not value1_inc and (not value2_inc):
        if value1_is_lower_bound == value2_is_lower_bound:
            return 0
        else:
            return 1 if value1_is_lower_bound else -1
    elif not value1_inc:
        return 1 if value1_is_lower_bound else -1
    elif not value2_inc:
        return -1 if value2_is_lower_bound else 1
    else:
        return 0

def contains(self, value: Union[_T, Range[_T]]) -> bool:
    if isinstance(value, Range):
        return value.contained_by(self)
    else:
        return self._contains_value(value)

def _upper_edge_adjacent_to_lower(self, value1: Optional[_T], bound1: str, value2: Optional[_T], bound2: str) -> bool:
    res = self._compare_edges(value1, bound1, value2, bound2, True)
    if res == -1:
        step = self._get_discrete_step()
        if step is None:
            return False
        if bound1 == ']':
            if bound2 == '[':
                return value1 == value2 - step
            else:
                return value1 == value2
        elif bound2 == '[':
            return value1 == value2
        else:
            return value1 == value2 - step
    elif res == 0:
        if bound1 == ']' and bound2 == '[' or (bound1 == ')' and bound2 == '('):
            step = self._get_discrete_step()
            if step is not None:
                return True
        return bound1 == ')' and bound2 == '[' or (bound1 == ']' and bound2 == '(')
    else:
        return False

def union(self, other: Range[_T]) -> Range[_T]:
    if self.empty:
        return other
    if other.empty:
        return self
    if not self.overlaps(other) and (not self.adjacent_to(other)):
        raise ValueError('Adding non-overlapping and non-adjacent ranges is not implemented')
    slower = self.lower
    slower_b = self.bounds[0]
    supper = self.upper
    supper_b = self.bounds[1]
    olower = other.lower
    olower_b = other.bounds[0]
    oupper = other.upper
    oupper_b = other.bounds[1]
    if self._compare_edges(slower, slower_b, olower, olower_b) < 0:
        rlower = slower
        rlower_b = slower_b
    else:
        rlower = olower
        rlower_b = olower_b
    if self._compare_edges(supper, supper_b, oupper, oupper_b) > 0:
        rupper = supper
        rupper_b = supper_b
    else:
        rupper = oupper
        rupper_b = oupper_b
    return Range(rlower, rupper, bounds=cast(_BoundsType, rlower_b + rupper_b))

def difference(self, other: Range[_T]) -> Range[_T]:
    if self.empty or other.empty:
        return self
    slower = self.lower
    slower_b = self.bounds[0]
    supper = self.upper
    supper_b = self.bounds[1]
    olower = other.lower
    olower_b = other.bounds[0]
    oupper = other.upper
    oupper_b = other.bounds[1]
    sl_vs_ol = self._compare_edges(slower, slower_b, olower, olower_b)
    su_vs_ou = self._compare_edges(supper, supper_b, oupper, oupper_b)
    if sl_vs_ol < 0 and su_vs_ou > 0:
        raise ValueError('Subtracting a strictly inner range is not implemented')
    sl_vs_ou = self._compare_edges(slower, slower_b, oupper, oupper_b)
    su_vs_ol = self._compare_edges(supper, supper_b, olower, olower_b)
    if sl_vs_ou > 0 or su_vs_ol < 0:
        return self
    if sl_vs_ol >= 0 and su_vs_ou <= 0:
        return Range(None, None, empty=True)
    if sl_vs_ol <= 0 and su_vs_ol >= 0 and (su_vs_ou <= 0):
        rupper_b = ')' if olower_b == '[' else ']'
        if slower_b != '[' and rupper_b != ']' and (self._compare_edges(slower, slower_b, olower, rupper_b) == 0):
            return Range(None, None, empty=True)
        else:
            return Range(slower, olower, bounds=cast(_BoundsType, slower_b + rupper_b))
    if sl_vs_ol >= 0 and su_vs_ou >= 0 and (sl_vs_ou <= 0):
        rlower_b = '(' if oupper_b == ']' else '['
        if rlower_b != '[' and supper_b != ']' and (self._compare_edges(oupper, rlower_b, supper, supper_b) == 0):
            return Range(None, None, empty=True)
        else:
            return Range(oupper, supper, bounds=cast(_BoundsType, rlower_b + supper_b))
    assert False, f'Unhandled case computing {self} - {other}'

def intersection(self, other: Range[_T]) -> Range[_T]:
    if self.empty or other.empty or (not self.overlaps(other)):
        return Range(None, None, empty=True)
    slower = self.lower
    slower_b = self.bounds[0]
    supper = self.upper
    supper_b = self.bounds[1]
    olower = other.lower
    olower_b = other.bounds[0]
    oupper = other.upper
    oupper_b = other.bounds[1]
    if self._compare_edges(slower, slower_b, olower, olower_b) < 0:
        rlower = olower
        rlower_b = olower_b
    else:
        rlower = slower
        rlower_b = slower_b
    if self._compare_edges(supper, supper_b, oupper, oupper_b) > 0:
        rupper = oupper
        rupper_b = oupper_b
    else:
        rupper = supper
        rupper_b = supper_b
    return Range(rlower, rupper, bounds=cast(_BoundsType, rlower_b + rupper_b))

def adapt(self, cls: Type[Union[TypeEngine[Any], TypeEngineMixin]], **kw: Any) -> TypeEngine[Any]:
    if issubclass(cls, (AbstractSingleRangeImpl, AbstractMultiRangeImpl)) and cls is not self.__class__:
        visit_name = self.__visit_name__
        return type(f'{visit_name}RangeImpl', (cls, self.__class__), {'__visit_name__': visit_name})()
    else:
        return super().adapt(cls)

