    return engine.pool

def _adapt_to_context(self, context: ExecutionContext) -> Self:
    if not context.compiled or not context.compiled._result_columns:
        return self
    compiled_statement = context.compiled.statement
    invoked_statement = context.invoked_statement
    if TYPE_CHECKING:
        assert isinstance(invoked_statement, elements.ClauseElement)
    if compiled_statement is invoked_statement:
        return self
    assert invoked_statement is not None
    keymap_by_position = self._keymap_by_result_column_idx
    if keymap_by_position is None:
        keymap_by_position = self._keymap_by_result_column_idx = {metadata_entry[MD_RESULT_MAP_INDEX]: metadata_entry for metadata_entry in self._keymap.values()}
    return self._make_new_metadata(keymap=self._keymap | {new: keymap_by_position[idx] for idx, new in enumerate(invoked_statement._all_selected_columns) if idx in keymap_by_position}, unpickled=self._unpickled, processors=self._processors, tuplefilter=self._tuplefilter, translated_indexes=None, keys=self._keys, safe_for_cache=self._safe_for_cache, keymap_by_result_column_idx=self._keymap_by_result_column_idx)

def _merge_cursor_description(self, context: DefaultExecutionContext, cursor_description: _DBAPICursorDescription, result_columns: Sequence[ResultColumnsEntry], num_ctx_cols: int, cols_are_ordered: bool, textual_ordered: bool, ad_hoc_textual: bool, loose_column_name_matching: bool, driver_column_names: bool) -> List[_CursorKeyMapRecType]:
    if num_ctx_cols and cols_are_ordered and (not textual_ordered) and (num_ctx_cols == len(cursor_description)) and (not driver_column_names):
        self._keys = [elem[0] for elem in result_columns]
        self._safe_for_cache = True
        return [(idx, idx, rmap_entry[RM_OBJECTS], rmap_entry[RM_NAME], rmap_entry[RM_RENDERED_NAME], context.get_result_processor(rmap_entry[RM_TYPE], rmap_entry[RM_RENDERED_NAME], cursor_description[idx][1]), None) for idx, rmap_entry in enumerate(result_columns)]
    else:
        if textual_ordered or (ad_hoc_textual and len(cursor_description) == num_ctx_cols):
            self._safe_for_cache = not driver_column_names
            raw_iterator = self._merge_textual_cols_by_position(context, cursor_description, result_columns, driver_column_names)
        elif num_ctx_cols:
            self._safe_for_cache = False
            raw_iterator = self._merge_cols_by_name(context, cursor_description, result_columns, loose_column_name_matching, driver_column_names)
        else:
            self._safe_for_cache = False
            raw_iterator = self._merge_cols_by_none(context, cursor_description, driver_column_names)
        return [(idx, ridx, obj, cursor_colname, cursor_colname, context.get_result_processor(mapped_type, cursor_colname, coltype), untranslated) for idx, ridx, cursor_colname, mapped_type, coltype, obj, untranslated in raw_iterator]

def _colnames_from_description(self, context: DefaultExecutionContext, cursor_description: _DBAPICursorDescription, driver_column_names: bool) -> Iterator[Tuple[int, str, str, Optional[str], DBAPIType]]:
    dialect = context.dialect
    translate_colname = context._translate_colname
    normalize_name = dialect.normalize_name if dialect.requires_name_normalize else None
    untranslated = None
    for idx, rec in enumerate(cursor_description):
        colname = unnormalized = rec[0]
        coltype = rec[1]
        if translate_colname:
            colname, untranslated = translate_colname(colname)
            assert untranslated is None or untranslated == unnormalized
        if normalize_name:
            colname = normalize_name(colname)
        if driver_column_names:
            yield (idx, colname, unnormalized, unnormalized, coltype)
        else:
            yield (idx, colname, unnormalized, untranslated, coltype)

@classmethod
def _create_description_match_map(cls, result_columns: Sequence[ResultColumnsEntry], loose_column_name_matching: bool=False) -> Dict[Union[str, object], Tuple[str, TupleAny, TypeEngine[Any], int]]:
    d: Dict[Union[str, object], Tuple[str, TupleAny, TypeEngine[Any], int]] = {}
    for ridx, elem in enumerate(result_columns):
        key = elem[RM_RENDERED_NAME]
        if key in d:
            e_name, e_obj, e_type, e_ridx = d[key]
            d[key] = (e_name, e_obj + elem[RM_OBJECTS], e_type, ridx)
        else:
            d[key] = (elem[RM_NAME], elem[RM_OBJECTS], elem[RM_TYPE], ridx)
        if loose_column_name_matching:
            for r_key in elem[RM_OBJECTS]:
                d.setdefault(r_key, (elem[RM_NAME], elem[RM_OBJECTS], elem[RM_TYPE], ridx))
    return d

def _buffer_rows(self, result: CursorResult[Any], dbapi_cursor: DBAPICursor) -> None:
    size = self._bufsize
    try:
        if size < 1:
            new_rows = dbapi_cursor.fetchall()
        else:
            new_rows = dbapi_cursor.fetchmany(size)
    except BaseException as e:
        self.handle_exception(result, dbapi_cursor, e)
    if not new_rows:
        return
    self._rowbuffer = collections.deque(new_rows)
    if self._growth_factor and size < self._max_row_buffer:
        self._bufsize = min(self._max_row_buffer, size * self._growth_factor)

def _soft_close(self, hard: bool=False) -> None:
    if not hard and self._soft_closed or (hard and self.closed):
        return
    if hard:
        self.closed = True
        self.cursor_strategy.hard_close(self, self.cursor)
    else:
        self.cursor_strategy.soft_close(self, self.cursor)
    if not self._soft_closed:
        cursor = self.cursor
        self.cursor = None
        self.connection._safe_close_cursor(cursor)
        self._soft_closed = True

