def _add_lazyload_options(self, options, effective_path, cache_path=None):
    key = ()
    if not cache_path:
        cache_path = effective_path
    for opt in options:
        if opt._is_legacy_option or opt._is_compile_state:
            ck = opt._generate_cache_key()
            if ck is None:
                self.spoil(full=True)
            else:
                assert not ck[1], 'loader options with variable bound parameters not supported with baked queries.  Please use new-style select() statements for cached ORM queries.'
                key += ck[0]
    self.add_criteria(lambda q: q._with_current_path(effective_path).options(*options), cache_path.path, key)

def to_query(self, query_or_session):
    if isinstance(query_or_session, Session):
        session = query_or_session
    elif isinstance(query_or_session, Query):
        session = query_or_session.session
        if session is None:
            raise sa_exc.ArgumentError('Given Query needs to be associated with a Session')
    else:
        raise TypeError('Query or Session object expected, got %r.' % type(query_or_session))
    return self._as_query(session)

def params(self, *args, **kw):
    if len(args) == 1:
        kw.update(args[0])
    elif len(args) > 0:
        raise sa_exc.ArgumentError('params() takes zero or one positional argument, which is a dictionary.')
    self._params.update(kw)
    return self

def count(self):
    col = func.count(literal_column('*'))
    bq = self.bq.with_criteria(lambda q: q._legacy_from_self(col))
    return bq.for_session(self.session).params(self._params).scalar()

def scalar(self):
    try:
        ret = self.one()
        if not isinstance(ret, collections_abc.Sequence):
            return ret
        return ret[0]
    except orm_exc.NoResultFound:
        return None

def first(self):
    bq = self.bq.with_criteria(lambda q: q.slice(0, 1))
    return bq.for_session(self.session).params(self._params)._using_post_criteria(self._post_criteria)._iter().first()

def get(self, ident):
    query = self.bq.steps[0](self.session)
    return query._get_impl(ident, self._load_on_pk_identity)

def _load_on_pk_identity(self, session, query, primary_key_identity, **kw):
    mapper = query._raw_columns[0]._annotations['parententity']
    _get_clause, _get_params = mapper._get_clause

    def setup(query):
        _lcl_get_clause = _get_clause
        q = query._clone()
        q._get_condition()
        q._order_by = None
        if None in primary_key_identity:
            nones = {_get_params[col].key for col, value in zip(mapper.primary_key, primary_key_identity) if value is None}
            _lcl_get_clause = sql_util.adapt_criterion_to_null(_lcl_get_clause, nones)
        q._where_criteria = (sql_util._deep_annotate(_lcl_get_clause, {'_orm_adapt': True}),)
        for fn in self._post_criteria:
            q = fn(q)
        return q
    bq = self.bq
    bq = bq._clone()
    bq._cache_key += (_get_clause,)
    bq = bq.with_criteria(setup, tuple((elem is None for elem in primary_key_identity)))
    params = {_get_params[primary_key].key: id_val for id_val, primary_key in zip(primary_key_identity, mapper.primary_key)}
    result = list(bq.for_session(self.session).params(**params))
    l = len(result)
    if l > 1:
        raise orm_exc.MultipleResultsFound()
    elif l:
        return result[0]
    else:
        return None

def compiles(class_: Type[Any], *specs: str) -> Callable[[_F], _F]:

    def decorate(fn: _F) -> _F:
        existing = class_.__dict__.get('_compiler_dispatcher', None)
        existing_dispatch = getattr(class_, '_compiler_dispatch', None)
        if not existing:
            existing = _dispatcher()
            if existing_dispatch:

                def _wrap_existing_dispatch(element: Any, compiler: SQLCompiler, **kw: Any) -> Any:
                    try:
                        return existing_dispatch(element, compiler, **kw)
                    except exc.UnsupportedCompilationError as uce:
                        raise exc.UnsupportedCompilationError(compiler, type(element), message='%s construct has no default compilation handler.' % type(element)) from uce
                existing.specs['default'] = _wrap_existing_dispatch
            setattr(class_, '_compiler_dispatch', lambda *arg, **kw: existing(*arg, **kw))
            setattr(class_, '_compiler_dispatcher', existing)
        if specs:
            for s in specs:
                existing.specs[s] = fn
        else:
            existing.specs['default'] = fn
        return fn
    return decorate

def deregister(class_: Type[Any]) -> None:
    if hasattr(class_, '_compiler_dispatcher'):
        class_._compiler_dispatch = class_._original_compiler_dispatch
        del class_._compiler_dispatcher

def __init__(self, shard_chooser: ShardChooser, identity_chooser: Optional[IdentityChooser]=None, execute_chooser: Optional[Callable[[ORMExecuteState], Iterable[Any]]]=None, shards: Optional[Dict[str, Any]]=None, query_cls: Type[Query[_T]]=ShardedQuery, *, id_chooser: Optional[Callable[[Query[_T], Iterable[_T]], Iterable[Any]]]=None, query_chooser: Optional[Callable[[Executable], Iterable[Any]]]=None, **kwargs: Any) -> None:
    super().__init__(query_cls=query_cls, **kwargs)
    event.listen(self, 'do_orm_execute', execute_and_instances, retval=True)
    self.shard_chooser = shard_chooser
    if id_chooser:
        _id_chooser = id_chooser
        util.warn_deprecated('The ``id_chooser`` parameter is deprecated; please use ``identity_chooser``.', '2.0')

        def _legacy_identity_chooser(mapper: Mapper[_T], primary_key: _PKIdentityArgument, *, lazy_loaded_from: Optional[InstanceState[Any]], execution_options: OrmExecuteOptionsParameter, bind_arguments: _BindArguments, **kw: Any) -> Any:
            q = self.query(mapper)
            if lazy_loaded_from:
                q = q._set_lazyload_from(lazy_loaded_from)
            return _id_chooser(q, primary_key)
        self.identity_chooser = _legacy_identity_chooser
    elif identity_chooser:
        self.identity_chooser = identity_chooser
    else:
        raise exc.ArgumentError('identity_chooser or id_chooser is required')
    if query_chooser:
        _query_chooser = query_chooser
        util.warn_deprecated('The ``query_chooser`` parameter is deprecated; please use ``execute_chooser``.', '1.4')
        if execute_chooser:
            raise exc.ArgumentError("Can't pass query_chooser and execute_chooser at the same time.")

        def _default_execute_chooser(orm_context: ORMExecuteState) -> Iterable[Any]:
            return _query_chooser(orm_context.statement)
        if execute_chooser is None:
            execute_chooser = _default_execute_chooser
    if execute_chooser is None:
        raise exc.ArgumentError('execute_chooser or query_chooser is required')
    self.execute_chooser = execute_chooser
    self.__shards: Dict[ShardIdentifier, _SessionBind] = {}
    if shards is not None:
        for k in shards:
            self.bind_shard(k, shards[k])

def _identity_lookup(self, mapper: Mapper[_O], primary_key_identity: Union[Any, Tuple[Any, ...]], identity_token: Optional[Any]=None, passive: PassiveFlag=PassiveFlag.PASSIVE_OFF, lazy_loaded_from: Optional[InstanceState[Any]]=None, execution_options: OrmExecuteOptionsParameter=util.EMPTY_DICT, bind_arguments: Optional[_BindArguments]=None, **kw: Any) -> Union[Optional[_O], LoaderCallableStatus]:
    if identity_token is not None:
        obj = super()._identity_lookup(mapper, primary_key_identity, identity_token=identity_token, **kw)
        return obj
    else:
        for shard_id in self.identity_chooser(mapper, primary_key_identity, lazy_loaded_from=lazy_loaded_from, execution_options=execution_options, bind_arguments=dict(bind_arguments) if bind_arguments else {}):
            obj2 = super()._identity_lookup(mapper, primary_key_identity, identity_token=shard_id, lazy_loaded_from=lazy_loaded_from, **kw)
            if obj2 is not None:
                return obj2
        return None

def connection_callable(self, mapper: Optional[Mapper[_T]]=None, instance: Optional[Any]=None, shard_id: Optional[ShardIdentifier]=None, **kw: Any) -> Connection:
    if shard_id is None:
        shard_id = self._choose_shard_and_assign(mapper, instance)
    if self.in_transaction():
        trans = self.get_transaction()
        assert trans is not None
        return trans.connection(mapper, shard_id=shard_id)
    else:
        bind = self.get_bind(mapper=mapper, shard_id=shard_id, instance=instance)
        if isinstance(bind, Engine):
            return bind.connect(**kw)
        else:
            assert isinstance(bind, Connection)
            return bind

