def __init__(self, attr_name: str, index: Union[int, str], default: _T=_NO_DEFAULT_ARGUMENT, datatype: Optional[Callable[[], Any]]=None, mutable: bool=True, onebased: bool=True):
    if mutable:
        super().__init__(self.fget, self.fset, self.fdel, self.expr)
    else:
        super().__init__(self.fget, None, None, self.expr)
    self.attr_name = attr_name
    self.index = index
    self.default = default
    is_numeric = isinstance(index, int)
    onebased = is_numeric and onebased
    if datatype is not None:
        self.datatype = datatype
    elif is_numeric:
        self.datatype = lambda: [None for x in range(index + 1)]
    else:
        self.datatype = dict
    self.onebased = onebased

def _collect_management_factories_for(self, cls):
    hierarchy = util.class_hierarchy(cls)
    factories = set()
    for member in hierarchy:
        manager = self.opt_manager_of_class(member)
        if manager is not None:
            factories.add(manager.factory)
        else:
            for finder in instrumentation_finders:
                factory = finder(member)
                if factory is not None:
                    break
            else:
                factory = None
            factories.add(factory)
    factories.discard(None)
    return factories

