def _create_proxied_attribute(descriptor: Any) -> Callable[..., QueryableAttribute[Any]]:

    class Proxy(QueryableAttribute[_T_co]):
        """Presents the :class:`.QueryableAttribute` interface as a
        proxy on top of a Python descriptor / :class:`.PropComparator`
        combination.

        """
        _extra_criteria = ()

        def __init__(self, class_: _ExternalEntityType[Any], key: str, descriptor: Any, comparator: interfaces.PropComparator[_T_co], adapt_to_entity: Optional[AliasedInsp[Any]]=None, doc: Optional[str]=None, original_property: Optional[QueryableAttribute[_T_co]]=None):
            self.class_ = class_
            self.key = key
            self.descriptor = descriptor
            self.original_property = original_property
            self._comparator = comparator
            self._adapt_to_entity = adapt_to_entity
            self._doc = self.__doc__ = doc

        @property
        def _parententity(self):
            return inspection.inspect(self.class_, raiseerr=False)

        @property
        def parent(self):
            return inspection.inspect(self.class_, raiseerr=False)
        _is_internal_proxy = True
        _cache_key_traversal = [('key', visitors.ExtendedInternalTraversal.dp_string), ('_parententity', visitors.ExtendedInternalTraversal.dp_multi)]

        def _column_strategy_attrs(self) -> Sequence[QueryableAttribute[Any]]:
            prop = self.original_property
            if prop is None:
                return ()
            else:
                return prop._column_strategy_attrs()

        @property
        def _impl_uses_objects(self):
            return self.original_property is not None and getattr(self.class_, self.key).impl.uses_objects

        @property
        def _entity_namespace(self):
            if hasattr(self._comparator, '_parententity'):
                return self._comparator._parententity
            else:
                return _AdHocHasEntityNamespace(self._parententity)

        @property
        def property(self):
            return self.comparator.property

        @util.memoized_property
        def comparator(self):
            if callable(self._comparator):
                self._comparator = self._comparator()
            if self._adapt_to_entity:
                self._comparator = self._comparator.adapt_to_entity(self._adapt_to_entity)
            return self._comparator

        def adapt_to_entity(self, adapt_to_entity):
            return self.__class__(adapt_to_entity.entity, self.key, self.descriptor, self._comparator, adapt_to_entity)

        def _clone(self, **kw):
            return self.__class__(self.class_, self.key, self.descriptor, self._comparator, adapt_to_entity=self._adapt_to_entity, original_property=self.original_property)

        def __get__(self, instance, owner):
            retval = self.descriptor.__get__(instance, owner)
            if retval is self.descriptor and instance is None:
                return self
            else:
                return retval

        def __str__(self) -> str:
            return f'{self.class_.__name__}.{self.key}'

        def __getattr__(self, attribute):
            """Delegate __getattr__ to the original descriptor and/or
            comparator."""
            try:
                return util.MemoizedSlots.__getattr__(self, attribute)
            except AttributeError:
                pass
            try:
                return getattr(descriptor, attribute)
            except AttributeError as err:
                if attribute == 'comparator':
                    raise AttributeError('comparator') from err
                try:
                    comparator = self.comparator
                except AttributeError as err2:
                    raise AttributeError('Neither %r object nor unconfigured comparator object associated with %s has an attribute %r' % (type(descriptor).__name__, self, attribute)) from err2
                else:
                    try:
                        return getattr(comparator, attribute)
                    except AttributeError as err3:
                        raise AttributeError('Neither %r object nor %r object associated with %s has an attribute %r' % (type(descriptor).__name__, type(comparator).__name__, self, attribute)) from err3
    Proxy.__name__ = type(descriptor).__name__ + 'Proxy'
    util.monkeypatch_proxied_specials(Proxy, type(descriptor), name='descriptor', from_instance=descriptor)
    return Proxy

def __getattr__(self, attribute):
    try:
        return util.MemoizedSlots.__getattr__(self, attribute)
    except AttributeError:
        pass
    try:
        return getattr(descriptor, attribute)
    except AttributeError as err:
        if attribute == 'comparator':
            raise AttributeError('comparator') from err
        try:
            comparator = self.comparator
        except AttributeError as err2:
            raise AttributeError('Neither %r object nor unconfigured comparator object associated with %s has an attribute %r' % (type(descriptor).__name__, self, attribute)) from err2
        else:
            try:
                return getattr(comparator, attribute)
            except AttributeError as err3:
                raise AttributeError('Neither %r object nor %r object associated with %s has an attribute %r' % (type(descriptor).__name__, type(comparator).__name__, self, attribute)) from err3

def sethasparent(self, state: InstanceState[Any], parent_state: InstanceState[Any], value: bool) -> None:
    msg = 'This AttributeImpl is not configured to track parents.'
    assert self.trackparent, msg
    id_ = id(self.parent_token)
    if value:
        state.parents[id_] = parent_state
    else:
        if id_ in state.parents:
            last_parent = state.parents[id_]
            if last_parent is not False and last_parent.key != parent_state.key:
                if last_parent.obj() is None:
                    raise orm_exc.StaleDataError("Removing state %s from parent state %s along attribute '%s', but the parent record has gone stale, can't be sure this is the most recent parent." % (state_str(state), state_str(parent_state), self.key))
                return
        state.parents[id_] = False

def get(self, state: InstanceState[Any], dict_: _InstanceDict, passive: PassiveFlag=PASSIVE_OFF) -> Any:
    if self.key in dict_:
        return dict_[self.key]
    else:
        key = self.key
        if key not in state.committed_state or state.committed_state[key] is NO_VALUE:
            if not passive & CALLABLES_OK:
                return PASSIVE_NO_RESULT
            value = self._fire_loader_callables(state, key, passive)
            if value is PASSIVE_NO_RESULT or value is NO_VALUE:
                return value
            elif value is ATTR_WAS_SET:
                try:
                    return dict_[key]
                except KeyError as err:
                    raise KeyError('Deferred loader for attribute %r failed to populate correctly' % key) from err
            elif value is not ATTR_EMPTY:
                return self.set_committed_value(state, dict_, value)
        if not passive & INIT_OK:
            return NO_VALUE
        else:
            return self._default_value(state, dict_)

def get_committed_value(self, state: InstanceState[Any], dict_: _InstanceDict, passive: PassiveFlag=PASSIVE_OFF) -> Any:
    if self.key in state.committed_state:
        value = state.committed_state[self.key]
        if value is NO_VALUE:
            return None
        else:
            return value
    else:
        return self.get(state, dict_, passive=passive)

def _default_value(self, state: InstanceState[Any], dict_: _InstanceDict) -> Any:
    assert self.key not in dict_, '_default_value should only be invoked for an uninitialized or expired attribute'
    value = self._default_scalar_value
    for fn in self.dispatch.init_scalar:
        ret = fn(state, value, dict_)
        if ret is not ATTR_EMPTY:
            value = ret
    return value

def set(self, state: InstanceState[Any], dict_: _InstanceDict, value: Any, initiator: Optional[AttributeEventToken]=None, passive: PassiveFlag=PASSIVE_OFF, check_old: Any=None, pop: bool=False) -> None:
    if value is DONT_SET:
        return
    if self.dispatch._active_history:
        old = self.get(state, dict_, passive=PASSIVE_ONLY_PERSISTENT | NO_AUTOFLUSH | LOAD_AGAINST_COMMITTED)
    else:
        old = self.get(state, dict_, passive=PASSIVE_NO_FETCH ^ INIT_OK | LOAD_AGAINST_COMMITTED | NO_RAISE)
    if check_old is not None and old is not PASSIVE_NO_RESULT and (check_old is not old):
        if pop:
            return
        else:
            raise ValueError("Object %s not associated with %s on attribute '%s'" % (instance_str(check_old), state_str(state), self.key))
    value = self.fire_replace_event(state, dict_, value, old, initiator)
    dict_[self.key] = value

def set_committed_value(self, state: InstanceState[Any], dict_: _InstanceDict, value: Any) -> _AdaptedCollectionProtocol:
    collection, user_data = self._initialize_collection(state)
    if value:
        collection.append_multiple_without_event(value)
    state.dict[self.key] = user_data
    state._commit(dict_, [self.key])
    if self.key in state._pending_mutations:
        state._modified_event(dict_, self, user_data, True)
        pending = state._pending_mutations.pop(self.key)
        added = pending.added_items
        removed = pending.deleted_items
        for item in added:
            collection.append_without_event(item)
        for item in removed:
            collection.remove_without_event(item)
    return user_data

def get_collection(self, state: InstanceState[Any], dict_: _InstanceDict, user_data: Optional[_AdaptedCollectionProtocol]=None, passive: PassiveFlag=PASSIVE_OFF) -> Union[Literal[LoaderCallableStatus.PASSIVE_NO_RESULT], CollectionAdapter]:
    if user_data is None:
        fetch_user_data = self.get(state, dict_, passive=passive)
        if fetch_user_data is LoaderCallableStatus.PASSIVE_NO_RESULT:
            return fetch_user_data
        else:
            user_data = cast('_AdaptedCollectionProtocol', fetch_user_data)
    return user_data._sa_adapter

def _backref_listeners(attribute: QueryableAttribute[Any], key: str, uselist: bool) -> None:
    parent_token = attribute.impl.parent_token
    parent_impl = attribute.impl

    def _acceptable_key_err(child_state, initiator, child_impl):
        raise ValueError('Bidirectional attribute conflict detected: Passing object %s to attribute "%s" triggers a modify event on attribute "%s" via the backref "%s".' % (state_str(child_state), initiator.parent_token, child_impl.parent_token, attribute.impl.parent_token))

    def emit_backref_from_scalar_set_event(state, child, oldchild, initiator, **kw):
        if oldchild is child:
            return child
        if oldchild is not None and oldchild is not PASSIVE_NO_RESULT and (oldchild is not NO_VALUE):
            old_state, old_dict = (instance_state(oldchild), instance_dict(oldchild))
            impl = old_state.manager[key].impl
            if not impl.collection and (not impl.dynamic):
                check_recursive_token = impl._replace_token
            else:
                check_recursive_token = impl._remove_token
            if initiator is not check_recursive_token:
                impl.pop(old_state, old_dict, state.obj(), parent_impl._append_token, passive=PASSIVE_NO_FETCH)
        if child is not None:
            child_state, child_dict = (instance_state(child), instance_dict(child))
            child_impl = child_state.manager[key].impl
            if initiator.parent_token is not parent_token and initiator.parent_token is not child_impl.parent_token:
                _acceptable_key_err(state, initiator, child_impl)
            check_append_token = child_impl._append_token
            check_bulk_replace_token = child_impl._bulk_replace_token if _is_collection_attribute_impl(child_impl) else None
            if initiator is not check_append_token and initiator is not check_bulk_replace_token:
                child_impl.append(child_state, child_dict, state.obj(), initiator, passive=PASSIVE_NO_FETCH)
        return child

    def emit_backref_from_collection_append_event(state, child, initiator, **kw):
        if child is None:
            return
        child_state, child_dict = (instance_state(child), instance_dict(child))
        child_impl = child_state.manager[key].impl
        if initiator.parent_token is not parent_token and initiator.parent_token is not child_impl.parent_token:
            _acceptable_key_err(state, initiator, child_impl)
        check_append_token = child_impl._append_token
        check_bulk_replace_token = child_impl._bulk_replace_token if _is_collection_attribute_impl(child_impl) else None
        if initiator is not check_append_token and initiator is not check_bulk_replace_token:
            child_impl.append(child_state, child_dict, state.obj(), initiator, passive=PASSIVE_NO_FETCH)
        return child

    def emit_backref_from_collection_remove_event(state, child, initiator, **kw):
        if child is not None and child is not PASSIVE_NO_RESULT and (child is not NO_VALUE):
            child_state, child_dict = (instance_state(child), instance_dict(child))
            child_impl = child_state.manager[key].impl
            check_replace_token: Optional[AttributeEventToken]
            if not child_impl.collection and (not child_impl.dynamic):
                check_remove_token = child_impl._remove_token
                check_replace_token = child_impl._replace_token
                check_for_dupes_on_remove = uselist and (not parent_impl.dynamic)
            else:
                check_remove_token = child_impl._remove_token
                check_replace_token = child_impl._bulk_replace_token if _is_collection_attribute_impl(child_impl) else None
                check_for_dupes_on_remove = False
            if initiator is not check_remove_token and initiator is not check_replace_token:
                if not check_for_dupes_on_remove or not util.has_dupes(state.dict[parent_impl.key], child):
                    child_impl.pop(child_state, child_dict, state.obj(), initiator, passive=PASSIVE_NO_FETCH)
    if uselist:
        event.listen(attribute, 'append', emit_backref_from_collection_append_event, retval=True, raw=True, include_key=True)
    else:
        event.listen(attribute, 'set', emit_backref_from_scalar_set_event, retval=True, raw=True, include_key=True)
    event.listen(attribute, 'remove', emit_backref_from_collection_remove_event, retval=True, raw=True, include_key=True)

