def bulk_replace(values, existing_adapter, new_adapter, initiator=None):
    assert isinstance(values, list)
    idset = util.IdentitySet
    existing_idset = idset(existing_adapter or ())
    constants = existing_idset.intersection(values or ())
    additions = idset(values or ()).difference(constants)
    removals = existing_idset.difference(constants)
    appender = new_adapter.bulk_appender()
    for member in values or ():
        if member in additions:
            appender(member, _sa_initiator=initiator)
        elif member in constants:
            appender(member, _sa_initiator=False)
    if existing_adapter:
        existing_adapter._fire_append_wo_mutation_event_bulk(constants, initiator=initiator)
        existing_adapter._fire_remove_event_bulk(removals, initiator=initiator)

def _prepare_instrumentation(factory: Union[Type[Collection[Any]], _CollectionFactoryType]) -> _CollectionFactoryType:
    impl_factory: _CollectionFactoryType
    if factory in __canned_instrumentation:
        impl_factory = __canned_instrumentation[factory]
    else:
        impl_factory = cast(_CollectionFactoryType, factory)
    cls: Union[_CollectionFactoryType, Type[Collection[Any]]]
    cls = type(impl_factory())
    if cls in __canned_instrumentation:
        impl_factory = __canned_instrumentation[cls]
        cls = type(impl_factory())
    if __instrumentation_mutex.acquire():
        try:
            if getattr(cls, '_sa_instrumented', None) != id(cls):
                _instrument_class(cls)
        finally:
            __instrumentation_mutex.release()
    return impl_factory

def _locate_roles_and_methods(cls):
    roles: Dict[str, str] = {}
    methods: Dict[str, Tuple[Optional[str], Optional[int], Optional[str]]] = {}
    for supercls in cls.__mro__:
        for name, method in vars(supercls).items():
            if not callable(method):
                continue
            if hasattr(method, '_sa_instrument_role'):
                role = method._sa_instrument_role
                assert role in ('appender', 'remover', 'iterator')
                roles.setdefault(role, name)
            before: Optional[Tuple[str, int]] = None
            after: Optional[str] = None
            if hasattr(method, '_sa_instrument_before'):
                op, argument = method._sa_instrument_before
                assert op in ('fire_append_event', 'fire_remove_event')
                before = (op, argument)
            if hasattr(method, '_sa_instrument_after'):
                op = method._sa_instrument_after
                assert op in ('fire_append_event', 'fire_remove_event')
                after = op
            if before:
                methods[name] = before + (after,)
            elif after:
                methods[name] = (None, None, after)
    return (roles, methods)

def _setup_canned_roles(cls, roles, methods):
    collection_type = util.duck_type_collection(cls)
    if collection_type in __interfaces:
        assert collection_type is not None
        canned_roles, decorators = __interfaces[collection_type]
        for role, name in canned_roles.items():
            roles.setdefault(role, name)
        for method, decorator in decorators.items():
            fn = getattr(cls, method, None)
            if fn and method not in methods and (not hasattr(fn, '_sa_instrumented')):
                setattr(cls, method, decorator(fn))

def _assert_required_roles(cls, roles, methods):
    if 'appender' not in roles or not hasattr(cls, roles['appender']):
        raise sa_exc.ArgumentError('Type %s must elect an appender method to be a collection class' % cls.__name__)
    elif roles['appender'] not in methods and (not hasattr(getattr(cls, roles['appender']), '_sa_instrumented')):
        methods[roles['appender']] = ('fire_append_event', 1, None)
    if 'remover' not in roles or not hasattr(cls, roles['remover']):
        raise sa_exc.ArgumentError('Type %s must elect a remover method to be a collection class' % cls.__name__)
    elif roles['remover'] not in methods and (not hasattr(getattr(cls, roles['remover']), '_sa_instrumented')):
        methods[roles['remover']] = ('fire_remove_event', 1, None)
    if 'iterator' not in roles or not hasattr(cls, roles['iterator']):
        raise sa_exc.ArgumentError('Type %s must elect an iterator method to be a collection class' % cls.__name__)

def _set_collection_attributes(cls, roles, methods):
    for method_name, (before, argument, after) in methods.items():
        setattr(cls, method_name, _instrument_membership_mutator(getattr(cls, method_name), before, argument, after))
    for role, method_name in roles.items():
        setattr(cls, '_sa_%s' % role, getattr(cls, method_name))
    cls._sa_adapter = None
    cls._sa_instrumented = id(cls)

def _instrument_membership_mutator(method, before, argument, after):
    if before:
        fn_args = list(util.flatten_iterator(inspect_getfullargspec(method)[0]))
        if isinstance(argument, int):
            pos_arg = argument
            named_arg = len(fn_args) > argument and fn_args[argument] or None
        else:
            if argument in fn_args:
                pos_arg = fn_args.index(argument)
            else:
                pos_arg = None
            named_arg = argument
        del fn_args

    def wrapper(*args, **kw):
        if before:
            if pos_arg is None:
                if named_arg not in kw:
                    raise sa_exc.ArgumentError('Missing argument %s' % argument)
                value = kw[named_arg]
            elif len(args) > pos_arg:
                value = args[pos_arg]
            elif named_arg in kw:
                value = kw[named_arg]
            else:
                raise sa_exc.ArgumentError('Missing argument %s' % argument)
        initiator = kw.pop('_sa_initiator', None)
        if initiator is False:
            executor = None
        else:
            executor = args[0]._sa_adapter
        if before and executor:
            getattr(executor, before)(value, initiator)
        if not after or not executor:
            return method(*args, **kw)
        else:
            res = method(*args, **kw)
            if res is not None:
                getattr(executor, after)(res, initiator)
            return res
    wrapper._sa_instrumented = True
    if hasattr(method, '_sa_instrument_role'):
        wrapper._sa_instrument_role = method._sa_instrument_role
    wrapper.__name__ = method.__name__
    wrapper.__doc__ = method.__doc__
    return wrapper

def __set_wo_mutation(collection, item, _sa_initiator=None):
    if _sa_initiator is not False:
        executor = collection._sa_adapter
        if executor:
            executor.fire_append_wo_mutation_event(item, _sa_initiator, key=None)

def __set(collection, item, _sa_initiator, key):
    if _sa_initiator is not False:
        executor = collection._sa_adapter
        if executor:
            item = executor.fire_append_event(item, _sa_initiator, key=key)
    return item

def __del(collection, item, _sa_initiator, key):
    if _sa_initiator is not False:
        executor = collection._sa_adapter
        if executor:
            executor.fire_remove_event(item, _sa_initiator, key=key)

def __before_pop(collection, _sa_initiator=None):
    executor = collection._sa_adapter
    if executor:
        executor.fire_pre_remove_event(_sa_initiator)

def _list_decorators() -> Dict[str, Callable[[_FN], _FN]]:

    def _tidy(fn):
        fn._sa_instrumented = True
        fn.__doc__ = getattr(list, fn.__name__).__doc__

    def append(fn):

        def append(self, item, _sa_initiator=None):
            item = __set(self, item, _sa_initiator, NO_KEY)
            fn(self, item)
        _tidy(append)
        return append

    def remove(fn):

        def remove(self, value, _sa_initiator=None):
            __del(self, value, _sa_initiator, NO_KEY)
            fn(self, value)
        _tidy(remove)
        return remove

    def insert(fn):

        def insert(self, index, value):
            value = __set(self, value, None, index)
            fn(self, index, value)
        _tidy(insert)
        return insert

    def __setitem__(fn):

        def __setitem__(self, index, value):
            if not isinstance(index, slice):
                existing = self[index]
                if existing is not None:
                    __del(self, existing, None, index)
                value = __set(self, value, None, index)
                fn(self, index, value)
            else:
                step = index.step or 1
                start = index.start or 0
                if start < 0:
                    start += len(self)
                if index.stop is not None:
                    stop = index.stop
                else:
                    stop = len(self)
                if stop < 0:
                    stop += len(self)
                if step == 1:
                    if value is self:
                        return
                    for i in range(start, stop, step):
                        if len(self) > start:
                            del self[start]
                    for i, item in enumerate(value):
                        self.insert(i + start, item)
                else:
                    rng = list(range(start, stop, step))
                    if len(value) != len(rng):
                        raise ValueError('attempt to assign sequence of size %s to extended slice of size %s' % (len(value), len(rng)))
                    for i, item in zip(rng, value):
                        self.__setitem__(i, item)
        _tidy(__setitem__)
        return __setitem__

    def __delitem__(fn):

        def __delitem__(self, index):
            if not isinstance(index, slice):
                item = self[index]
                __del(self, item, None, index)
                fn(self, index)
            else:
                for item in self[index]:
                    __del(self, item, None, index)
                fn(self, index)
        _tidy(__delitem__)
        return __delitem__

    def extend(fn):

        def extend(self, iterable):
            for value in list(iterable):
                self.append(value)
        _tidy(extend)
        return extend

    def __iadd__(fn):

        def __iadd__(self, iterable):
            for value in list(iterable):
                self.append(value)
            return self
        _tidy(__iadd__)
        return __iadd__

    def pop(fn):

        def pop(self, index=-1):
            __before_pop(self)
            item = fn(self, index)
            __del(self, item, None, index)
            return item
        _tidy(pop)
        return pop

    def clear(fn):

        def clear(self, index=-1):
            for item in self:
                __del(self, item, None, index)
            fn(self)
        _tidy(clear)
        return clear
    l = locals().copy()
    l.pop('_tidy')
    return l

def _dict_decorators() -> Dict[str, Callable[[_FN], _FN]]:

    def _tidy(fn):
        fn._sa_instrumented = True
        fn.__doc__ = getattr(dict, fn.__name__).__doc__

    def __setitem__(fn):

        def __setitem__(self, key, value, _sa_initiator=None):
            if key in self:
                __del(self, self[key], _sa_initiator, key)
            value = __set(self, value, _sa_initiator, key)
            fn(self, key, value)
        _tidy(__setitem__)
        return __setitem__

    def __delitem__(fn):

        def __delitem__(self, key, _sa_initiator=None):
            if key in self:
                __del(self, self[key], _sa_initiator, key)
            fn(self, key)
        _tidy(__delitem__)
        return __delitem__

    def clear(fn):

        def clear(self):
            for key in self:
                __del(self, self[key], None, key)
            fn(self)
        _tidy(clear)
        return clear

    def pop(fn):

        def pop(self, key, default=NO_ARG):
            __before_pop(self)
            _to_del = key in self
            if default is NO_ARG:
                item = fn(self, key)
            else:
                item = fn(self, key, default)
            if _to_del:
                __del(self, item, None, key)
            return item
        _tidy(pop)
        return pop

    def popitem(fn):

        def popitem(self):
            __before_pop(self)
            item = fn(self)
            __del(self, item[1], None, 1)
            return item
        _tidy(popitem)
        return popitem

    def setdefault(fn):

        def setdefault(self, key, default=None):
            if key not in self:
                self.__setitem__(key, default)
                return default
            else:
                value = self.__getitem__(key)
                if value is default:
                    __set_wo_mutation(self, value, None)
                return value
        _tidy(setdefault)
        return setdefault

    def update(fn):

        def update(self, __other=NO_ARG, **kw):
            if __other is not NO_ARG:
                if hasattr(__other, 'keys'):
                    for key in list(__other):
                        if key not in self or self[key] is not __other[key]:
                            self[key] = __other[key]
                        else:
                            __set_wo_mutation(self, __other[key], None)
                else:
                    for key, value in __other:
                        if key not in self or self[key] is not value:
                            self[key] = value
                        else:
                            __set_wo_mutation(self, value, None)
            for key in kw:
                if key not in self or self[key] is not kw[key]:
                    self[key] = kw[key]
                else:
                    __set_wo_mutation(self, kw[key], None)
        _tidy(update)
        return update
    l = locals().copy()
    l.pop('_tidy')
    return l

def _set_decorators() -> Dict[str, Callable[[_FN], _FN]]:

    def _tidy(fn):
        fn._sa_instrumented = True
        fn.__doc__ = getattr(set, fn.__name__).__doc__

    def add(fn):

        def add(self, value, _sa_initiator=None):
            if value not in self:
                value = __set(self, value, _sa_initiator, NO_KEY)
            else:
                __set_wo_mutation(self, value, _sa_initiator)
            fn(self, value)
        _tidy(add)
        return add

    def discard(fn):

        def discard(self, value, _sa_initiator=None):
            if value in self:
                __del(self, value, _sa_initiator, NO_KEY)
            fn(self, value)
        _tidy(discard)
        return discard

    def remove(fn):

        def remove(self, value, _sa_initiator=None):
            if value in self:
                __del(self, value, _sa_initiator, NO_KEY)
            fn(self, value)
        _tidy(remove)
        return remove

    def pop(fn):

        def pop(self):
            __before_pop(self)
            item = fn(self)
            __del(self, item, None, NO_KEY)
            return item
        _tidy(pop)
        return pop

    def clear(fn):

        def clear(self):
            for item in list(self):
                self.remove(item)
        _tidy(clear)
        return clear

    def update(fn):

        def update(self, value):
            for item in value:
                self.add(item)
        _tidy(update)
        return update

    def __ior__(fn):

        def __ior__(self, value):
            if not _set_binops_check_strict(self, value):
                return NotImplemented
            for item in value:
                self.add(item)
            return self
        _tidy(__ior__)
        return __ior__

    def difference_update(fn):

        def difference_update(self, value):
            for item in value:
                self.discard(item)
        _tidy(difference_update)
        return difference_update

    def __isub__(fn):

        def __isub__(self, value):
            if not _set_binops_check_strict(self, value):
