        _tidy(__isub__)
        return __isub__

    def intersection_update(fn):

        def intersection_update(self, other):
            want, have = (self.intersection(other), set(self))
            remove, add = (have - want, want - have)
            for item in remove:
                self.remove(item)
            for item in add:
                self.add(item)
        _tidy(intersection_update)
        return intersection_update

    def __iand__(fn):

