def _is_supercls_for_inherits(cls: Type[Any]) -> bool:
    if _DeferredDeclarativeConfig.has_cls(cls):
        return not _get_immediate_cls_attr(cls, '_sa_decl_prepare_nocascade', strict=True)
    elif _is_mapped_class(cls):
        return True
    else:
