def instances(cursor: CursorResult[Unpack[TupleAny]], context: QueryContext) -> Result[Unpack[TupleAny]]:
    context.runid = _new_runid()
    if context.top_level_context:
        is_top_level = False
        context.post_load_paths = context.top_level_context.post_load_paths
    else:
        is_top_level = True
        context.post_load_paths = {}
    compile_state = context.compile_state
    filtered = compile_state._has_mapper_entities
    single_entity = not context.load_options._only_return_tuples and len(compile_state._entities) == 1 and compile_state._entities[0].supports_single_entity
    try:
        process, labels, extra = list(zip(*[query_entity.row_processor(context, cursor) for query_entity in context.compile_state._entities]))
        if context.yield_per and (context.loaders_require_buffering or context.loaders_require_uniquing):
            raise sa_exc.InvalidRequestError("Can't use yield_per with eager loaders that require uniquing or row buffering, e.g. joinedload() against collections or subqueryload().  Consider the selectinload() strategy for better flexibility in loading objects.")
    except Exception:
        with util.safe_reraise():
            cursor.close()

    def _not_hashable(datatype, *, legacy=False, uncertain=False):
        if not legacy:

            def go(obj):
                if uncertain:
                    try:
                        return hash(obj)
                    except:
                        pass
                raise sa_exc.InvalidRequestError(f"Can't apply uniqueness to row tuple containing value of type {datatype!r}; {('the values returned appear to be' if uncertain else 'this datatype produces')} non-hashable values")
            return go
        elif not uncertain:
            return id
        else:
            _use_id = False

            def go(obj):
                nonlocal _use_id
                if not _use_id:
                    try:
                        return hash(obj)
                    except:
                        pass
                    _use_id = True
                return id(obj)
            return go
    _uniquing_is_active = False

    def _create_unique_filters(result):
        nonlocal _uniquing_is_active
        if result._yield_per:
            raise sa_exc.InvalidRequestError("Can't use the ORM yield_per feature in conjunction with unique()")
        _uniquing_is_active = True
        return [_not_hashable(ent.column.type, legacy=context.load_options._legacy_uniquing, uncertain=ent._null_column_type) if not ent.use_id_for_hash and (ent._non_hashable_value or ent._null_column_type) else id if ent.use_id_for_hash else None for ent in context.compile_state._entities]
    row_metadata = SimpleResultMetaData(labels, extra, _create_unique_filters=_create_unique_filters)

    def chunks(size):
        while True:
            yield_per = size
            context.partials = {}
            if yield_per:
                if _uniquing_is_active:
                    raise sa_exc.InvalidRequestError("Can't use the ORM yield_per feature in conjunction with unique()")
                fetch = cursor.fetchmany(yield_per)
                if not fetch:
                    break
            else:
                fetch = cursor._raw_all_tuples()
            if single_entity:
                proc = process[0]
                rows = [proc(row) for row in fetch]
            else:
                rows = [tuple([proc(row) for proc in process]) for row in fetch]
            if is_top_level:
                if yield_per:
                    top_level_post_loads = list(context.post_load_paths.items())
                while context.post_load_paths:
                    post_loads = list(context.post_load_paths.items())
                    context.post_load_paths.clear()
                    for path, post_load in post_loads:
                        post_load.invoke(context, path)
                if yield_per:
                    context.post_load_paths.clear()
                    context.post_load_paths.update(top_level_post_loads)
            yield rows
            if not yield_per:
                break
    if context.execution_options.get('prebuffer_rows', False):
        _prebuffered = list(chunks(None))

        def chunks(size):
            return iter(_prebuffered)
    result = ChunkedIteratorResult(row_metadata, chunks, source_supports_scalars=single_entity, raw=cursor, dynamic_yield_per=cursor.context._is_server_side, context=context)
    result._attributes = result._attributes.union(dict(filtered=filtered, is_single_entity=single_entity))
    if context.requires_uniquing:

        def require_unique(obj):
            raise sa_exc.InvalidRequestError('The unique() method must be invoked on this Result, as it contains results that include joined eager loads against collections')
        result._unique_filter_state = (set(), require_unique)
    if context.yield_per:
        result.yield_per(context.yield_per)
    return result

@util.preload_module('sqlalchemy.orm.context')
def merge_frozen_result(session, statement, frozen_result, load=True):
    querycontext = util.preloaded.orm_context
    if load:
        session._autoflush()
    ctx = querycontext._ORMSelectCompileState._create_entities_collection(statement, legacy=False)
    with session.no_autoflush:
        mapped_entities = [i for i, e in enumerate(ctx._entities) if isinstance(e, querycontext._MapperEntity)]
        keys = [ent._label_name for ent in ctx._entities]
        keyed_tuple = result_tuple(keys, [ent._extra_entities for ent in ctx._entities])
        result = []
        for newrow in frozen_result._rewrite_rows():
            for i in mapped_entities:
                if newrow[i] is not None:
                    newrow[i] = session._merge(attributes.instance_state(newrow[i]), attributes.instance_dict(newrow[i]), load=load, _recursive={}, _resolve_conflict_map={})
            result.append(keyed_tuple(newrow))
        return frozen_result.with_new_rows(result)

@util.became_legacy_20(':func:`_orm.merge_result`', alternative='The function as well as the method on :class:`_orm.Query` is superseded by the :func:`_orm.merge_frozen_result` function.')
@util.preload_module('sqlalchemy.orm.context')
def merge_result(query: Query[Any], iterator: Union[FrozenResult, Iterable[Sequence[Any]], Iterable[object]], load: bool=True) -> Union[FrozenResult, Iterable[Any]]:
    querycontext = util.preloaded.orm_context
    session = query.session
    if load:
        session._autoflush()
    if isinstance(iterator, FrozenResult):
        frozen_result = iterator
        iterator = iter(frozen_result.data)
    else:
        frozen_result = None
    ctx = querycontext._ORMSelectCompileState._create_entities_collection(query, legacy=True)
    autoflush = session.autoflush
    try:
        session.autoflush = False
        single_entity = not frozen_result and len(ctx._entities) == 1
        if single_entity:
            if isinstance(ctx._entities[0], querycontext._MapperEntity):
                result = [session._merge(attributes.instance_state(instance), attributes.instance_dict(instance), load=load, _recursive={}, _resolve_conflict_map={}) for instance in iterator]
            else:
                result = list(iterator)
        else:
            mapped_entities = [i for i, e in enumerate(ctx._entities) if isinstance(e, querycontext._MapperEntity)]
            result = []
            keys = [ent._label_name for ent in ctx._entities]
            keyed_tuple = result_tuple(keys, [ent._extra_entities for ent in ctx._entities])
            for row in iterator:
                newrow = list(row)
                for i in mapped_entities:
                    if newrow[i] is not None:
                        newrow[i] = session._merge(attributes.instance_state(newrow[i]), attributes.instance_dict(newrow[i]), load=load, _recursive={}, _resolve_conflict_map={})
                result.append(keyed_tuple(newrow))
        if frozen_result:
            return frozen_result.with_new_rows(result)
        else:
            return iter(result)
    finally:
        session.autoflush = autoflush

def get_from_identity(session: Session, mapper: Mapper[_O], key: _IdentityKeyType[_O], passive: PassiveFlag) -> Union[LoaderCallableStatus, Optional[_O]]:
    instance = session.identity_map.get(key)
    if instance is not None:
        state = attributes.instance_state(instance)
        if mapper.inherits and (not state.mapper.isa(mapper)):
            return attributes.PASSIVE_CLASS_MISMATCH
        if state.expired:
            if not passive & attributes.SQL_OK:
                return attributes.PASSIVE_NO_RESULT
            elif not passive & attributes.RELATED_OBJECT_OK:
                return instance
            try:
                state._load_expired(state, passive)
            except orm_exc.ObjectDeletedError:
                session._remove_newly_deleted([state])
                return None
        return instance
    else:
        return None

def _load_on_pk_identity(session: Session, statement: Union[Select, FromStatement], primary_key_identity: Optional[Tuple[Any, ...]], *, load_options: Optional[Sequence[ORMOption]]=None, refresh_state: Optional[InstanceState[Any]]=None, with_for_update: Optional[ForUpdateArg]=None, only_load_props: Optional[Iterable[str]]=None, identity_token: Optional[Any]=None, no_autoflush: bool=False, bind_arguments: Mapping[str, Any]=util.EMPTY_DICT, execution_options: _ExecuteOptions=util.EMPTY_DICT, require_pk_cols: bool=False, is_user_refresh: bool=False):
    query = statement
    q = query._clone()
    assert not q._is_lambda_element
    if load_options is None:
        load_options = QueryContext.default_load_options
    if statement._compile_options is SelectState.default_select_compile_options:
        compile_options = _ORMCompileState.default_compile_options
    else:
        compile_options = statement._compile_options
    if primary_key_identity is not None:
        mapper = query._propagate_attrs['plugin_subject']
        _get_clause, _get_params = mapper._get_clause
        if None in primary_key_identity:
            nones = {_get_params[col].key for col, value in zip(mapper.primary_key, primary_key_identity) if value is None}
            _get_clause = sql_util.adapt_criterion_to_null(_get_clause, nones)
            if len(nones) == len(primary_key_identity):
                util.warn('fully NULL primary key identity cannot load any object.  This condition may raise an error in a future release.')
        q._where_criteria = (_get_clause,)
        params = {_get_params[primary_key].key: id_val for id_val, primary_key in zip(primary_key_identity, mapper.primary_key)}
    else:
        params = None
    if with_for_update is not None:
        version_check = True
        q._for_update_arg = with_for_update
    elif query._for_update_arg is not None:
        version_check = True
        q._for_update_arg = query._for_update_arg
    else:
        version_check = False
    if require_pk_cols and only_load_props:
        if not refresh_state:
            raise sa_exc.ArgumentError('refresh_state is required when require_pk_cols is present')
        refresh_state_prokeys = refresh_state.mapper._primary_key_propkeys
        has_changes = {key for key in refresh_state_prokeys.difference(only_load_props) if refresh_state.attrs[key].history.has_changes()}
        if has_changes:
            raise sa_exc.InvalidRequestError(f'Please flush pending primary key changes on attributes {has_changes} for mapper {refresh_state.mapper} before proceeding with a refresh')
        mp = refresh_state.mapper._props
        for p in only_load_props:
            if mp[p]._is_relationship:
                only_load_props = refresh_state_prokeys.union(only_load_props)
                break
    if refresh_state and refresh_state.load_options:
        compile_options += {'_current_path': refresh_state.load_path.parent}
        q = q.options(*refresh_state.load_options)
    new_compile_options, load_options = _set_get_options(compile_options, load_options, version_check=version_check, only_load_props=only_load_props, refresh_state=refresh_state, identity_token=identity_token, is_user_refresh=is_user_refresh)
    q._compile_options = new_compile_options
    q._order_by = None
    if no_autoflush:
        load_options += {'_autoflush': False}
    execution_options = util.EMPTY_DICT.merge_with(execution_options, util.immutabledict(_sa_orm_load_options=load_options))
    result = session.execute(q, params=params, execution_options=execution_options, bind_arguments=bind_arguments).unique().scalars()
    try:
        return result.one()
    except orm_exc.NoResultFound:
        return None

def _instance_processor(query_entity, mapper, context, result, path, adapter, only_load_props=None, refresh_state=None, polymorphic_discriminator=None, _polymorphic_from=None):
    identity_class = mapper._identity_class
    compile_state = context.compile_state
    getter_key = ('getters', mapper)
    getters = path.get(compile_state.attributes, getter_key, None)
    if getters is None:
        props = mapper._prop_set
        if only_load_props is not None:
            props = props.intersection((mapper._props[k] for k in only_load_props))
        quick_populators = path.get(context.attributes, 'memoized_setups', EMPTY_DICT)
        todo = []
        cached_populators = {'new': [], 'quick': [], 'deferred': [], 'expire': [], 'existing': [], 'eager': []}
        if refresh_state is None:
            pk_cols = mapper.primary_key
            if adapter:
                pk_cols = [adapter.columns[c] for c in pk_cols]
            primary_key_getter = result._tuple_getter(pk_cols)
        else:
            primary_key_getter = None
        getters = {'cached_populators': cached_populators, 'todo': todo, 'primary_key_getter': primary_key_getter}
        for prop in props:
            if prop in quick_populators:
                col = quick_populators[prop]
                if col is _DEFER_FOR_STATE:
                    cached_populators['new'].append((prop.key, prop._deferred_column_loader))
                elif col is _SET_DEFERRED_EXPIRED:
                    cached_populators['expire'].append((prop.key, False))
                elif col is _RAISE_FOR_STATE:
                    cached_populators['new'].append((prop.key, prop._raise_column_loader))
                else:
                    getter = None
                    if adapter:
                        adapted_col = adapter.columns[col]
                        if adapted_col is not None:
                            getter = result._getter(adapted_col, False)
                    if not getter:
                        getter = result._getter(col, False)
                    if getter:
                        cached_populators['quick'].append((prop.key, getter))
                    else:
                        prop.create_row_processor(context, query_entity, path, mapper, result, adapter, cached_populators)
            else:
                todo.append(prop)
        path.set(compile_state.attributes, getter_key, getters)
    cached_populators = getters['cached_populators']
    populators = {key: list(value) for key, value in cached_populators.items()}
    for prop in getters['todo']:
        prop.create_row_processor(context, query_entity, path, mapper, result, adapter, populators)
    propagated_loader_options = context.propagated_loader_options
    load_path = context.compile_state.current_path + path if context.compile_state.current_path.path else path
    session_identity_map = context.session.identity_map
    populate_existing = context.populate_existing or mapper.always_refresh
    load_evt = bool(mapper.class_manager.dispatch.load)
    refresh_evt = bool(mapper.class_manager.dispatch.refresh)
    persistent_evt = bool(context.session.dispatch.loaded_as_persistent)
    if persistent_evt:
        loaded_as_persistent = context.session.dispatch.loaded_as_persistent
    instance_state = attributes.instance_state
    instance_dict = attributes.instance_dict
    session_id = context.session.hash_key
    runid = context.runid
    identity_token = context.identity_token
    version_check = context.version_check
    if version_check:
        version_id_col = mapper.version_id_col
        if version_id_col is not None:
            if adapter:
                version_id_col = adapter.columns[version_id_col]
            version_id_getter = result._getter(version_id_col)
        else:
            version_id_getter = None
    if not refresh_state and _polymorphic_from is not None:
        key = ('loader', path.path)
        if key in context.attributes and context.attributes[key].strategy == (('selectinload_polymorphic', True),):
            option_entities = context.attributes[key].local_opts['entities']
        else:
            option_entities = None
        selectin_load_via = mapper._should_selectin_load(option_entities, _polymorphic_from)
        if selectin_load_via and selectin_load_via is not _polymorphic_from:
            assert only_load_props is None
            if selectin_load_via.is_mapper:
                _load_supers = []
                _endmost_mapper = selectin_load_via
                while _endmost_mapper and _endmost_mapper is not _polymorphic_from:
                    _load_supers.append(_endmost_mapper)
                    _endmost_mapper = _endmost_mapper.inherits
            else:
                _load_supers = [selectin_load_via]
            for _selectinload_entity in _load_supers:
                if _PostLoad.path_exists(context, load_path, _selectinload_entity):
                    continue
                callable_ = _load_subclass_via_in(context, path, _selectinload_entity, _polymorphic_from, option_entities)
                _PostLoad.callable_for_path(context, load_path, _selectinload_entity.mapper, _selectinload_entity, callable_, _selectinload_entity)
    post_load = _PostLoad.for_context(context, load_path, only_load_props)
    if refresh_state:
        refresh_identity_key = refresh_state.key
        if refresh_identity_key is None:
            refresh_identity_key = mapper._identity_key_from_state(refresh_state)
    else:
        refresh_identity_key = None
        primary_key_getter = getters['primary_key_getter']
    if mapper.allow_partial_pks:
        is_not_primary_key = _none_set.issuperset
    else:
        is_not_primary_key = _none_set.intersection

    def _instance(row):
        if refresh_identity_key:
            state = refresh_state
            instance = state.obj()
            dict_ = instance_dict(instance)
            isnew = state.runid != runid
            currentload = True
            loaded_instance = False
        else:
            identitykey = (identity_class, primary_key_getter(row), identity_token)
            instance = session_identity_map.get(identitykey)
            if instance is not None:
                state = instance_state(instance)
                dict_ = instance_dict(instance)
                isnew = state.runid != runid
                currentload = not isnew
                loaded_instance = False
                if version_check and version_id_getter and (not currentload):
                    _validate_version_id(mapper, state, dict_, row, version_id_getter)
            else:
                if is_not_primary_key(identitykey[1]):
                    return None
                isnew = True
                currentload = True
                loaded_instance = True
                instance = mapper.class_manager.new_instance()
                dict_ = instance_dict(instance)
                state = instance_state(instance)
