        polymorphic_key = prop.key
    else:
        for mapper in self.iterate_to_root():
            if mapper.polymorphic_on is not None:
                if self.persist_selectable is mapper.persist_selectable:
                    self.polymorphic_on = mapper.polymorphic_on
