    stmt: Union[Select[_T], FromStatement[_T], UpdateBase]
    if not self._compile_options._set_base_alias:
        stmt = self._statement_20(for_statement=True)
    else:
        stmt = self._compile_state(for_statement=True).statement
    if self._params:
        stmt = stmt.params(self._params)
    return stmt

def _final_statement(self, legacy_query_style: bool=True) -> Select[Unpack[TupleAny]]:
    q = self._clone()
    return q._compile_state(use_legacy_query_style=legacy_query_style).statement

def subquery(self, name: Optional[str]=None, with_labels: bool=False, reduce_columns: bool=False) -> Subquery:
    q = self.enable_eagerloads(False)
    if with_labels:
        q = q.set_label_style(LABEL_STYLE_TABLENAME_PLUS_COL)
    stmt = q._get_select_statement_only()
    if TYPE_CHECKING:
        assert isinstance(stmt, Select)
    if reduce_columns:
        stmt = stmt.reduce_columns()
    return stmt.subquery(name=name)

