def delete(self, synchronize_session: SynchronizeSessionArgument='auto', delete_args: Optional[Dict[Any, Any]]=None) -> int:
    bulk_del = BulkDelete(self, delete_args)
    if self.dispatch.before_compile_delete:
        for fn in self.dispatch.before_compile_delete:
            new_query = fn(bulk_del.query, bulk_del)
            if new_query is not None:
                bulk_del.query = new_query
            self = bulk_del.query
    delete_ = sql.delete(*self._raw_columns)
    if delete_args:
        delete_ = delete_.with_dialect_options(**delete_args)
    delete_._where_criteria = self._where_criteria
    for ext in self._syntax_extensions:
        delete_._apply_syntax_extension_to_self(ext)
    result = cast('CursorResult[Any]', self.session.execute(delete_, self._params, execution_options=self._execution_options.union({'synchronize_session': synchronize_session})))
    bulk_del.result = result
    self.session.dispatch.after_bulk_delete(bulk_del)
    result.close()
    return result.rowcount

def update(self, values: Dict[_DMLColumnArgument, Any], synchronize_session: SynchronizeSessionArgument='auto', update_args: Optional[Dict[Any, Any]]=None) -> int:
    update_args = update_args or {}
    bulk_ud = BulkUpdate(self, values, update_args)
    if self.dispatch.before_compile_update:
        for fn in self.dispatch.before_compile_update:
            new_query = fn(bulk_ud.query, bulk_ud)
            if new_query is not None:
                bulk_ud.query = new_query
        self = bulk_ud.query
    upd = sql.update(*self._raw_columns)
    ppo = update_args.pop('preserve_parameter_order', False)
    if ppo:
        upd = upd.ordered_values(*values)
    else:
        upd = upd.values(values)
    if update_args:
        upd = upd.with_dialect_options(**update_args)
    upd._where_criteria = self._where_criteria
    for ext in self._syntax_extensions:
        upd._apply_syntax_extension_to_self(ext)
    result = cast('CursorResult[Any]', self.session.execute(upd, self._params, execution_options=self._execution_options.union({'synchronize_session': synchronize_session})))
    bulk_ud.result = result
    self.session.dispatch.after_bulk_update(bulk_ud)
    result.close()
    return result.rowcount

