    if not self._is_crud:
        raise sa_exc.InvalidRequestError('This ORM execution is not against an UPDATE or DELETE statement so there are no update options.')
    uo: Union[bulk_persistence._BulkUDCompileState.default_update_options, Type[bulk_persistence._BulkUDCompileState.default_update_options]] = self.execution_options.get('_sa_orm_update_options', bulk_persistence._BulkUDCompileState.default_update_options)
    return uo

@property
def user_defined_options(self) -> Sequence[UserDefinedOption]:
    items = [self.statement, *getattr(self.statement, '_memoized_select_entities', ())]
    return [opt for item in items for opt in item._with_options if is_user_defined_option(opt)]

@property
def parent(self) -> Optional[SessionTransaction]:
    return self._parent

def _restore_snapshot(self, dirty_only: bool=False) -> None:
    assert self._is_transaction_boundary
    to_expunge = set(self._new).union(self.session._new)
    self.session._expunge_states(to_expunge, to_transient=True)
    for s, (oldkey, newkey) in self._key_switches.items():
        self.session.identity_map.safe_discard(s)
        s.key = oldkey
        if s not in to_expunge:
            self.session.identity_map.replace(s)
    for s in set(self._deleted).union(self.session._deleted):
        self.session._update_impl(s, revert_deletion=True)
    assert not self.session._deleted
    for s in self.session.identity_map.all_states():
        if not dirty_only or s.modified or s in self._dirty:
            s._expire(s.dict, self.session.identity_map._modified)

def __init__(self, bind: Optional[_SessionBind]=None, *, autoflush: bool=True, future: Literal[True]=True, expire_on_commit: bool=True, autobegin: bool=True, twophase: bool=False, binds: Optional[Dict[_SessionBindKey, _SessionBind]]=None, enable_baked_queries: bool=True, info: Optional[_InfoType]=None, query_cls: Optional[Type[Query[Any]]]=None, autocommit: Literal[False]=False, join_transaction_mode: JoinTransactionMode='conditional_savepoint', close_resets_only: Union[bool, _NoArg]=_NoArg.NO_ARG, execution_options: OrmExecuteOptionsParameter=util.EMPTY_DICT):
    if autocommit:
        raise sa_exc.ArgumentError('autocommit=True is no longer supported')
    self.identity_map = identity._WeakInstanceDict()
    if not future:
        raise sa_exc.ArgumentError("The 'future' parameter passed to Session() may only be set to True.")
    self._new = {}
    self._deleted = {}
    self.bind = bind
    self.__binds = {}
    self._flushing = False
    self._warn_on_events = False
    self._transaction = None
    self._nested_transaction = None
    self.hash_key = _new_sessionid()
    self.autobegin = autobegin
    self.autoflush = autoflush
    self.expire_on_commit = expire_on_commit
    self.enable_baked_queries = enable_baked_queries
    if execution_options:
        self.execution_options = self.execution_options.union(execution_options)
    if close_resets_only in (True, _NoArg.NO_ARG):
        self._close_state = _SessionCloseState.CLOSE_IS_RESET
    else:
        self._close_state = _SessionCloseState.ACTIVE
    if join_transaction_mode and join_transaction_mode not in JoinTransactionMode.__args__:
        raise sa_exc.ArgumentError(f'invalid selection for join_transaction_mode: "{join_transaction_mode}"')
    self.join_transaction_mode = join_transaction_mode
    self.twophase = twophase
    self._query_cls = query_cls if query_cls else query.Query
    if info:
        self.info.update(info)
    if binds is not None:
        for key, bind in binds.items():
            self._add_bind(key, bind)
    _sessions[self.hash_key] = self

def get_transaction(self) -> Optional[SessionTransaction]:
    trans = self._transaction
    while trans is not None and trans._parent is not None:
        trans = trans._parent
    return trans

@util.memoized_property
def info(self) -> _InfoType:
    return {}

def begin(self, nested: bool=False) -> SessionTransaction:
    trans = self._transaction
    if trans is None:
        trans = self._autobegin_t(begin=True)
        if not nested:
            return trans
    assert trans is not None
    if nested:
        trans = trans._begin(nested=nested)
        assert self._transaction is trans
        self._nested_transaction = trans
    else:
        raise sa_exc.InvalidRequestError('A transaction is already begun on this Session.')
    return trans

def rollback(self) -> None:
    if self._transaction is None:
        pass
    else:
        self._transaction.rollback(_to_root=True)

def commit(self) -> None:
    trans = self._transaction
    if trans is None:
        trans = self._autobegin_t()
    trans.commit(_to_root=True)

def prepare(self) -> None:
    trans = self._transaction
    if trans is None:
        trans = self._autobegin_t()
    trans.prepare()

def connection(self, bind_arguments: Optional[_BindArguments]=None, execution_options: Optional[CoreExecuteOptionsParameter]=None) -> Connection:
    if bind_arguments:
        bind = bind_arguments.pop('bind', None)
        if bind is None:
            bind = self.get_bind(**bind_arguments)
    else:
        bind = self.get_bind()
    return self._connection_for_bind(bind, execution_options=execution_options)

def expunge_all(self) -> None:
    all_states = self.identity_map.all_states() + list(self._new)
    self.identity_map._kill()
    self.identity_map = identity._WeakInstanceDict()
    self._new = {}
    self._deleted = {}
    statelib.InstanceState._detach_states(all_states, self)

def get_bind(self, mapper: Optional[_EntityBindKey[_O]]=None, *, clause: Optional[ClauseElement]=None, bind: Optional[_SessionBind]=None, _sa_skip_events: Optional[bool]=None, _sa_skip_for_implicit_returning: bool=False, **kw: Any) -> Union[Engine, Connection]:
    if bind:
        return bind
    elif not self.__binds and self.bind:
        return self.bind
    if mapper is None and clause is None:
        if self.bind:
            return self.bind
        else:
            raise sa_exc.UnboundExecutionError('This session is not bound to a single Engine or Connection, and no context was provided to locate a binding.')
    if mapper is not None:
        try:
            inspected_mapper = inspect(mapper)
        except sa_exc.NoInspectionAvailable as err:
            if isinstance(mapper, type):
                raise exc.UnmappedClassError(mapper) from err
            else:
                raise
    else:
        inspected_mapper = None
    if self.__binds:
        if inspected_mapper:
            for cls in inspected_mapper.class_.__mro__:
                if cls in self.__binds:
                    return self.__binds[cls]
            if clause is None:
                clause = inspected_mapper.persist_selectable
        if clause is not None:
            plugin_subject = clause._propagate_attrs.get('plugin_subject', None)
            if plugin_subject is not None:
                for cls in plugin_subject.mapper.class_.__mro__:
                    if cls in self.__binds:
                        return self.__binds[cls]
            for obj in visitors.iterate(clause):
                if obj in self.__binds:
                    if TYPE_CHECKING:
                        assert isinstance(obj, Table)
                    return self.__binds[obj]
    if self.bind:
        return self.bind
    context = []
    if inspected_mapper is not None:
        context.append(f'mapper {inspected_mapper}')
    if clause is not None:
        context.append('SQL expression')
    raise sa_exc.UnboundExecutionError(f"Could not locate a bind configured on {', '.join(context)} or this Session.")

@util.non_memoized_property
@contextlib.contextmanager
def no_autoflush(self) -> Iterator[Session]:
    autoflush = self.autoflush
    self.autoflush = False
    try:
        yield self
    finally:
        self.autoflush = autoflush

def refresh(self, instance: object, attribute_names: Optional[Iterable[str]]=None, with_for_update: ForUpdateParameter=None) -> None:
    try:
        state = attributes.instance_state(instance)
    except exc.NO_STATE as err:
        raise exc.UnmappedInstanceError(instance) from err
    self._expire_state(state, attribute_names)
    self._autoflush()
    if with_for_update == {}:
        raise sa_exc.ArgumentError('with_for_update should be the boolean value True, or a dictionary with options.  A blank dictionary is ambiguous.')
    with_for_update = ForUpdateArg._from_argument(with_for_update)
    stmt: Select[Unpack[TupleAny]] = sql.select(object_mapper(instance))
    if loading._load_on_ident(self, stmt, state.key, refresh_state=state, with_for_update=with_for_update, only_load_props=attribute_names, require_pk_cols=True, no_autoflush=True, is_user_refresh=True) is None:
        raise sa_exc.InvalidRequestError("Could not refresh instance '%s'" % instance_str(instance))

def expire_all(self) -> None:
    for state in self.identity_map.all_states():
        state._expire(state.dict, self.identity_map._modified)

def expire(self, instance: object, attribute_names: Optional[Iterable[str]]=None) -> None:
    try:
        state = attributes.instance_state(instance)
    except exc.NO_STATE as err:
        raise exc.UnmappedInstanceError(instance) from err
    self._expire_state(state, attribute_names)

def _conditional_expire(self, state: InstanceState[Any], autoflush: Optional[bool]=None) -> None:
    if state.key:
        state._expire(state.dict, self.identity_map._modified)
    elif state in self._new:
        self._new.pop(state)
        state._detach(self)

def expunge(self, instance: object) -> None:
    try:
        state = attributes.instance_state(instance)
    except exc.NO_STATE as err:
        raise exc.UnmappedInstanceError(instance) from err
    if state.session_id is not self.hash_key:
        raise sa_exc.InvalidRequestError('Instance %s is not present in this Session' % state_str(state))
    cascaded = list(state.manager.mapper.cascade_iterator('expunge', state))
    self._expunge_states([state] + [st_ for o, m, st_, dct_ in cascaded])

def _register_persistent(self, states: Set[InstanceState[Any]]) -> None:
    pending_to_persistent = self.dispatch.pending_to_persistent or None
    for state in states:
        mapper = _state_mapper(state)
        obj = state.obj()
        if obj is not None:
            instance_key = mapper._identity_key_from_state(state)
            if _none_set.intersection(instance_key[1]) and (not mapper.allow_partial_pks) or _none_set.issuperset(instance_key[1]):
                raise exc.FlushError('Instance %s has a NULL identity key.  If this is an auto-generated value, check that the database table allows generation of new primary key values, and that the mapped Column object is configured to expect these generated values.  Ensure also that this flush() is not occurring at an inappropriate time, such as within a load() event.' % state_str(state))
            if state.key is None:
                state.key = instance_key
            elif state.key != instance_key:
                self.identity_map.safe_discard(state)
                trans = self._transaction
                assert trans is not None
                if state in trans._key_switches:
                    orig_key = trans._key_switches[state][0]
                else:
                    orig_key = state.key
                trans._key_switches[state] = (orig_key, instance_key)
                state.key = instance_key
            old = self.identity_map.replace(state)
            if old is not None and mapper._identity_key_from_state(old) == instance_key and (old.obj() is not None):
                util.warn('Identity map already had an identity for %s, replacing it with newly flushed object.   Are there load operations occurring inside of an event handler within the flush?' % (instance_key,))
            state._orphaned_outside_of_session = False
    statelib.InstanceState._commit_all_states(((state, state.dict) for state in states), self.identity_map)
    self._register_altered(states)
    if pending_to_persistent is not None:
        for state in states.intersection(self._new):
            pending_to_persistent(self, state)
    for state in set(states).intersection(self._new):
        self._new.pop(state)

def add(self, instance: object, *, _warn: bool=True) -> None:
    if _warn and self._warn_on_events:
        self._flush_warning('Session.add()')
    try:
        state = attributes.instance_state(instance)
    except exc.NO_STATE as err:
        raise exc.UnmappedInstanceError(instance) from err
    self._save_or_update_state(state)

def add_all(self, instances: Iterable[object]) -> None:
    if self._warn_on_events:
        self._flush_warning('Session.add_all()')
    for instance in instances:
        self.add(instance, _warn=False)

def delete(self, instance: object) -> None:
    if self._warn_on_events:
        self._flush_warning('Session.delete()')
    self._delete_impl(object_state(instance), instance, head=True)

def delete_all(self, instances: Iterable[object]) -> None:
    if self._warn_on_events:
        self._flush_warning('Session.delete_all()')
    for instance in instances:
        self._delete_impl(object_state(instance), instance, head=True)

def merge(self, instance: _O, *, load: bool=True, options: Optional[Sequence[ORMOption]]=None) -> _O:
    if self._warn_on_events:
        self._flush_warning('Session.merge()')
    if load:
        self._autoflush()
    with self.no_autoflush:
        return self._merge(object_state(instance), attributes.instance_dict(instance), load=load, options=options, _recursive={}, _resolve_conflict_map={})

def merge_all(self, instances: Iterable[_O], *, load: bool=True, options: Optional[Sequence[ORMOption]]=None) -> Sequence[_O]:
    if self._warn_on_events:
        self._flush_warning('Session.merge_all()')
    if load:
        self._autoflush()
    return [self._merge(object_state(instance), attributes.instance_dict(instance), load=load, options=options, _recursive={}, _resolve_conflict_map={}) for instance in instances]

def enable_relationship_loading(self, obj: object) -> None:
    try:
        state = attributes.instance_state(obj)
    except exc.NO_STATE as err:
        raise exc.UnmappedInstanceError(obj) from err
    to_attach = self._before_attach(state, obj)
    state._load_pending = True
    if to_attach:
        self._after_attach(state, obj)

def __contains__(self, instance: object) -> bool:
    try:
        state = attributes.instance_state(instance)
    except exc.NO_STATE as err:
        raise exc.UnmappedInstanceError(instance) from err
    return self._contains_state(state)

def flush(self, objects: Optional[Sequence[Any]]=None) -> None:
    if self._flushing:
        raise sa_exc.InvalidRequestError('Session is already flushing')
    if self._is_clean():
        return
    try:
        self._flushing = True
        self._flush(objects)
    finally:
        self._flushing = False

def bulk_save_objects(self, objects: Iterable[object], return_defaults: bool=False, update_changed_only: bool=True, preserve_order: bool=True) -> None:
    obj_states: Iterable[InstanceState[Any]]
    obj_states = (attributes.instance_state(obj) for obj in objects)
    if not preserve_order:
        obj_states = sorted(obj_states, key=lambda state: (id(state.mapper), state.key is not None))

    def grouping_key(state: InstanceState[_O]) -> Tuple[Mapper[_O], bool]:
        return (state.mapper, state.key is not None)
    for (mapper, isupdate), states in itertools.groupby(obj_states, grouping_key):
        self._bulk_save_mappings(mapper, states, isupdate=isupdate, isstates=True, return_defaults=return_defaults, update_changed_only=update_changed_only, render_nulls=False)

def is_modified(self, instance: object, include_collections: bool=True) -> bool:
    state = object_state(instance)
    if not state.modified:
        return False
    dict_ = state.dict
    for attr in state.manager.attributes:
        if not include_collections and hasattr(attr.impl, 'get_collection') or not hasattr(attr.impl, 'get_history'):
            continue
        added, unchanged, deleted = attr.impl.get_history(state, dict_, passive=PassiveFlag.NO_CHANGE)
        if added or deleted:
            return True
    else:
        return False

@property
def is_active(self) -> bool:
    return self._transaction is None or self._transaction.is_active

@property
def _dirty_states(self) -> Iterable[InstanceState[Any]]:
    return self.identity_map._dirty_states()

@property
def dirty(self) -> IdentitySet:
    return IdentitySet([state.obj() for state in self._dirty_states if state not in self._deleted])

@property
def deleted(self) -> IdentitySet:
    return util.IdentitySet(list(self._deleted.values()))

@property
def new(self) -> IdentitySet:
    return util.IdentitySet(list(self._new.values()))

def begin(self) -> contextlib.AbstractContextManager[_S]:
    session = self()
    return session._maker_context_manager()

def __call__(self, **local_kw: Any) -> _S:
    for k, v in self.kw.items():
        if k == 'info' and 'info' in local_kw:
            d = v.copy()
            d.update(local_kw['info'])
            local_kw['info'] = d
        else:
            local_kw.setdefault(k, v)
    return self.class_(**local_kw)

def close_all_sessions() -> None:
    for sess in _sessions.values():
        sess.close()

def make_transient(instance: object) -> None:
    state = attributes.instance_state(instance)
    s = _state_session(state)
    if s:
        s._expunge_states([state])
    state.expired_attributes.clear()
    if state.callables:
        del state.callables
    if state.key:
        del state.key
    if state._deleted:
        del state._deleted

def make_transient_to_detached(instance: object) -> None:
    state = attributes.instance_state(instance)
    if state.session_id or state.key:
        raise sa_exc.InvalidRequestError('Given object must be transient')
    state.key = state.mapper._identity_key_from_state(state)
    if state._deleted:
        del state._deleted
    state._commit_all(state.dict)
    state._expire_attributes(state.dict, state.unloaded)

def object_session(instance: object) -> Optional[Session]:
    try:
        state = attributes.instance_state(instance)
    except exc.NO_STATE as err:
        raise exc.UnmappedInstanceError(instance) from err
    else:
        return _state_session(state)

@util.memoized_property
def attrs(self) -> util.ReadOnlyProperties[AttributeState]:
    return util.ReadOnlyProperties({key: AttributeState(self, key) for key in self.manager})

@property
def transient(self) -> bool:
    return self.key is None and (not self._attached)

@property
def pending(self) -> bool:
    return self.key is None and self._attached

@property
def deleted(self) -> bool:
    return self.key is not None and self._attached and self._deleted

@property
def was_deleted(self) -> bool:
    return self._deleted

@property
def persistent(self) -> bool:
    return self.key is not None and self._attached and (not self._deleted)

@property
def detached(self) -> bool:
    return self.key is not None and (not self._attached)

def _track_last_known_value(self, key: str) -> None:
    lkv = self._last_known_values
    if lkv is None:
        self._last_known_values = lkv = {}
    if key not in lkv:
        lkv[key] = NO_VALUE

@property
def session(self) -> Optional[Session]:
    if self.session_id:
        try:
            return _sessions[self.session_id]
        except KeyError:
            pass
    return None

@property
def async_session(self) -> Optional[AsyncSession]:
    if _async_provider is None:
        return None
    sess = self.session
    if sess is not None:
        return _async_provider(sess)
    else:
        return None

@property
def object(self) -> Optional[_O]:
    return self.obj()

@property
def identity(self) -> Optional[Tuple[Any, ...]]:
    if self.key is None:
        return None
    else:
        return self.key[1]

@property
def identity_key(self) -> Optional[_IdentityKeyType[_O]]:
    return self.key

@util.memoized_property
def mapper(self) -> Mapper[_O]:
    return self.manager.mapper

@property
def has_identity(self) -> bool:
    return bool(self.key)

def _cleanup(self, ref: weakref.ref[_O]) -> None:
    if dict is None:
        return
    instance_dict = self._instance_dict()
    if instance_dict is not None:
        instance_dict._fast_discard(self)
        del self._instance_dict
    self.session_id = self._strong_obj = None

@property
def dict(self) -> _InstanceDict:
    o = self.obj()
    if o is not None:
        return base.instance_dict(o)
    else:
        return {}

def _reset(self, dict_: _InstanceDict, key: str) -> None:
    old = dict_.pop(key, None)
    manager_impl = self.manager[key].impl
    if old is not None and is_collection_impl(manager_impl):
        manager_impl._invalidate_collection(old)
    self.expired_attributes.discard(key)
    if self.callables:
        self.callables.pop(key, None)

@property
def unmodified(self) -> Set[str]:
    return set(self.manager).difference(self.committed_state)

@property
def unloaded(self) -> Set[str]:
    return set(self.manager).difference(self.committed_state).difference(self.dict)

@property
@util.deprecated('2.0', 'The :attr:`.InstanceState.unloaded_expirable` attribute is deprecated.  Please use :attr:`.InstanceState.unloaded`.')
def unloaded_expirable(self) -> Set[str]:
    return self.unloaded

def _commit(self, dict_: _InstanceDict, keys: Iterable[str]) -> None:
    for key in keys:
        self.committed_state.pop(key, None)
    self.expired = False
    self.expired_attributes.difference_update(set(keys).intersection(dict_))
    if self.callables:
        for key in set(self.callables).intersection(keys).intersection(dict_):
            del self.callables[key]

@classmethod
def _commit_all_states(self, iter_: Iterable[Tuple[InstanceState[Any], _InstanceDict]], instance_dict: Optional[IdentityMap]=None) -> None:
    for state, dict_ in iter_:
        state_dict = state.__dict__
        state.committed_state.clear()
        if '_pending_mutations' in state_dict:
            del state_dict['_pending_mutations']
        state.expired_attributes.difference_update(dict_)
        if instance_dict and state.modified:
            instance_dict._modified.discard(state)
        state.modified = state.expired = False
        state._strong_obj = None

@property
def loaded_value(self) -> Any:
    return self.state.dict.get(self.key, NO_VALUE)

@property
def value(self) -> Any:
    return self.state.manager[self.key].__get__(self.state.obj(), self.state.class_)

@property
def history(self) -> History:
    return self.state.get_history(self.key, PASSIVE_NO_INITIALIZE)

@classmethod
def declare_states(cls, prerequisite_states: Union[Literal[_StateChangeStates.ANY], Tuple[_StateChangeState, ...]], moves_to: _StateChangeState) -> Callable[[_F], _F]:
    assert prerequisite_states, 'no prerequisite states sent'
    has_prerequisite_states = prerequisite_states is not _StateChangeStates.ANY
    prerequisite_state_collection = cast('Tuple[_StateChangeState, ...]', prerequisite_states)
    expect_state_change = moves_to is not _StateChangeStates.NO_CHANGE

    @util.decorator
    def _go(fn: _F, self: Any, *arg: Any, **kw: Any) -> Any:
        current_state = self._state
        if has_prerequisite_states and current_state not in prerequisite_state_collection:
            self._raise_for_prerequisite_state(fn.__name__, current_state)
        next_state = self._next_state
        existing_fn = self._current_fn
        expect_state = moves_to if expect_state_change else current_state
        if next_state is not _StateChangeStates.ANY and expect_state_change and (next_state is not expect_state):
            if existing_fn and next_state in (_StateChangeStates.NO_CHANGE, _StateChangeStates.CHANGE_IN_PROGRESS):
                raise sa_exc.IllegalStateChangeError(f"Method '{fn.__name__}()' can't be called here; method '{existing_fn.__name__}()' is already in progress and this would cause an unexpected state change to {moves_to!r}", code='isce')
            else:
                raise sa_exc.IllegalStateChangeError(f"Can't run operation '{fn.__name__}()' here; will move to state {moves_to!r} where we are expecting {next_state!r}", code='isce')
        self._current_fn = fn
        self._next_state = _StateChangeStates.CHANGE_IN_PROGRESS
        try:
            ret_value = fn(self, *arg, **kw)
        except:
            raise
        else:
            if self._state is expect_state:
                return ret_value
            if self._state is current_state:
                raise sa_exc.IllegalStateChangeError(f"Method '{fn.__name__}()' failed to change state to {moves_to!r} as expected", code='isce')
            elif existing_fn:
                raise sa_exc.IllegalStateChangeError(f"While method '{existing_fn.__name__}()' was running, method '{fn.__name__}()' caused an unexpected state change to {self._state!r}", code='isce')
            else:
                raise sa_exc.IllegalStateChangeError(f"Method '{fn.__name__}()' caused an unexpected state change to {self._state!r}", code='isce')
        finally:
            self._next_state = next_state
            self._current_fn = existing_fn
    return _go

@contextlib.contextmanager
def _expect_state(self, expected: _StateChangeState) -> Iterator[Any]:
    assert self._next_state is _StateChangeStates.CHANGE_IN_PROGRESS, 'Unexpected call to _expect_state outside of state-changing method'
    self._next_state = expected
    try:
        yield
    except:
        raise
    else:
        if self._state is not expected:
            raise sa_exc.IllegalStateChangeError(f'Unexpected state change to {self._state!r}', code='isce')
    finally:
        self._next_state = _StateChangeStates.CHANGE_IN_PROGRESS

def setup_query(self, compile_state, query_entity, path, loadopt, adapter, column_collection=None, parentmapper=None, chained_from_outerjoin=False, **kwargs):
    if not compile_state.compile_options._enable_eagerloads:
        return
    elif loadopt and compile_state.statement is not None and compile_state.statement.is_dml:
        util.warn_deprecated('The joinedload loader option is not compatible with DML statements such as INSERT, UPDATE.  Only SELECT may be used.This warning will become an exception in a future release.', '2.0')
    elif self.uselist:
        compile_state.multi_row_eager_loaders = True
    path = path[self.parent_property]
    user_defined_adapter = self._init_user_defined_eager_proc(loadopt, compile_state, compile_state.attributes) if loadopt else False
    if user_defined_adapter is not False:
        clauses, adapter, add_to_collection = self._setup_query_on_user_defined_adapter(compile_state, query_entity, path, adapter, user_defined_adapter)
    else:
        if not path.contains(compile_state.attributes, 'loader'):
            if self.join_depth:
                if path.length / 2 > self.join_depth:
                    return
            elif path.contains_mapper(self.mapper):
                return
        clauses, adapter, add_to_collection, chained_from_outerjoin = self._generate_row_adapter(compile_state, query_entity, path, loadopt, adapter, column_collection, parentmapper, chained_from_outerjoin)
        compile_state.eager_adding_joins = True
    with_poly_entity = path.get(compile_state.attributes, 'path_with_polymorphic', None)
    if with_poly_entity is not None:
        with_polymorphic = inspect(with_poly_entity).with_polymorphic_mappers
    else:
        with_polymorphic = None
    path = path[self.entity]
    loading._setup_entity_query(compile_state, self.mapper, query_entity, path, clauses, add_to_collection, with_polymorphic=with_polymorphic, parentmapper=self.mapper, chained_from_outerjoin=chained_from_outerjoin)
    has_nones = util.NONE_SET.intersection(compile_state.secondary_columns)
    if has_nones:
        if with_poly_entity is not None:
            raise sa_exc.InvalidRequestError('Detected unaliased columns when generating joined load.  Make sure to use aliased=True or flat=True when using joined loading with with_polymorphic().')
        else:
            compile_state.secondary_columns = [c for c in compile_state.secondary_columns if c is not None]

def contains_eager(self, attr: _AttrType, alias: Optional[_FromClauseArgument]=None, _is_chain: bool=False, _propagate_to_loaders: bool=False) -> Self:
    if alias is not None:
        if not isinstance(alias, str):
            coerced_alias = coercions.expect(roles.FromClauseRole, alias)
        else:
            util.warn_deprecated("Passing a string name for the 'alias' argument to 'contains_eager()` is deprecated, and will not work in a future release.  Please use a sqlalchemy.alias() or sqlalchemy.orm.aliased() construct.", version='1.4')
            coerced_alias = alias
    elif getattr(attr, '_of_type', None):
        assert isinstance(attr, QueryableAttribute)
        ot: Optional[_InternalEntityType[Any]] = inspect(attr._of_type)
        assert ot is not None
        coerced_alias = ot.selectable
    else:
        coerced_alias = None
    cloned = self._set_relationship_strategy(attr, {'lazy': 'joined'}, propagate_to_loaders=_propagate_to_loaders, opts={'eager_from_alias': coerced_alias}, _reconcile_to_other=True if _is_chain else None)
    return cloned

def load_only(self, *attrs: _AttrType, raiseload: bool=False) -> Self:
    cloned = self._set_column_strategy(_expand_column_strategy_attrs(attrs), {'deferred': False, 'instrument': True})
    wildcard_strategy = {'deferred': True, 'instrument': True}
    if raiseload:
        wildcard_strategy['raiseload'] = True
    cloned = cloned._set_column_strategy(('*',), wildcard_strategy)
    return cloned

def joinedload(self, attr: _AttrType, innerjoin: Optional[bool]=None) -> Self:
    loader = self._set_relationship_strategy(attr, {'lazy': 'joined'}, opts={'innerjoin': innerjoin} if innerjoin is not None else util.EMPTY_DICT)
    return loader

def immediateload(self, attr: _AttrType, recursion_depth: Optional[int]=None) -> Self:
    loader = self._set_relationship_strategy(attr, {'lazy': 'immediate'}, opts={'recursion_depth': recursion_depth})
    return loader

@util.deprecated('2.1', 'The :func:`_orm.noload` option is deprecated and will be removed in a future release.  This option produces incorrect results by returning ``None`` for related items.')
def noload(self, attr: _AttrType) -> Self:
    return self._set_relationship_strategy(attr, {'lazy': 'noload'})

def defer(self, key: _AttrType, raiseload: bool=False) -> Self:
    strategy = {'deferred': True, 'instrument': True}
    if raiseload:
        strategy['raiseload'] = True
    return self._set_column_strategy(_expand_column_strategy_attrs((key,)), strategy)

def with_expression(self, key: _AttrType, expression: _ColumnExpressionArgument[Any]) -> Self:
    expression = _orm_full_deannotate(coercions.expect(roles.LabeledColumnExprRole, expression))
    return self._set_column_strategy((key,), {'query_expression': True}, extra_criteria=(expression,))

def selectin_polymorphic(self, classes: Iterable[Type[Any]]) -> Self:
    self = self._set_class_strategy({'selectinload_polymorphic': True}, opts={'entities': tuple(sorted((inspect(cls) for cls in classes), key=id))})
    return self

def _adjust_for_extra_criteria(self, context: QueryContext) -> Load:
    for value in self.context:
        if value._extra_criteria:
            break
    else:
        return self
    replacement_cache_key = context.user_passed_query._generate_cache_key()
    if replacement_cache_key is None:
        return self
    orig_query = context.compile_state.select_statement
    orig_cache_key = orig_query._generate_cache_key()
    assert orig_cache_key is not None

    def process(opt: _LoadElement, replacement_cache_key: CacheKey, orig_cache_key: CacheKey) -> _LoadElement:
        cloned_opt = opt._clone()
        cloned_opt._extra_criteria = tuple((replacement_cache_key._apply_params_to_element(orig_cache_key, crit) for crit in cloned_opt._extra_criteria))
        return cloned_opt
    cloned = self._clone()
    cloned.context = tuple((process(value, replacement_cache_key, orig_cache_key) if value._extra_criteria else value for value in self.context))
    return cloned

def _reconcile_query_entities_with_us(self, mapper_entities, raiseerr):
    path = self.path
    for ent in mapper_entities:
        ezero = ent.entity_zero
        if ezero and orm_util._entity_corresponds_to(ezero, cast('_InternalEntityType[Any]', path[0])):
            return ezero
    return None

def _apply_to_parent(self, parent: Load) -> None:
    cloned = self._generate()
    assert cloned.propagate_to_loaders == self.propagate_to_loaders
    if not any((orm_util._entity_corresponds_to_use_path_impl(elem, cloned.path.odd_element(0)) for elem in (parent.path.odd_element(-1),) + parent.additional_source_entities)):
        if len(cloned.path) > 1:
            attrname = cloned.path[1]
            parent_entity = cloned.path[0]
        else:
            attrname = cloned.path[0]
            parent_entity = cloned.path[0]
        _raise_for_does_not_link(parent.path, attrname, parent_entity)
    cloned.path = PathRegistry.coerce(parent.path[0:-1] + cloned.path[:])
    if self.context:
        cloned.context = tuple((value._prepend_path_from(parent) for value in self.context))
    if cloned.context:
        parent.context += cloned.context
        parent.additional_source_entities += cloned.additional_source_entities

@_generative
def options(self, *opts: _AbstractLoad) -> Self:
    for opt in opts:
        try:
            opt._apply_to_parent(self)
        except AttributeError as ae:
            if not isinstance(opt, _AbstractLoad):
                raise sa_exc.ArgumentError(f'Loader option {opt} is not compatible with the Load.options() method.') from ae
            else:
                raise
    return self

def process_compile_state(self, parent_loader, compile_state, mapper_entities, reconciled_lead_entity, raiseerr):
    keys = self._prepare_for_compile_state(parent_loader, compile_state, mapper_entities, reconciled_lead_entity, raiseerr)
    for key in keys:
        if key in compile_state.attributes:
            compile_state.attributes[key] = _LoadElement._reconcile(self, compile_state.attributes[key])
        else:
            compile_state.attributes[key] = self

def _prepend_path_from(self, parent: Load) -> _LoadElement:
    if not any((orm_util._entity_corresponds_to_use_path_impl(elem, self.path.odd_element(0)) for elem in (parent.path.odd_element(-1),) + parent.additional_source_entities)):
        raise sa_exc.ArgumentError(f'Attribute "{self.path[1]}" does not link from element "{entity_str(parent.path[-1])}".')
    return self._prepend_path(parent.path)

@staticmethod
def _reconcile(replacement: _LoadElement, existing: _LoadElement) -> _LoadElement:
    if replacement._reconcile_to_other:
        return existing
    elif replacement._reconcile_to_other is False:
        return replacement
    elif existing._reconcile_to_other:
        return replacement
    elif existing._reconcile_to_other is False:
        return existing
    if existing is replacement:
        return replacement
    elif existing.strategy == replacement.strategy and existing.local_opts == replacement.local_opts:
        return replacement
    elif replacement.is_opts_only:
        existing = existing._clone()
        existing.local_opts = existing.local_opts.union(replacement.local_opts)
        existing._extra_criteria += replacement._extra_criteria
        return existing
    elif existing.is_opts_only:
        replacement = replacement._clone()
        replacement.local_opts = replacement.local_opts.union(existing.local_opts)
        replacement._extra_criteria += existing._extra_criteria
        return replacement
    elif replacement.path.is_token:
        return replacement
    raise sa_exc.InvalidRequestError(f'Loader strategy replacement {replacement._to_option_method_string()} is in conflict with existing strategy {existing._to_option_method_string()}')

def _to_option_method_string(self) -> str:
    assert self.strategy is not None, 'to_option_method_string() requires a strategy to be set'
    for opt_key in self.local_opts:
        fn = _STRATEGY_FN_LABELS.get((self.strategy, opt_key))
        if fn:
            break
    else:
        fn = _STRATEGY_FN_LABELS.get((self.strategy, None))
    assert fn is not None, f'No _STRATEGY_FN_LABELS entry for strategy {self.strategy!r}'
    return f'{fn}({self.path.path_string()})'

def _prepend_path(self, path: PathRegistry) -> Self:
    cloned = super()._prepend_path(path)
    if self._path_with_polymorphic_path is not None:
        cloned._path_with_polymorphic_path = PathRegistry.coerce(path[0:-1] + self._path_with_polymorphic_path[:])
    return cloned

def _parse_attr_argument(attr: _AttrType) -> Tuple[InspectionAttr, _InternalEntityType[Any], MapperProperty[Any]]:
    try:
        insp: InspectionAttr = inspect(attr)
    except sa_exc.NoInspectionAvailable as err:
        raise sa_exc.ArgumentError('expected ORM mapped attribute for loader strategy argument') from err
    lead_entity: _InternalEntityType[Any]
    if insp_is_mapper_property(insp):
        lead_entity = insp.parent
        prop = insp
    elif insp_is_attribute(insp):
        lead_entity = insp.parent
        prop = insp.prop
    else:
        raise sa_exc.ArgumentError('expected ORM mapped attribute for loader strategy argument')
    return (insp, lead_entity, prop)

def _strategy_labels(*strategy_keys: 'Any', discriminating_opt: Optional[str]=None) -> Callable[[_FN], _FN]:

    def decorator(fn: _FN) -> _FN:
        for key in strategy_keys:
            _STRATEGY_FN_LABELS[key, discriminating_opt] = fn.__name__
        return fn
    return decorator

def _source_modified(uowcommit, source, source_mapper, synchronize_pairs):
    for l, r in synchronize_pairs:
        try:
            prop = source_mapper._columntoproperty[l]
        except exc.UnmappedColumnError as err:
            _raise_col_to_prop(False, source_mapper, l, None, r, err)
        history = uowcommit.get_attribute_history(source, prop.key, PassiveFlag.PASSIVE_NO_INITIALIZE)
        if bool(history.deleted):
            return True
    else:
        return False

def _track_cascade_events(descriptor, prop):
    key = prop.key

    def append(state, item, initiator, **kw):
        if item is None:
            return
        sess = state.session
        if sess:
            if sess._warn_on_events:
                sess._flush_warning('collection append')
            prop = state.manager.mapper._props[key]
            item_state = attributes.instance_state(item)
            if prop._cascade.save_update and key == initiator.key and (not sess._contains_state(item_state)):
                sess._save_or_update_state(item_state)
        return item

    def remove(state, item, initiator, **kw):
        if item is None:
            return
        sess = state.session
        prop = state.manager.mapper._props[key]
        if sess and sess._warn_on_events:
            sess._flush_warning('collection remove' if prop.uselist else 'related attribute delete')
        if item is not None and item is not attributes.NEVER_SET and (item is not attributes.PASSIVE_NO_RESULT) and prop._cascade.delete_orphan:
            item_state = attributes.instance_state(item)
            if prop.mapper._is_orphan(item_state):
                if sess and item_state in sess._new:
                    sess.expunge(item)
                else:
                    item_state._orphaned_outside_of_session = True

    def set_(state, newvalue, oldvalue, initiator, **kw):
        if oldvalue is newvalue:
            return newvalue
        sess = state.session
        if sess:
            if sess._warn_on_events:
                sess._flush_warning('related attribute set')
            prop = state.manager.mapper._props[key]
            if newvalue is not None:
                newvalue_state = attributes.instance_state(newvalue)
                if prop._cascade.save_update and key == initiator.key and (not sess._contains_state(newvalue_state)):
                    sess._save_or_update_state(newvalue_state)
            if oldvalue is not None and oldvalue is not attributes.NEVER_SET and (oldvalue is not attributes.PASSIVE_NO_RESULT) and prop._cascade.delete_orphan:
                oldvalue_state = attributes.instance_state(oldvalue)
                if oldvalue_state in sess._new and prop.mapper._is_orphan(oldvalue_state):
                    sess.expunge(oldvalue)
        return newvalue
    event.listen(descriptor, 'append_wo_mutation', append, raw=True, include_key=True)
    event.listen(descriptor, 'append', append, raw=True, retval=True, include_key=True)
    event.listen(descriptor, 'remove', remove, raw=True, retval=True, include_key=True)
    event.listen(descriptor, 'set', set_, raw=True, retval=True, include_key=True)

def was_already_deleted(self, state):
    if state.expired:
        try:
            state._load_expired(state, attributes.PASSIVE_OFF)
        except orm_exc.ObjectDeletedError:
            self.session._remove_newly_deleted([state])
            return True
    return False

def remove_state_actions(self, state):
    isdelete = self.states[state][0]
    self.states[state] = (isdelete, True)

def get_attribute_history(self, state, key, passive=attributes.PASSIVE_NO_INITIALIZE):
    hashkey = ('history', state, key)
    if hashkey in self.attributes:
        history, state_history, cached_passive = self.attributes[hashkey]
        if not cached_passive & attributes.SQL_OK and passive & attributes.SQL_OK:
            impl = state.manager[key].impl
            history = impl.get_history(state, state.dict, attributes.PASSIVE_OFF | attributes.LOAD_AGAINST_COMMITTED | attributes.NO_RAISE)
            if history and impl.uses_objects:
                state_history = history.as_state()
            else:
                state_history = history
            self.attributes[hashkey] = (history, state_history, passive)
    else:
        impl = state.manager[key].impl
        history = impl.get_history(state, state.dict, passive | attributes.LOAD_AGAINST_COMMITTED | attributes.NO_RAISE)
        if history and impl.uses_objects:
            state_history = history.as_state()
        else:
            state_history = history
        self.attributes[hashkey] = (history, state_history, passive)
    return state_history

@util.memoized_property
def _mapper_for_dep(self):
    return util.PopulateDict(lambda tup: tup[0]._props.get(tup[1].key) is tup[1].prop)

def filter_states_for_dep(self, dep, states):
    mapper_for_dep = self._mapper_for_dep
    return [s for s in states if mapper_for_dep[s.manager.mapper, dep]]

def _generate_actions(self):
    while True:
        ret = False
        for action in list(self.presort_actions.values()):
            if action.execute(self):
                ret = True
        if not ret:
            break
    self.cycles = cycles = topological.find_cycles(self.dependencies, list(self.postsort_actions.values()))
    if cycles:
        convert = {rec: set(rec.per_state_flush_actions(self)) for rec in cycles}
        for edge in list(self.dependencies):
            if None in edge or edge[0].disabled or edge[1].disabled or cycles.issuperset(edge):
                self.dependencies.remove(edge)
            elif edge[0] in cycles:
                self.dependencies.remove(edge)
                for dep in convert[edge[0]]:
                    self.dependencies.add((dep, edge[1]))
            elif edge[1] in cycles:
                self.dependencies.remove(edge)
                for dep in convert[edge[1]]:
                    self.dependencies.add((edge[0], dep))
    return {a for a in self.postsort_actions.values() if not a.disabled}.difference(cycles)

def finalize_flush_changes(self) -> None:
    if not self.states:
        return
    states = set(self.states)
    isdel = {s for s, (isdelete, listonly) in self.states.items() if isdelete}
    other = states.difference(isdel)
    if isdel:
        self.session._remove_newly_deleted(isdel)
    if other:
        self.session._register_persistent(other)

def _validator_events(desc, key, validator, include_removes, include_backrefs):
    if not include_backrefs:

        def detect_is_backref(state, initiator):
            impl = state.manager[key].impl
            return initiator.impl is not impl
    if include_removes:

        def append(state, value, initiator):
            if initiator.op is not attributes.OP_BULK_REPLACE and (include_backrefs or not detect_is_backref(state, initiator)):
                return validator(state.obj(), key, value, False)
            else:
                return value

        def bulk_set(state, values, initiator):
            if include_backrefs or not detect_is_backref(state, initiator):
                obj = state.obj()
                values[:] = [validator(obj, key, value, False) for value in values]

        def set_(state, value, oldvalue, initiator):
            if include_backrefs or not detect_is_backref(state, initiator):
                return validator(state.obj(), key, value, False)
            else:
                return value

        def remove(state, value, initiator):
            if include_backrefs or not detect_is_backref(state, initiator):
                validator(state.obj(), key, value, True)
    else:

        def append(state, value, initiator):
            if initiator.op is not attributes.OP_BULK_REPLACE and (include_backrefs or not detect_is_backref(state, initiator)):
                return validator(state.obj(), key, value)
            else:
                return value

        def bulk_set(state, values, initiator):
            if include_backrefs or not detect_is_backref(state, initiator):
                obj = state.obj()
                values[:] = [validator(obj, key, value) for value in values]

        def set_(state, value, oldvalue, initiator):
            if include_backrefs or not detect_is_backref(state, initiator):
                return validator(state.obj(), key, value)
            else:
                return value
    event.listen(desc, 'append', append, raw=True, retval=True)
    event.listen(desc, 'bulk_replace', bulk_set, raw=True)
    event.listen(desc, 'set', set_, raw=True, retval=True)
    if include_removes:
        event.listen(desc, 'remove', remove, raw=True, retval=True)

def polymorphic_union(table_map, typecolname, aliasname='p_union', cast_nulls=True):
    colnames: util.OrderedSet[str] = util.OrderedSet()
    colnamemaps = {}
    types = {}
    for key in table_map:
        table = table_map[key]
        table = coercions.expect(roles.FromClauseRole, table)
        table_map[key] = table
        m = {}
        for c in table.c:
            if c.key == typecolname:
                raise sa_exc.InvalidRequestError("Polymorphic union can't use '%s' as the discriminator column due to mapped column %r; please apply the 'typecolname' argument; this is available on ConcreteBase as '_concrete_discriminator_name'" % (typecolname, c))
            colnames.add(c.key)
            m[c.key] = c
            types[c.key] = c.type
        colnamemaps[table] = m

    def col(name, table):
        try:
            return colnamemaps[table][name]
        except KeyError:
            if cast_nulls:
                return sql.cast(sql.null(), types[name]).label(name)
            else:
                return sql.type_coerce(sql.null(), types[name]).label(name)
    result = []
    for type_, table in table_map.items():
        if typecolname is not None:
            result.append(sql.select(*[col(name, table) for name in colnames] + [sql.literal_column(sql_util._quote_ddl_expr(type_)).label(typecolname)]).select_from(table))
        else:
            result.append(sql.select(*[col(name, table) for name in colnames]).select_from(table))
    return sql.union_all(*result).alias(aliasname)

def identity_key(class_: Optional[Type[_T]]=None, ident: Union[Any, Tuple[Any, ...]]=None, *, instance: Optional[_T]=None, row: Optional[Union[Row[Unpack[TupleAny]], RowMapping]]=None, identity_token: Optional[Any]=None) -> _IdentityKeyType[_T]:
    if class_ is not None:
        mapper = class_mapper(class_)
        if row is None:
            if ident is None:
                raise sa_exc.ArgumentError('ident or row is required')
            return mapper.identity_key_from_primary_key(tuple(util.to_list(ident)), identity_token=identity_token)
        else:
            return mapper.identity_key_from_row(row, identity_token=identity_token)
    elif instance is not None:
        mapper = object_mapper(instance)
        return mapper.identity_key_from_instance(instance)
    else:
        raise sa_exc.ArgumentError('class or instance is required')

@property
def class_(self) -> Type[_O]:
    return self.mapper.class_

def path_string(self) -> str:
    if self._is_with_polymorphic:
        return 'with_polymorphic(%s, [%s])' % (self._target.__name__, ', '.join((mp.class_.__name__ for mp in self.with_polymorphic_mappers if mp is not self.mapper)))
    else:
        return 'aliased(%s)' % (self._target.__name__,)

def create_row_processor(self, query: Select[Unpack[TupleAny]], procs: Sequence[Callable[[Row[Unpack[TupleAny]]], Any]], labels: Sequence[str]) -> Callable[[Row[Unpack[TupleAny]]], Any]:
    keyed_tuple = result_tuple(labels, [() for l in labels])

    def proc(row: Row[Unpack[TupleAny]]) -> Any:
        return keyed_tuple([proc(row) for proc in procs])
    return proc

def _splice_into_center(self, other):
    leftmost = other
    while isinstance(leftmost, sql.Join):
        leftmost = leftmost.left
    assert self.right is leftmost
    left = _ORMJoin(self.left, other.left, self.onclause, isouter=self.isouter, _left_memo=self._left_memo, _right_memo=other._left_memo._path_registry)
    return _ORMJoin(left, other.right, other.onclause, isouter=other.isouter, _right_memo=other._right_memo)

def with_parent(instance: object, prop: attributes.QueryableAttribute[Any], from_entity: Optional[_EntityType[Any]]=None) -> ColumnElement[bool]:
    prop_t: RelationshipProperty[Any]
    if isinstance(prop, str):
        raise sa_exc.ArgumentError('with_parent() accepts class-bound mapped attributes, not strings')
    elif isinstance(prop, attributes.QueryableAttribute):
        if prop._of_type:
            from_entity = prop._of_type
        mapper_property = prop.property
        if mapper_property is None or not prop_is_relationship(mapper_property):
            raise sa_exc.ArgumentError(f'Expected relationship property for with_parent(), got {mapper_property}')
        prop_t = mapper_property
    else:
        prop_t = prop
    return prop_t._with_parent(instance, from_entity=from_entity)

