def __init__(self, creator: Union[_CreatorFnType, _CreatorWRecFnType], recycle: int=-1, echo: log._EchoFlagType=None, logging_name: Optional[str]=None, reset_on_return: _ResetStyleArgType=True, events: Optional[List[Tuple[_ListenerFnType, str]]]=None, dialect: Optional[Union[_ConnDialect, Dialect]]=None, pre_ping: bool=False, _dispatch: Optional[_DispatchCommon[Pool]]=None):
    if logging_name:
        self.logging_name = self._orig_logging_name = logging_name
    else:
        self._orig_logging_name = None
    log.instance_logger(self, echoflag=echo)
    self._creator = creator
    self._recycle = recycle
    self._invalidate_time = 0
    self._pre_ping = pre_ping
    self._reset_on_return = util.parse_user_argument_for_enum(reset_on_return, {ResetStyle.reset_rollback: ['rollback', True], ResetStyle.reset_none: ['none', None, False], ResetStyle.reset_commit: ['commit']}, 'reset_on_return')
    self.echo = echo
    if _dispatch:
        self.dispatch._update(_dispatch, only_propagate=False)
    if dialect:
        self._dialect = dialect
    if events:
        for fn, target in events:
            event.listen(self, target, fn)

def _should_wrap_creator(self, creator: Union[_CreatorFnType, _CreatorWRecFnType]) -> _CreatorWRecFnType:
    try:
        argspec = util.get_callable_argspec(self._creator, no_self=True)
    except TypeError:
        creator_fn = cast(_CreatorFnType, creator)
        return lambda rec: creator_fn()
    if argspec.defaults is not None:
        defaulted = len(argspec.defaults)
    else:
        defaulted = 0
    positionals = len(argspec[0]) - defaulted
    if (argspec[0], argspec[3]) == (['connection_record'], (None,)):
        return cast(_CreatorWRecFnType, creator)
    elif positionals == 1:
        return cast(_CreatorWRecFnType, creator)
    else:
        creator_fn = cast(_CreatorFnType, creator)
        return lambda rec: creator_fn()

def _invalidate(self, connection: PoolProxiedConnection, exception: Optional[BaseException]=None, _checkin: bool=True) -> None:
    rec = getattr(connection, '_connection_record', None)
    if not rec or self._invalidate_time < rec.starttime:
        self._invalidate_time = time.time()
    if _checkin and getattr(connection, 'is_valid', False):
        connection.invalidate(exception)

