def _cloned_intersection(a: Iterable[_CLE], b: Iterable[_CLE]) -> Set[_CLE]:
    all_overlap: Set[_CLE] = set(_expand_cloned(a)).intersection(_expand_cloned(b))
    return {elem for elem in a if all_overlap.intersection(elem._cloned_set)}

def get_dialect_option(self, dialect: Dialect, argument_name: str, *, else_: Any=None, deprecated_fallback: Optional[str]=None) -> Any:
    registry = DialectKWArgs._kw_registry[dialect.name]
    if registry is None:
        return else_
    if argument_name in registry.get(self.__class__, {}):
        if deprecated_fallback is None or dialect.name == deprecated_fallback:
            return self.dialect_options[dialect.name][argument_name]
        if dialect.name in self.dialect_options and argument_name in self.dialect_options[dialect.name]._non_defaults:
            return self.dialect_options[dialect.name][argument_name]
        elif deprecated_fallback in self.dialect_options and argument_name in self.dialect_options[deprecated_fallback]._non_defaults:
            warn_deprecated(f"Using '{deprecated_fallback}_{argument_name}' with the '{dialect.name}' dialect is deprecated; please additionally specify '{dialect.name}_{argument_name}'.", version='2.1')
            return self.dialect_options[deprecated_fallback][argument_name]
        return self.dialect_options[dialect.name][argument_name]
    else:
        return else_

