@contextlib.contextmanager
def _nested_result(self):
    result_columns, ordered_columns = (self._result_columns, self._ordered_columns)
    self._result_columns, self._ordered_columns = ([], False)
    try:
        if self.stack:
            entry = self.stack[-1]
            entry['need_result_map_for_nested'] = True
        else:
            entry = None
        yield (self._result_columns, self._ordered_columns)
    finally:
        if entry:
            entry.pop('need_result_map_for_nested')
        self._result_columns, self._ordered_columns = (result_columns, ordered_columns)

def construct_expanded_state(self, params: Optional[_CoreSingleExecuteParams]=None, escape_names: bool=True) -> ExpandedState:
    parameters = self.construct_params(params, escape_names=escape_names, _no_postcompile=True)
    return self._process_parameters_for_postcompile(parameters)

def construct_params(self, params: Optional[_CoreSingleExecuteParams]=None, extracted_parameters: Optional[Sequence[BindParameter[Any]]]=None, escape_names: bool=True, _group_number: Optional[int]=None, _check: bool=True, _no_postcompile: bool=False, _collected_params: _CoreSingleExecuteParams | None=None) -> _MutableCoreSingleExecuteParams:
    if _collected_params is not None:
        assert not self._collect_params
    elif self._collect_params:
        _collected_params = self._collected_params
    if _collected_params:
        if not params:
            params = _collected_params
        else:
            params = {**_collected_params, **params}
    if self._render_postcompile and (not _no_postcompile):
        assert self._post_compile_expanded_state is not None
        if not params:
            return dict(self._post_compile_expanded_state.parameters)
        else:
            raise exc.InvalidRequestError("can't construct new parameters when render_postcompile is used; the statement is hard-linked to the original parameters.  Use construct_expanded_state to generate a new statement and parameters.")
    has_escaped_names = escape_names and bool(self.escaped_bind_names)
    if extracted_parameters:
        if self.cache_key is None:
            raise exc.CompileError("This compiled object has no original cache key; can't pass extracted_parameters to construct_params")
        else:
            orig_extracted = self.cache_key[1]
        ckbm_tuple = self._cache_key_bind_match
        assert ckbm_tuple is not None
        ckbm, _ = ckbm_tuple
        resolved_extracted = {bind: extracted for b, extracted in zip(orig_extracted, extracted_parameters) for bind in ckbm[b]}
    else:
        resolved_extracted = None
    if params:
        pd = {}
        for bindparam, name in self.bind_names.items():
            escaped_name = self.escaped_bind_names.get(name, name) if has_escaped_names else name
            if bindparam.key in params:
                pd[escaped_name] = params[bindparam.key]
            elif name in params:
                pd[escaped_name] = params[name]
            elif _check and bindparam.required:
                if _group_number:
                    raise exc.InvalidRequestError('A value is required for bind parameter %r, in parameter group %d' % (bindparam.key, _group_number), code='cd3x')
                else:
                    raise exc.InvalidRequestError('A value is required for bind parameter %r' % bindparam.key, code='cd3x')
            else:
                if resolved_extracted:
                    value_param = resolved_extracted.get(bindparam, bindparam)
                else:
                    value_param = bindparam
                if bindparam.callable:
                    pd[escaped_name] = value_param.effective_value
                else:
                    pd[escaped_name] = value_param.value
        return pd
    else:
        pd = {}
        for bindparam, name in self.bind_names.items():
            escaped_name = self.escaped_bind_names.get(name, name) if has_escaped_names else name
            if _check and bindparam.required:
                if _group_number:
                    raise exc.InvalidRequestError('A value is required for bind parameter %r, in parameter group %d' % (bindparam.key, _group_number), code='cd3x')
                else:
                    raise exc.InvalidRequestError('A value is required for bind parameter %r' % bindparam.key, code='cd3x')
            if resolved_extracted:
                value_param = resolved_extracted.get(bindparam, bindparam)
            else:
                value_param = bindparam
            if bindparam.callable:
                pd[escaped_name] = value_param.effective_value
            else:
                pd[escaped_name] = value_param.value
        return pd

@property
def params(self):
    return self.construct_params(_check=False)

def _process_parameters_for_postcompile(self, parameters: _MutableCoreSingleExecuteParams, _populate_self: bool=False) -> ExpandedState:
    expanded_parameters = {}
    new_positiontup: Optional[List[str]]
    pre_expanded_string = self._pre_expanded_string
    if pre_expanded_string is None:
        pre_expanded_string = self.string
    if self.positional:
        new_positiontup = []
        pre_expanded_positiontup = self._pre_expanded_positiontup
        if pre_expanded_positiontup is None:
            pre_expanded_positiontup = self.positiontup
    else:
        new_positiontup = pre_expanded_positiontup = None
    processors = self._bind_processors
    single_processors = cast('Mapping[str, _BindProcessorType[Any]]', processors)
    tuple_processors = cast('Mapping[str, Sequence[_BindProcessorType[Any]]]', processors)
    new_processors: Dict[str, _BindProcessorType[Any]] = {}
    replacement_expressions: Dict[str, Any] = {}
    to_update_sets: Dict[str, Any] = {}
    numeric_positiontup: Optional[List[str]] = None
    if self.positional and pre_expanded_positiontup is not None:
        names: Iterable[str] = pre_expanded_positiontup
        if self._numeric_binds:
            numeric_positiontup = []
    else:
        names = self.bind_names.values()
    ebn = self.escaped_bind_names
    for name in names:
        escaped_name = ebn.get(name, name) if ebn else name
        parameter = self.binds[name]
        if parameter in self.literal_execute_params:
            if escaped_name not in replacement_expressions:
                replacement_expressions[escaped_name] = self.render_literal_bindparam(parameter, render_literal_value=parameters.pop(escaped_name))
            continue
        if parameter in self.post_compile_params:
            if escaped_name in replacement_expressions:
                to_update = to_update_sets[escaped_name]
                values = None
            else:
                values = parameters.pop(name)
                leep_res = self._literal_execute_expanding_parameter(escaped_name, parameter, values)
                to_update, replacement_expr = leep_res
                to_update_sets[escaped_name] = to_update
                replacement_expressions[escaped_name] = replacement_expr
            if not parameter.literal_execute:
                parameters.update(to_update)
                if parameter.type._is_tuple_type:
                    assert values is not None
                    new_processors.update((('%s_%s_%s' % (name, i, j), tuple_processors[name][j - 1]) for i, tuple_element in enumerate(values, 1) for j, _ in enumerate(tuple_element, 1) if name in tuple_processors and tuple_processors[name][j - 1] is not None))
                else:
                    new_processors.update(((key, single_processors[name]) for key, _ in to_update if name in single_processors))
                if numeric_positiontup is not None:
                    numeric_positiontup.extend((name for name, _ in to_update))
                elif new_positiontup is not None:
                    new_positiontup.extend((name for name, _ in to_update))
                expanded_parameters[name] = [expand_key for expand_key, _ in to_update]
        elif new_positiontup is not None:
            new_positiontup.append(name)

    def process_expanding(m):
        key = m.group(1)
        expr = replacement_expressions[key]
        if m.group(2):
            tok = m.group(2).split('~~')
            be_left, be_right = (tok[1], tok[3])
            expr = ', '.join(('%s%s%s' % (be_left, exp, be_right) for exp in expr.split(', ')))
        return expr
    statement = re.sub(self._post_compile_pattern, process_expanding, pre_expanded_string)
    if numeric_positiontup is not None:
        assert new_positiontup is not None
        param_pos = {key: f'{self._numeric_binds_identifier_char}{num}' for num, key in enumerate(numeric_positiontup, self.next_numeric_pos)}
        statement = self._pyformat_pattern.sub(lambda m: param_pos[m.group(1)], statement)
        new_positiontup.extend(numeric_positiontup)
    expanded_state = ExpandedState(statement, parameters, new_processors, new_positiontup, expanded_parameters)
    if _populate_self:
        self._pre_expanded_string = pre_expanded_string
        self._pre_expanded_positiontup = pre_expanded_positiontup
        self.string = expanded_state.statement
        self.positiontup = list(expanded_state.positiontup or ()) if self.positional else None
        self._post_compile_expanded_state = expanded_state
    return expanded_state

@util.preload_module('sqlalchemy.engine.cursor')
def _create_result_map(self):
    cursor = util.preloaded.engine_cursor
    return cursor.CursorResultMetaData._create_description_match_map(self._result_columns)

def get(lastrowid, parameters):
    if lastrowid_processor is not None:
        lastrowid = lastrowid_processor(lastrowid)
    if lastrowid is None:
        return row_fn((getter(parameters) for getter, col in getters))
    else:
        return row_fn(((autoinc_getter(lastrowid, parameters) if autoinc_getter is not None else lastrowid) if col is autoinc_col else getter(parameters) for getter, col in getters))

def visit_override_binds(self, override_binds, **kw):
    sqltext = override_binds.element._compiler_dispatch(self, **kw)
    for k in override_binds.translate:
        if k not in self.binds:
            continue
        bp = self.binds[k]
        new_bp = bp._with_value(override_binds.translate[bp.key], maintain_key=True, required=False)
        name = self.bind_names[bp]
        self.binds[k] = self.binds[name] = new_bp
        self.bind_names[new_bp] = name
        self.bind_names.pop(bp, None)
        if bp in self.post_compile_params:
            self.post_compile_params |= {new_bp}
        if bp in self.literal_execute_params:
            self.literal_execute_params |= {new_bp}
        ckbm_tuple = self._cache_key_bind_match
        if ckbm_tuple:
            ckbm, cksm = ckbm_tuple
            for bp in bp._cloned_set:
                if bp.key in cksm:
                    cb = cksm[bp.key]
                    ckbm[cb].append(new_bp)
    return sqltext

def render_literal_value(self, value: Any, type_: sqltypes.TypeEngine[Any]) -> str:
    if value is None and (not type_.should_evaluate_none):
        return self.process(elements.Null._instance())
    processor = type_._cached_literal_processor(self.dialect)
    if processor:
        try:
            return processor(value)
        except Exception as e:
            raise exc.CompileError(f'Could not render literal value "{sql_util._repr_single_value(value)}" with datatype {type_}; see parent stack trace for more detail.') from e
    else:
        raise exc.CompileError(f'No literal value renderer is available for literal value "{sql_util._repr_single_value(value)}" with datatype {type_}')

def _label_select_column(self, select, column, populate_result_map, asfrom, column_clause_args, name=None, proxy_name=None, fallback_label_name=None, within_columns_clause=True, column_is_repeated=False, need_column_expressions=False, include_table=True):
    impl = column.type.dialect_impl(self.dialect)
    if impl._has_column_expression and (need_column_expressions or populate_result_map):
        col_expr = impl.column_expression(column)
    else:
        col_expr = column
    if populate_result_map:
        add_to_result_map = self._add_to_result_map
        if column_is_repeated:
            _add_to_result_map = add_to_result_map

            def add_to_result_map(keyname, name, objects, type_):
                _add_to_result_map(keyname, name, (keyname,), type_)
        elif col_expr is not column:
            _add_to_result_map = add_to_result_map

            def add_to_result_map(keyname, name, objects, type_):
                _add_to_result_map(keyname, name, (column,) + objects, type_)
    else:
        add_to_result_map = None
    assert within_columns_clause, '_label_select_column is only relevant within the columns clause of a SELECT or RETURNING'
    result_expr: elements.Label[Any] | _CompileLabel
    if isinstance(column, elements.Label):
        if col_expr is not column:
            result_expr = _CompileLabel(col_expr, column.name, alt_names=(column.element,))
        else:
            result_expr = col_expr
    elif name:
        assert proxy_name is not None, "proxy_name is required if 'name' is passed"
        result_expr = _CompileLabel(col_expr, name, alt_names=(proxy_name, column._tq_label))
    else:
        if col_expr is not column:
            render_with_label = True
        elif isinstance(column, elements.ColumnClause):
            render_with_label = asfrom and (not column.is_literal) and (column.table is not None)
        elif isinstance(column, elements.TextClause):
            render_with_label = False
        elif isinstance(column, elements.UnaryExpression):
            render_with_label = column.operator in (operators.is_false, operators.is_true) and (not self.dialect.supports_native_boolean) or column._wraps_unnamed_column() or asfrom
        elif not isinstance(column, elements.NamedColumn) and column._non_anon_label is None:
            render_with_label = True
        else:
            render_with_label = False
        if render_with_label:
            if not fallback_label_name:
                assert not column_is_repeated
                fallback_label_name = column._anon_name_label
            fallback_label_name = elements._truncated_label(fallback_label_name) if not isinstance(fallback_label_name, elements._truncated_label) else fallback_label_name
            result_expr = _CompileLabel(col_expr, fallback_label_name, alt_names=(proxy_name,))
        else:
            result_expr = col_expr
    column_clause_args.update(within_columns_clause=within_columns_clause, add_to_result_map=add_to_result_map, include_table=include_table, within_tstring=False)
    return result_expr._compiler_dispatch(self, **column_clause_args)

def _render_cte_clause(self, nesting_level=None, include_following_stack=False):
    if not self.ctes:
        return ''
    ctes: MutableMapping[CTE, str]
    if nesting_level and nesting_level > 1:
        ctes = util.OrderedDict()
        for cte in list(self.ctes.keys()):
            cte_level, cte_name, cte_opts = self.level_name_by_cte[cte._get_reference_cte()]
            nesting = cte.nesting or cte_opts.nesting
            is_rendered_level = cte_level == nesting_level or (include_following_stack and cte_level == nesting_level + 1)
            if not (nesting and is_rendered_level):
                continue
            ctes[cte] = self.ctes[cte]
    else:
        ctes = self.ctes
    if not ctes:
        return ''
    ctes_recursive = any([cte.recursive for cte in ctes])
    cte_text = self.get_cte_preamble(ctes_recursive) + ' '
    cte_text += ', \n'.join([txt for txt in ctes.values()])
    cte_text += '\n '
    if nesting_level and nesting_level > 1:
        for cte in list(ctes.keys()):
            cte_level, cte_name, cte_opts = self.level_name_by_cte[cte._get_reference_cte()]
            del self.ctes[cte]
            del self.ctes_by_level_name[cte_level, cte_name]
            del self.level_name_by_cte[cte._get_reference_cte()]
    return cte_text

def get_select_precolumns(self, select: Select[Any], **kw: Any) -> str:
    if select._distinct_on:
        util.warn_deprecated('DISTINCT ON is currently supported only by the PostgreSQL dialect.  Use of DISTINCT ON for other backends is currently silently ignored, however this usage is deprecated, and will raise CompileError in a future release for all backends that do not support this syntax.', version='1.4')
    return 'DISTINCT ' if select._distinct else ''

def group_by_clause(self, select, **kw):
    group_by = self._generate_delimited_list(select._group_by_clauses, OPERATORS[operators.comma_op], **kw)
    if group_by:
        return ' GROUP BY ' + group_by
    else:
        return ''

def order_by_clause(self, select, **kw):
    order_by = self._generate_delimited_list(select._order_by_clauses, OPERATORS[operators.comma_op], **kw)
    if order_by:
        return ' ORDER BY ' + order_by
    else:
        return ''

def _get_sentinel_column_for_table(self, table: Table) -> Optional[Sequence[Column[Any]]]:
    sentinel_opts = self.dialect.insertmanyvalues_implicit_sentinel
    sentinel_characteristics = table._sentinel_column_characteristics
    sent_cols = sentinel_characteristics.columns
    if sent_cols is None:
        return None
    if sentinel_characteristics.is_autoinc:
        bitmask = self._sentinel_col_autoinc_lookup.get(sentinel_characteristics.default_characterization, 0)
    else:
        bitmask = self._sentinel_col_non_autoinc_lookup.get(sentinel_characteristics.default_characterization, 0)
    if sentinel_opts & bitmask:
        return sent_cols
    if sentinel_characteristics.is_explicit:
        raise exc.InvalidRequestError(f"Column {sent_cols[0]} can't be explicitly marked as a sentinel column when using the {self.dialect.name} dialect, as the particular type of default generation on this column is not currently compatible with this dialect's specific INSERT..RETURNING syntax which can receive the server-generated value in a deterministic way.  To remove this error, remove insert_sentinel=True from primary key autoincrement columns; these columns are automatically used as sentinels for supported dialects in any case.")
    return None

def update_tables_clause(self, update_stmt, from_table, extra_froms, **kw):
    kw['asfrom'] = True
    return from_table._compiler_dispatch(self, iscrud=True, **kw)

def update_post_criteria_clause(self, update_stmt: Update, **kw: Any) -> Optional[str]:
    if update_stmt._post_criteria_clause is not None:
        return self.process(update_stmt._post_criteria_clause, **kw)
    else:
        return None

def delete_post_criteria_clause(self, delete_stmt: Delete, **kw: Any) -> Optional[str]:
    if delete_stmt._post_criteria_clause is not None:
        return self.process(delete_stmt._post_criteria_clause, **kw)
    else:
        return None

def _escape_identifier(self, value: str) -> str:
    value = value.replace(self.escape_quote, self.escape_to_quote)
    if self._double_percents:
        value = value.replace('%', '%%')
    return value

def validate_sql_phrase(self, element, reg):
    if element is not None and (not reg.match(element)):
        raise exc.CompileError('Unexpected SQL phrase: %r (matching against %r)' % (element, reg.pattern))
    return element

def _requires_quotes(self, value: str) -> bool:
    lc_value = value.lower()
    return lc_value in self.reserved_words or value[0] in self.illegal_initial_characters or (not self.legal_characters.match(str(value))) or (lc_value != value)

def quote(self, ident: str) -> str:
    force = getattr(ident, 'quote', None)
    if force is None:
        if ident in self._strings:
            return self._strings[ident]
        else:
            if self._requires_quotes(ident):
                self._strings[ident] = self.quote_identifier(ident)
            else:
                self._strings[ident] = ident
            return self._strings[ident]
    elif force:
        return self.quote_identifier(ident)
    else:
        return ident

def format_table(self, table: FromClause, use_schema: bool=True, name: Optional[str]=None) -> str:
    if name is None:
        if TYPE_CHECKING:
            assert isinstance(table, NamedFromClause)
        name = table.name
    result = self.quote(name)
    effective_schema = self.schema_for_object(table)
    if not self.omit_schema and use_schema and effective_schema:
        result = self.quote_schema(effective_schema) + '.' + result
    return result

def format_label_name(self, name, anon_map=None):
    if anon_map is not None and isinstance(name, elements._truncated_label):
        name = name.apply_map(anon_map)
    return self.quote(name)

def format_column(self, column: ColumnElement[Any], use_table: bool=False, name: Optional[str]=None, table_name: Optional[str]=None, use_schema: bool=False, anon_map: Optional[Mapping[str, Any]]=None) -> str:
    if name is None:
        name = column.name
        assert name is not None
    if anon_map is not None and isinstance(name, elements._truncated_label):
        name = name.apply_map(anon_map)
    if not getattr(column, 'is_literal', False):
        if use_table:
            return self.format_table(column.table, use_schema=use_schema, name=table_name) + '.' + self.quote(name)
        else:
            return self.quote(name)
    elif use_table:
        return self.format_table(column.table, use_schema=use_schema, name=table_name) + '.' + name
    else:
        return name

def format_table_seq(self, table, use_schema=True):
    effective_schema = self.schema_for_object(table)
    if not self.omit_schema and use_schema and effective_schema:
        return (self.quote_schema(effective_schema), self.format_table(table, use_schema=False))
    else:
        return (self.format_table(table, use_schema=False),)

def unformat_identifiers(self, identifiers: str) -> Sequence[str]:
    r = self._r_identifiers
    return [self._unescape_identifier(i) for i in [a or b for a, b in r.findall(identifiers)]]

def _get_crud_params(compiler: SQLCompiler, stmt: ValuesBase, compile_state: DMLState, toplevel: bool, **kw: Any) -> _CrudParams:
    compiler.postfetch = []
    compiler.insert_prefetch = []
    compiler.update_prefetch = []
    compiler.implicit_returning = []
    visiting_cte = kw.get('visiting_cte', None)
    if visiting_cte is not None:
        kw.pop('accumulate_bind_names', None)
    assert 'accumulate_bind_names' not in kw, "Don't know how to handle insert within insert without a CTE"
    bindmarkers: MutableMapping[ColumnElement[Any], DMLTargetCopy[Any]] = {}
    kw['bindmarkers'] = bindmarkers
    _column_as_key, _getattr_col_key, _col_bind_name = _key_getters_for_crud_column(compiler, stmt, compile_state)
    compiler._get_bind_name_for_col = _col_bind_name
    if stmt._returning and stmt._return_defaults:
        raise exc.CompileError("Can't compile statement that includes returning() and return_defaults() simultaneously")
    if compile_state.isdelete:
        _setup_delete_return_defaults(compiler, stmt, compile_state, (), _getattr_col_key, _column_as_key, _col_bind_name, (), (), toplevel, kw)
        return _CrudParams([], [])
    if compiler.column_keys is None and compile_state._no_parameters:
        return _CrudParams([(c, compiler.preparer.format_column(c), _create_bind_param(compiler, c, None, required=True), (c.key,)) for c in stmt.table.columns if not c._omit_from_statements], [])
    stmt_parameter_tuples: Optional[List[Tuple[Union[str, ColumnClause[Any]], Any]]]
    spd: Optional[MutableMapping[_DMLColumnElement, Any]]
    if _compile_state_isinsert(compile_state) and compile_state._has_multi_parameters:
        mp = compile_state._multi_parameters
        assert mp is not None
        spd = mp[0]
        stmt_parameter_tuples = list(spd.items())
        spd_str_key = {_column_as_key(key) for key in spd}
    elif compile_state._dict_parameters:
        spd = compile_state._dict_parameters
        stmt_parameter_tuples = list(spd.items())
        spd_str_key = {_column_as_key(key) for key in spd}
    else:
        stmt_parameter_tuples = spd_str_key = None
    if compiler.column_keys is None:
        parameters = {}
    elif stmt_parameter_tuples:
        assert spd_str_key is not None
        parameters = {_column_as_key(key): REQUIRED for key in compiler.column_keys if key not in spd_str_key}
    else:
        parameters = {_column_as_key(key): REQUIRED for key in compiler.column_keys}
    values: List[_CrudParamElementStr] = []
    if stmt_parameter_tuples is not None:
        _get_stmt_parameter_tuples_params(compiler, compile_state, parameters, stmt_parameter_tuples, _column_as_key, values, kw)
    check_columns: Dict[str, ColumnClause[Any]] = {}
    if dml.isupdate(compile_state) and compile_state.is_multitable:
        _get_update_multitable_params(compiler, stmt, compile_state, stmt_parameter_tuples, check_columns, _col_bind_name, _getattr_col_key, values, kw)
    if _compile_state_isinsert(compile_state) and stmt._select_names:
        assert not compile_state._has_multi_parameters
        _scan_insert_from_select_cols(compiler, stmt, compile_state, parameters, _getattr_col_key, _column_as_key, _col_bind_name, check_columns, values, toplevel, kw)
        use_insertmanyvalues = False
        use_sentinel_columns = None
    else:
        use_insertmanyvalues, use_sentinel_columns = _scan_cols(compiler, stmt, compile_state, parameters, _getattr_col_key, _column_as_key, _col_bind_name, check_columns, values, toplevel, kw)
    if parameters and stmt_parameter_tuples:
        check = set(parameters).intersection((_column_as_key(k) for k, v in stmt_parameter_tuples)).difference(check_columns)
        if check:
            if dml.isupdate(compile_state):
                tables_mentioned = set((c.table for c, v in stmt_parameter_tuples if isinstance(c, ColumnClause) and c.table is not None)).difference([compile_state.dml_table])
                multi_not_in_from = tables_mentioned.difference(compile_state._extra_froms)
                if tables_mentioned and (not compile_state.is_multitable or not compiler.render_table_with_column_in_update_from):
                    if not compiler.render_table_with_column_in_update_from:
                        preamble = 'Backend does not support additional tables in the SET clause'
                    else:
                        preamble = 'Statement is not a multi-table UPDATE statement'
                    raise exc.CompileError(f"""{preamble}; cannot include columns from table(s) {', '.join((f"'{t.description}'" for t in tables_mentioned))} in SET clause""")
                elif multi_not_in_from:
                    assert compiler.render_table_with_column_in_update_from
                    raise exc.CompileError(f"""Multi-table UPDATE statement does not include table(s) {', '.join((f"'{t.description}'" for t in multi_not_in_from))}""")
            raise exc.CompileError('Unconsumed column names: %s' % ', '.join(('%s' % (c,) for c in check)))
    is_default_metavalue_only = False
    if _compile_state_isinsert(compile_state) and compile_state._has_multi_parameters:
        assert not stmt._select_names
        multi_extended_values = _extend_values_for_multiparams(compiler, stmt, compile_state, cast('Sequence[_CrudParamElementStr]', values), cast('Callable[..., str]', _column_as_key), kw)
        if bindmarkers:
            _replace_bindmarkers(compiler, _column_as_key, bindmarkers, compile_state, values, kw)
            for m_v in multi_extended_values:
                _replace_bindmarkers(compiler, _column_as_key, bindmarkers, compile_state, m_v, kw)
        return _CrudParams(values, multi_extended_values)
    elif not values and compiler.for_executemany and compiler.dialect.supports_default_metavalue:
        values = [(_as_dml_column(stmt.table.columns[0]), compiler.preparer.format_column(stmt.table.columns[0]), compiler.dialect.default_metavalue_token, ())]
        is_default_metavalue_only = True
    if bindmarkers:
        _replace_bindmarkers(compiler, _column_as_key, bindmarkers, compile_state, values, kw)
    return _CrudParams(values, [], is_default_metavalue_only=is_default_metavalue_only, use_insertmanyvalues=use_insertmanyvalues, use_sentinel_columns=use_sentinel_columns)

def _append_param_insert_pk_returning(compiler, stmt, c, values, kw):
    if c.default is not None:
        if c.default.is_sequence:
            if compiler.dialect.supports_sequences and (not c.default.optional or not compiler.dialect.sequences_optional):
                accumulated_bind_names: Set[str] = set()
                values.append((c, compiler.preparer.format_column(c), compiler.process(c.default, accumulate_bind_names=accumulated_bind_names, **kw), accumulated_bind_names))
            compiler.implicit_returning.append(c)
        elif c.default.is_clause_element:
            accumulated_bind_names = set()
            values.append((c, compiler.preparer.format_column(c), compiler.process(c.default.arg.self_group(), accumulate_bind_names=accumulated_bind_names, **kw), accumulated_bind_names))
            compiler.implicit_returning.append(c)
        else:
            values.append((c, compiler.preparer.format_column(c), _create_insert_prefetch_bind_param(compiler, c, **kw), (c.key,)))
    elif c is stmt.table._autoincrement_column or c.server_default is not None:
        compiler.implicit_returning.append(c)
    elif not c.nullable:
        _warn_pk_with_no_anticipated_value(c)

def _append_param_insert_pk_no_returning(compiler, stmt, c, values, kw):
    if c.default is not None and (not c.default.is_sequence or (compiler.dialect.supports_sequences and (not c.default.optional or not compiler.dialect.sequences_optional))) or (c is stmt.table._autoincrement_column and (not compiler.dialect.postfetch_lastrowid and (c.default is not None and c.default.is_sequence and compiler.dialect.supports_sequences or (c.default is None and compiler.dialect.preexecute_autoincrement_sequences)))):
        values.append((c, compiler.preparer.format_column(c), _create_insert_prefetch_bind_param(compiler, c, **kw), (c.key,)))
    elif c.default is None and c.server_default is None and (not c.nullable) and (c is not stmt.table._autoincrement_column):
        _warn_pk_with_no_anticipated_value(c)
    elif compiler.dialect.postfetch_lastrowid:
        compiler.postfetch_lastrowid = True

@util.memoized_property
def _default_description_tuple(self) -> _DefaultDescriptionTuple:
    return _DefaultDescriptionTuple._from_column_default(self.default)

@util.memoized_property
def _onupdate_description_tuple(self) -> _DefaultDescriptionTuple:
    return _DefaultDescriptionTuple._from_column_default(self.onupdate)

def _get_returning_modifiers(compiler, stmt, compile_state, toplevel):
    dialect = compiler.dialect
    need_pks = toplevel and _compile_state_isinsert(compile_state) and (not stmt._inline) and (not compiler.for_executemany or (dialect.insert_executemany_returning and stmt._return_defaults)) and (not stmt._returning) and (not compile_state._has_multi_parameters)
    postfetch_lastrowid = need_pks and dialect.postfetch_lastrowid and (stmt.table._autoincrement_column is not None)
    implicit_returning = need_pks and dialect.insert_returning and compile_state._primary_table.implicit_returning and compile_state._supports_implicit_returning and ((not postfetch_lastrowid or dialect.favor_returning_over_lastrowid) or compile_state._has_multi_parameters or stmt._return_defaults)
    if implicit_returning:
        postfetch_lastrowid = False
    if _compile_state_isinsert(compile_state):
        should_implicit_return_defaults = implicit_returning and stmt._return_defaults
        explicit_returning = should_implicit_return_defaults or stmt._returning or stmt._supplemental_returning
        use_insertmanyvalues = toplevel and compiler.for_executemany and dialect.use_insertmanyvalues and (explicit_returning or (dialect.use_insertmanyvalues_wo_returning and stmt._post_values_clause is None))
        use_sentinel_columns = None
        if use_insertmanyvalues and explicit_returning and stmt._sort_by_parameter_order:
            use_sentinel_columns = compiler._get_sentinel_column_for_table(stmt.table)
    elif compile_state.isupdate:
        should_implicit_return_defaults = stmt._return_defaults and compile_state._primary_table.implicit_returning and compile_state._supports_implicit_returning and dialect.update_returning
        use_insertmanyvalues = False
        use_sentinel_columns = None
    elif compile_state.isdelete:
        should_implicit_return_defaults = stmt._return_defaults and compile_state._primary_table.implicit_returning and compile_state._supports_implicit_returning and dialect.delete_returning
        use_insertmanyvalues = False
        use_sentinel_columns = None
    else:
        should_implicit_return_defaults = False
        use_insertmanyvalues = False
        use_sentinel_columns = None
    if should_implicit_return_defaults:
        if not stmt._return_defaults_columns:
            implicit_return_defaults = set(stmt.table.c)
        else:
            implicit_return_defaults = set(stmt._return_defaults_columns)
    else:
        implicit_return_defaults = None
    return (need_pks, implicit_returning or should_implicit_return_defaults, implicit_return_defaults, postfetch_lastrowid, use_insertmanyvalues, use_sentinel_columns)

@_generative
def against(self, target: SchemaItem) -> Self:
    self.target = target
    return self

@_generative
def execute_if(self, dialect: Optional[str]=None, callable_: Optional[DDLIfCallable]=None, state: Optional[Any]=None) -> Self:
    self._ddl_if = DDLIf(dialect, callable_, state)
    return self

def __init__(self, statement, context=None):
    if not isinstance(statement, str):
        raise exc.ArgumentError("Expected a string or unicode SQL statement, got '%r'" % statement)
    self.statement = statement
    self.context = context or {}

def __init__(self, name: str, cascade: bool=False, if_exists: bool=False) -> None:
    super().__init__(element=name, if_exists=if_exists)
    self.cascade = cascade

def __init__(self, element: Constraint, *, isolate_from_table: bool=True) -> None:
    super().__init__(element)
    if isolate_from_table:
        element._create_rule = self._create_rule_disable

def __init__(self, element: Constraint, *, cascade: bool=False, if_exists: bool=False, isolate_from_table: bool | _NoArg=NO_ARG, **kw: Any) -> None:
    self.cascade = cascade
    super().__init__(element, if_exists=if_exists, **kw)
    if isolate_from_table is not NO_ARG:
        util.warn_deprecated('The ``isolate_from_table`` is deprecated and it be removed in a future release.', '2.1')
        if isolate_from_table:
            element._create_rule = self._create_rule_disable

@contextlib.contextmanager
def with_ddl_events(self, target, **kw):
    raise NotImplementedError()

@contextlib.contextmanager
def with_ddl_events(self, target, **kw):
    target.dispatch.before_create(target, self.connection, _ddl_runner=self, **kw)
    yield
    target.dispatch.after_create(target, self.connection, _ddl_runner=self, **kw)

@contextlib.contextmanager
def with_ddl_events(self, target, **kw):
    target.dispatch.before_drop(target, self.connection, _ddl_runner=self, **kw)
    yield
    target.dispatch.after_drop(target, self.connection, _ddl_runner=self, **kw)

def sort_tables(tables: Iterable[TableClause], skip_fn: Optional[Callable[[ForeignKeyConstraint], bool]]=None, extra_dependencies: Optional[typing_Sequence[Tuple[TableClause, TableClause]]]=None) -> List[Table]:
    if skip_fn is not None:
        fixed_skip_fn = skip_fn

        def _skip_fn(fkc):
            for fk in fkc.elements:
                if fixed_skip_fn(fk):
                    return True
            else:
                return None
    else:
        _skip_fn = None
    return [t for t, fkcs in sort_tables_and_constraints(tables, filter_fn=_skip_fn, extra_dependencies=extra_dependencies, _warn_for_cycles=True) if t is not None]

@util.preload_module('sqlalchemy.sql.schema')
def sort_tables_and_constraints(tables, filter_fn=None, extra_dependencies=None, _warn_for_cycles=False):
    Table = util.preloaded.sql_schema.Table
    fixed_dependencies = set()
    mutable_dependencies = set()
    if extra_dependencies is not None:
        fixed_dependencies.update(extra_dependencies)
    remaining_fkcs = set()
    for table in tables:
        for fkc in table.foreign_key_constraints:
            if fkc.use_alter is True:
                remaining_fkcs.add(fkc)
                continue
            if filter_fn:
                filtered = filter_fn(fkc)
                if filtered is True:
                    remaining_fkcs.add(fkc)
                    continue
            dependent_on = fkc.referred_table
            if dependent_on is not table:
                mutable_dependencies.add((dependent_on, table))
        if isinstance(table._creator_ddl, _TableViaSelect):
            selectable = table._creator_ddl.selectable
            for selected_table in sql_util.find_tables(selectable, check_columns=True, include_aliases=True, include_joins=True, include_selects=True, include_crud=True):
                if isinstance(selected_table, Table) and selected_table.metadata is table.metadata:
                    fixed_dependencies.add((selected_table, table))
        fixed_dependencies.update(((parent, table) for parent in table._extra_dependencies))
    try:
        candidate_sort = list(topological.sort(fixed_dependencies.union(mutable_dependencies), tables))
    except exc.CircularDependencyError as err:
        if _warn_for_cycles:
            util.warn('Cannot correctly sort tables; there are unresolvable cycles between tables "%s", which is usually caused by mutually dependent foreign key constraints.  Foreign key constraints involving these tables will not be considered; this warning may raise an error in a future release.' % (', '.join(sorted((t.fullname for t in err.cycles))),))
        for edge in err.edges:
            if edge in mutable_dependencies:
                table = edge[1]
                if table not in err.cycles:
                    continue
                can_remove = [fkc for fkc in table.foreign_key_constraints if filter_fn is None or filter_fn(fkc) is not False]
                remaining_fkcs.update(can_remove)
                for fkc in can_remove:
                    dependent_on = fkc.referred_table
                    if dependent_on is not table:
                        mutable_dependencies.discard((dependent_on, table))
        candidate_sort = list(topological.sort(fixed_dependencies.union(mutable_dependencies), tables))
    return [(table, table.foreign_key_constraints.difference(remaining_fkcs)) for table in candidate_sort] + [(None, list(remaining_fkcs))]

def _inv_impl(expr: ColumnElement[Any], op: OperatorType, **kw: Any) -> ColumnElement[Any]:
    if hasattr(expr, 'negation_clause'):
        return expr.negation_clause
    else:
        return expr._negate()

@_generative
def with_dialect_options(self, **opt: Any) -> Self:
    self._validate_dialect_kwargs(opt)
    return self

@_generative
def return_defaults(self, *cols: _DMLColumnArgument, supplemental_cols: Optional[Iterable[_DMLColumnArgument]]=None, sort_by_parameter_order: bool=False) -> Self:
    if self._return_defaults:
        if self._return_defaults_columns and cols:
            self._return_defaults_columns = tuple(util.OrderedSet(self._return_defaults_columns).union((coercions.expect(roles.ColumnsClauseRole, c) for c in cols)))
        else:
            self._return_defaults_columns = ()
    else:
        self._return_defaults_columns = tuple((coercions.expect(roles.ColumnsClauseRole, c) for c in cols))
    self._return_defaults = True
    if sort_by_parameter_order:
        if not self.is_insert:
            raise exc.ArgumentError("The 'sort_by_parameter_order' argument to return_defaults() only applies to INSERT statements")
        self._sort_by_parameter_order = True
    if supplemental_cols:
        supplemental_col_tup = (coercions.expect(roles.ColumnsClauseRole, c) for c in supplemental_cols)
        if self._supplemental_returning is None:
            self._supplemental_returning = tuple(util.unique_list(supplemental_col_tup))
        else:
            self._supplemental_returning = tuple(util.unique_list(self._supplemental_returning + tuple(supplemental_col_tup)))
    return self

@_generative
def returning(self, *cols: _ColumnsClauseArgument[Any], sort_by_parameter_order: bool=False, **__kw: Any) -> UpdateBase:
    if __kw:
        raise _unexpected_kw('UpdateBase.returning()', __kw)
    if self._return_defaults:
        raise exc.InvalidRequestError('return_defaults() is already configured on this statement')
