                return fixed_process_value(fixed_impl_processor(value), dialect)
        else:
            fixed_process_value = process_value

            def process(value: Any) -> Optional[_T]:
                return fixed_process_value(value, dialect)
        return process
    else:
        return self.impl_instance.result_processor(dialect, coltype)

@util.memoized_property
def _has_column_expression(self) -> bool:
    return util.method_is_overridden(self, TypeDecorator.column_expression) or self.impl_instance._has_column_expression

def find_join_source(clauses: List[FromClause], join_to: FromClause) -> List[int]:
    selectables = list(_from_objects(join_to))
    idx = []
    for i, f in enumerate(clauses):
        for s in selectables:
            if f.is_derived_from(s):
                idx.append(i)
    return idx

def find_left_clause_that_matches_given(clauses: Sequence[FromClause], join_from: FromClause) -> List[int]:
    selectables = list(_from_objects(join_from))
    liberal_idx = []
    for i, f in enumerate(clauses):
        for s in selectables:
            if f.is_derived_from(s):
                liberal_idx.append(i)
                break
    if len(liberal_idx) > 1:
        conservative_idx = []
        for idx in liberal_idx:
            f = clauses[idx]
            for s in selectables:
                if set(surface_selectables(f)).intersection(surface_selectables(s)):
                    conservative_idx.append(idx)
                    break
        if conservative_idx:
            return conservative_idx
    return liberal_idx

def find_left_clause_to_join_from(clauses: Sequence[FromClause], join_to: _JoinTargetElement, onclause: Optional[ColumnElement[Any]]) -> List[int]:
    idx = []
    selectables = set(_from_objects(join_to))
    if len(clauses) > 1 and onclause is not None:
        resolve_ambiguity = True
        cols_in_onclause = _find_columns(onclause)
    else:
        resolve_ambiguity = False
        cols_in_onclause = None
    for i, f in enumerate(clauses):
        for s in selectables.difference([f]):
            if resolve_ambiguity:
                assert cols_in_onclause is not None
                if set(f.c).union(s.c).issuperset(cols_in_onclause):
                    idx.append(i)
                    break
            elif onclause is not None or Join._can_join(f, s):
                idx.append(i)
                break
    if len(idx) > 1:
        toremove = set(chain(*[_expand_cloned(f._hide_froms) for f in clauses]))
        idx = [i for i in idx if clauses[i] not in toremove]
    if not idx and onclause is not None:
        return list(range(len(clauses)))
    else:
        return idx

def visit_binary_product(fn: Callable[[BinaryExpression[Any], ColumnElement[Any], ColumnElement[Any]], None], expr: ColumnElement[Any]) -> None:
    stack: List[BinaryExpression[Any]] = []

    def visit(element: ClauseElement) -> Iterator[ColumnElement[Any]]:
        if isinstance(element, ScalarSelect):
            yield element
        elif element.__visit_name__ == 'binary' and operators.is_comparison(element.operator):
            stack.insert(0, element)
            for l in visit(element.left):
                for r in visit(element.right):
                    fn(stack[0], l, r)
            stack.pop(0)
            for elem in element.get_children():
                visit(elem)
        else:
            if isinstance(element, ColumnClause):
                yield element
            for elem in element.get_children():
                yield from visit(elem)
    list(visit(expr))
    visit = None

def find_tables(clause: ClauseElement, *, check_columns: bool=False, include_aliases: bool=False, include_joins: bool=False, include_selects: bool=False, include_crud: bool=False) -> List[TableClause]:
    tables: List[TableClause] = []
    _visitors: Dict[str, _TraverseCallableType[Any]] = {}
    if include_selects:
        _visitors['select'] = _visitors['compound_select'] = tables.append
    if include_joins:
        _visitors['join'] = tables.append
    if include_aliases:
        _visitors['alias'] = _visitors['subquery'] = _visitors['tablesample'] = _visitors['lateral'] = tables.append
    if include_crud:
        _visitors['insert'] = _visitors['update'] = _visitors['delete'] = lambda ent: tables.append(ent.table)
    if check_columns:

        def visit_column(column):
            tables.append(column.table)
        _visitors['column'] = visit_column
    _visitors['table'] = tables.append
    visitors.traverse(clause, {}, _visitors)
    return tables

def unwrap_order_by(clause: Any) -> Any:
    cols = util.column_set()
    result = []
    stack = deque([clause])
    while stack:
        t = stack.popleft()
        if isinstance(t, ColumnElement) and (not isinstance(t, UnaryExpression) or not operators.is_ordering_modifier(t.modifier)):
            if isinstance(t, Label) and (not isinstance(t.element, ScalarSelect)):
                t = t.element
                if isinstance(t, Grouping):
                    t = t.element
                stack.append(t)
                continue
            elif isinstance(t, _label_reference):
                t = t.element
                stack.append(t)
                continue
            if isinstance(t, _textual_label_reference):
                continue
            if t not in cols:
                cols.add(t)
                result.append(t)
        else:
            for c in t.get_children():
                stack.append(c)
    return result

def expand_column_list_from_order_by(collist, order_by):
    cols_already_present = {col.element if col._order_by_label_element is not None else col for col in collist}
    to_look_for = list(chain(*[unwrap_order_by(o) for o in order_by]))
    return [col for col in to_look_for if col not in cols_already_present]

def clause_is_present(clause, search):
    for elem in surface_selectables(search):
        if clause == elem:
            return True
    else:
        return False

def bind_values(clause):
    v = []

    def visit_bindparam(bind):
        v.append(bind.effective_value)
    visitors.traverse(clause, {}, {'bindparam': visit_bindparam})
    return v

def adapt_criterion_to_null(crit: _CE, nulls: Collection[Any]) -> _CE:

    def visit_binary(binary):
        if isinstance(binary.left, BindParameter) and binary.left._identifying_key in nulls:
            binary.left = binary.right
            binary.right = Null()
            binary.operator = operators.is_
            binary.negate = operators.is_not
        elif isinstance(binary.right, BindParameter) and binary.right._identifying_key in nulls:
            binary.right = Null()
            binary.operator = operators.is_
            binary.negate = operators.is_not
    return visitors.cloned_traverse(crit, {}, {'binary': visit_binary})

def reduce_columns(columns: _SelectIterable, *clauses: Optional[ClauseElement], **kw: bool) -> Collection[Union[ColumnElement[Any], AbstractTextClause]]:
    ignore_nonexistent_tables = kw.pop('ignore_nonexistent_tables', False)
    only_synonyms = kw.pop('only_synonyms', False)
    column_set = util.OrderedSet(columns)
    cset_no_text: util.OrderedSet[ColumnElement[Any]] = column_set.difference((c for c in column_set if is_text_clause(c)))
    omit = util.column_set()
    for col in cset_no_text:
        for fk in chain(*[c.foreign_keys for c in col.proxy_set]):
            for c in cset_no_text:
                if c is col:
                    continue
                try:
                    fk_col = fk.column
                except exc.NoReferencedColumnError:
                    if ignore_nonexistent_tables:
                        continue
                    else:
                        raise
                except exc.NoReferencedTableError:
                    if ignore_nonexistent_tables:
                        continue
                    else:
                        raise
                if fk_col.shares_lineage(c) and (not only_synonyms or c.name == col.name):
                    omit.add(col)
                    break
    if clauses:

        def visit_binary(binary):
            if binary.operator == operators.eq:
                cols = util.column_set(chain(*[c.proxy_set for c in cset_no_text.difference(omit)]))
                if binary.left in cols and binary.right in cols:
                    for c in reversed(cset_no_text):
                        if c.shares_lineage(binary.right) and (not only_synonyms or c.name == binary.left.name):
                            omit.add(c)
                            break
        for clause in clauses:
            if clause is not None:
                visitors.traverse(clause, {}, {'binary': visit_binary})
    return column_set.difference(omit)

def criterion_as_pairs(expression, consider_as_foreign_keys=None, consider_as_referenced_keys=None, any_operator=False):
    if consider_as_foreign_keys and consider_as_referenced_keys:
        raise exc.ArgumentError("Can only specify one of 'consider_as_foreign_keys' or 'consider_as_referenced_keys'")

    def col_is(a, b):
        return a.compare(b)

    def visit_binary(binary):
        if not any_operator and binary.operator is not operators.eq:
            return
        if not isinstance(binary.left, ColumnElement) or not isinstance(binary.right, ColumnElement):
            return
        if consider_as_foreign_keys:
            if binary.left in consider_as_foreign_keys and (col_is(binary.right, binary.left) or binary.right not in consider_as_foreign_keys):
                pairs.append((binary.right, binary.left))
            elif binary.right in consider_as_foreign_keys and (col_is(binary.left, binary.right) or binary.left not in consider_as_foreign_keys):
                pairs.append((binary.left, binary.right))
        elif consider_as_referenced_keys:
            if binary.left in consider_as_referenced_keys and (col_is(binary.right, binary.left) or binary.right not in consider_as_referenced_keys):
                pairs.append((binary.left, binary.right))
            elif binary.right in consider_as_referenced_keys and (col_is(binary.left, binary.right) or binary.left not in consider_as_referenced_keys):
                pairs.append((binary.right, binary.left))
        elif isinstance(binary.left, Column) and isinstance(binary.right, Column):
            if binary.left.references(binary.right):
                pairs.append((binary.right, binary.left))
            elif binary.right.references(binary.left):
                pairs.append((binary.left, binary.right))
    pairs: List[Tuple[ColumnElement[Any], ColumnElement[Any]]] = []
    visitors.traverse(expression, {}, {'binary': visit_binary})
    return pairs

def _offset_or_limit_clause_asint_if_possible(clause: _LimitOffsetType) -> _LimitOffsetType:
    if clause is None:
        return None
    if hasattr(clause, '_limit_offset_value'):
        value = clause._limit_offset_value
        return util.asint(value)
    else:
        return clause

def _make_slice(limit_clause: _LimitOffsetType, offset_clause: _LimitOffsetType, start: int, stop: int) -> Tuple[Optional[ColumnElement[int]], Optional[ColumnElement[int]]]:
    if start is not None and stop is not None:
        offset_clause = _offset_or_limit_clause_asint_if_possible(offset_clause)
        if offset_clause is None:
            offset_clause = 0
        if start != 0:
            offset_clause = offset_clause + start
        if offset_clause == 0:
            offset_clause = None
        else:
            assert offset_clause is not None
            offset_clause = _offset_or_limit_clause(offset_clause)
        limit_clause = _offset_or_limit_clause(stop - start)
    elif start is None and stop is not None:
        limit_clause = _offset_or_limit_clause(stop)
    elif start is not None and stop is None:
        offset_clause = _offset_or_limit_clause_asint_if_possible(offset_clause)
        if offset_clause is None:
            offset_clause = 0
        if start != 0:
            offset_clause = offset_clause + start
        if offset_clause == 0:
            offset_clause = None
        else:
            offset_clause = _offset_or_limit_clause(offset_clause)
    return (limit_clause, offset_clause)

