@property
def visitor_iterator(self) -> Iterator[ExternalTraversal]:
    v: Optional[ExternalTraversal] = self
    while v:
        yield v
        v = getattr(v, '_next', None)

def traverse(self, obj: Optional[ExternallyTraversible]) -> Optional[ExternallyTraversible]:

    def replace(element: ExternallyTraversible, **kw: Any) -> Optional[ExternallyTraversible]:
        for v in self.visitor_iterator:
            e = cast(ReplacingExternalTraversal, v).replace(element)
            if e is not None:
                return e
        return None
    return replacement_traverse(obj, self.__traverse_options__, replace)

def iterate(obj: Optional[ExternallyTraversible], opts: Mapping[str, Any]=util.EMPTY_DICT) -> Iterator[ExternallyTraversible]:
    if obj is None:
        return
    yield obj
    children = obj.get_children(**opts)
    if not children:
        return
    stack = deque([children])
    while stack:
        t_iterator = stack.popleft()
        for t in t_iterator:
            yield t
            stack.append(t.get_children(**opts))

def traverse_using(iterator: Iterable[ExternallyTraversible], obj: Optional[ExternallyTraversible], visitors: Mapping[str, _TraverseCallableType[Any]]) -> Optional[ExternallyTraversible]:
    for target in iterator:
        meth = visitors.get(target.__visit_name__, None)
        if meth:
            meth(target)
    return obj

def cloned_traverse(obj: Optional[ExternallyTraversible], opts: Mapping[str, Any], visitors: Mapping[str, _TraverseCallableType[Any]]) -> Optional[ExternallyTraversible]:
    cloned: Dict[int, ExternallyTraversible] = {}
    stop_on = set(opts.get('stop_on', []))

    def deferred_copy_internals(obj: ExternallyTraversible) -> ExternallyTraversible:
        return cloned_traverse(obj, opts, visitors)

    def clone(elem: ExternallyTraversible, **kw: Any) -> ExternallyTraversible:
        if elem in stop_on:
            return elem
        else:
            if id(elem) not in cloned:
                if 'replace' in kw:
                    newelem = cast(Optional[ExternallyTraversible], kw['replace'](elem))
                    if newelem is not None:
                        cloned[id(elem)] = newelem
                        return newelem
                cloned[id(elem)] = newelem = elem._clone(clone=clone, **kw)
                newelem._copy_internals(clone=clone, **kw)
                if not elem._is_immutable:
                    meth = visitors.get(newelem.__visit_name__, None)
                    if meth:
                        meth(newelem)
            return cloned[id(elem)]
    if obj is not None:
        obj = clone(obj, deferred_copy_internals=deferred_copy_internals, **opts)
    clone = None
    return obj

def replacement_traverse(obj: Optional[ExternallyTraversible], opts: Mapping[str, Any], replace: _TraverseTransformCallableType[Any]) -> Optional[ExternallyTraversible]:
    cloned = {}
    stop_on = {id(x) for x in opts.get('stop_on', [])}

    def deferred_copy_internals(obj: ExternallyTraversible) -> ExternallyTraversible:
        return replacement_traverse(obj, opts, replace)

    def clone(elem: ExternallyTraversible, **kw: Any) -> ExternallyTraversible:
        if id(elem) in stop_on or 'no_replacement_traverse' in elem._annotations:
            return elem
        else:
            newelem = replace(elem)
            if newelem is not None:
                stop_on.add(id(newelem))
                return newelem
            else:
                id_elem = id(elem)
                if id_elem not in cloned:
                    if 'replace' in kw:
                        newelem = kw['replace'](elem)
                        if newelem is not None:
                            cloned[id_elem] = newelem
                            return newelem
                    cloned[id_elem] = newelem = elem._clone(**kw)
                    newelem._copy_internals(clone=clone, **kw)
                return cloned[id_elem]
    if obj is not None:
        obj = clone(obj, deferred_copy_internals=deferred_copy_internals, **opts)
    clone = None
    return obj

