def mock_engine(dialect_name=None):
    from sqlalchemy import create_mock_engine
    if not dialect_name:
        dialect_name = config.db.name
    buffer = []

    def executor(sql, *a, **kw):
        buffer.append(sql)

    def assert_sql(stmts):
        recv = [re.sub('[\\n\\t]', '', str(s)) for s in buffer]
        assert recv == stmts, recv

    def print_sql():
        d = engine.dialect
        return '\n'.join((str(s.compile(dialect=d)) for s in engine.mock))
    engine = create_mock_engine(dialect_name + '://', executor)
    assert not hasattr(engine, 'mock')
    engine.mock = buffer
    engine.assert_sql = assert_sql
    engine.print_sql = print_sql
    return engine

def __eq__(self, other):
    if other is self:
        return True
    elif not self.__class__ == other.__class__:
        return False
    if id(self) in _recursion_stack:
        return True
    _recursion_stack.add(id(self))
    try:
        try:
            self_key = sa.orm.attributes.instance_state(self).key
        except sa.orm.exc.NO_STATE:
            self_key = None
        if other is None:
            a = self
            b = other
        elif self_key is not None:
            a = other
            b = self
        else:
            a = self
            b = other
        for attr in list(a.__dict__):
            if attr.startswith('_'):
                continue
            value = getattr(a, attr)
            if isinstance(value, WriteOnlyCollection):
                continue
            try:
                battr = getattr(b, attr)
            except (AttributeError, sa_exc.UnboundExecutionError):
                return False
            if hasattr(value, '__iter__') and (not isinstance(value, str)):
                if hasattr(value, '__getitem__') and (not hasattr(value, 'keys')):
                    if list(value) != list(battr):
                        return False
                elif set(value) != set(battr):
                    return False
            elif value is not None and value != battr:
                return False
        return True
    finally:
        _recursion_stack.remove(id(self))

def function_call_count(variance=0.05, times=1, warmup=0):
    from sqlalchemy.util import decorator

    @decorator
    def wrap(fn, *args, **kw):
        for warm in range(warmup):
            fn(*args, **kw)
        timerange = range(times)
        with count_functions(variance=variance):
            for time in timerange:
                rv = fn(*args, **kw)
            return rv
    return wrap

def generate_db_urls(db_urls, extra_drivers):
    urls = set()
    backend_to_driver_we_already_have = collections.defaultdict(set)
    urls_plus_dialects = [(url_obj, url_obj.get_dialect()) for url_obj in [sa_url.make_url(db_url) for db_url in db_urls]]
    for url_obj, dialect in urls_plus_dialects:
        driver_name = url_obj.get_driver_name()
        backend_to_driver_we_already_have[dialect.name].add(driver_name)
    backend_to_driver_we_need = {}
    for url_obj, dialect in urls_plus_dialects:
        backend = dialect.name
        dialect.load_provisioning()
        if backend not in backend_to_driver_we_need:
            backend_to_driver_we_need[backend] = extra_per_backend = set(extra_drivers).difference(backend_to_driver_we_already_have[backend])
        else:
            extra_per_backend = backend_to_driver_we_need[backend]
        for driver_url in _generate_driver_urls(url_obj, extra_per_backend):
            if driver_url in urls:
                continue
            urls.add(driver_url)
            yield driver_url

