    if savepoints:
        savepoints = savepoints.enabled
    inspector = inspect(connection)
    for table in reversed([t for t, fks in sort_tables_and_constraints(metadata.tables.values()) if t is not None and t.name in inspector.get_table_names(schema=t.schema)]):
