def _parametrize_cls(module, cls):
    if '_sa_parametrize' not in cls.__dict__:
        return [cls]
    _sa_parametrize = cls._sa_parametrize
    classes = []
    for full_param_set in itertools.product(*[params for argname, params in _sa_parametrize]):
        cls_variables = {}
        for argname, param in zip([_sa_param[0] for _sa_param in _sa_parametrize], full_param_set):
            if not argname:
                raise TypeError('need argnames for class-based combinations')
            argname_split = re.split(',\\s*', argname)
            for arg, val in zip(argname_split, param.values):
                cls_variables[arg] = val
        parametrized_name = '_'.join((re.sub('\\W', '', token) for param in full_param_set for token in param.id.split('-')))
        name = '%s_%s' % (cls.__name__, parametrized_name)
        newcls = type.__new__(type, name, (cls,), cls_variables)
        setattr(module, name, newcls)
        classes.append(newcls)
    return classes

def _pytest_fn_decorator(target):
    from sqlalchemy.util.langhelpers import format_argspec_plus
    from sqlalchemy.util.compat import inspect_getfullargspec

    def _exec_code_in_env(code, env, fn_name):
        exec(code, env)
        return env[fn_name]

    def decorate(fn, add_positional_parameters=()):
        spec = inspect_getfullargspec(fn)
        if add_positional_parameters:
            spec.args.extend(add_positional_parameters)
        metadata = dict(__target_fn='__target_fn', __orig_fn='__orig_fn', name=fn.__name__)
        metadata.update(format_argspec_plus(spec, grouped=False))
        code = 'def %(name)s%(grouped_args)s:\n    return %(__target_fn)s(%(__orig_fn)s, %(apply_kw)s)\n' % metadata
        decorated = _exec_code_in_env(code, {'__target_fn': target, '__orig_fn': fn}, fn.__name__)
        if not add_positional_parameters:
            decorated.__defaults__ = getattr(fn, '__func__', fn).__defaults__
            decorated.__wrapped__ = fn
            return update_wrapper(decorated, fn)
        else:
            decorated.__module__ = fn.__module__
            decorated.__name__ = fn.__name__
            if hasattr(fn, 'pytestmark'):
                decorated.pytestmark = fn.pytestmark
            return decorated
    return decorate

def combinations(self, *arg_sets, **kw):
    from sqlalchemy.testing import exclusions
    if len(arg_sets) == 1 and hasattr(arg_sets[0], '__next__'):
        arg_sets = list(arg_sets[0])
    argnames = kw.pop('argnames', None)

    def _filter_exclusions(args):
        result = []
        gathered_exclusions = []
        for a in args:
            if isinstance(a, exclusions.compound):
                gathered_exclusions.append(a)
            else:
                result.append(a)
        return (result, gathered_exclusions)
    id_ = kw.pop('id_', None)
    tobuild_pytest_params = []
    has_exclusions = False
    if id_:
        _combination_id_fns = self._combination_id_fns
        _arg_getter = operator.itemgetter(0, *[idx for idx, char in enumerate(id_) if char in ('n', 'r', 's', 'a')])
        fns = [(operator.itemgetter(idx), _combination_id_fns[char]) for idx, char in enumerate(id_) if char in _combination_id_fns]
        for arg in arg_sets:
            if not isinstance(arg, tuple):
                arg = (arg,)
            fn_params, param_exclusions = _filter_exclusions(arg)
            parameters = _arg_getter(fn_params)[1:]
            if param_exclusions:
                has_exclusions = True
            tobuild_pytest_params.append((parameters, param_exclusions, '-'.join((comb_fn(getter(arg)) for getter, comb_fn in fns))))
    else:
        for arg in arg_sets:
            if not isinstance(arg, tuple):
                arg = (arg,)
            fn_params, param_exclusions = _filter_exclusions(arg)
            if param_exclusions:
                has_exclusions = True
            tobuild_pytest_params.append((fn_params, param_exclusions, None))
    pytest_params = []
    for parameters, param_exclusions, id_ in tobuild_pytest_params:
        if has_exclusions:
            parameters += (param_exclusions,)
        param = pytest.param(*parameters, id=id_)
        pytest_params.append(param)

    def decorate(fn):
        if inspect.isclass(fn):
            if has_exclusions:
                raise NotImplementedError('exclusions not supported for class level combinations')
            if '_sa_parametrize' not in fn.__dict__:
                fn._sa_parametrize = []
            fn._sa_parametrize.append((argnames, pytest_params))
            return fn
        else:
            _fn_argnames = inspect.getfullargspec(fn).args[1:]
            if argnames is None:
                _argnames = _fn_argnames
            else:
                _argnames = re.split(', *', argnames)
            if has_exclusions:
                existing_exl = sum((1 for n in _fn_argnames if n.startswith('_exclusions')))
                current_exclusion_name = f'_exclusions_{existing_exl}'
                _argnames += [current_exclusion_name]

                @_pytest_fn_decorator
                def check_exclusions(fn, *args, **kw):
                    _exclusions = args[-1]
                    if _exclusions:
                        exlu = exclusions.compound().add(*_exclusions)
                        fn = exlu(fn)
                    return fn(*args[:-1], **kw)
                fn = check_exclusions(fn, add_positional_parameters=(current_exclusion_name,))
            return pytest.mark.parametrize(_argnames, pytest_params)(fn)
    return decorate

