def inspect_getfullargspec(func: Callable[..., Any]) -> FullArgSpec:
    if inspect.ismethod(func):
        func = func.__func__
    if not inspect.isfunction(func) and (not hasattr(func, '__code__')):
        raise TypeError(f'{func!r} is not a Python function')
    co = func.__code__
    if not inspect.iscode(co):
        raise TypeError(f'{co!r} is not a code object')
    nargs = co.co_argcount
    names = co.co_varnames
    nkwargs = co.co_kwonlyargcount
    args = list(names[:nargs])
    kwonlyargs = list(names[nargs:nargs + nkwargs])
    nargs += nkwargs
    varargs = None
    if co.co_flags & inspect.CO_VARARGS:
        varargs = co.co_varnames[nargs]
        nargs = nargs + 1
    varkw = None
    if co.co_flags & inspect.CO_VARKEYWORDS:
        varkw = co.co_varnames[nargs]
    return FullArgSpec(args, varargs, varkw, func.__defaults__, kwonlyargs, func.__kwdefaults__, get_annotations(func))

def _formatannotation(annotation, base_module=None):
    if isinstance(annotation, str):
        return annotation
    if getattr(annotation, '__module__', None) == 'typing':
        return repr(annotation).replace('typing.', '').replace('~', '')
    if isinstance(annotation, type):
        if annotation.__module__ in ('builtins', base_module):
            return repr(annotation.__qualname__)
        return annotation.__module__ + '.' + annotation.__qualname__
    elif isinstance(annotation, typing.TypeVar):
        return repr(annotation).replace('~', '')
    return repr(annotation).replace('~', '')

def inspect_formatargspec(args: List[str], varargs: Optional[str]=None, varkw: Optional[str]=None, defaults: Optional[Sequence[Any]]=None, kwonlyargs: Optional[Sequence[str]]=(), kwonlydefaults: Optional[Mapping[str, Any]]={}, annotations: Mapping[str, Any]={}, formatarg: Callable[[str], str]=str, formatvarargs: Callable[[str], str]=lambda name: '*' + name, formatvarkw: Callable[[str], str]=lambda name: '**' + name, formatvalue: Callable[[Any], str]=lambda value: '=' + repr(value), formatreturns: Callable[[Any], str]=lambda text: ' -> ' + str(text), formatannotation: Callable[[Any], str]=_formatannotation) -> str:
    kwonlydefaults = kwonlydefaults or {}
    annotations = annotations or {}

    def formatargandannotation(arg):
        result = formatarg(arg)
        if arg in annotations:
            result += ': ' + formatannotation(annotations[arg])
        return result
    specs = []
    if defaults:
        firstdefault = len(args) - len(defaults)
    else:
        firstdefault = -1
    for i, arg in enumerate(args):
        spec = formatargandannotation(arg)
        if defaults and i >= firstdefault:
            spec = spec + formatvalue(defaults[i - firstdefault])
        specs.append(spec)
    if varargs is not None:
        specs.append(formatvarargs(formatargandannotation(varargs)))
    elif kwonlyargs:
        specs.append('*')
    if kwonlyargs:
        for kwonlyarg in kwonlyargs:
            spec = formatargandannotation(kwonlyarg)
            if kwonlydefaults and kwonlyarg in kwonlydefaults:
                spec += formatvalue(kwonlydefaults[kwonlyarg])
            specs.append(spec)
    if varkw is not None:
        specs.append(formatvarkw(formatargandannotation(varkw)))
    result = '(' + ', '.join(specs) + ')'
    if 'return' in annotations:
        result += formatreturns(formatannotation(annotations['return']))
    return result

def dataclass_fields(cls: Type[Any]) -> Iterable[dataclasses.Field[Any]]:
    if dataclasses.is_dataclass(cls):
        return dataclasses.fields(cls)
    else:
        return []

def local_dataclass_fields(cls: Type[Any]) -> Iterable[dataclasses.Field[Any]]:
    if dataclasses.is_dataclass(cls):
        super_fields: Set[dataclasses.Field[Any]] = set()
        for sup in cls.__bases__:
            super_fields.update(dataclass_fields(sup))
        return [f for f in dataclasses.fields(cls) if f not in super_fields]
    else:
        return []

def _initialize(self, *, raise_: bool=True) -> None:
    if 'greenlet' in globals():
        return
    if not TYPE_CHECKING:
        global getcurrent, greenlet, _AsyncIoGreenlet
        global _has_gr_context
    try:
        from greenlet import getcurrent
        from greenlet import greenlet
    except ImportError as e:
        if not TYPE_CHECKING:
            greenlet = None
        self._has_greenlet = False
        self._initialize_no_greenlet()
        if raise_:
            raise ImportError(_ERROR_MESSAGE) from e
    else:
        self._has_greenlet = True
        _has_gr_context = hasattr(getcurrent(), 'gr_context')

        class _AsyncIoGreenlet(greenlet):
            dead: bool
            __sqlalchemy_greenlet_provider__ = True

            def __init__(self, fn: Callable[..., Any], driver: greenlet):
                greenlet.__init__(self, fn, driver)
                if _has_gr_context:
                    self.gr_context = driver.gr_context
        self.greenlet = greenlet
        self.getcurrent = getcurrent
        self._AsyncIoGreenlet = _AsyncIoGreenlet

def await_(awaitable: Awaitable[_T]) -> _T:
    current = _concurrency_shim.getcurrent()
    if not getattr(current, '__sqlalchemy_greenlet_provider__', False):
        _safe_cancel_awaitable(awaitable)
        raise exc.MissingGreenlet("greenlet_spawn has not been called; can't call await_() here. Was IO attempted in an unexpected place?")
    assert current.parent
    return current.parent.switch(awaitable)

async def greenlet_spawn(fn: Callable[..., _T], *args: Any, _require_await: bool=False, **kwargs: Any) -> _T:
    result: Any
    context = _concurrency_shim._AsyncIoGreenlet(fn, _concurrency_shim.getcurrent())
    switch_occurred = False
    result = context.switch(*args, **kwargs)
    while not context.dead:
        switch_occurred = True
        try:
            value = await result
        except BaseException:
            result = context.throw(*sys.exc_info())
        else:
            result = context.switch(value)
    if _require_await and (not switch_occurred):
        raise exc.AwaitRequired('The current operation required an async execution but none was detected. This will usually happen when using a non compatible DBAPI driver. Please ensure that an async DBAPI is used.')
    return result

def run_in_greenlet(self, fn: Callable[..., _T], *args: Any, **kwargs: Any) -> _T:
    _concurrency_shim._initialize(raise_=False)
    if _concurrency_shim._has_greenlet:
        if self.runner.get_loop().is_running():
            assert in_greenlet()
            return fn(*args, **kwargs)
        else:
            return self.runner.run(greenlet_spawn(fn, *args, **kwargs))
    else:
        return fn(*args, **kwargs)

