def quoted_token_parser(value):
    if '"' not in value:
        return value.split('.')
    state = 0
    result: List[List[str]] = [[]]
    idx = 0
    lv = len(value)
    while idx < lv:
        char = value[idx]
        if char == '"':
            if state == 1 and idx < lv - 1 and (value[idx + 1] == '"'):
                result[-1].append('"')
                idx += 1
            else:
                state ^= 1
        elif char == '.' and state == 0:
            result.append([])
        else:
            result[-1].append(char)
        idx += 1
    return [''.join(token) for token in result]

